def _marker_spelling_provenance_report(run_dir: Path) -> dict:
    canonical_probe = _marker_spelling_parser_probe(
        "# EVOLVE-BLOCK-START solve\nx = 1\n# EVOLVE-BLOCK-END\n"
    )
    space_variant_probe = _marker_spelling_parser_probe(
        "# EVOLVE-BLOCK START solve\nx = 1\n# EVOLVE-BLOCK-END\n"
    )
    source_artifacts = _marker_spelling_source_artifacts(run_dir)
    page_artifacts = source_artifacts["page_artifacts"]
    figure_3_artifact = source_artifacts["figure_3_marker_text_artifact"]
    source_hashes_attached = all(
        artifact.get("status") == "attached"
        for artifact in page_artifacts.values()
    )
    figure_3_text_attached = figure_3_artifact.get("status") == "attached"
    final_variant_classification = source_hashes_attached and figure_3_text_attached
    records = [
        {
            "record_id": "alphaevolve_section_2_1_page_4_start",
            "paper": "2506.13131__AlphaEvolve.pdf",
            "local_pdf_page": 4,
            "source_location": "Section 2.1 API prose",
            "marker_text": "# EVOLVE-BLOCK-START",
            "marker_role": "start",
            "source_surface": "section_prose",
            "provisional_classification": "canonical_marker_spelling",
            "final_classification": "canonical_marker_spelling",
            "local_parser_probe": canonical_probe,
            "local_support": "supported",
            "source_artifact": _marker_source_artifact_record(
                page_artifacts.get("4"),
                "# EVOLVE-BLOCK-START",
                run_dir=run_dir,
            ),
        },
        {
            "record_id": "alphaevolve_section_2_1_page_4_end",
            "paper": "2506.13131__AlphaEvolve.pdf",
            "local_pdf_page": 4,
            "source_location": "Section 2.1 API prose",
            "marker_text": "# EVOLVE-BLOCK-END",
            "marker_role": "end",
            "source_surface": "section_prose",
            "provisional_classification": "canonical_marker_spelling",
            "final_classification": "canonical_marker_spelling",
            "local_parser_probe": canonical_probe,
            "local_support": "supported",
            "source_artifact": _marker_source_artifact_record(
                page_artifacts.get("4"),
                "# EVOLVE-BLOCK-END",
                run_dir=run_dir,
            ),
        },
        {
            "record_id": "alphaevolve_figure_3a_page_6_space_start",
            "paper": "2506.13131__AlphaEvolve.pdf",
            "local_pdf_page": 6,
            "source_location": "Figure 3(a) extracted/rendered marker text",
            "marker_text": "# EVOLVE-BLOCK START",
            "marker_role": "start",
            "source_surface": "figure_text_extraction",
            "provisional_classification": (
                "figure_text_variant_or_extraction_uncertainty"
            ),
            "final_classification": (
                "pdf_text_extraction_uncertainty_not_supported_parser_syntax"
            ),
            "local_parser_probe": space_variant_probe,
            "local_support": "unsupported_current_parser",
            "source_artifact": _marker_source_artifact_record(
                page_artifacts.get("6"),
                "# EVOLVE-BLOCK START",
                run_dir=run_dir,
            ),
        },
        {
            "record_id": "alphaevolve_figure_3a_page_6_hyphenated_start",
            "paper": "2506.13131__AlphaEvolve.pdf",
            "local_pdf_page": 6,
            "source_location": "Figure 3(a) extracted/rendered marker text",
            "marker_text": "# EVOLVE-BLOCK-START",
            "marker_role": "start",
            "source_surface": "figure_text_extraction",
            "provisional_classification": "canonical_marker_spelling_in_figure",
            "final_classification": "canonical_marker_spelling_in_figure_text_extract",
            "local_parser_probe": canonical_probe,
            "local_support": "supported",
            "source_artifact": _marker_source_artifact_record(
                page_artifacts.get("6"),
                "# EVOLVE-BLOCK-START",
                run_dir=run_dir,
            ),
        },
    ]
    remaining_gap = []
    if not source_hashes_attached:
        remaining_gap.append("source_pdf_excerpt_or_screenshot_hashes")
    if not figure_3_text_attached:
        remaining_gap.append("exact_figure_3_text_artifact")
    if not final_variant_classification:
        remaining_gap.append("final_classification_as_rendered_text_ocr_or_paper_typo")
    report = {
        "schema": "libreevolve.marker_spelling_provenance_report.v1",
        "source": "alphaevolve_paper_source_locations_and_local_parser_probe",
        "canonical_start_marker": "# EVOLVE-BLOCK-START",
        "canonical_end_marker": "# EVOLVE-BLOCK-END",
        "record_count": len(records),
        "records": records,
        "source_artifacts": source_artifacts,
        "variant_classification": {
            "schema": "libreevolve.marker_variant_classification.v1",
            "space_variant": "# EVOLVE-BLOCK START",
            "classification": (
                "pdf_text_extraction_uncertainty_not_supported_parser_syntax"
            ),
            "classification_basis": [
                "local_pypdf_page_6_text_extract",
                "local_parser_probe_orphan_end",
                "section_2_1_canonical_marker_prose",
            ],
            "rendered_figure_text_confirmed": False,
            "paper_typo_confirmed": False,
            "parser_compatibility_changed": False,
        },
        "compatibility_decision": {
            "policy": "canonical_hyphenated_markers_only",
            "space_variant_supported": False,
            "space_variant_probe_error": space_variant_probe["error"],
            "compatibility_mode": "not_configured",
            "documentation_policy": (
                "document Figure 3 space spelling as source variant or extraction "
                "uncertainty, not as supported parser syntax"
            ),
        },
        "claim_ready": not remaining_gap,
        "claim_readiness": {
            "source_locations_recorded": True,
            "parser_probe_recorded": True,
            "compatibility_decision_recorded": True,
            "source_artifact_hashes_attached": source_hashes_attached,
            "source_screenshots_attached": False,
            "exact_figure_3_text_artifact": figure_3_text_attached,
            "final_variant_classification": final_variant_classification,
            "intentional_space_variant_compatibility_mode_needed": False,
            "remaining_gap": remaining_gap,
        },
    }
    report["validation"] = validate_marker_spelling_provenance_report(report)
    return report


def _marker_spelling_parser_probe(code: str) -> dict:
    error = validate_evolve_blocks(code)
    blocks = extract_evolve_blocks(code) if error is None else []
    return {
        "sample_sha256": hashlib.sha256(code.encode("utf-8")).hexdigest(),
        "accepted": error is None,
        "error": error,
        "block_count": len(blocks),
        "block_names": [block.name for block in blocks],
    }


def _marker_spelling_source_artifacts(run_dir: Path) -> dict:
    paper_rel = Path("papers") / "2506.13131__AlphaEvolve.pdf"
    paper_path = Path(__file__).resolve().parents[2] / paper_rel
    artifact_dir = run_dir / "paper_artifacts" / "marker_spelling"
    page_artifacts: dict[str, dict] = {}
    if not paper_path.is_file():
        missing = _marker_source_artifact_missing(
            "local_alphaevolve_pdf_missing",
            paper_rel.as_posix(),
        )
        return {
            "schema": "libreevolve.marker_spelling_source_artifacts.v1",
            "paper": paper_rel.name,
            "paper_path": paper_rel.as_posix(),
            "paper_sha256": None,
            "page_artifacts": {"4": missing, "6": missing},
            "figure_3_marker_text_artifact": missing,
        }
    try:
        raw_pdf = paper_path.read_bytes()
        from pypdf import PdfReader

        reader = PdfReader(str(paper_path))
        artifact_dir.mkdir(parents=True, exist_ok=True)
        paper_sha = hashlib.sha256(raw_pdf).hexdigest()
        for page_number in (4, 6):
            text = reader.pages[page_number - 1].extract_text() or ""
            page_artifacts[str(page_number)] = _write_marker_source_text_artifact(
                artifact_dir,
                run_dir,
                f"alphaevolve_page_{page_number}_text.txt",
                text,
                paper_rel=paper_rel,
                paper_sha=paper_sha,
                page_number=page_number,
                artifact_type="pypdf_page_text_extract",
            )
        figure_3_lines = "\n".join(
            line
            for line in (reader.pages[5].extract_text() or "").splitlines()
            if "EVOLVE-BLOCK" in line or "def evaluate" in line
        )
        figure_3_artifact = _write_marker_source_text_artifact(
            artifact_dir,
            run_dir,
            "alphaevolve_figure_3a_marker_text.txt",
            figure_3_lines + ("\n" if figure_3_lines else ""),
            paper_rel=paper_rel,
            paper_sha=paper_sha,
            page_number=6,
            artifact_type="pypdf_figure_3a_marker_line_extract",
        )
        return {
            "schema": "libreevolve.marker_spelling_source_artifacts.v1",
            "paper": paper_rel.name,
            "paper_path": paper_rel.as_posix(),
            "paper_sha256": paper_sha,
            "page_artifacts": page_artifacts,
            "figure_3_marker_text_artifact": figure_3_artifact,
        }
    except Exception as exc:
        error = _marker_source_artifact_missing(
            "source_artifact_generation_failed",
            paper_rel.as_posix(),
            error_type=exc.__class__.__name__,
            error=redact_sensitive_text(str(exc)),
        )
        return {
            "schema": "libreevolve.marker_spelling_source_artifacts.v1",
            "paper": paper_rel.name,
            "paper_path": paper_rel.as_posix(),
            "paper_sha256": None,
            "page_artifacts": {"4": error, "6": error},
            "figure_3_marker_text_artifact": error,
        }


def _write_marker_source_text_artifact(
    artifact_dir: Path,
    run_dir: Path,
    name: str,
    text: str,
    *,
    paper_rel: Path,
    paper_sha: str,
    page_number: int,
    artifact_type: str,
) -> dict:
    path = artifact_dir / name
    path.write_text(text, encoding="utf-8", newline="\n")
    payload = text.encode("utf-8")
    return {
        "status": "attached",
        "artifact_type": artifact_type,
        "artifact_path": path.relative_to(run_dir).as_posix(),
        "sha256": hashlib.sha256(payload).hexdigest(),
        "bytes": len(payload),
        "paper": paper_rel.name,
        "paper_path": paper_rel.as_posix(),
        "paper_sha256": paper_sha,
        "local_pdf_page": page_number,
        "extraction": "pypdf.extract_text",
    }


def _marker_source_artifact_missing(
    reason: str,
    paper_path: str,
    *,
    error_type: str | None = None,
    error: str | None = None,
) -> dict:
    record = {
        "status": "missing",
        "artifact_path": None,
        "sha256": None,
        "paper_path": paper_path,
        "reason": reason,
    }
    if error_type is not None:
        record["error_type"] = error_type
    if error is not None:
        record["error"] = error
    return record


def _marker_source_artifact_record(
    artifact: Mapping[str, object] | None,
    marker_text: str,
    *,
    run_dir: Path,
) -> dict:
    if not isinstance(artifact, Mapping):
        return _marker_source_artifact_missing("page_artifact_missing", "")
    record = dict(artifact)
    record["marker_text"] = marker_text
    record["marker_text_sha256"] = hashlib.sha256(
        marker_text.encode("utf-8")
    ).hexdigest()
    if record.get("status") == "attached":
        artifact_path = record.get("artifact_path")
        record["marker_text_found_policy"] = "substring_in_extracted_page_text"
        record["marker_text_found"] = _marker_text_found_in_artifact(
            artifact_path,
            marker_text,
            run_dir=run_dir,
        )
        marker_token = marker_text.removeprefix("# ").strip()
        record["marker_token"] = marker_token
        record["marker_token_found"] = _marker_text_found_in_artifact(
            artifact_path,
            marker_token,
            run_dir=run_dir,
        )
    return record


def _marker_text_found_in_artifact(
    artifact_path: object,
    marker_text: str,
    *,
    run_dir: Path,
) -> bool:
    if not isinstance(artifact_path, str):
        return False
    path = Path(artifact_path)
    if not path.is_absolute():
        path = run_dir / path
    try:
        return marker_text in path.read_text(encoding="utf-8")
    except OSError:
        return False


def _initial_program_validity_report(
    startup_manifest: Mapping[str, object],
    programs: list[Program],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    objective_schema = (
        problem.get("objective_schema")
        if isinstance(problem.get("objective_schema"), Mapping)
        else {}
    )
    declared_metrics = _declared_metric_names_from_objective_schema(objective_schema)
    seed_programs = [
        program
        for program in programs
        if isinstance(program.metadata, Mapping)
        and program.metadata.get("candidate_type") == "seed"
    ]
    records = [
        _initial_program_validity_record(program, declared_metrics)
        for program in seed_programs
    ]
    retained_records = records[:50]
    evaluator_valid_count = sum(
        1 for record in retained_records if record["evaluator_is_valid"] is True
    )
    declared_metric_complete_count = sum(
        1 for record in retained_records if not record["missing_declared_metrics"]
    )
    strict_valid_count = sum(
        1 for record in retained_records if record["strict_initial_program_valid"] is True
    )
    invalid_count = len(retained_records) - strict_valid_count
    policy = config.get("initial_program_validity_policy")
    if not isinstance(policy, str):
        policy = "permissive_baseline"
    strict_policy_enabled = policy == "alphaevolve_strict"
    report = {
        "schema": "libreevolve.initial_program_validity_report.v1",
        "source": "generation_zero_seed_evaluations",
        "policy": {
            "manifest_path": "config.initial_program_validity_policy",
            "value": policy,
            "permissive_behavior": "invalid_seeds_logged_as_generation_zero_baselines",
            "strict_behavior": (
                "stop_before_mutation_if_any_seed_lacks_evaluator_validity_or_"
                "declared_metrics"
            ),
            "strict_stop_reason": "invalid_initial_programs",
        },
        "seed_program_count": len(seed_programs),
        "record_count": len(retained_records),
        "records": retained_records,
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "declared_metric_names": declared_metrics,
        "evaluator_valid_seed_count": evaluator_valid_count,
        "declared_metric_complete_seed_count": declared_metric_complete_count,
        "strict_valid_seed_count": strict_valid_count,
        "strict_invalid_seed_count": invalid_count,
        "strict_policy_enabled": strict_policy_enabled,
        "claim_ready": strict_policy_enabled and len(retained_records) > 0 and invalid_count == 0,
        "claim_readiness": {
            "seed_evaluation_before_mutation": True,
            "all_seed_history_rows_present": len(seed_programs) == len(records),
            "all_selected_seeds_evaluator_valid": (
                len(retained_records) > 0 and evaluator_valid_count == len(retained_records)
            ),
            "all_selected_seeds_have_declared_metrics": (
                len(retained_records) > 0
                and declared_metric_complete_count == len(retained_records)
            ),
            "strict_policy_enabled": strict_policy_enabled,
            "strict_stop_on_invalid_seed": strict_policy_enabled,
            "alphaevolve_complete_initial_program_parity": (
                strict_policy_enabled and len(retained_records) > 0 and invalid_count == 0
            ),
            "remaining_gap": (
                []
                if strict_policy_enabled and len(retained_records) > 0 and invalid_count == 0
                else [
                    "enable_alphaevolve_strict_initial_program_policy",
                    "all_selected_seeds_evaluator_valid",
                    "all_selected_seeds_have_declared_metrics",
                    "strict_mode_stop_evidence_for_invalid_seed_fixtures",
                ]
            ),
        },
    }
    report["validation"] = validate_initial_program_validity_report(report)
    return report


def _declared_metric_names_from_objective_schema(schema: Mapping[str, object]) -> list[str]:
    metrics = schema.get("metrics")
    if not isinstance(metrics, list):
        return []
    names = []
    for metric in metrics:
        if isinstance(metric, Mapping) and isinstance(metric.get("name"), str):
            names.append(metric["name"])
    return names


def _seed_meets_strict_initial_program_contract(
    program: Program,
    problem: Problem,
) -> bool:
    metric_names = [
        metric.get("name")
        for metric in problem.metrics
        if isinstance(metric, Mapping) and isinstance(metric.get("name"), str)
    ]
    return (
        isinstance(program.evaluation, Mapping)
        and program.evaluation.get("is_valid") is True
        and all(name in program.metrics for name in metric_names)
    )


def _initial_program_validity_record(
    program: Program,
    declared_metrics: list[str],
) -> dict:
    evaluation = program.evaluation if isinstance(program.evaluation, Mapping) else {}
    admission = (
        program.metadata.get("archive_admission")
        if isinstance(program.metadata, Mapping)
        and isinstance(program.metadata.get("archive_admission"), Mapping)
        else {}
    )
    missing_metrics = [
        name for name in declared_metrics if name not in program.metrics
    ]
    evaluator_is_valid = evaluation.get("is_valid") is True
    strict_valid = evaluator_is_valid and not missing_metrics
    return {
        "program_id": program.id,
        "seed_index": program.metadata.get("seed_index")
        if isinstance(program.metadata, Mapping)
        else None,
        "seed_source_kind": program.metadata.get("seed_source_kind")
        if isinstance(program.metadata, Mapping)
        else None,
        "seed_source_path": program.metadata.get("seed_source_path")
        if isinstance(program.metadata, Mapping)
        else None,
        "workspace_sha256": _workspace_sha256(program.workspace()),
        "evaluator_is_valid": evaluator_is_valid,
        "declared_metric_names": declared_metrics,
        "observed_metric_names": sorted(
            name for name in program.metrics if name != "is_valid"
        ),
        "missing_declared_metrics": missing_metrics,
        "strict_initial_program_valid": strict_valid,
        "archive_admitted": admission.get("admitted"),
        "archive_admission_reason": admission.get("reason"),
        "sampling_eligible": admission.get("sampling_eligible"),
    }


def validate_initial_program_validity_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.initial_program_validity_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "initial-program validity report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "policy",
        "seed_program_count",
        "record_count",
        "records",
        "declared_metric_names",
        "evaluator_valid_seed_count",
        "declared_metric_complete_seed_count",
        "strict_valid_seed_count",
        "strict_invalid_seed_count",
        "strict_policy_enabled",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"initial-program validity report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.initial_program_validity_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "unsupported initial-program validity report schema",
            }
        )
    if report.get("source") != "generation_zero_seed_evaluations":
        issues.append(
            {
                "code": "invalid_source",
                "message": "unsupported initial-program validity report source",
            }
        )
    policy = report.get("policy")
    if not isinstance(policy, Mapping):
        issues.append({"code": "invalid_policy", "message": "policy must be an object"})
        policy_value = None
    else:
        policy_value = policy.get("value")
        if policy.get("manifest_path") != "config.initial_program_validity_policy":
            issues.append(
                {
                    "code": "invalid_policy_manifest_path",
                    "message": "policy manifest path is unsupported",
                }
            )
        if policy_value not in {"permissive_baseline", "alphaevolve_strict"}:
            issues.append(
                {
                    "code": "invalid_policy_value",
                    "message": "initial-program validity policy is unsupported",
                }
            )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    _validate_report_count(report, "record_count", len(records), issues)
    declared_metric_names = report.get("declared_metric_names")
    if not isinstance(declared_metric_names, list) or not all(
        isinstance(name, str) for name in declared_metric_names
    ):
        issues.append(
            {
                "code": "invalid_declared_metric_names",
                "message": "declared_metric_names must be strings",
            }
        )
        declared_metric_names = []
    evaluator_valid_count = 0
    metric_complete_count = 0
    strict_valid_count = 0
    for record in records:
        if not isinstance(record, Mapping):
            issues.append({"code": "invalid_record", "message": "records must be objects"})
            continue
        if not _is_sha256_hex(record.get("workspace_sha256")):
            issues.append(
                {
                    "code": "invalid_workspace_hash",
                    "message": "workspace_sha256 must be sha256 hex",
                }
            )
        missing_metrics = record.get("missing_declared_metrics")
        if not isinstance(missing_metrics, list) or not all(
            isinstance(name, str) for name in missing_metrics
        ):
            issues.append(
                {
                    "code": "invalid_missing_declared_metrics",
                    "message": "missing_declared_metrics must be strings",
                }
            )
            missing_metrics = []
        if record.get("evaluator_is_valid") is True:
            evaluator_valid_count += 1
        if not missing_metrics:
            metric_complete_count += 1
        expected_strict = record.get("evaluator_is_valid") is True and not missing_metrics
        if record.get("strict_initial_program_valid") != expected_strict:
            issues.append(
                {
                    "code": "strict_validity_mismatch",
                    "message": "strict validity must match evaluator validity and metric presence",
                }
            )
        if expected_strict:
            strict_valid_count += 1
    _validate_report_count(report, "evaluator_valid_seed_count", evaluator_valid_count, issues)
    _validate_report_count(
        report,
        "declared_metric_complete_seed_count",
        metric_complete_count,
        issues,
    )
    _validate_report_count(report, "strict_valid_seed_count", strict_valid_count, issues)
    _validate_report_count(
        report,
        "strict_invalid_seed_count",
        len(records) - strict_valid_count,
        issues,
    )
    strict_policy_enabled = policy_value == "alphaevolve_strict"
    if report.get("strict_policy_enabled") != strict_policy_enabled:
        issues.append(
            {
                "code": "strict_policy_enabled_mismatch",
                "message": "strict_policy_enabled must match policy value",
            }
        )
    expected_claim_ready = strict_policy_enabled and len(records) > 0 and strict_valid_count == len(records)
    if report.get("claim_ready") != expected_claim_ready:
        issues.append(
            {
                "code": "claim_ready_mismatch",
                "message": "claim_ready must require strict policy and all seeds valid",
            }
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("alphaevolve_complete_initial_program_parity") != expected_claim_ready:
            issues.append(
                {
                    "code": "initial_program_parity_overclaim",
                    "message": "complete initial-program parity must match strict claim readiness",
                }
            )
        if readiness.get("strict_policy_enabled") != strict_policy_enabled:
            issues.append(
                {
                    "code": "readiness_policy_mismatch",
                    "message": "readiness strict_policy_enabled mismatch",
                }
            )
    return {
        "schema": "libreevolve.initial_program_validity_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _initial_pool_divergence_report(programs: list[Program]) -> dict:
    seeds = [
        program
        for program in programs
        if isinstance(program.metadata, Mapping)
        and program.metadata.get("candidate_type") == "seed"
    ]
    generated = [
        program
        for program in programs
        if isinstance(program.metadata, Mapping)
        and program.metadata.get("candidate_type") == "generated"
    ]
    seed_records = [_initial_pool_seed_record(program) for program in seeds]
    candidate_records = [
        _initial_pool_candidate_record(program, seeds) for program in generated
    ]
    exact_seed_match_count = sum(
        1 for record in candidate_records if record["exact_seed_workspace_match"]
    )
    syntactic_distances = [
        record["closest_seed"]["primary_text_distance"]
        for record in candidate_records
        if record.get("closest_seed")
        and isinstance(record["closest_seed"].get("primary_text_distance"), float)
    ]
    metric_distances = [
        record["closest_seed"]["numeric_metric_l1_distance"]
        for record in candidate_records
        if record.get("closest_seed")
        and isinstance(record["closest_seed"].get("numeric_metric_l1_distance"), float)
    ]
    report = {
        "schema": "libreevolve.initial_pool_divergence_report.v1",
        "source": "runtime_history_seed_and_generated_workspaces",
        "seed_program_count": len(seeds),
        "generated_candidate_count": len(generated),
        "seed_records": seed_records[:50],
        "seed_records_truncated": len(seed_records) > 50,
        "candidate_records": candidate_records[:50],
        "candidate_records_truncated": len(candidate_records) > 50,
        "exact_seed_workspace_match_count": exact_seed_match_count,
        "non_seed_workspace_count": len(candidate_records) - exact_seed_match_count,
        "max_primary_text_distance": max(syntactic_distances, default=0.0),
        "max_numeric_metric_l1_distance": max(metric_distances, default=0.0),
        "distance_policy": {
            "schema": "libreevolve.initial_pool_divergence_policy.v1",
            "workspace_identity": "canonical_workspace_sha256",
            "syntactic_distance": "bounded_primary_file_sequence_distance",
            "syntactic_distance_max_chars": 50000,
            "changed_component_summary": "text_file_set_added_removed_modified",
            "metric_distance": "numeric_metric_l1_over_shared_metric_names",
            "functional_distance_artifacts": False,
            "task_specific_behavior_distance": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "seed_pool_baseline_recorded": bool(seed_records),
            "syntactic_distance_reported": bool(candidate_records),
            "metric_distance_reported": bool(metric_distances),
            "functional_distance_reported": False,
            "task_specific_behavior_artifacts": False,
            "substantially_different_claim_ready": False,
            "remaining_gap": [
                "task_specific_functional_distance_artifacts",
                "behavior_or_output_distance_metrics",
                "thresholds_for_substantially_different_claims",
                "benchmark_level_discovery_distance_telemetry",
            ],
        },
    }
    report["validation"] = validate_initial_pool_divergence_report(report)
    return report


def _initial_pool_seed_record(program: Program) -> dict:
    workspace = program.workspace()
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    return {
        "program_id": program.id,
        "generation": program.generation,
        "seed_index": metadata.get("seed_index"),
        "workspace_sha256": _workspace_sha256(workspace),
        "file_count": len(workspace.files),
        "primary_file": workspace.primary_file,
        "primary_file_chars": len(workspace.code),
        "numeric_metrics": _initial_pool_numeric_metrics(program),
    }


def _initial_pool_candidate_record(program: Program, seeds: list[Program]) -> dict:
    workspace = program.workspace()
    workspace_hash = _workspace_sha256(workspace)
    seed_comparisons = [
        _initial_pool_seed_comparison(program, seed) for seed in seeds
    ]
    closest_seed = min(
        seed_comparisons,
        key=lambda record: (
            record["primary_text_distance"],
            record["numeric_metric_l1_distance"],
            record["seed_program_id"],
        ),
        default=None,
    )
    return {
        "program_id": program.id,
        "generation": program.generation,
        "parent_id": program.parent_id,
        "workspace_sha256": workspace_hash,
        "file_count": len(workspace.files),
        "primary_file": workspace.primary_file,
        "primary_file_chars": len(workspace.code),
        "exact_seed_workspace_match": any(
            comparison["exact_workspace_match"] for comparison in seed_comparisons
        ),
        "closest_seed": closest_seed,
        "seed_comparison_count": len(seed_comparisons),
    }


def _initial_pool_seed_comparison(program: Program, seed: Program) -> dict:
    program_workspace = program.workspace()
    seed_workspace = seed.workspace()
    program_hash = _workspace_sha256(program_workspace)
    seed_hash = _workspace_sha256(seed_workspace)
    changed = _initial_pool_changed_components(program_workspace, seed_workspace)
    metric_distance, metric_names = _initial_pool_metric_distance(program, seed)
    return {
        "seed_program_id": seed.id,
        "seed_index": seed.metadata.get("seed_index")
        if isinstance(seed.metadata, Mapping)
        else None,
        "seed_workspace_sha256": seed_hash,
        "exact_workspace_match": program_hash == seed_hash,
        "primary_text_distance": _initial_pool_primary_text_distance(
            program_workspace.code,
            seed_workspace.code,
        ),
        "changed_components": changed,
        "numeric_metric_l1_distance": metric_distance,
        "shared_metric_names": metric_names,
    }


def _initial_pool_primary_text_distance(left: str, right: str) -> float:
    max_chars = 50000
    ratio = difflib.SequenceMatcher(
        None,
        left[:max_chars],
        right[:max_chars],
        autojunk=False,
    ).ratio()
    return round(1.0 - ratio, 6)


def _initial_pool_changed_components(
    program_workspace: CandidateWorkspace,
    seed_workspace: CandidateWorkspace,
) -> dict:
    program_files = program_workspace.files
    seed_files = seed_workspace.files
    program_paths = set(program_files)
    seed_paths = set(seed_files)
    shared = sorted(program_paths & seed_paths)
    modified = [
        path for path in shared if program_files.get(path) != seed_files.get(path)
    ]
    added = sorted(program_paths - seed_paths)
    removed = sorted(seed_paths - program_paths)
    return {
        "added_files": added[:25],
        "removed_files": removed[:25],
        "modified_files": modified[:25],
        "added_file_count": len(added),
        "removed_file_count": len(removed),
        "modified_file_count": len(modified),
    }


def _initial_pool_numeric_metrics(program: Program) -> dict[str, float]:
    metrics: dict[str, float] = {}
    for name, value in program.metrics.items():
        if (
            isinstance(name, str)
            and name != "is_valid"
            and not isinstance(value, bool)
            and isinstance(value, (int, float))
            and math.isfinite(float(value))
        ):
            metrics[name] = float(value)
    return dict(sorted(metrics.items()))


def _initial_pool_metric_distance(program: Program, seed: Program) -> tuple[float, list[str]]:
    left = _initial_pool_numeric_metrics(program)
    right = _initial_pool_numeric_metrics(seed)
    names = sorted(set(left) & set(right))
    distance = sum(abs(left[name] - right[name]) for name in names)
    return round(distance, 6), names


def validate_initial_pool_divergence_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.initial_pool_divergence_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "initial-pool divergence report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "seed_program_count",
        "generated_candidate_count",
        "seed_records",
        "seed_records_truncated",
        "candidate_records",
        "candidate_records_truncated",
        "exact_seed_workspace_match_count",
        "non_seed_workspace_count",
        "max_primary_text_distance",
        "max_numeric_metric_l1_distance",
        "distance_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "initial-pool divergence report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.initial_pool_divergence_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "initial-pool divergence report schema is unsupported",
            }
        )
    if report.get("source") != "runtime_history_seed_and_generated_workspaces":
        issues.append(
            {
                "code": "invalid_source",
                "message": "initial-pool divergence report source is unsupported",
            }
        )
    for field in (
        "seed_program_count",
        "generated_candidate_count",
        "exact_seed_workspace_match_count",
        "non_seed_workspace_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    for field in ("max_primary_text_distance", "max_numeric_metric_l1_distance"):
        value = report.get(field)
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
            or float(value) < 0.0
        ):
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative finite number",
                }
            )
    seed_records = report.get("seed_records")
    if not isinstance(seed_records, list):
        issues.append(
            {"code": "invalid_seed_records", "message": "seed_records must be a list"}
        )
        seed_records = []
    for index, record in enumerate(seed_records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_seed_record",
                    "message": f"seed record {index} must be an object",
                }
            )
            continue
        if not _is_sha256_hex(record.get("workspace_sha256")):
            issues.append(
                {
                    "code": "invalid_seed_workspace_hash",
                    "message": f"seed record {index} workspace hash is invalid",
                }
            )
    candidate_records = report.get("candidate_records")
    if not isinstance(candidate_records, list):
        issues.append(
            {
                "code": "invalid_candidate_records",
                "message": "candidate_records must be a list",
            }
        )
        candidate_records = []
    exact_matches = 0
    for index, record in enumerate(candidate_records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_candidate_record",
                    "message": f"candidate record {index} must be an object",
                }
            )
            continue
        if not _is_sha256_hex(record.get("workspace_sha256")):
            issues.append(
                {
                    "code": "invalid_candidate_workspace_hash",
                    "message": f"candidate record {index} workspace hash is invalid",
                }
            )
        if record.get("exact_seed_workspace_match") is True:
            exact_matches += 1
        closest = record.get("closest_seed")
        if closest is not None:
            if not isinstance(closest, dict):
                issues.append(
                    {
                        "code": "invalid_closest_seed",
                        "message": f"candidate record {index} closest_seed must be an object",
                    }
                )
            else:
                if not _is_sha256_hex(closest.get("seed_workspace_sha256")):
                    issues.append(
                        {
                            "code": "invalid_closest_seed_hash",
                            "message": f"candidate record {index} seed hash is invalid",
                        }
                    )
                distance = closest.get("primary_text_distance")
                if (
                    isinstance(distance, bool)
                    or not isinstance(distance, (int, float))
                    or not 0.0 <= float(distance) <= 1.0
                ):
                    issues.append(
                        {
                            "code": "invalid_primary_text_distance",
                            "message": f"candidate record {index} primary distance is invalid",
                        }
                    )
    if report.get("candidate_records_truncated") is not True:
        _validate_report_count(
            report,
            "exact_seed_workspace_match_count",
            exact_matches,
            issues,
        )
        non_seed = len(candidate_records) - exact_matches
        _validate_report_count(report, "non_seed_workspace_count", non_seed, issues)
    policy = report.get("distance_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_distance_policy",
                "message": "distance_policy must be an object",
            }
        )
        policy = {}
    if policy.get("functional_distance_artifacts") is not False:
        issues.append(
            {
                "code": "functional_distance_overclaim",
                "message": "functional distance artifacts must remain false",
            }
        )
    if policy.get("task_specific_behavior_distance") is not False:
        issues.append(
            {
                "code": "behavior_distance_overclaim",
                "message": "task-specific behavior distance must remain false",
            }
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
        readiness = {}
    for field in (
        "functional_distance_reported",
        "task_specific_behavior_artifacts",
        "substantially_different_claim_ready",
    ):
        if readiness.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"claim_readiness.{field} must be false",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "claim_ready_overclaim",
                "message": "initial-pool divergence report must not claim full readiness",
            }
        )
    return {
        "schema": "libreevolve.initial_pool_divergence_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _problem_formulation_provenance_report(
    startup_manifest: Mapping[str, object],
) -> dict:
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    raw_metadata = (
        problem.get("formulation_metadata")
        if isinstance(problem.get("formulation_metadata"), Mapping)
        else {}
    )
    metadata = dict(raw_metadata)
    contributors = (
        metadata.get("contributors")
        if isinstance(metadata.get("contributors"), list)
        else []
    )
    roles = sorted(
        {
            contributor.get("role")
            for contributor in contributors
            if isinstance(contributor, Mapping)
            and isinstance(contributor.get("role"), str)
        }
    )
    review = (
        metadata.get("review")
        if isinstance(metadata.get("review"), Mapping)
        else {}
    )
    review_status = review.get("status")
    has_expert_roles = bool(
        {
            "problem_suggester",
            "formulation_advisor",
            "objective_reviewer",
            "evaluator_reviewer",
            "domain_owner",
        }
        & set(roles)
    )
    objective_rationale = isinstance(metadata.get("objective_rationale"), str)
    evaluator_rationale = isinstance(metadata.get("evaluator_rationale"), str)
    parameter_scope = (
        metadata.get("parameter_scope")
        if isinstance(metadata.get("parameter_scope"), list)
        else []
    )
    background_refs = (
        metadata.get("background_knowledge_refs")
        if isinstance(metadata.get("background_knowledge_refs"), list)
        else []
    )
    expert_review = review_status in {
        "expert_reviewed",
        "domain_owner_signed_off",
    }
    claim_ready = (
        metadata.get("status") == "provided"
        and has_expert_roles
        and objective_rationale
        and evaluator_rationale
        and bool(parameter_scope)
        and bool(background_refs)
        and expert_review
    )
    report = {
        "schema": "libreevolve.problem_formulation_provenance_report.v1",
        "source": "problem_formulation_metadata",
        "metadata_schema": metadata.get("schema"),
        "manifest_path": "problem.formulation_metadata",
        "metadata_status": metadata.get("status"),
        "problem_origin": metadata.get("problem_origin"),
        "contributor_count": len(contributors),
        "contributor_roles": roles,
        "formulation_notes_present": isinstance(
            metadata.get("formulation_notes"), str
        ),
        "objective_rationale_present": objective_rationale,
        "evaluator_rationale_present": evaluator_rationale,
        "parameter_scope_count": len(parameter_scope),
        "background_knowledge_ref_count": len(background_refs),
        "review_status": review_status,
        "reviewer_count": len(
            review.get("reviewer_labels", [])
            if isinstance(review.get("reviewer_labels"), list)
            else []
        ),
        "claim_ready": claim_ready,
        "claim_readiness": {
            "metadata_present": metadata.get("status") == "provided",
            "expert_contributor_roles_recorded": has_expert_roles,
            "formulation_notes_recorded": isinstance(
                metadata.get("formulation_notes"), str
            ),
            "objective_rationale_recorded": objective_rationale,
            "evaluator_rationale_recorded": evaluator_rationale,
            "parameter_scope_recorded": bool(parameter_scope),
            "background_knowledge_linkage_recorded": bool(background_refs),
            "expert_review_or_domain_owner_signoff": expert_review,
            "alphaevolve_expert_guided_formulation_parity": claim_ready,
            "remaining_gap": []
            if claim_ready
            else [
                gap
                for gap, ready in (
                    ("formulation_yaml_in_problem_fixture", metadata.get("status") == "provided"),
                    ("expert_contributor_roles", has_expert_roles),
                    ("formulation_notes", isinstance(metadata.get("formulation_notes"), str)),
                    ("objective_rationale", objective_rationale),
                    ("evaluator_rationale", evaluator_rationale),
                    ("parameter_scope_decisions", bool(parameter_scope)),
                    ("background_knowledge_refs", bool(background_refs)),
                    ("expert_review_or_domain_owner_signoff", expert_review),
                )
                if not ready
            ],
        },
        "metadata_contract": {
            "manifest_path": "problem.formulation_metadata",
            "optional_problem_file": "formulation.yaml",
            "allowed_problem_origins": [
                "unknown",
                "benchmark_fixture",
                "research_literature",
                "expert_suggested",
                "application_owner_requested",
                "manual_demo",
            ],
            "allowed_contributor_roles": [
                "problem_suggester",
                "formulation_advisor",
                "objective_reviewer",
                "evaluator_reviewer",
                "domain_owner",
                "implementation_author",
            ],
            "allowed_review_statuses": [
                "not_reviewed",
                "self_reviewed",
                "expert_reviewed",
                "domain_owner_signed_off",
            ],
        },
    }
    report["validation"] = validate_problem_formulation_provenance_report(report)
    return report


def validate_problem_formulation_provenance_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.problem_formulation_provenance_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "problem formulation provenance report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "metadata_schema",
        "manifest_path",
        "metadata_status",
        "problem_origin",
        "contributor_count",
        "contributor_roles",
        "formulation_notes_present",
        "objective_rationale_present",
        "evaluator_rationale_present",
        "parameter_scope_count",
        "background_knowledge_ref_count",
        "review_status",
        "reviewer_count",
        "claim_ready",
        "claim_readiness",
        "metadata_contract",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"problem formulation report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.problem_formulation_provenance_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "unsupported problem formulation report schema",
            }
        )
    if report.get("source") != "problem_formulation_metadata":
        issues.append(
            {
                "code": "invalid_source",
                "message": "unsupported problem formulation report source",
            }
        )
    if report.get("metadata_schema") != "libreevolve.problem_formulation_metadata.v1":
        issues.append(
            {
                "code": "invalid_metadata_schema",
                "message": "report must reference the problem formulation metadata schema",
            }
        )
    if report.get("manifest_path") != "problem.formulation_metadata":
        issues.append(
            {
                "code": "invalid_manifest_path",
                "message": "manifest path must point at problem.formulation_metadata",
            }
        )
    if report.get("metadata_status") not in {"provided", "not_provided"}:
        issues.append(
            {
                "code": "invalid_metadata_status",
                "message": "metadata_status is unsupported",
            }
        )
    if report.get("problem_origin") not in {
        "unknown",
        "benchmark_fixture",
        "research_literature",
        "expert_suggested",
        "application_owner_requested",
        "manual_demo",
    }:
        issues.append(
            {
                "code": "invalid_problem_origin",
                "message": "problem_origin is unsupported",
            }
        )
    roles = report.get("contributor_roles")
    allowed_roles = {
        "problem_suggester",
        "formulation_advisor",
        "objective_reviewer",
        "evaluator_reviewer",
        "domain_owner",
        "implementation_author",
    }
    if not isinstance(roles, list) or not all(role in allowed_roles for role in roles):
        issues.append(
            {
                "code": "invalid_contributor_roles",
                "message": "contributor_roles must be supported role labels",
            }
        )
        roles = []
    for field in (
        "contributor_count",
        "parameter_scope_count",
        "background_knowledge_ref_count",
        "reviewer_count",
    ):
        value = report.get(field)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    for field in (
        "formulation_notes_present",
        "objective_rationale_present",
        "evaluator_rationale_present",
    ):
        if not isinstance(report.get(field), bool):
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be boolean",
                }
            )
    review_status = report.get("review_status")
    if review_status not in {
        "not_reviewed",
        "self_reviewed",
        "expert_reviewed",
        "domain_owner_signed_off",
    }:
        issues.append(
            {
                "code": "invalid_review_status",
                "message": "review_status is unsupported",
            }
        )
    readiness = report.get("claim_readiness")
    expected_claim_ready = (
        report.get("metadata_status") == "provided"
        and bool(
            {
                "problem_suggester",
                "formulation_advisor",
                "objective_reviewer",
                "evaluator_reviewer",
                "domain_owner",
            }
            & set(roles)
        )
        and report.get("objective_rationale_present") is True
        and report.get("evaluator_rationale_present") is True
        and isinstance(report.get("parameter_scope_count"), int)
        and not isinstance(report.get("parameter_scope_count"), bool)
        and report.get("parameter_scope_count") > 0
        and isinstance(report.get("background_knowledge_ref_count"), int)
        and not isinstance(report.get("background_knowledge_ref_count"), bool)
        and report.get("background_knowledge_ref_count") > 0
        and review_status in {"expert_reviewed", "domain_owner_signed_off"}
    )
    if not isinstance(readiness, Mapping):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("alphaevolve_expert_guided_formulation_parity") != expected_claim_ready:
            issues.append(
                {
                    "code": "formulation_parity_mismatch",
                    "message": "AlphaEvolve formulation parity must match report readiness",
                }
            )
        if readiness.get("expert_review_or_domain_owner_signoff") != (
            review_status in {"expert_reviewed", "domain_owner_signed_off"}
        ):
            issues.append(
                {
                    "code": "review_readiness_mismatch",
                    "message": "review readiness must match review_status",
                }
            )
    if report.get("claim_ready") != expected_claim_ready:
        issues.append(
            {
                "code": "claim_ready_mismatch",
                "message": "claim_ready must match formulation provenance readiness",
            }
        )
    contract = report.get("metadata_contract")
    if not isinstance(contract, Mapping):
        issues.append(
            {
                "code": "invalid_metadata_contract",
                "message": "metadata_contract must be an object",
            }
        )
    elif contract.get("optional_problem_file") != "formulation.yaml":
        issues.append(
            {
                "code": "invalid_contract_file",
                "message": "metadata contract must name formulation.yaml",
            }
        )
    return {
        "schema": "libreevolve.problem_formulation_provenance_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _collaborator_feedback_provenance_report(
    startup_manifest: Mapping[str, object],
) -> dict:
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    metadata = (
        problem.get("collaborator_feedback_metadata")
        if isinstance(problem.get("collaborator_feedback_metadata"), Mapping)
        else {}
    )
    cohorts = (
        metadata.get("cohorts")
        if isinstance(metadata.get("cohorts"), list)
        else []
    )
    events = (
        metadata.get("feedback_events")
        if isinstance(metadata.get("feedback_events"), list)
        else []
    )
    privacy = (
        metadata.get("privacy_policy")
        if isinstance(metadata.get("privacy_policy"), Mapping)
        else {}
    )
    review = (
        metadata.get("review")
        if isinstance(metadata.get("review"), Mapping)
        else {}
    )
    cohort_roles = sorted(
        {
            cohort.get("role")
            for cohort in cohorts
            if isinstance(cohort, Mapping) and isinstance(cohort.get("role"), str)
        }
    )
    use_case_areas = sorted(
        {
            cohort.get("use_case_area")
            for cohort in cohorts
            if isinstance(cohort, Mapping)
            and isinstance(cohort.get("use_case_area"), str)
        }
    )
    claim_links = sorted(
        {
            link
            for event in events
            if isinstance(event, Mapping)
            for link in (
                event.get("claim_links")
                if isinstance(event.get("claim_links"), list)
                else []
            )
            if isinstance(link, str)
        }
    )
    event_status_counts: dict[str, int] = {}
    affected_workflow_areas: set[str] = set()
    events_with_change_links = 0
    events_with_validation = 0
    for event in events:
        if not isinstance(event, Mapping):
            continue
        status = event.get("status")
        if isinstance(status, str):
            event_status_counts[status] = event_status_counts.get(status, 0) + 1
        workflows = event.get("affected_workflow_areas")
        if isinstance(workflows, list):
            affected_workflow_areas.update(
                workflow for workflow in workflows if isinstance(workflow, str)
            )
        if isinstance(event.get("change_artifact_links"), list) and event.get(
            "change_artifact_links"
        ):
            events_with_change_links += 1
        if isinstance(event.get("validation_outcomes"), list) and event.get(
            "validation_outcomes"
        ):
            events_with_validation += 1
    metadata_present = metadata.get("status") == "provided"
    diverse_use_cases = len(use_case_areas) >= 2 and len(cohorts) >= 2
    event_ids_recorded = all(
        isinstance(event, Mapping)
        and isinstance(event.get("feedback_id"), str)
        and event.get("feedback_id")
        for event in events
    ) and bool(events)
    workflows_recorded = all(
        isinstance(event, Mapping)
        and isinstance(event.get("affected_workflow_areas"), list)
        and bool(event.get("affected_workflow_areas"))
        for event in events
    ) and bool(events)
    change_links_recorded = events_with_change_links == len(events) and bool(events)
    validation_recorded = events_with_validation == len(events) and bool(events)
    privacy_recorded = (
        isinstance(privacy.get("retention"), str)
        and isinstance(privacy.get("redaction"), str)
    )
    reviewed = review.get("status") in {
        "collaborator_reviewed",
        "owner_signed_off",
    }
    robustness_or_versatility = bool({"robustness", "versatility"} & set(claim_links))
    claim_ready = (
        metadata_present
        and diverse_use_cases
        and event_ids_recorded
        and workflows_recorded
        and change_links_recorded
        and validation_recorded
        and privacy_recorded
        and reviewed
        and robustness_or_versatility
    )
    report = {
        "schema": "libreevolve.collaborator_feedback_provenance_report.v1",
        "source": "collaborator_feedback_metadata",
        "metadata_schema": metadata.get("schema"),
        "manifest_path": "problem.collaborator_feedback_metadata",
        "metadata_status": metadata.get("status"),
        "cohort_count": len(cohorts),
        "cohort_roles": cohort_roles,
        "use_case_area_count": len(use_case_areas),
        "use_case_areas": use_case_areas[:50],
        "feedback_event_count": len(events),
        "event_status_counts": event_status_counts,
        "affected_workflow_area_count": len(affected_workflow_areas),
        "events_with_change_artifact_links": events_with_change_links,
        "events_with_validation_outcomes": events_with_validation,
        "claim_links": claim_links,
        "privacy_policy": {
            "retention": privacy.get("retention"),
            "redaction": privacy.get("redaction"),
        },
        "review_status": review.get("status"),
        "reviewer_count": len(
            review.get("reviewer_labels", [])
            if isinstance(review.get("reviewer_labels"), list)
            else []
        ),
        "claim_ready": claim_ready,
        "claim_readiness": {
            "metadata_present": metadata_present,
            "diverse_use_case_cohorts": diverse_use_cases,
            "feedback_event_ids_recorded": event_ids_recorded,
            "affected_workflow_areas_recorded": workflows_recorded,
            "change_artifact_links_recorded": change_links_recorded,
            "validation_outcomes_recorded": validation_recorded,
            "privacy_redaction_policy_recorded": privacy_recorded,
            "collaborator_review_or_owner_signoff": reviewed,
            "robustness_or_versatility_claim_linked": robustness_or_versatility,
            "alphaevolve_collaborator_feedback_parity": claim_ready,
            "remaining_gap": []
            if claim_ready
            else [
                gap
                for gap, ready in (
                    ("collaborator_feedback_yaml_in_problem_fixture", metadata_present),
                    ("diverse_use_case_cohorts", diverse_use_cases),
                    ("feedback_event_ids", event_ids_recorded),
                    ("affected_workflow_areas", workflows_recorded),
                    ("change_artifact_links", change_links_recorded),
                    ("validation_outcomes", validation_recorded),
                    ("privacy_redaction_policy", privacy_recorded),
                    ("collaborator_review_or_owner_signoff", reviewed),
                    (
                        "robustness_or_versatility_claim_links",
                        robustness_or_versatility,
                    ),
                )
                if not ready
            ],
        },
        "metadata_contract": {
            "manifest_path": "problem.collaborator_feedback_metadata",
            "optional_problem_file": "collaborator_feedback.yaml",
            "allowed_cohort_roles": [
                "early_user",
                "collaborator",
                "domain_partner",
                "application_owner",
                "internal_reviewer",
            ],
            "allowed_event_statuses": [
                "collected",
                "triaged",
                "applied",
                "validated",
            ],
            "allowed_claim_links": [
                "robustness",
                "versatility",
                "usability",
                "workflow_coverage",
            ],
            "allowed_review_statuses": [
                "not_reviewed",
                "self_reviewed",
                "collaborator_reviewed",
                "owner_signed_off",
            ],
        },
    }
    report["validation"] = validate_collaborator_feedback_provenance_report(report)
    return report


def validate_collaborator_feedback_provenance_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.collaborator_feedback_provenance_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "collaborator feedback provenance report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "metadata_schema",
        "manifest_path",
        "metadata_status",
        "cohort_count",
        "cohort_roles",
        "use_case_area_count",
        "use_case_areas",
        "feedback_event_count",
        "event_status_counts",
        "affected_workflow_area_count",
        "events_with_change_artifact_links",
        "events_with_validation_outcomes",
        "claim_links",
        "privacy_policy",
        "review_status",
        "reviewer_count",
        "claim_ready",
        "claim_readiness",
        "metadata_contract",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"collaborator feedback report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.collaborator_feedback_provenance_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "unsupported collaborator feedback report schema",
            }
        )
    if report.get("source") != "collaborator_feedback_metadata":
        issues.append(
            {
                "code": "invalid_source",
                "message": "unsupported collaborator feedback report source",
            }
        )
    if report.get("metadata_schema") != "libreevolve.collaborator_feedback_metadata.v1":
        issues.append(
            {
                "code": "invalid_metadata_schema",
                "message": "report must reference collaborator feedback metadata schema",
            }
        )
    if report.get("manifest_path") != "problem.collaborator_feedback_metadata":
        issues.append(
            {
                "code": "invalid_manifest_path",
                "message": "manifest path must point at collaborator feedback metadata",
            }
        )
    if report.get("metadata_status") not in {"provided", "not_provided"}:
        issues.append(
            {
                "code": "invalid_metadata_status",
                "message": "metadata_status is unsupported",
            }
        )
    allowed_roles = {
        "early_user",
        "collaborator",
        "domain_partner",
        "application_owner",
        "internal_reviewer",
    }
    roles = report.get("cohort_roles")
    if not isinstance(roles, list) or not all(role in allowed_roles for role in roles):
        issues.append(
            {
                "code": "invalid_cohort_roles",
                "message": "cohort_roles must use supported role labels",
            }
        )
        roles = []
    allowed_claim_links = {
        "robustness",
        "versatility",
        "usability",
        "workflow_coverage",
    }
    claim_links = report.get("claim_links")
    if not isinstance(claim_links, list) or not all(
        link in allowed_claim_links for link in claim_links
    ):
        issues.append(
            {
                "code": "invalid_claim_links",
                "message": "claim_links must use supported claim labels",
            }
        )
        claim_links = []
    for field in (
        "cohort_count",
        "use_case_area_count",
        "feedback_event_count",
        "affected_workflow_area_count",
        "events_with_change_artifact_links",
        "events_with_validation_outcomes",
        "reviewer_count",
    ):
        value = report.get(field)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    use_case_areas = report.get("use_case_areas")
    if not isinstance(use_case_areas, list) or not all(
        isinstance(item, str) and item for item in use_case_areas
    ):
        issues.append(
            {
                "code": "invalid_use_case_areas",
                "message": "use_case_areas must be text labels",
            }
        )
    status_counts = report.get("event_status_counts")
    if not isinstance(status_counts, Mapping):
        issues.append(
            {
                "code": "invalid_event_status_counts",
                "message": "event_status_counts must be an object",
            }
        )
    else:
        allowed_statuses = {"collected", "triaged", "applied", "validated"}
        for status, count in status_counts.items():
            if status not in allowed_statuses:
                issues.append(
                    {
                        "code": "invalid_event_status",
                        "message": "event status is unsupported",
                    }
                )
            if not isinstance(count, int) or isinstance(count, bool) or count < 0:
                issues.append(
                    {
                        "code": "invalid_event_status_count",
                        "message": "event status counts must be non-negative integers",
                    }
                )
    privacy = report.get("privacy_policy")
    privacy_recorded = False
    if not isinstance(privacy, Mapping):
        issues.append(
            {
                "code": "invalid_privacy_policy",
                "message": "privacy_policy must be an object",
            }
        )
    else:
        privacy_recorded = isinstance(privacy.get("retention"), str) and isinstance(
            privacy.get("redaction"), str
        )
    review_status = report.get("review_status")
    if review_status not in {
        "not_reviewed",
        "self_reviewed",
        "collaborator_reviewed",
        "owner_signed_off",
    }:
        issues.append(
            {
                "code": "invalid_review_status",
                "message": "review_status is unsupported",
            }
        )
    cohort_count = report.get("cohort_count")
    use_case_count = report.get("use_case_area_count")
    event_count = report.get("feedback_event_count")
    change_count = report.get("events_with_change_artifact_links")
    validation_count = report.get("events_with_validation_outcomes")
    expected_claim_ready = (
        report.get("metadata_status") == "provided"
        and isinstance(cohort_count, int)
        and not isinstance(cohort_count, bool)
        and cohort_count >= 2
        and isinstance(use_case_count, int)
        and not isinstance(use_case_count, bool)
        and use_case_count >= 2
        and isinstance(event_count, int)
        and not isinstance(event_count, bool)
        and event_count > 0
        and isinstance(report.get("affected_workflow_area_count"), int)
        and not isinstance(report.get("affected_workflow_area_count"), bool)
        and report.get("affected_workflow_area_count") > 0
        and isinstance(change_count, int)
        and not isinstance(change_count, bool)
        and change_count == event_count
        and isinstance(validation_count, int)
        and not isinstance(validation_count, bool)
        and validation_count == event_count
        and privacy_recorded
        and review_status in {"collaborator_reviewed", "owner_signed_off"}
        and bool({"robustness", "versatility"} & set(claim_links))
    )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("alphaevolve_collaborator_feedback_parity") != expected_claim_ready:
            issues.append(
                {
                    "code": "collaborator_feedback_parity_mismatch",
                    "message": "collaborator feedback parity must match report readiness",
                }
            )
        if readiness.get("collaborator_review_or_owner_signoff") != (
            review_status in {"collaborator_reviewed", "owner_signed_off"}
        ):
            issues.append(
                {
                    "code": "review_readiness_mismatch",
                    "message": "review readiness must match review_status",
                }
            )
    if report.get("claim_ready") != expected_claim_ready:
        issues.append(
            {
                "code": "claim_ready_mismatch",
                "message": "claim_ready must match collaborator feedback readiness",
            }
        )
    contract = report.get("metadata_contract")
    if not isinstance(contract, Mapping):
        issues.append(
            {
                "code": "invalid_metadata_contract",
                "message": "metadata_contract must be an object",
            }
        )
    elif contract.get("optional_problem_file") != "collaborator_feedback.yaml":
        issues.append(
            {
                "code": "invalid_contract_file",
                "message": "metadata contract must name collaborator_feedback.yaml",
            }
        )
    return {
        "schema": "libreevolve.collaborator_feedback_provenance_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _acknowledgement_role_provenance_report(
    startup_manifest: Mapping[str, object],
) -> dict:
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    metadata = (
        problem.get("acknowledgement_metadata")
        if isinstance(problem.get("acknowledgement_metadata"), Mapping)
        else {}
    )
    records = (
        metadata.get("records")
        if isinstance(metadata.get("records"), list)
        else []
    )
    privacy = (
        metadata.get("privacy_policy")
        if isinstance(metadata.get("privacy_policy"), Mapping)
        else {}
    )
    review = (
        metadata.get("review")
        if isinstance(metadata.get("review"), Mapping)
        else {}
    )
    role_counts: dict[str, int] = {}
    scope_counts: dict[str, int] = {}
    source_pages: set[int] = set()
    records_with_source = 0
    for record in records:
        if not isinstance(record, Mapping):
            continue
        role = record.get("role_category")
        if isinstance(role, str):
            role_counts[role] = role_counts.get(role, 0) + 1
        scope = record.get("scope_type")
        if isinstance(scope, str):
            scope_counts[scope] = scope_counts.get(scope, 0) + 1
        page = record.get("source_page")
        if isinstance(page, int) and not isinstance(page, bool):
            source_pages.add(page)
        if isinstance(record.get("source_section"), str) and isinstance(page, int):
            records_with_source += 1
    required_roles = {
        "white_paper_review",
        "early_exploration",
        "support_advice",
        "practical_application_management_advice",
        "application_review",
        "application_specific_advice",
    }
    role_coverage_complete = required_roles <= set(role_counts)
    metadata_present = metadata.get("status") == "provided"
    privacy_recorded = (
        isinstance(privacy.get("retention"), str)
        and isinstance(privacy.get("redaction"), str)
    )
    reviewed = review.get("status") in {
        "paper_process_reviewed",
        "owner_signed_off",
    }
    source_linked = bool(records) and records_with_source == len(records)
    claim_ready = (
        metadata_present
        and role_coverage_complete
        and source_linked
        and privacy_recorded
        and reviewed
    )
    report = {
        "schema": "libreevolve.acknowledgement_role_provenance_report.v1",
        "source": "acknowledgement_metadata",
        "metadata_schema": metadata.get("schema"),
        "manifest_path": "problem.acknowledgement_metadata",
        "metadata_status": metadata.get("status"),
        "record_count": len(records),
        "role_category_counts": role_counts,
        "scope_type_counts": scope_counts,
        "source_page_count": len(source_pages),
        "source_pages": sorted(source_pages),
        "records_with_source_locator": records_with_source,
        "privacy_policy": {
            "retention": privacy.get("retention"),
            "redaction": privacy.get("redaction"),
        },
        "review_status": review.get("status"),
        "reviewer_count": len(
            review.get("reviewer_labels", [])
            if isinstance(review.get("reviewer_labels"), list)
            else []
        ),
        "claim_ready": claim_ready,
        "claim_readiness": {
            "metadata_present": metadata_present,
            "all_acknowledgement_role_categories_recorded": role_coverage_complete,
            "source_page_and_section_recorded": source_linked,
            "privacy_redaction_policy_recorded": privacy_recorded,
            "paper_process_review_or_owner_signoff": reviewed,
            "technical_validation_boundary_separated": True,
            "publication_author_boundary_separated": True,
            "alphaevolve_acknowledgement_role_parity": claim_ready,
            "remaining_gap": []
            if claim_ready
            else [
                gap
                for gap, ready in (
                    ("acknowledgements_yaml_in_problem_fixture", metadata_present),
                    ("all_acknowledgement_role_categories", role_coverage_complete),
                    ("source_page_and_section_locators", source_linked),
                    ("privacy_redaction_policy", privacy_recorded),
                    ("paper_process_review_or_owner_signoff", reviewed),
                )
                if not ready
            ],
        },
        "metadata_contract": {
            "manifest_path": "problem.acknowledgement_metadata",
            "optional_problem_file": "acknowledgements.yaml",
            "allowed_role_categories": [
                "white_paper_review",
                "early_exploration",
                "support_advice",
                "practical_application_management_advice",
                "application_review",
                "application_specific_advice",
            ],
            "allowed_scope_types": [
                "white_paper",
                "general_system",
                "practical_application",
                "application_specific_work",
            ],
            "allowed_review_statuses": [
                "not_reviewed",
                "self_reviewed",
                "paper_process_reviewed",
                "owner_signed_off",
            ],
            "boundary": (
                "paper_process_acknowledgements_not_technical_validation_or_"
                "publication_author_metadata"
            ),
        },
    }
    report["validation"] = validate_acknowledgement_role_provenance_report(report)
    return report


