def _process_node(
    node_id: str,
    label: str,
    local_component: str,
    status: str,
    evidence_paths: list[str],
) -> dict:
    return {
        "node_id": node_id,
        "label": label,
        "local_component": local_component,
        "status": status,
        "evidence_paths": evidence_paths,
    }


def _process_edge(from_node: str, to_node: str, relationship: str) -> dict:
    return {
        "from": from_node,
        "to": to_node,
        "relationship": relationship,
    }


def _process_step(
    step_id: str,
    displayed_call: str,
    local_component: str,
    status: str,
    evidence_paths: list[str],
) -> dict:
    return {
        "step_id": step_id,
        "displayed_call": displayed_call,
        "local_component": local_component,
        "status": status,
        "evidence_paths": evidence_paths,
    }


def _process_rendered_artifact_placeholder(figure_id: str) -> dict:
    return {
        "figure_id": figure_id,
        "status": "not_generated",
        "path": None,
        "sha256": None,
        "reason": "source figure is mapped as manifest metadata only in this slice",
    }


def _process_exhibit_artifact_evidence(run_dir: Path) -> list[dict]:
    artifact_roles = {
        "manifest.json": ["run_manifest", "task_specification", "runtime_history"],
        "task_specification.json": ["standalone_task_specification"],
        "history.jsonl": ["candidate_history", "database_add", "evaluation_results"],
        "evaluator_results.jsonl": ["evaluator_result_rows"],
        "failure_history.jsonl": ["rejected_candidates", "diff_or_evaluation_failures"],
        "archive_events.jsonl": ["program_database_archive_events"],
        "controller_budget_events.jsonl": ["controller_budget_events"],
        "llm_calls.jsonl": ["llm_generation_calls"],
        "prompt_history.jsonl": ["prompt_sampler_outputs"],
        "evaluator_artifacts": ["evaluator_copy_out"],
        "best.py": ["improved_solution_export"],
        "best_workspace": ["improved_solution_workspace_export"],
    }
    resolved_run_dir = _resolve_path_for_scope(run_dir)
    records = []
    for path_name, roles in artifact_roles.items():
        if path_name == "manifest.json":
            pointer = {
                "path": path_name,
                "present": (run_dir / path_name).exists(),
                "kind": "file",
                "hash_scope": "final_manifest_self_reference_deferred",
            }
        else:
            pointer = _runtime_artifact_pointer(
                run_dir / path_name,
                path_name,
                resolved_run_dir,
            )
        record = {
            "path": path_name,
            "roles": roles,
            "present": pointer.get("present") is True,
            "kind": pointer.get("kind"),
        }
        if _is_sha256_hex(pointer.get("sha256")):
            record["sha256"] = pointer["sha256"]
            record["hash_scope"] = pointer.get("hash_scope")
        elif pointer.get("hash_scope") == "final_manifest_self_reference_deferred":
            record["hash_scope"] = pointer["hash_scope"]
        if isinstance(pointer.get("bytes"), int):
            record["bytes"] = pointer["bytes"]
        if _is_sha256_hex(pointer.get("tree_hash")):
            record["tree_hash"] = pointer["tree_hash"]
            record["hash_scope"] = pointer.get("tree_hash_scope")
        records.append(record)
    return records


def validate_alphaevolve_process_exhibit_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.alphaevolve_process_exhibit_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "process exhibit report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "runtime_scope",
        "controller_model",
        "figures",
        "figure_count",
        "node_count",
        "edge_count",
        "pseudocode_step_count",
        "artifact_evidence",
        "artifact_evidence_paths",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"process exhibit report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.alphaevolve_process_exhibit_report.v1":
        issues.append({"code": "invalid_schema", "message": "unsupported process exhibit report schema"})
    if report.get("source") != "runtime_history_static_figure_mapping":
        issues.append({"code": "invalid_source", "message": "unsupported process exhibit report source"})
    if report.get("runtime_scope") != "single_completed_run":
        issues.append({"code": "invalid_runtime_scope", "message": "runtime_scope must be single_completed_run"})
    if report.get("controller_model") != "single_process_serial_loop":
        issues.append({"code": "invalid_controller_model", "message": "controller model must match current runtime boundary"})

    figures = report.get("figures")
    if not isinstance(figures, list):
        issues.append({"code": "invalid_figures", "message": "figures must be a list"})
        figures = []
    figure_ids = {
        figure.get("figure_id")
        for figure in figures
        if isinstance(figure, Mapping)
    }
    expected_ids = {"alphaevolve_figure_1", "alphaevolve_figure_2"}
    if figure_ids != expected_ids:
        issues.append({"code": "invalid_figure_ids", "message": "figure ids must cover AlphaEvolve figures 1 and 2"})
    nodes_seen: set[str] = set()
    edge_count = 0
    step_count = 0
    for figure_index, figure in enumerate(figures):
        if not isinstance(figure, Mapping):
            issues.append({"code": "invalid_figure", "message": f"figure {figure_index} must be an object"})
            continue
        if not isinstance(figure.get("local_pdf_page"), int) or isinstance(figure.get("local_pdf_page"), bool):
            issues.append({"code": "invalid_source_page", "message": f"figure {figure_index} local_pdf_page must be an int"})
        nodes = figure.get("nodes")
        if not isinstance(nodes, list) or not nodes:
            issues.append({"code": "invalid_nodes", "message": f"figure {figure_index} must include nodes"})
            nodes = []
        for node in nodes:
            if not isinstance(node, Mapping):
                issues.append({"code": "invalid_node", "message": "node records must be objects"})
                continue
            node_id = node.get("node_id")
            if not isinstance(node_id, str) or not node_id:
                issues.append({"code": "invalid_node_id", "message": "node_id must be non-empty text"})
                continue
            nodes_seen.add(node_id)
            _validate_process_status(node.get("status"), issues, "node")
            _validate_process_evidence_paths(node.get("evidence_paths"), issues, "node")
        edges = figure.get("edges")
        if not isinstance(edges, list) or not edges:
            issues.append({"code": "invalid_edges", "message": f"figure {figure_index} must include edges"})
            edges = []
        edge_count += len(edges)
        for edge in edges:
            if not isinstance(edge, Mapping):
                issues.append({"code": "invalid_edge", "message": "edge records must be objects"})
                continue
            if not isinstance(edge.get("from"), str) or not isinstance(edge.get("to"), str):
                issues.append({"code": "invalid_edge_endpoint", "message": "edge endpoints must be node ids"})
            if not isinstance(edge.get("relationship"), str) or not edge.get("relationship"):
                issues.append({"code": "invalid_edge_relationship", "message": "edge relationship must be non-empty text"})
        steps = figure.get("pseudocode_steps", [])
        if steps:
            if not isinstance(steps, list):
                issues.append({"code": "invalid_steps", "message": "pseudocode_steps must be a list"})
                steps = []
            step_count += len(steps)
            for step in steps:
                if not isinstance(step, Mapping):
                    issues.append({"code": "invalid_step", "message": "pseudocode step records must be objects"})
                    continue
                if not isinstance(step.get("step_id"), str) or not step.get("step_id"):
                    issues.append({"code": "invalid_step_id", "message": "step_id must be non-empty text"})
                if not isinstance(step.get("displayed_call"), str) or not step.get("displayed_call"):
                    issues.append({"code": "invalid_displayed_call", "message": "displayed_call must be non-empty text"})
                _validate_process_status(step.get("status"), issues, "step")
                _validate_process_evidence_paths(step.get("evidence_paths"), issues, "step")
        rendered = figure.get("rendered_artifact")
        if not isinstance(rendered, Mapping):
            issues.append({"code": "invalid_rendered_artifact", "message": "rendered_artifact must be an object"})
        elif rendered.get("status") != "not_generated":
            issues.append({"code": "rendered_artifact_overclaim", "message": "rendered figure artifacts are not generated by this report"})

    if isinstance(report.get("figure_count"), int) and not isinstance(report.get("figure_count"), bool):
        if report["figure_count"] != len(figures):
            issues.append({"code": "figure_count_mismatch", "message": "figure_count must match figures length"})
    else:
        issues.append({"code": "invalid_figure_count", "message": "figure_count must be an integer"})
    if isinstance(report.get("node_count"), int) and not isinstance(report.get("node_count"), bool):
        if report["node_count"] != len(nodes_seen):
            issues.append({"code": "node_count_mismatch", "message": "node_count must match unique node ids"})
    else:
        issues.append({"code": "invalid_node_count", "message": "node_count must be an integer"})
    if isinstance(report.get("edge_count"), int) and not isinstance(report.get("edge_count"), bool):
        if report["edge_count"] != edge_count:
            issues.append({"code": "edge_count_mismatch", "message": "edge_count must match edge records"})
    else:
        issues.append({"code": "invalid_edge_count", "message": "edge_count must be an integer"})
    if isinstance(report.get("pseudocode_step_count"), int) and not isinstance(report.get("pseudocode_step_count"), bool):
        if report["pseudocode_step_count"] != step_count:
            issues.append({"code": "step_count_mismatch", "message": "pseudocode_step_count must match step records"})
    else:
        issues.append({"code": "invalid_step_count", "message": "pseudocode_step_count must be an integer"})

    artifacts = report.get("artifact_evidence")
    artifact_paths = report.get("artifact_evidence_paths")
    if not isinstance(artifacts, list):
        issues.append({"code": "invalid_artifact_evidence", "message": "artifact_evidence must be a list"})
        artifacts = []
    if not isinstance(artifact_paths, list) or not all(isinstance(path, str) for path in artifact_paths):
        issues.append({"code": "invalid_artifact_paths", "message": "artifact_evidence_paths must be text paths"})
        artifact_paths = []
    if [artifact.get("path") for artifact in artifacts if isinstance(artifact, Mapping)] != artifact_paths:
        issues.append({"code": "artifact_path_mismatch", "message": "artifact_evidence_paths must match artifact records"})
    for artifact in artifacts:
        if not isinstance(artifact, Mapping):
            issues.append({"code": "invalid_artifact", "message": "artifact records must be objects"})
            continue
        if not isinstance(artifact.get("path"), str) or not artifact.get("path"):
            issues.append({"code": "invalid_artifact_path", "message": "artifact path must be non-empty text"})
        roles = artifact.get("roles")
        if not isinstance(roles, list) or not all(isinstance(role, str) and role for role in roles):
            issues.append({"code": "invalid_artifact_roles", "message": "artifact roles must be non-empty text"})
        if not isinstance(artifact.get("present"), bool):
            issues.append({"code": "invalid_artifact_present", "message": "artifact present must be boolean"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    else:
        if readiness.get("rendered_diagram_artifacts") is not False:
            issues.append({"code": "rendered_diagram_overclaim", "message": "rendered diagram artifacts must remain false"})
        if readiness.get("full_alphaevolve_process_parity") is not False:
            issues.append({"code": "process_parity_overclaim", "message": "full AlphaEvolve process parity must remain false"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "process exhibit report must not claim full process-diagram parity"})
    return {
        "schema": "libreevolve.alphaevolve_process_exhibit_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _validate_process_status(value: object, issues: list[dict], owner: str) -> None:
    if value not in {"implemented_sync", "partial", "unsupported", "not_applicable"}:
        issues.append({"code": "invalid_process_status", "message": f"{owner} status is unsupported"})


def _validate_process_evidence_paths(value: object, issues: list[dict], owner: str) -> None:
    if not isinstance(value, list) or not all(isinstance(path, str) and path for path in value):
        issues.append({"code": "invalid_process_evidence_paths", "message": f"{owner} evidence_paths must be non-empty text"})


def _evaluation_cascade_report(
    programs: list[Program],
    startup_manifest: Mapping[str, object] | None = None,
) -> dict:
    stages: dict[str, dict] = {}
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest, Mapping)
        and isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    evaluator_sources = (
        problem.get("evaluator_sources")
        if isinstance(problem.get("evaluator_sources"), list)
        else []
    )
    source_by_stage = _evaluator_source_by_stage(evaluator_sources)
    candidate_stage_records: list[dict] = []
    candidate_stage_records_limit = 200
    configured_candidate_count = 0
    main_test_exposure_count = 0
    stop_reasons: dict[str, int] = {}
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        metadata = evaluation.get("metadata") if isinstance(evaluation.get("metadata"), dict) else {}
        configured = metadata.get("configured_stage_results")
        if not isinstance(configured, list):
            continue
        configured_candidate_count += 1
        if configured and isinstance(configured[-1], dict) and configured[-1].get("passed") is True:
            main_test_exposure_count += 1
        stopped_at = metadata.get("stopped_at")
        for stage_index, raw_stage in enumerate(configured):
            if not isinstance(raw_stage, dict):
                continue
            name = str(raw_stage.get("name", f"stage_{stage_index}"))
            raw_stage_index = raw_stage.get("stage_index", stage_index)
            source = (
                source_by_stage.get((raw_stage_index, name), {})
                if isinstance(raw_stage_index, int)
                and not isinstance(raw_stage_index, bool)
                else {}
            )
            stage = stages.setdefault(
                f"{raw_stage_index}:{name}",
                {
                    "name": name,
                    "stage_id": f"{raw_stage_index}:{name}",
                    "stage_index": raw_stage_index,
                    "source": _evaluator_oracle_source_ref(source),
                    "difficulty_or_scale": {"status": "not_declared"},
                    "entered": 0,
                    "passed": 0,
                    "failed": 0,
                    "threshold_failed": 0,
                    "local_invalid": 0,
                    "sample_count": 0,
                    "retry_attempts": 0,
                    "subprocess_attempts": 0,
                    "timeout_count": 0,
                    "elapsed_sec": 0.0,
                    "candidate_ids": [],
                    "failure_reasons": {},
                    "thresholds": {
                        "fitness": raw_stage.get("threshold"),
                        "metric_thresholds": raw_stage.get("metric_thresholds", []),
                        "artifact_output_checks": raw_stage.get("artifact_output_checks", []),
                    },
                    "hypothesis_test": {
                        "configured": False,
                        "test_count": 0,
                        "passed": 0,
                        "failed": 0,
                        "confidence_interval_count": 0,
                        "p_value_count": 0,
                        "sequential_stopping_configured": False,
                        "sequential_stop_count": 0,
                        "error_budget_configured": False,
                        "error_budget_passed": 0,
                        "error_budget_failed": 0,
                        "false_promotion_budget_count": 0,
                        "false_rejection_budget_count": 0,
                    },
                },
            )
            stage["entered"] += 1
            stage["candidate_ids"].append(program.id)
            if raw_stage.get("passed") is True:
                stage["passed"] += 1
            else:
                stage["failed"] += 1
                reason = str(
                    raw_stage.get("stop_reason")
                    or raw_stage.get("error")
                    or "stage_threshold_not_met"
                )
                stage["failure_reasons"][reason] = stage["failure_reasons"].get(reason, 0) + 1
                stop_reasons[reason] = stop_reasons.get(reason, 0) + 1
            if raw_stage.get("threshold_passed") is False:
                stage["threshold_failed"] += 1
            if raw_stage.get("local_valid") is False:
                stage["local_invalid"] += 1
            hypothesis_test_result = raw_stage.get("hypothesis_test_result")
            if isinstance(hypothesis_test_result, Mapping) and hypothesis_test_result.get("configured") is True:
                stage["hypothesis_test"]["configured"] = True
                stage["hypothesis_test"]["test_count"] += 1
                if hypothesis_test_result.get("passed") is True:
                    stage["hypothesis_test"]["passed"] += 1
                else:
                    stage["hypothesis_test"]["failed"] += 1
                if isinstance(hypothesis_test_result.get("confidence_interval"), Mapping):
                    stage["hypothesis_test"]["confidence_interval_count"] += 1
                if isinstance(hypothesis_test_result.get("p_value"), (int, float)) and not isinstance(hypothesis_test_result.get("p_value"), bool):
                    stage["hypothesis_test"]["p_value_count"] += 1
                if hypothesis_test_result.get("sequential_stopping") is True:
                    stage["hypothesis_test"]["sequential_stopping_configured"] = True
                sequential_stop = hypothesis_test_result.get("sequential_stop")
                if (
                    isinstance(sequential_stop, Mapping)
                    and sequential_stop.get("stopped_early") is True
                ):
                    stage["hypothesis_test"]["sequential_stop_count"] += 1
                error_budget = hypothesis_test_result.get("error_budget")
                if (
                    isinstance(error_budget, Mapping)
                    and error_budget.get("configured") is True
                ):
                    stage["hypothesis_test"]["error_budget_configured"] = True
                    if error_budget.get("passed") is True:
                        stage["hypothesis_test"]["error_budget_passed"] += 1
                    else:
                        stage["hypothesis_test"]["error_budget_failed"] += 1
                    false_promotion = error_budget.get("false_promotion")
                    if (
                        isinstance(false_promotion, Mapping)
                        and false_promotion.get("configured") is True
                    ):
                        stage["hypothesis_test"][
                            "false_promotion_budget_count"
                        ] += 1
                    false_rejection = error_budget.get("false_rejection")
                    if (
                        isinstance(false_rejection, Mapping)
                        and false_rejection.get("configured") is True
                    ):
                        stage["hypothesis_test"][
                            "false_rejection_budget_count"
                        ] += 1
            accounting = evaluation_accounting(raw_stage)
            stage["sample_count"] += int(accounting.get("configured_stage_samples", 0))
            stage["retry_attempts"] += int(accounting.get("retry_attempts", 0))
            stage["subprocess_attempts"] += int(accounting.get("subprocess_attempts", 0))
            stage["timeout_count"] += int(accounting.get("timeout_count", 0))
            elapsed = raw_stage.get("elapsed_sec")
            if isinstance(elapsed, (int, float)) and not isinstance(elapsed, bool):
                stage["elapsed_sec"] += float(elapsed)
            if len(candidate_stage_records) < candidate_stage_records_limit:
                candidate_stage_records.append(
                    _cascade_candidate_stage_record(
                        program,
                        raw_stage,
                        stage_index,
                        name,
                        raw_stage_index,
                        accounting,
                        source,
                    )
                )
        if isinstance(stopped_at, str):
            stop_reasons.setdefault(f"stopped_at:{stopped_at}", 0)
            stop_reasons[f"stopped_at:{stopped_at}"] += 1
    ordered_stages = [
        _finalize_cascade_stage_record(record)
        for record in sorted(stages.values(), key=lambda item: (item["stage_index"], item["name"]))
    ]
    report = {
        "schema": "libreevolve.evaluation_cascade_report.v1",
        "source": "runtime_history_configured_stage_results",
        "configured_candidate_count": configured_candidate_count,
        "stage_count": len(ordered_stages),
        "stages": ordered_stages,
        "candidate_stage_records_limit": candidate_stage_records_limit,
        "candidate_stage_records_truncated": sum(
            stage["candidate_count"] for stage in ordered_stages
        )
        > len(candidate_stage_records),
        "candidate_stage_record_count": sum(
            stage["candidate_count"] for stage in ordered_stages
        ),
        "candidate_stage_records": candidate_stage_records,
        "denominator_policy": {
            "schema": "libreevolve.evaluation_cascade_denominator_policy.v1",
            "configured_candidate_denominator": (
                "history_programs_with_evaluation_metadata_configured_stage_results"
            ),
            "stage_entry_denominator": "per_stage_configured_stage_result_records",
            "main_test_exposure_denominator": (
                "candidates_whose_final_configured_stage_record_passed"
            ),
            "early_prune_denominator": (
                "configured_candidate_count_minus_main_test_exposure_count"
            ),
            "seed_sample_denominator_status": (
                "runtime_accounting_only_not_matrix_benchmark_seed_policy"
            ),
            "counterfactual_cost_savings_status": "not_emitted",
            "paper_claim_ready": False,
        },
        "source_identity_summary": {
            "configured_stage_source_count": sum(
                1
                for source in evaluator_sources
                if isinstance(source, Mapping) and source.get("role") == "stage"
            ),
            "reported_stage_count": len(ordered_stages),
            "missing_stage_source_count": sum(
                1
                for stage in ordered_stages
                if stage.get("source") == {"status": "not_available"}
            ),
        },
        "main_test_exposure_count": main_test_exposure_count,
        "early_prune_count": max(0, configured_candidate_count - main_test_exposure_count),
        "stop_reasons": dict(sorted(stop_reasons.items())),
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_cascade_efficiency": False,
            "reason": (
                "stage promotion and attrition counts exist, but difficulty/scale "
                "rationale and evaluator test-set identities are not yet complete"
            ),
            "remaining_gap": [
                "stage_difficulty_or_scale_labels",
                "evaluator_test_set_hashes",
                "benchmark_seed_sample_denominator_policy",
                "cost_savings_counterfactual",
            ],
        },
    }
    report["validation"] = validate_evaluation_cascade_report(report)
    return report


def _cascade_hypothesis_test_policy_report(
    cascade_report: Mapping[str, object],
    startup_manifest: Mapping[str, object],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    eval_stages = (
        config.get("eval_stages")
        if isinstance(config.get("eval_stages"), list)
        else []
    )
    stages_by_id = {
        stage.get("stage_id"): stage
        for stage in cascade_report.get("stages", [])
        if isinstance(stage, Mapping) and isinstance(stage.get("stage_id"), str)
    }
    stage_policies = [
        _cascade_hypothesis_stage_policy(index, stage, len(eval_stages), stages_by_id)
        for index, stage in enumerate(eval_stages)
        if isinstance(stage, Mapping)
    ]
    statistical_test_configured = any(
        stage.get("statistical_test", {}).get("configured") is True
        for stage in stage_policies
    )
    confidence_records = any(
        stage.get("statistical_test", {}).get("confidence_interval_count", 0) > 0
        for stage in stage_policies
    )
    p_value_records = any(
        stage.get("statistical_test", {}).get("p_value_count", 0) > 0
        for stage in stage_policies
    )
    sequential_stopping_configured = any(
        stage.get("statistical_test", {}).get("sequential_stopping") is True
        for stage in stage_policies
    )
    false_promotion_budget_configured = any(
        stage.get("statistical_test", {}).get("false_promotion_budget")
        is not None
        for stage in stage_policies
    )
    false_rejection_budget_configured = any(
        stage.get("statistical_test", {}).get("false_rejection_budget")
        is not None
        for stage in stage_policies
    )
    explicit_roles_configured = bool(stage_policies) and all(
        stage.get("role_source") == "configured" for stage in stage_policies
    )
    observed_stage_count = (
        cascade_report.get("stage_count")
        if isinstance(cascade_report.get("stage_count"), int)
        and not isinstance(cascade_report.get("stage_count"), bool)
        else 0
    )
    report = {
        "schema": "libreevolve.cascade_hypothesis_test_policy_report.v1",
        "source": "config_eval_stages_and_evaluation_cascade_report",
        "cascade_report_schema": cascade_report.get("schema"),
        "configured_stage_policy_count": len(stage_policies),
        "observed_stage_count": observed_stage_count,
        "stage_policies": stage_policies,
        "current_policy": {
            "schema": "libreevolve.cascade_promotion_policy_boundary.v1",
            "promotion_mechanism": (
                "configured_statistical_gate_after_threshold_checks"
                if statistical_test_configured
                else "deterministic_threshold_and_artifact_checks"
            ),
            "statistical_hypothesis_tests_supported": statistical_test_configured,
            "confidence_intervals_supported": confidence_records,
            "p_values_supported": p_value_records,
            "sequential_stopping_supported": sequential_stopping_configured,
            "false_promotion_budget_supported": false_promotion_budget_configured,
            "false_rejection_budget_supported": false_rejection_budget_configured,
            "per_sample_observation_retention": (
                "hypothesis_test_observations_when_configured"
                if statistical_test_configured
                else "stage_accounting_and_candidate_stage_summary_only"
            ),
            "paper_claim_ready": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_section_2_4_hypothesis_testing": False,
            "small_scale_filter_roles_named": bool(stage_policies),
            "main_test_role_named": bool(stage_policies),
            "explicit_stage_roles_configured": explicit_roles_configured,
            "fixed_threshold_promotion_evidence": True,
            "statistical_test_configuration": statistical_test_configured,
            "confidence_or_p_value_records": confidence_records or p_value_records,
            "sequential_stopping_diagnostics": sequential_stopping_configured,
            "false_promotion_false_rejection_budgets": (
                false_promotion_budget_configured
                and false_rejection_budget_configured
            ),
            "remaining_gap": [
                "statistical_test_configuration",
                "retained_per_sample_observations",
                "confidence_interval_or_p_value_records",
                "sequential_stopping_rule",
                "noisy_repeated_seed_promotion_tests",
            ]
            + (
                []
                if (
                    false_promotion_budget_configured
                    and false_rejection_budget_configured
                )
                else ["false_promotion_false_rejection_budget"]
            ),
        },
    }
    report["validation"] = validate_cascade_hypothesis_test_policy_report(report)
    return report


def _cascade_hypothesis_stage_policy(
    index: int,
    stage: Mapping[str, object],
    stage_count: int,
    stages_by_id: Mapping[object, Mapping[str, object]],
) -> dict:
    name = str(stage.get("name", f"stage_{index}"))
    stage_id = f"{index}:{name}"
    observed = stages_by_id.get(stage_id, {})
    role = "main_test" if index == stage_count - 1 else "small_scale_filter"
    if stage_count > 2 and 0 < index < stage_count - 1:
        role = "intermediate_filter"
    configured_role = (
        stage.get("role") if isinstance(stage.get("role"), str) else None
    )
    stage_role = configured_role or role
    samples = stage.get("samples", 1)
    configured_samples = (
        samples
        if isinstance(samples, int) and not isinstance(samples, bool)
        else 1
    )
    seeds = stage.get("seeds")
    seed_count = (
        len(seeds)
        if isinstance(seeds, list)
        else 0
    )
    hypothesis_test = (
        stage.get("hypothesis_test")
        if isinstance(stage.get("hypothesis_test"), Mapping)
        else {}
    )
    error_budget = (
        hypothesis_test.get("error_budget")
        if isinstance(hypothesis_test.get("error_budget"), Mapping)
        else {}
    )
    observed_hypothesis_test = (
        observed.get("hypothesis_test")
        if isinstance(observed.get("hypothesis_test"), Mapping)
        else {}
    )
    statistical_configured = bool(hypothesis_test)
    test_name = hypothesis_test.get("type") if statistical_configured else None
    false_promotion_calibration_method = (
        "one_sided_wilson_confidence_level"
        if test_name == "binomial_success_rate"
        else "one_sided_confidence_level"
    )
    false_rejection_calibration_method = (
        "exact_binomial_min_effect_size"
        if test_name == "binomial_success_rate"
        else "normal_approximation_min_effect_size"
    )
    return {
        "stage_id": stage_id,
        "stage_index": index,
        "stage_name": name,
        "stage_role": stage_role,
        "configured_role": configured_role,
        "inferred_role": role,
        "role_source": (
            "configured"
            if configured_role is not None
            else "inferred_from_stage_order"
        ),
        "promotion_decision_source": (
            "statistical_hypothesis_test"
            if statistical_configured
            else "fixed_threshold_and_artifact_checks"
        ),
        "thresholds": {
            "fitness": stage.get("min_score"),
            "metric_thresholds_configured": isinstance(stage.get("metric_thresholds"), Mapping),
            "artifact_checks_configured": any(
                key in stage
                for key in (
                    "min_artifacts",
                    "program_output_checks",
                    "require_program_output",
                    "required_artifacts",
                )
            ),
        },
        "sample_design": {
            "configured_samples": configured_samples,
            "configured_seed_count": seed_count,
            "explicit_seeds_configured": seed_count > 0,
            "repeated_sample_or_seed_design": configured_samples > 1 or seed_count > 1,
        },
        "observed": {
            "entered": observed.get("candidate_count", 0),
            "passed": observed.get("passed", 0),
            "failed": observed.get("failed", 0),
            "sample_count": observed.get("sample_count", 0),
            "promotion_rate": observed.get("promotion_rate"),
        },
        "statistical_test": {
            "configured": statistical_configured,
            "test_name": test_name,
            "metric": hypothesis_test.get("metric", "fitness")
            if statistical_configured
            else None,
            "min": hypothesis_test.get("min") if statistical_configured else None,
            "min_success_rate": hypothesis_test.get("min_success_rate")
            if statistical_configured
            else None,
            "success_threshold": hypothesis_test.get("success_threshold")
            if statistical_configured
            else None,
            "confidence": hypothesis_test.get("confidence", 0.95)
            if statistical_configured
            else None,
            "min_samples": hypothesis_test.get("min_samples", 2)
            if statistical_configured
            else None,
            "test_count": observed_hypothesis_test.get("test_count", 0),
            "passed": observed_hypothesis_test.get("passed", 0),
            "failed": observed_hypothesis_test.get("failed", 0),
            "confidence_interval_count": observed_hypothesis_test.get(
                "confidence_interval_count", 0
            ),
            "p_value_count": observed_hypothesis_test.get("p_value_count", 0),
            "sequential_stopping": hypothesis_test.get("sequential_stopping") is True
            if statistical_configured
            else False,
            "sequential_stop_count": observed_hypothesis_test.get(
                "sequential_stop_count", 0
            ),
            "error_budget_configured": bool(error_budget)
            if statistical_configured
            else False,
            "error_budget_passed": observed_hypothesis_test.get(
                "error_budget_passed", 0
            ),
            "error_budget_failed": observed_hypothesis_test.get(
                "error_budget_failed", 0
            ),
            "false_promotion_budget": (
                {
                    "max_rate": error_budget.get("max_false_promotion_rate"),
                    "observed_count": observed_hypothesis_test.get(
                        "false_promotion_budget_count", 0
                    ),
                    "calibration_method": false_promotion_calibration_method,
                }
                if statistical_configured
                and "max_false_promotion_rate" in error_budget
                else None
            ),
            "false_rejection_budget": (
                {
                    "max_rate": error_budget.get("max_false_rejection_rate"),
                    "min_effect_size": error_budget.get("min_effect_size"),
                    "observed_count": observed_hypothesis_test.get(
                        "false_rejection_budget_count", 0
                    ),
                    "calibration_method": false_rejection_calibration_method,
                }
                if statistical_configured
                and "max_false_rejection_rate" in error_budget
                else None
            ),
        },
        "claim_ready": False,
    }


def _cascade_candidate_stage_record(
    program: Program,
    raw_stage: Mapping[str, object],
    stage_record_index: int,
    stage_name: str,
    stage_index: object,
    accounting: Mapping[str, object],
    source: Mapping[str, object],
) -> dict:
    fitness = _finite_json_number(raw_stage.get("fitness"))
    elapsed = _finite_json_number(raw_stage.get("elapsed_sec"))
    metrics = raw_stage.get("metrics")
    metric_names = (
        sorted(name for name in metrics if isinstance(name, str))
        if isinstance(metrics, Mapping)
        else []
    )
    stop_reason = raw_stage.get("stop_reason") or raw_stage.get("error")
    return {
        "program_id": program.id,
        "generation": program.generation,
        "candidate_type": _program_candidate_type(program),
        "stage_name": stage_name,
        "stage_index": stage_index,
        "stage_record_index": stage_record_index,
        "history_path": "history.jsonl",
        "metadata_path": (
            f"evaluation.metadata.configured_stage_results[{stage_record_index}]"
        ),
        "stage_result_id": f"{program.id}:{stage_record_index}:{stage_name}",
        "passed": raw_stage.get("passed") is True,
        "local_valid": (
            raw_stage.get("local_valid")
            if isinstance(raw_stage.get("local_valid"), bool)
            else None
        ),
        "threshold_passed": (
            raw_stage.get("threshold_passed")
            if isinstance(raw_stage.get("threshold_passed"), bool)
            else None
        ),
        "hypothesis_test_result": (
            copy.deepcopy(raw_stage.get("hypothesis_test_result"))
            if isinstance(raw_stage.get("hypothesis_test_result"), Mapping)
            else {"configured": False, "passed": True, "test_name": None}
        ),
        "stop_reason": str(stop_reason) if stop_reason is not None else None,
        "fitness": fitness,
        "metric_names": metric_names,
        "elapsed_sec": round(elapsed, 9) if elapsed is not None else None,
        "accounting": {
            "configured_stage_samples": int(
                accounting.get("configured_stage_samples", 0)
            ),
            "retry_attempts": int(accounting.get("retry_attempts", 0)),
            "subprocess_attempts": int(accounting.get("subprocess_attempts", 0)),
            "timeout_count": int(accounting.get("timeout_count", 0)),
        },
        "source": _evaluator_oracle_source_ref(source),
    }


def _paper_evaluator_metric_contract_report(
    db: ProgramDatabase,
    programs: list[Program],
) -> dict:
    objective_schema = db.objective_schema_snapshot()
    metrics = objective_schema.get("metrics", [])
    metric_records = [
        _paper_metric_contract_metric_record(metric, programs)
        for metric in metrics
        if isinstance(metric, Mapping)
    ]
    paper_metric_names = [
        record["name"] for record in metric_records if record["paper_metric"] is True
    ]
    excluded_declared_metrics = [
        {
            "name": record["name"],
            "source": record["source"],
            "reason": f"declared_metric_source_{record['source']}_not_evaluator",
        }
        for record in metric_records
        if record["paper_metric"] is False
    ]
    validity_gate = _paper_metric_validity_gate(programs)
    attachments = _paper_metric_attachment_exclusions(programs)
    report = {
        "schema": "libreevolve.paper_evaluator_metric_contract.v1",
        "source": "objective_schema_and_runtime_history",
        "primary_metric": objective_schema.get("primary_metric"),
        "declared_metric_names": [record["name"] for record in metric_records],
        "paper_metric_names": paper_metric_names,
        "excluded_declared_metrics": excluded_declared_metrics,
        "metric_count": len(metric_records),
        "paper_metric_count": len(paper_metric_names),
        "metrics": metric_records,
        "validity_gate": validity_gate,
        "excluded_reserved_fields": [
            {
                "field": "is_valid",
                "reason": "local_validity_gate_not_scored_metric",
            },
            {
                "field": "outputs",
                "reason": "non_scalar_program_output_attachment",
            },
            {
                "field": "program_output",
                "reason": "non_scalar_program_output_attachment",
            },
            {
                "field": "feedback_adjusted_fitness",
                "reason": "local_feedback_composition_not_evaluator_scalar_metric",
            },
            {
                "field": "llm_feedback",
                "reason": "post_evaluator_feedback_records_not_evaluator_scalar_metric",
            },
        ],
        "non_scalar_attachment_summary": attachments,
        "feedback_metric_exclusion_policy": (
            "metrics_yaml_source_feedback_plugin_or_final_fitness_are_not_paper_evaluator_metrics"
        ),
        "normalization_policy": (
            "declared_evaluator_metrics_are_transformed_to_higher_is_better_normalized_unit_scores"
        ),
        "claim_ready": True,
        "claim_readiness": {
            "alphaevolve_scalar_metric_boundary": True,
            "remaining_gap": [
                "cross_run_metric_contract_diff_report",
            ],
        },
    }
    report["validation"] = validate_paper_evaluator_metric_contract(report)
    return report


def _paper_metric_contract_metric_record(
    metric: Mapping[str, object],
    programs: list[Program],
) -> dict:
    name = str(metric.get("name"))
    source = str(metric.get("source", "evaluator"))
    direction = str(metric.get("direction", "maximize"))
    bounds = metric.get("bounds")
    lo = float(bounds[0]) if isinstance(bounds, list) and len(bounds) == 2 else 0.0
    hi = float(bounds[1]) if isinstance(bounds, list) and len(bounds) == 2 else 1.0
    observed, observed_count, missing_count, non_numeric_count = _paper_metric_observed_values(
        name,
        direction,
        lo,
        hi,
        programs,
    )
    return {
        "name": name,
        "source": source,
        "paper_metric": source == "evaluator",
        "primary": metric.get("primary") is True,
        "direction": direction,
        "bounds": [lo, hi],
        "weight": float(metric.get("weight", 1.0)),
        "maximize_transform": (
            "raw_value" if direction == "maximize" else "upper_bound_minus_raw_value"
        ),
        "normalized_transform": (
            "(raw_value - lower_bound) / (upper_bound - lower_bound)"
            if direction == "maximize"
            else "(upper_bound - raw_value) / (upper_bound - lower_bound)"
        ),
        "raw_value_source": f"Program.metrics.{name}",
        "normalized_value_source": f"Program.metadata.normalized_metrics.{name}",
        "observed_count": observed_count,
        "missing_count": missing_count,
        "non_numeric_count": non_numeric_count,
        "observed_values": observed,
        "observed_values_limit": 25,
    }


def _paper_metric_observed_values(
    name: str,
    direction: str,
    lo: float,
    hi: float,
    programs: list[Program],
) -> tuple[list[dict], int, int, int]:
    observed: list[dict] = []
    missing_count = 0
    non_numeric_count = 0
    for program in programs:
        if name not in program.metrics:
            missing_count += 1
            continue
        value = program.metrics[name]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            non_numeric_count += 1
            continue
        numeric = float(value)
        if not math.isfinite(numeric):
            non_numeric_count += 1
            continue
        normalized = _paper_metric_normalized_value(program, name, direction, lo, hi)
        observed.append(
            {
                "program_id": program.id,
                "raw_value": numeric,
                "maximized_value": numeric if direction == "maximize" else hi - numeric,
                "normalized_value": normalized,
                "is_valid": _paper_metric_program_is_valid(program),
            }
        )
    return observed[:25], len(observed), missing_count, non_numeric_count


def _paper_metric_normalized_value(
    program: Program,
    name: str,
    direction: str,
    lo: float,
    hi: float,
) -> float | None:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    normalized_metrics = metadata.get("normalized_metrics")
    if isinstance(normalized_metrics, dict):
        value = normalized_metrics.get(name)
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            numeric = float(value)
            if math.isfinite(numeric):
                return numeric
    value = program.metrics.get(name)
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    numeric = float(value)
    if not math.isfinite(numeric):
        return None
    rng = hi - lo
    if rng == 0:
        return 0.5
    if direction == "minimize":
        normalized = (hi - numeric) / rng
    else:
        normalized = (numeric - lo) / rng
    return max(0.0, min(1.0, normalized))


def _paper_metric_program_is_valid(program: Program) -> bool | None:
    evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
    value = evaluation.get("is_valid")
    if isinstance(value, bool):
        return value
    metrics_value = program.metrics.get("is_valid")
    return metrics_value if isinstance(metrics_value, bool) else None


def _paper_metric_validity_gate(programs: list[Program]) -> dict:
    true_count = 0
    false_count = 0
    missing_count = 0
    for program in programs:
        value = _paper_metric_program_is_valid(program)
        if value is True:
            true_count += 1
        elif value is False:
            false_count += 1
        else:
            missing_count += 1
    return {
        "field": "is_valid",
        "sources": ["evaluation.is_valid", "Program.metrics.is_valid"],
        "scored_metric": False,
        "valid_true_count": true_count,
        "valid_false_count": false_count,
        "missing_count": missing_count,
        "admission_policy": "validity_gate_before_program_database_admission",
    }


def _paper_metric_attachment_exclusions(programs: list[Program]) -> dict:
    program_output_count = 0
    llm_feedback_count = 0
    feedback_adjusted_fitness_count = 0
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        metadata = evaluation.get("metadata") if isinstance(evaluation.get("metadata"), dict) else {}
        if isinstance(metadata.get("program_outputs"), dict):
            program_output_count += 1
        if isinstance(metadata.get("llm_feedback"), list) and metadata["llm_feedback"]:
            llm_feedback_count += 1
        if "feedback_adjusted_fitness" in metadata:
            feedback_adjusted_fitness_count += 1
    return {
        "program_output_attachment_count": program_output_count,
        "llm_feedback_record_count": llm_feedback_count,
        "feedback_adjusted_fitness_count": feedback_adjusted_fitness_count,
        "scored_metric": False,
    }


_PAPER_METRIC_TABLE_COLUMNS = [
    "metric_name",
    "program_id",
    "is_valid",
    "primary",
    "direction",
    "raw_value",
    "raw_display",
    "maximized_value",
    "maximized_display",
    "normalized_value",
    "normalized_display",
]


def _paper_metric_table_export_report(contract: Mapping[str, object]) -> dict:
    rows: list[dict] = []
    metrics = contract.get("metrics") if isinstance(contract.get("metrics"), list) else []
    for metric in metrics:
        if not isinstance(metric, Mapping) or metric.get("paper_metric") is not True:
            continue
        rows.extend(_paper_metric_table_rows(metric))
    display_policy = {
        "schema": "libreevolve.paper_metric_table_display_policy.v1",
        "raw_value_format": "significant_digits",
        "raw_value_significant_digits": 12,
        "maximized_value_format": "significant_digits",
        "maximized_value_significant_digits": 12,
        "normalized_value_format": "fixed_decimal_places",
        "normalized_value_decimal_places": 6,
        "rounding": "python_format_half_even_for_binary_float",
        "missing_value": "",
        "boolean_format": "json_lowercase",
    }
    table_payload = {
        "columns": list(_PAPER_METRIC_TABLE_COLUMNS),
        "rows": rows,
    }
    report = {
        "schema": "libreevolve.paper_metric_table_export.v1",
        "source": "runtime.history.paper_evaluator_metric_contract",
        "contract_schema": contract.get("schema"),
        "primary_metric": contract.get("primary_metric"),
        "paper_metric_names": list(contract.get("paper_metric_names", []))
        if isinstance(contract.get("paper_metric_names"), list)
        else [],
        "excluded_declared_metrics": copy.deepcopy(
            contract.get("excluded_declared_metrics", [])
        )
        if isinstance(contract.get("excluded_declared_metrics"), list)
        else [],
        "columns": list(_PAPER_METRIC_TABLE_COLUMNS),
        "row_count": len(rows),
        "rows": rows,
        "rows_limit": 250,
        "rows_truncated": False,
        "display_policy": display_policy,
        "export_formats": {
            "manifest_json_rows": True,
            "csv_header_order": list(_PAPER_METRIC_TABLE_COLUMNS),
            "external_file_written": False,
        },
        "table_sha256": hashlib.sha256(
            json.dumps(table_payload, sort_keys=True, separators=(",", ":")).encode(
                "utf-8"
            )
        ).hexdigest(),
        "claim_ready": True,
        "claim_readiness": {
            "single_run_paper_metric_table": True,
            "cross_run_metric_contract_diff": False,
            "remaining_gap": ["cross_run_metric_contract_diff_report"],
        },
    }
    if len(rows) > report["rows_limit"]:
        report["rows"] = rows[: report["rows_limit"]]
        report["rows_truncated"] = True
    report["validation"] = validate_paper_metric_table_export(report)
    return report


def _paper_metric_table_rows(metric: Mapping[str, object]) -> list[dict]:
    name = str(metric.get("name"))
    direction = str(metric.get("direction", "maximize"))
    primary = metric.get("primary") is True
    rows = []
    observed_values = (
        metric.get("observed_values")
        if isinstance(metric.get("observed_values"), list)
        else []
    )
    for observed in observed_values:
        if not isinstance(observed, Mapping):
            continue
        raw_value = _paper_metric_table_number(observed.get("raw_value"))
        maximized_value = _paper_metric_table_number(observed.get("maximized_value"))
        normalized_value = _paper_metric_table_number(observed.get("normalized_value"))
        rows.append(
            {
                "metric_name": name,
                "program_id": observed.get("program_id"),
                "is_valid": observed.get("is_valid"),
                "primary": primary,
                "direction": direction,
                "raw_value": raw_value,
                "raw_display": _paper_metric_display_significant(raw_value, 12),
                "maximized_value": maximized_value,
                "maximized_display": _paper_metric_display_significant(
                    maximized_value,
                    12,
                ),
                "normalized_value": normalized_value,
                "normalized_display": _paper_metric_display_fixed(
                    normalized_value,
                    6,
                ),
            }
        )
    return rows


def _paper_metric_table_number(value: object) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    numeric = float(value)
    if not math.isfinite(numeric):
        return None
    return numeric


def _paper_metric_display_significant(value: float | None, digits: int) -> str:
    if value is None:
        return ""
    return f"{value:.{digits}g}"


def _paper_metric_display_fixed(value: float | None, places: int) -> str:
    if value is None:
        return ""
    return f"{value:.{places}f}"


def validate_paper_metric_table_export(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.paper_metric_table_export.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "paper metric table export must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "contract_schema",
        "primary_metric",
        "paper_metric_names",
        "excluded_declared_metrics",
        "columns",
        "row_count",
        "rows",
        "rows_limit",
        "rows_truncated",
        "display_policy",
        "export_formats",
        "table_sha256",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"paper metric table export missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.paper_metric_table_export.v1":
        issues.append({"code": "invalid_schema", "message": "paper metric table export schema is unsupported"})
    if report.get("source") != "runtime.history.paper_evaluator_metric_contract":
        issues.append({"code": "invalid_source", "message": "paper metric table export source is unsupported"})
    if report.get("contract_schema") != "libreevolve.paper_evaluator_metric_contract.v1":
        issues.append({"code": "invalid_contract_schema", "message": "paper metric table export must consume the evaluator metric contract"})
    columns = report.get("columns")
    if columns != _PAPER_METRIC_TABLE_COLUMNS:
        issues.append({"code": "invalid_columns", "message": "paper metric table columns are not stable"})
    rows = report.get("rows")
    if not isinstance(rows, list):
        issues.append({"code": "invalid_rows", "message": "paper metric table rows must be a list"})
        rows = []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            issues.append({"code": "invalid_row", "message": f"paper metric table row {index} must be an object"})
            continue
        missing_columns = set(_PAPER_METRIC_TABLE_COLUMNS) - set(row)
        if missing_columns:
            issues.append({"code": "missing_row_columns", "message": f"paper metric table row {index} missing columns: {sorted(missing_columns)}"})
        if not isinstance(row.get("metric_name"), str) or not row.get("metric_name"):
            issues.append({"code": "invalid_metric_name", "message": f"paper metric table row {index} metric_name is invalid"})
        if not isinstance(row.get("program_id"), str) or not row.get("program_id"):
            issues.append({"code": "invalid_program_id", "message": f"paper metric table row {index} program_id is invalid"})
        if row.get("direction") not in {"maximize", "minimize"}:
            issues.append({"code": "invalid_direction", "message": f"paper metric table row {index} direction is invalid"})
        for field in ("raw_value", "maximized_value"):
            value = row.get(field)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                issues.append({"code": f"invalid_{field}", "message": f"paper metric table row {index} {field} must be finite"})
        normalized = row.get("normalized_value")
        if normalized is not None and (
            isinstance(normalized, bool)
            or not isinstance(normalized, (int, float))
            or not math.isfinite(float(normalized))
            or not 0.0 <= float(normalized) <= 1.0
        ):
            issues.append({"code": "invalid_normalized_value", "message": f"paper metric table row {index} normalized_value must be in [0, 1] or null"})
        if row.get("raw_display") != _paper_metric_display_significant(_paper_metric_table_number(row.get("raw_value")), 12):
            issues.append({"code": "invalid_raw_display", "message": f"paper metric table row {index} raw_display does not match policy"})
        if row.get("maximized_display") != _paper_metric_display_significant(_paper_metric_table_number(row.get("maximized_value")), 12):
            issues.append({"code": "invalid_maximized_display", "message": f"paper metric table row {index} maximized_display does not match policy"})
        if row.get("normalized_display") != _paper_metric_display_fixed(_paper_metric_table_number(row.get("normalized_value")), 6):
            issues.append({"code": "invalid_normalized_display", "message": f"paper metric table row {index} normalized_display does not match policy"})
    if isinstance(report.get("row_count"), int) and not isinstance(report.get("row_count"), bool):
        if report.get("rows_truncated") is not True and report["row_count"] != len(rows):
            issues.append({"code": "invalid_row_count", "message": "row_count must match rows when not truncated"})
    else:
        issues.append({"code": "invalid_row_count", "message": "row_count must be an integer"})
    if not isinstance(report.get("display_policy"), dict):
        issues.append({"code": "invalid_display_policy", "message": "display_policy must be an object"})
    if not isinstance(report.get("export_formats"), dict):
        issues.append({"code": "invalid_export_formats", "message": "export_formats must be an object"})
    table_sha = report.get("table_sha256")
    if not isinstance(table_sha, str) or not re.fullmatch(r"[0-9a-f]{64}", table_sha):
        issues.append({"code": "invalid_table_sha256", "message": "table_sha256 must be a SHA-256 hex digest"})
    elif report.get("rows_truncated") is not True and columns == _PAPER_METRIC_TABLE_COLUMNS:
        expected_sha = hashlib.sha256(
            json.dumps(
                {"columns": columns, "rows": rows},
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if table_sha != expected_sha:
            issues.append({"code": "table_sha256_mismatch", "message": "table_sha256 must match stable column/row payload"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    elif readiness.get("cross_run_metric_contract_diff") is not False:
        issues.append({"code": "cross_run_overclaim", "message": "cross-run metric contract diff must remain false until implemented"})
    return {
        "schema": "libreevolve.paper_metric_table_export.v1",
        "ok": not issues,
        "issues": issues,
    }


def paper_metric_cross_run_report(
    manifests: list[Mapping[str, object]] | tuple[Mapping[str, object], ...],
    *,
    run_labels: list[str] | tuple[str, ...] | None = None,
) -> dict:
    """Compare paper metric contracts and table exports across run manifests."""
    manifest_list = list(manifests) if isinstance(manifests, (list, tuple)) else []
    labels = list(run_labels) if isinstance(run_labels, (list, tuple)) else []
    run_records = [
        _paper_metric_cross_run_record(
            manifest,
            run_index=index,
            run_label=labels[index] if index < len(labels) else None,
        )
        for index, manifest in enumerate(manifest_list)
        if isinstance(manifest, Mapping)
    ]
    drift_records = _paper_metric_cross_run_drift_records(run_records)
    table_records = [
        {
            "run_id": record["run_id"],
            "problem_name": record["problem_name"],
            "table_sha256": record["table_sha256"],
            "row_count": record["row_count"],
            "paper_metric_names": record["paper_metric_names"],
        }
        for record in run_records
    ]
    metric_names = sorted(
        {
            name
            for record in run_records
            for name in record["paper_metric_names"]
            if isinstance(name, str)
        }
    )
    validation_failures = [
        record["run_id"]
        for record in run_records
        if not (
            record["contract_validation_ok"] is True
            and record["table_validation_ok"] is True
        )
    ]
    remaining_gap = []
    if len(run_records) < 2:
        remaining_gap.append("fewer_than_two_runs")
    if validation_failures:
        remaining_gap.append("invalid_single_run_metric_artifacts")
    if drift_records:
        remaining_gap.append("metric_contract_or_display_policy_drift")
    claim_ready = not remaining_gap
    report = {
        "schema": "libreevolve.paper_metric_cross_run_report.v1",
        "source": "manifest_runtime_history_paper_metric_reports",
        "run_count": len(run_records),
        "runs": run_records,
        "metric_names": metric_names,
        "metric_name_count": len(metric_names),
        "table_records": table_records,
        "table_record_count": len(table_records),
        "drift_records": drift_records,
        "drift_count": len(drift_records),
        "validation_failure_run_ids": validation_failures,
        "claim_ready": claim_ready,
        "claim_readiness": {
            "cross_run_metric_contract_diff": claim_ready,
            "at_least_two_runs": len(run_records) >= 2,
            "single_run_reports_valid": not validation_failures,
            "stable_metric_contract": not drift_records,
            "stable_display_policy": not any(
                record.get("drift_type") == "display_policy"
                for record in drift_records
            ),
            "remaining_gap": remaining_gap,
        },
    }
    report["validation"] = validate_paper_metric_cross_run_report(report)
    return report


def _paper_metric_cross_run_record(
    manifest: Mapping[str, object],
    *,
    run_index: int,
    run_label: str | None,
) -> dict:
    config = manifest.get("config") if isinstance(manifest.get("config"), Mapping) else {}
    runtime = manifest.get("runtime") if isinstance(manifest.get("runtime"), Mapping) else {}
    history = runtime.get("history") if isinstance(runtime.get("history"), Mapping) else {}
    contract = (
        history.get("paper_evaluator_metric_contract")
        if isinstance(history.get("paper_evaluator_metric_contract"), Mapping)
        else {}
    )
    table = (
        history.get("paper_metric_table_export")
        if isinstance(history.get("paper_metric_table_export"), Mapping)
        else {}
    )
    contract_validation = validate_paper_evaluator_metric_contract(contract)
    table_validation = validate_paper_metric_table_export(table)
    run_id = run_label or str(
        config.get("run_id") or config.get("problem_name") or f"run_{run_index}"
    )
    display_policy = (
        table.get("display_policy") if isinstance(table.get("display_policy"), Mapping) else {}
    )
    excluded = (
        table.get("excluded_declared_metrics")
        if isinstance(table.get("excluded_declared_metrics"), list)
        else []
    )
    columns = table.get("columns") if isinstance(table.get("columns"), list) else []
    paper_metric_names = (
        table.get("paper_metric_names")
        if isinstance(table.get("paper_metric_names"), list)
        else []
    )
    return {
        "run_index": run_index,
        "run_id": redact_sensitive_text(run_id),
        "problem_name": redact_sensitive_text(str(config.get("problem_name", ""))),
        "manifest_schema_version": manifest.get("schema_version"),
        "contract_schema": contract.get("schema"),
        "contract_validation_ok": contract_validation["ok"],
        "contract_sha256": _paper_metric_cross_run_hash(contract),
        "table_schema": table.get("schema"),
        "table_validation_ok": table_validation["ok"],
        "table_sha256": table.get("table_sha256"),
        "primary_metric": table.get("primary_metric"),
        "paper_metric_names": list(paper_metric_names),
        "excluded_declared_metrics": copy.deepcopy(excluded),
        "columns": list(columns),
        "columns_sha256": _paper_metric_cross_run_hash(columns),
        "display_policy_sha256": _paper_metric_cross_run_hash(display_policy),
        "row_count": table.get("row_count"),
        "rows_truncated": table.get("rows_truncated") is True,
    }


def _paper_metric_cross_run_hash(value: object) -> str:
    return hashlib.sha256(
        json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
            default=str,
        ).encode("utf-8")
    ).hexdigest()


def _paper_metric_cross_run_drift_records(records: list[dict]) -> list[dict]:
    if len(records) < 2:
        return []
    baseline = records[0]
    drift: list[dict] = []
    comparisons = (
        ("paper_metric_names", "metric_contract"),
        ("primary_metric", "metric_contract"),
        ("excluded_declared_metrics", "metric_contract"),
        ("columns", "table_columns"),
        ("display_policy_sha256", "display_policy"),
    )
    for record in records[1:]:
        for field, drift_type in comparisons:
            if record.get(field) != baseline.get(field):
                drift.append(
                    {
                        "drift_type": drift_type,
                        "field": field,
                        "baseline_run_id": baseline["run_id"],
                        "run_id": record["run_id"],
                        "baseline_value_sha256": _paper_metric_cross_run_hash(
                            baseline.get(field)
                        ),
                        "value_sha256": _paper_metric_cross_run_hash(record.get(field)),
                    }
                )
    return drift


def validate_paper_metric_cross_run_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.paper_metric_cross_run_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "paper metric cross-run report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "run_count",
        "runs",
        "metric_names",
        "metric_name_count",
        "table_records",
        "table_record_count",
        "drift_records",
        "drift_count",
        "validation_failure_run_ids",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"paper metric cross-run report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.paper_metric_cross_run_report.v1":
        issues.append({"code": "invalid_schema", "message": "paper metric cross-run report schema is unsupported"})
    if report.get("source") != "manifest_runtime_history_paper_metric_reports":
        issues.append({"code": "invalid_source", "message": "paper metric cross-run report source is unsupported"})
    runs = report.get("runs")
    if not isinstance(runs, list):
        issues.append({"code": "invalid_runs", "message": "runs must be a list"})
        runs = []
    _validate_report_count(report, "run_count", len(runs), issues)
    for index, record in enumerate(runs):
        _validate_paper_metric_cross_run_record(index, record, issues)
    metric_names = report.get("metric_names")
    expected_metric_names = sorted(
        {
            name
            for record in runs
            if isinstance(record, Mapping)
            for name in record.get("paper_metric_names", [])
            if isinstance(name, str)
        }
    )
    if metric_names != expected_metric_names:
        issues.append({"code": "metric_names_mismatch", "message": "metric_names must aggregate run metric names"})
    _validate_report_count(report, "metric_name_count", len(expected_metric_names), issues)
    table_records = report.get("table_records")
    if not isinstance(table_records, list):
        issues.append({"code": "invalid_table_records", "message": "table_records must be a list"})
        table_records = []
    _validate_report_count(report, "table_record_count", len(table_records), issues)
    drift_records = report.get("drift_records")
    if not isinstance(drift_records, list):
        issues.append({"code": "invalid_drift_records", "message": "drift_records must be a list"})
        drift_records = []
    _validate_report_count(report, "drift_count", len(drift_records), issues)
    for drift in drift_records:
        if not isinstance(drift, Mapping):
            issues.append({"code": "invalid_drift_record", "message": "drift records must be objects"})
            continue
        if drift.get("drift_type") not in {"metric_contract", "table_columns", "display_policy"}:
            issues.append({"code": "invalid_drift_type", "message": "drift_type is unsupported"})
        for field in ("baseline_value_sha256", "value_sha256"):
            if not _is_sha256_hex(drift.get(field)):
                issues.append({"code": "invalid_drift_hash", "message": f"{field} must be sha256 hex"})
    failures = report.get("validation_failure_run_ids")
    if not isinstance(failures, list) or not all(isinstance(item, str) for item in failures):
        issues.append({"code": "invalid_validation_failures", "message": "validation_failure_run_ids must be text ids"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    else:
        expected_ready = (
            len(runs) >= 2
            and not failures
            and not drift_records
        )
        if readiness.get("cross_run_metric_contract_diff") is not expected_ready:
            issues.append({"code": "claim_readiness_mismatch", "message": "cross_run_metric_contract_diff readiness must match validation inputs"})
        if not isinstance(readiness.get("remaining_gap"), list):
            issues.append({"code": "invalid_remaining_gap", "message": "remaining_gap must be a list"})
    if report.get("claim_ready") not in {True, False}:
        issues.append({"code": "invalid_claim_ready", "message": "claim_ready must be boolean"})
    elif isinstance(readiness, Mapping):
        expected_ready = (
            len(runs) >= 2
            and not failures
            and not drift_records
        )
        if report.get("claim_ready") is not expected_ready:
            issues.append({"code": "claim_ready_mismatch", "message": "claim_ready must match cross-run readiness"})
    return {
        "schema": "libreevolve.paper_metric_cross_run_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _validate_paper_metric_cross_run_record(
    index: int,
    record: object,
    issues: list[dict],
) -> None:
    if not isinstance(record, Mapping):
        issues.append({"code": "invalid_run_record", "message": f"run record {index} must be an object"})
        return
    if not isinstance(record.get("run_index"), int) or isinstance(record.get("run_index"), bool):
        issues.append({"code": "invalid_run_index", "message": f"run record {index} run_index must be an int"})
    if not isinstance(record.get("run_id"), str) or not record.get("run_id"):
        issues.append({"code": "invalid_run_id", "message": f"run record {index} run_id must be non-empty text"})
    for field in ("contract_sha256", "columns_sha256", "display_policy_sha256"):
        if not _is_sha256_hex(record.get(field)):
            issues.append({"code": f"invalid_{field}", "message": f"run record {index} {field} must be sha256 hex"})
    table_sha = record.get("table_sha256")
    if table_sha is not None and not _is_sha256_hex(table_sha):
        issues.append({"code": "invalid_table_sha256", "message": f"run record {index} table_sha256 must be null or sha256 hex"})
    if record.get("contract_validation_ok") not in {True, False}:
        issues.append({"code": "invalid_contract_validation", "message": f"run record {index} contract validation flag must be boolean"})
    if record.get("table_validation_ok") not in {True, False}:
        issues.append({"code": "invalid_table_validation", "message": f"run record {index} table validation flag must be boolean"})
    if not isinstance(record.get("paper_metric_names"), list) or not all(
        isinstance(name, str) for name in record.get("paper_metric_names", [])
    ):
        issues.append({"code": "invalid_paper_metric_names", "message": f"run record {index} paper_metric_names must be text"})
    if record.get("columns") != _PAPER_METRIC_TABLE_COLUMNS:
        issues.append({"code": "invalid_run_columns", "message": f"run record {index} columns must match paper metric table columns"})
    if not isinstance(record.get("row_count"), int) or isinstance(record.get("row_count"), bool) or record.get("row_count") < 0:
        issues.append({"code": "invalid_run_row_count", "message": f"run record {index} row_count must be a non-negative int"})


def validate_paper_evaluator_metric_contract(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.paper_evaluator_metric_contract.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "paper evaluator metric contract must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "primary_metric",
        "declared_metric_names",
        "paper_metric_names",
        "excluded_declared_metrics",
        "metric_count",
        "paper_metric_count",
        "metrics",
        "validity_gate",
        "excluded_reserved_fields",
        "non_scalar_attachment_summary",
        "feedback_metric_exclusion_policy",
        "normalization_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"metric contract missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.paper_evaluator_metric_contract.v1":
        issues.append({"code": "invalid_schema", "message": "metric contract schema is unsupported"})
    if report.get("source") != "objective_schema_and_runtime_history":
        issues.append({"code": "invalid_source", "message": "metric contract source is unsupported"})
    metrics = report.get("metrics")
    if not isinstance(metrics, list):
        issues.append({"code": "invalid_metrics", "message": "metrics must be a list"})
        metrics = []
    declared_names: list[str] = []
    paper_names: list[str] = []
    for index, metric in enumerate(metrics):
        if not isinstance(metric, dict):
            issues.append({"code": "invalid_metric", "message": f"metric {index} must be an object"})
            continue
        name = metric.get("name")
        if not isinstance(name, str) or not name:
            issues.append({"code": "invalid_metric_name", "message": f"metric {index} name is invalid"})
            continue
        declared_names.append(name)
        if name in {"is_valid", "outputs", "program_output", "feedback_adjusted_fitness"}:
            issues.append({"code": "reserved_metric_name", "message": f"reserved field {name} must not be a paper metric"})
        if metric.get("paper_metric") is True:
            paper_names.append(name)
            if metric.get("source") != "evaluator":
                issues.append({"code": "invalid_paper_metric_source", "message": f"paper metric {name} is not evaluator-sourced"})
        elif metric.get("source") == "evaluator":
            issues.append({"code": "evaluator_metric_not_paper_metric", "message": f"evaluator metric {name} must be paper-facing"})
        if metric.get("direction") not in {"maximize", "minimize"}:
            issues.append({"code": "invalid_direction", "message": f"metric {name} direction is invalid"})
        bounds = metric.get("bounds")
        if (
            not isinstance(bounds, list)
            or len(bounds) != 2
            or any(isinstance(item, bool) or not isinstance(item, (int, float)) for item in bounds)
            or not float(bounds[0]) < float(bounds[1])
        ):
            issues.append({"code": "invalid_bounds", "message": f"metric {name} bounds are invalid"})
        observed = metric.get("observed_values")
        if not isinstance(observed, list):
            issues.append({"code": "invalid_observed_values", "message": f"metric {name} observed_values must be a list"})
        else:
            for value_index, observed_value in enumerate(observed):
                if not isinstance(observed_value, dict):
                    issues.append({"code": "invalid_observed_value", "message": f"metric {name} observed value {value_index} must be an object"})
                    continue
                for field in ("raw_value", "maximized_value"):
                    value = observed_value.get(field)
                    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                        issues.append({"code": "invalid_observed_number", "message": f"metric {name} observed {field} must be finite"})
                normalized = observed_value.get("normalized_value")
                if normalized is not None and (
                    isinstance(normalized, bool)
                    or not isinstance(normalized, (int, float))
                    or not math.isfinite(float(normalized))
                    or not 0.0 <= float(normalized) <= 1.0
                ):
                    issues.append({"code": "invalid_normalized_value", "message": f"metric {name} normalized value must be in [0, 1]"})
    if report.get("declared_metric_names") != declared_names:
        issues.append({"code": "invalid_declared_names", "message": "declared_metric_names must match metrics order"})
    if report.get("paper_metric_names") != paper_names:
        issues.append({"code": "invalid_paper_names", "message": "paper_metric_names must match evaluator-sourced metrics"})
    if report.get("metric_count") != len(metrics):
        issues.append({"code": "invalid_metric_count", "message": "metric_count must match metrics length"})
    if report.get("paper_metric_count") != len(paper_names):
        issues.append({"code": "invalid_paper_metric_count", "message": "paper_metric_count must match paper_metric_names length"})
    validity_gate = report.get("validity_gate")
    if not isinstance(validity_gate, dict) or validity_gate.get("scored_metric") is not False:
        issues.append({"code": "invalid_validity_gate", "message": "is_valid must be documented as a non-scored gate"})
    reserved_fields = report.get("excluded_reserved_fields")
    if not isinstance(reserved_fields, list):
        issues.append({"code": "invalid_reserved_fields", "message": "excluded_reserved_fields must be a list"})
    else:
        excluded = {field.get("field") for field in reserved_fields if isinstance(field, dict)}
        for field in ("is_valid", "outputs", "program_output", "feedback_adjusted_fitness", "llm_feedback"):
            if field not in excluded:
                issues.append({"code": "missing_reserved_exclusion", "message": f"{field} exclusion is missing"})
    return {
        "schema": "libreevolve.paper_evaluator_metric_contract.v1",
        "ok": not issues,
        "issues": issues,
    }


def _metric_diverse_inspiration_record(
    inspirations: list[Program],
    selection_metadata: Mapping[str, object],
    prompt_metadata: Mapping[str, object],
    objective_schema: Mapping[str, object],
) -> dict:
    policy = (
        prompt_metadata.get("inspiration_policy")
        if isinstance(prompt_metadata.get("inspiration_policy"), Mapping)
        else {}
    )
    rendered_count = policy.get("rendered_count")
    if isinstance(rendered_count, bool) or not isinstance(rendered_count, int):
        limit = policy.get("limit")
        if isinstance(limit, bool) or not isinstance(limit, int):
            visible = list(inspirations)
        elif limit <= 0:
            visible = []
        else:
            visible = list(inspirations)[:limit]
    else:
        visible = list(inspirations)[: max(0, rendered_count)]
    metric_order = _metric_diverse_declared_metric_order(objective_schema)
    target_metrics = _metric_diverse_target_metrics(selection_metadata)
    target_metrics_by_program: dict[str, list[str]] = {}
    for target in target_metrics:
        program_id = target["program_id"]
        metric = target["metric"]
        target_metrics_by_program.setdefault(program_id, [])
        if metric not in target_metrics_by_program[program_id]:
            target_metrics_by_program[program_id].append(metric)

    records: list[dict] = []
    for index, program in enumerate(visible):
        record = _metric_diverse_visible_inspiration_record(
            program,
            index,
            metric_order,
            target_metrics_by_program.get(program.id, []),
        )
        if record is not None:
            records.append(record)
    distinct_metric_niches = _unique_in_order(
        [
            str(record["metric_niche"])
            for record in records
            if isinstance(record.get("metric_niche"), str)
        ]
    )
    metric_diverse = len(distinct_metric_niches) >= 2
    prompt_sha256 = prompt_metadata.get("prompt_sha256")
    return {
        "schema": "libreevolve.metric_diverse_inspiration.v1",
        "source": "prompt_visible_inspiration_selection_metadata",
        "selection_strategy": selection_metadata.get("strategy"),
        "sample_kind": selection_metadata.get("sample_kind"),
        "requested_count": selection_metadata.get("requested_count"),
        "selected_count": selection_metadata.get("selected_count"),
        "selected_program_ids": list(selection_metadata.get("selected_program_ids", []))
        if isinstance(selection_metadata.get("selected_program_ids"), list)
        else [],
        "visible_count": len(visible),
        "visible_program_ids": [program.id for program in visible],
        "rendered_count_source": "prompt_diagnostics.inspiration_policy.rendered_count",
        "prompt_sha256": prompt_sha256 if isinstance(prompt_sha256, str) else None,
        "declared_metric_order": metric_order,
        "target_metrics": target_metrics,
        "records": records,
        "record_count": len(records),
        "distinct_metric_count": len(distinct_metric_niches),
        "distinct_metric_niches": distinct_metric_niches,
        "metric_diverse_prompt_visible": metric_diverse,
        "status": (
            "metric_diverse_prompt_visible"
            if metric_diverse
            else "not_metric_diverse_prompt_visible"
        ),
        "benchmark_policy": {
            "schema": "libreevolve.metric_diverse_prompt_benchmark_boundary.v1",
            "benchmark_required_metric_diverse_prompt_policy": False,
            "cross_run_metric_diverse_prompt_fixture": False,
            "scalar_and_single_metric_comparison": False,
            "alphaevolve_section_2_4_claim_ready": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "prompt_visible_metric_diversity_evidence": metric_diverse,
            "benchmark_required_metric_diverse_prompt_policy": False,
            "cross_run_metric_diverse_prompt_fixture": False,
            "scalar_and_single_metric_comparison": False,
            "remaining_gap": (
                [
                    "benchmark_required_metric_diverse_prompt_policy",
                    "cross_run_metric_diverse_prompt_fixture",
                    "scalar_and_single_metric_comparison",
                ]
                if metric_diverse
                else [
                    "prompt_visible_slate_did_not_cover_multiple_metric_niches",
                    "benchmark_required_metric_diverse_prompt_policy",
                    "cross_run_metric_diverse_prompt_fixture",
                    "scalar_and_single_metric_comparison",
                ]
            ),
        },
    }


def _metric_diverse_declared_metric_order(
    objective_schema: Mapping[str, object],
) -> list[str]:
    metrics = objective_schema.get("metrics")
    if not isinstance(metrics, list):
        return []
    names: list[str] = []
    for metric in metrics:
        if not isinstance(metric, Mapping):
            continue
        name = metric.get("name")
        if isinstance(name, str) and name and name not in names:
            names.append(name)
    return names


def _metric_diverse_target_metrics(
    selection_metadata: Mapping[str, object],
) -> list[dict]:
    records = selection_metadata.get("target_metrics")
    if not isinstance(records, list):
        return []
    normalized: list[dict] = []
    for record in records:
        if not isinstance(record, Mapping):
            continue
        metric = record.get("metric")
        program_id = record.get("program_id")
        if isinstance(metric, str) and metric and isinstance(program_id, str) and program_id:
            normalized.append({"metric": metric, "program_id": program_id})
    return normalized


def _metric_diverse_visible_inspiration_record(
    program: Program,
    visible_index: int,
    metric_order: list[str],
    target_metrics: list[str],
) -> dict | None:
    normalized_metrics = _metric_diverse_normalized_metrics(program, metric_order)
    if not normalized_metrics:
        return None
    metric_niche = _metric_diverse_metric_niche(
        normalized_metrics,
        metric_order,
        target_metrics,
    )
    if metric_niche is None:
        return None
    raw_value = program.metrics.get(metric_niche)
    normalized_value = normalized_metrics.get(metric_niche)
    return {
        "program_id": program.id,
        "visible_index": visible_index,
        "metric_niche": metric_niche,
        "metric_niche_source": (
            "selection_metadata.target_metrics"
            if metric_niche in target_metrics
            else "max_normalized_declared_metric"
        ),
        "target_metrics": list(target_metrics),
        "raw_metric_value": float(raw_value)
        if isinstance(raw_value, (int, float)) and not isinstance(raw_value, bool)
        else None,
        "normalized_metric_value": normalized_value,
        "normalized_metrics": normalized_metrics,
        "fitness": program.fitness,
        "generation": program.generation,
    }


def _metric_diverse_normalized_metrics(
    program: Program,
    metric_order: list[str],
) -> dict[str, float]:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    raw = metadata.get("normalized_metrics")
    if not isinstance(raw, Mapping):
        return {}
    allowed = set(metric_order)
    values: dict[str, float] = {}
    for name in metric_order:
        value = raw.get(name)
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            numeric = float(value)
            if math.isfinite(numeric):
                values[name] = max(0.0, min(1.0, numeric))
    if values or allowed:
        return values
    for name, value in raw.items():
        if not isinstance(name, str) or not name:
            continue
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            numeric = float(value)
            if math.isfinite(numeric):
                values[name] = max(0.0, min(1.0, numeric))
    return values


def _metric_diverse_metric_niche(
    normalized_metrics: Mapping[str, float],
    metric_order: list[str],
    target_metrics: list[str],
) -> str | None:
    for metric in target_metrics:
        if metric in normalized_metrics:
            return metric
    ordered_names = [
        name for name in metric_order if name in normalized_metrics
    ] + sorted(name for name in normalized_metrics if name not in set(metric_order))
    if not ordered_names:
        return None
    order_index = {name: index for index, name in enumerate(ordered_names)}
    return max(
        ordered_names,
        key=lambda name: (
            float(normalized_metrics[name]),
            -order_index[name],
        ),
    )


def _unique_in_order(values: list[str]) -> list[str]:
    seen: set[str] = set()
    ordered: list[str] = []
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        ordered.append(value)
    return ordered


def _metric_diverse_inspiration_report(programs: list[Program]) -> dict:
    records: list[dict] = []
    for program in programs:
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        inspiration = metadata.get("inspiration_selection")
        if not isinstance(inspiration, Mapping):
            continue
        diversity = inspiration.get("metric_diversity")
        if not isinstance(diversity, Mapping):
            continue
        records.append(
            {
                "program_id": program.id,
                "generation": program.generation,
                "parent_id": program.parent_id,
                "candidate_type": metadata.get("candidate_type"),
                "prompt_sha256": diversity.get("prompt_sha256"),
                "selection_strategy": diversity.get("selection_strategy"),
                "visible_count": diversity.get("visible_count"),
                "visible_program_ids": list(diversity.get("visible_program_ids", []))
                if isinstance(diversity.get("visible_program_ids"), list)
                else [],
                "distinct_metric_count": diversity.get("distinct_metric_count"),
                "distinct_metric_niches": list(
                    diversity.get("distinct_metric_niches", [])
                )
                if isinstance(diversity.get("distinct_metric_niches"), list)
                else [],
                "metric_diverse_prompt_visible": (
                    diversity.get("metric_diverse_prompt_visible") is True
                ),
                "benchmark_policy": copy.deepcopy(diversity.get("benchmark_policy"))
                if isinstance(diversity.get("benchmark_policy"), Mapping)
                else {},
                "records": copy.deepcopy(diversity.get("records", []))
                if isinstance(diversity.get("records"), list)
                else [],
            }
        )
    metric_diverse_count = sum(
        1 for record in records if record["metric_diverse_prompt_visible"] is True
    )
    report = {
        "schema": "libreevolve.metric_diverse_inspiration_report.v1",
        "source": "history_program_metadata_inspiration_selection_metric_diversity",
        "candidate_count": len(records),
        "prompt_visible_candidate_count": sum(
            1
            for record in records
            if isinstance(record.get("visible_count"), int)
            and record.get("visible_count", 0) > 0
        ),
        "metric_diverse_prompt_count": metric_diverse_count,
        "records_limit": 100,
        "records_truncated": len(records) > 100,
        "records": records[:100],
        "evidence_policy": {
            "schema": "libreevolve.metric_diverse_inspiration_policy.v1",
            "prompt_visible_surface": (
                "prompt_diagnostics.inspiration_policy.rendered_count"
            ),
            "metric_niche_source_order": [
                "selection_metadata.target_metrics",
                "max_normalized_declared_metric",
            ],
            "normalized_metric_source": "Program.metadata.normalized_metrics",
            "metric_diverse_threshold": "at_least_two_distinct_visible_metric_niches",
            "benchmark_policy_source": "not_configured_by_current_run_summary",
            "comparison_policy": "not_emitted_by_metric_diverse_inspiration_report",
        },
        "benchmark_policy": {
            "schema": "libreevolve.metric_diverse_prompt_benchmark_boundary.v1",
            "benchmark_required_metric_diverse_prompt_policy": False,
            "cross_run_metric_diverse_prompt_fixture": False,
            "scalar_and_single_metric_comparison": False,
            "alphaevolve_section_2_4_claim_ready": False,
            "remaining_required_evidence": [
                "benchmark_required_metric_diverse_prompt_policy",
                "cross_run_metric_diverse_prompt_fixture",
                "scalar_and_single_metric_comparison",
            ],
        },
        "claim_ready": False,
        "claim_readiness": {
            "prompt_visible_metric_diversity_evidence": metric_diverse_count > 0,
            "benchmark_required_metric_diverse_prompt_policy": False,
            "cross_run_metric_diverse_prompt_fixture": False,
            "scalar_and_single_metric_comparison": False,
            "remaining_gap": [
                "benchmark_required_metric_diverse_prompt_policy",
                "cross_run_metric_diverse_prompt_fixture",
                "scalar_and_single_metric_comparison",
            ],
        },
    }
    report["validation"] = validate_metric_diverse_inspiration_report(report)
    return report


def validate_metric_diverse_inspiration_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.metric_diverse_inspiration_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "metric-diverse inspiration report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "candidate_count",
        "prompt_visible_candidate_count",
        "metric_diverse_prompt_count",
        "records_limit",
        "records_truncated",
        "records",
        "evidence_policy",
        "benchmark_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "metric-diverse inspiration report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.metric_diverse_inspiration_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "metric-diverse inspiration report schema is unsupported",
            }
        )
    if (
        report.get("source")
        != "history_program_metadata_inspiration_selection_metric_diversity"
    ):
        issues.append(
            {
                "code": "invalid_source",
                "message": "metric-diverse inspiration report source is unsupported",
            }
        )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    visible_count = 0
    diverse_count = 0
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_record",
                    "message": f"record {index} must be an object",
                }
            )
            continue
        if not isinstance(record.get("program_id"), str) or not record.get("program_id"):
            issues.append(
                {
                    "code": "invalid_program_id",
                    "message": f"record {index} program_id is invalid",
                }
            )
        rendered = record.get("visible_count")
        if isinstance(rendered, bool) or not isinstance(rendered, int) or rendered < 0:
            issues.append(
                {
                    "code": "invalid_visible_count",
                    "message": f"record {index} visible_count is invalid",
                }
            )
        elif rendered > 0:
            visible_count += 1
        distinct = record.get("distinct_metric_count")
        niches = record.get("distinct_metric_niches")
        if isinstance(distinct, bool) or not isinstance(distinct, int) or distinct < 0:
            issues.append(
                {
                    "code": "invalid_distinct_metric_count",
                    "message": f"record {index} distinct_metric_count is invalid",
                }
            )
        if not isinstance(niches, list) or any(
            not isinstance(item, str) or not item for item in niches
        ):
            issues.append(
                {
                    "code": "invalid_distinct_metric_niches",
                    "message": f"record {index} distinct_metric_niches is invalid",
                }
            )
        elif isinstance(distinct, int) and not isinstance(distinct, bool) and distinct != len(niches):
            issues.append(
                {
                    "code": "distinct_metric_count_mismatch",
                    "message": (
                        f"record {index} distinct_metric_count must match niches"
                    ),
                }
            )
        if record.get("metric_diverse_prompt_visible") is True:
            diverse_count += 1
            if not isinstance(distinct, int) or distinct < 2:
                issues.append(
                    {
                        "code": "invalid_metric_diverse_record",
                        "message": (
                            f"record {index} cannot be metric-diverse with fewer "
                            "than two distinct metric niches"
                        ),
                    }
                )
        slate = record.get("records")
        record_policy = record.get("benchmark_policy")
        if not _is_metric_diverse_benchmark_boundary(record_policy):
            issues.append(
                {
                    "code": "invalid_record_benchmark_policy",
                    "message": (
                        f"record {index} benchmark_policy must preserve the "
                        "benchmark policy/fixture boundary"
                    ),
                }
            )
        if not isinstance(slate, list):
            issues.append(
                {
                    "code": "invalid_visible_records",
                    "message": f"record {index} records must be a list",
                }
            )
            continue
        for visible_index, visible_record in enumerate(slate):
            if not isinstance(visible_record, dict):
                issues.append(
                    {
                        "code": "invalid_visible_record",
                        "message": (
                            f"record {index} visible record {visible_index} must be "
                            "an object"
                        ),
                    }
                )
                continue
            metric = visible_record.get("metric_niche")
            if not isinstance(metric, str) or not metric:
                issues.append(
                    {
                        "code": "invalid_metric_niche",
                        "message": (
                            f"record {index} visible record {visible_index} metric "
                            "niche is invalid"
                        ),
                    }
                )
            normalized = visible_record.get("normalized_metric_value")
            if (
                isinstance(normalized, bool)
                or not isinstance(normalized, (int, float))
                or not math.isfinite(float(normalized))
                or not 0.0 <= float(normalized) <= 1.0
            ):
                issues.append(
                    {
                        "code": "invalid_normalized_metric_value",
                        "message": (
                            f"record {index} visible record {visible_index} "
                            "normalized metric value must be in [0, 1]"
                        ),
                    }
                )
    if report.get("records_truncated") is not True:
        if report.get("candidate_count") != len(records):
            issues.append(
                {
                    "code": "invalid_candidate_count",
                    "message": "candidate_count must match records",
                }
            )
        if report.get("prompt_visible_candidate_count") != visible_count:
            issues.append(
                {
                    "code": "invalid_prompt_visible_count",
                    "message": (
                        "prompt_visible_candidate_count must match records"
                    ),
                }
            )
        if report.get("metric_diverse_prompt_count") != diverse_count:
            issues.append(
                {
                    "code": "invalid_metric_diverse_count",
                    "message": "metric_diverse_prompt_count must match records",
                }
            )
    if not isinstance(report.get("evidence_policy"), dict):
        issues.append(
            {
                "code": "invalid_evidence_policy",
                "message": "evidence_policy must be an object",
            }
        )
    if not _is_metric_diverse_benchmark_boundary(report.get("benchmark_policy")):
        issues.append(
            {
                "code": "invalid_benchmark_policy",
                "message": (
                    "benchmark_policy must keep benchmark-required metric-diverse "
                    "prompt policy, fixture, and comparison claims false"
                ),
            }
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        for field in (
            "benchmark_required_metric_diverse_prompt_policy",
            "cross_run_metric_diverse_prompt_fixture",
            "scalar_and_single_metric_comparison",
        ):
            if readiness.get(field) is not False:
                issues.append(
                    {
                        "code": "benchmark_claim_overclaim",
                        "message": f"{field} must remain false in this report",
                    }
                )
        remaining = readiness.get("remaining_gap")
        required_gaps = {
            "benchmark_required_metric_diverse_prompt_policy",
            "cross_run_metric_diverse_prompt_fixture",
            "scalar_and_single_metric_comparison",
        }
        if not isinstance(remaining, list) or not required_gaps.issubset(
            {item for item in remaining if isinstance(item, str)}
        ):
            issues.append(
                {
                    "code": "missing_benchmark_remaining_gap",
                    "message": "remaining_gap must preserve benchmark policy, fixture, and comparison gaps",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "claim_ready must remain false until benchmark policy and fixture evidence exists",
            }
        )
    return {
        "schema": "libreevolve.metric_diverse_inspiration_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _is_metric_diverse_benchmark_boundary(value: object) -> bool:
    if not isinstance(value, Mapping):
        return False
    if value.get("schema") != "libreevolve.metric_diverse_prompt_benchmark_boundary.v1":
        return False
    return all(
        value.get(field) is False
        for field in (
            "benchmark_required_metric_diverse_prompt_policy",
            "cross_run_metric_diverse_prompt_fixture",
            "scalar_and_single_metric_comparison",
            "alphaevolve_section_2_4_claim_ready",
        )
    )


def _duplicate_work_policy_report(programs: list[Program]) -> dict:
    records = [_duplicate_work_program_record(program) for program in programs]
    cache_hit_ids = [
        record["program_id"]
        for record in records
        if record.get("evaluation_cache", {}).get("cache_hit") is True
    ]
    cache_store_ids = [
        record["program_id"]
        for record in records
        if record.get("evaluation_cache", {}).get("status") == "stored"
    ]
    by_workspace: dict[str, list[dict]] = {}
    for record in records:
        by_workspace.setdefault(record["workspace_sha256"], []).append(record)
    duplicate_groups = [
        _duplicate_work_group(workspace_hash, group)
        for workspace_hash, group in sorted(by_workspace.items())
        if len(group) > 1
    ]
    generated_duplicate_ids = _unique_in_order(
        [
            program_id
            for group in duplicate_groups
            for program_id in group["generated_duplicate_program_ids"]
        ]
    )
    report = {
        "schema": "libreevolve.duplicate_work_policy_report.v1",
        "source": "runtime_history_workspace_hashes",
        "program_count": len(records),
        "generated_candidate_count": sum(
            1 for record in records if record["candidate_type"] == "generated"
        ),
        "unique_workspace_count": len(by_workspace),
        "duplicate_workspace_group_count": len(duplicate_groups),
        "duplicate_generated_candidate_count": len(generated_duplicate_ids),
        "duplicate_generated_program_ids": generated_duplicate_ids[:100],
        "duplicate_generated_program_ids_truncated": len(generated_duplicate_ids) > 100,
        "evaluation_cache_store_count": len(cache_store_ids),
        "evaluation_cache_hit_count": len(cache_hit_ids),
        "evaluation_cache_hit_program_ids": cache_hit_ids[:100],
        "evaluation_cache_hit_program_ids_truncated": len(cache_hit_ids) > 100,
        "records_limit": 100,
        "records_truncated": len(duplicate_groups) > 100,
        "duplicate_workspace_groups": duplicate_groups[:100],
        "evaluation_cache_policy": {
            "schema": "libreevolve.evaluation_cache_policy.v1",
            "candidate_id_policy": "deterministic_id_includes_workspace_hash",
            "workspace_hash_source": "CandidateWorkspace.files_primary_and_static_members",
            "pre_evaluation_duplicate_skip": True,
            "evaluation_result_reuse": True,
            "duplicate_observation_policy": (
                "diff_error_free_exact_workspace_cache_hits_reuse_prior_evaluator_result"
            ),
            "cache_key_scope": (
                "canonical_workspace_sha256_plus_evaluator_contract_sha256"
            ),
            "cache_eligibility": (
                "diff_error_must_be_absent; llm_feedback_and_plugin_scores_run_after_reuse"
            ),
            "budget_policy": (
                "cache_hits_emit_candidate_evaluation_cache_hit_events_and_do_not_"
                "consume_evaluator_call_budget"
            ),
            "cache_storage": "run_local_memory",
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_grade_duplicate_work_memory": False,
            "duplicate_detection_reported": bool(duplicate_groups),
            "run_local_cache_hit_reported": bool(cache_hit_ids),
            "run_local_evaluation_result_reuse": True,
            "remaining_gap": [
                "cross_run_workspace_hash_index",
                "durable_evaluation_cache_storage",
                "cache_replay_across_resume_boundaries",
                "semantic_near_duplicate_detection",
            ],
        },
    }
    report["validation"] = validate_duplicate_work_policy_report(report)
    return report


def _duplicate_work_program_record(program: Program) -> dict:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
    return {
        "program_id": program.id,
        "generation": program.generation,
        "parent_id": program.parent_id,
        "candidate_type": metadata.get("candidate_type", "seed"),
        "candidate_status": metadata.get("candidate_status"),
        "workspace_sha256": _workspace_sha256(program.workspace()),
        "fitness": program.fitness,
        "is_valid": evaluation.get("is_valid"),
        "evaluation_cache": (
            dict(metadata["evaluation_cache"])
            if isinstance(metadata.get("evaluation_cache"), Mapping)
            else {}
        ),
    }


def _duplicate_work_group(workspace_hash: str, records: list[dict]) -> dict:
    ordered = sorted(
        records,
        key=lambda record: (
            int(record.get("generation", 0))
            if isinstance(record.get("generation"), int)
            and not isinstance(record.get("generation"), bool)
            else 10**9,
            str(record.get("program_id", "")),
        ),
    )
    first = ordered[0]
    generated = [
        record
        for record in ordered
        if record.get("candidate_type") == "generated"
    ]
    generated_duplicates = [
        record
        for record in generated
        if record.get("program_id") != first.get("program_id")
    ]
    return {
        "workspace_sha256": workspace_hash,
        "program_count": len(ordered),
        "program_ids": [record["program_id"] for record in ordered],
        "first_program_id": first["program_id"],
        "first_candidate_type": first.get("candidate_type"),
        "generated_program_count": len(generated),
        "generated_duplicate_program_ids": [
            record["program_id"] for record in generated_duplicates
        ],
        "evaluated_again": any(
            record.get("evaluation_cache", {}).get("cache_hit") is not True
            for record in generated_duplicates
        ),
        "cache_hit_program_ids": [
            record["program_id"]
            for record in generated
            if record.get("evaluation_cache", {}).get("cache_hit") is True
        ],
        "records": ordered[:25],
        "records_truncated": len(ordered) > 25,
    }


def validate_duplicate_work_policy_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.duplicate_work_policy_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "duplicate-work policy report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "program_count",
        "generated_candidate_count",
        "unique_workspace_count",
        "duplicate_workspace_group_count",
        "duplicate_generated_candidate_count",
        "duplicate_generated_program_ids",
        "duplicate_generated_program_ids_truncated",
        "evaluation_cache_store_count",
        "evaluation_cache_hit_count",
        "evaluation_cache_hit_program_ids",
        "evaluation_cache_hit_program_ids_truncated",
        "records_limit",
        "records_truncated",
        "duplicate_workspace_groups",
        "evaluation_cache_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "duplicate-work policy report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.duplicate_work_policy_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "duplicate-work policy report schema is unsupported",
            }
        )
    if report.get("source") != "runtime_history_workspace_hashes":
        issues.append(
            {
                "code": "invalid_source",
                "message": "duplicate-work policy report source is unsupported",
            }
        )
    groups = report.get("duplicate_workspace_groups")
    if not isinstance(groups, list):
        issues.append(
            {
                "code": "invalid_duplicate_workspace_groups",
                "message": "duplicate_workspace_groups must be a list",
            }
        )
        groups = []
    duplicate_generated_ids: list[str] = []
    cache_hit_ids: list[str] = []
    for index, group in enumerate(groups):
        if not isinstance(group, dict):
            issues.append(
                {
                    "code": "invalid_duplicate_workspace_group",
                    "message": f"duplicate workspace group {index} must be an object",
                }
            )
            continue
        workspace_hash = group.get("workspace_sha256")
        if not _is_sha256_hex(workspace_hash):
            issues.append(
                {
                    "code": "invalid_workspace_hash",
                    "message": f"duplicate workspace group {index} hash is invalid",
                }
            )
        program_ids = group.get("program_ids")
        if not isinstance(program_ids, list) or len(program_ids) < 2 or any(
            not isinstance(program_id, str) or not program_id
            for program_id in program_ids
        ):
            issues.append(
                {
                    "code": "invalid_program_ids",
                    "message": (
                        f"duplicate workspace group {index} must include at least "
                        "two program ids"
                    ),
                }
            )
        if group.get("program_count") != (
            len(program_ids) if isinstance(program_ids, list) else None
        ):
            issues.append(
                {
                    "code": "invalid_program_count",
                    "message": (
                        f"duplicate workspace group {index} program_count must "
                        "match program_ids"
                    ),
                }
            )
        generated_ids = group.get("generated_duplicate_program_ids")
        if not isinstance(generated_ids, list) or any(
            not isinstance(program_id, str) or not program_id
            for program_id in generated_ids
        ):
            issues.append(
                {
                    "code": "invalid_generated_duplicate_ids",
                    "message": (
                        f"duplicate workspace group {index} generated duplicate "
                        "ids are invalid"
                    ),
                }
            )
        else:
            duplicate_generated_ids.extend(generated_ids)
        records = group.get("records")
        if not isinstance(records, list):
            issues.append(
                {
                    "code": "invalid_duplicate_records",
                    "message": f"duplicate workspace group {index} records must be a list",
                }
            )
        else:
            for record_index, record in enumerate(records):
                if not isinstance(record, dict):
                    issues.append(
                        {
                            "code": "invalid_duplicate_record",
                            "message": (
                                f"duplicate workspace group {index} record "
                                f"{record_index} must be an object"
                            ),
                        }
                    )
                    continue
                if record.get("workspace_sha256") != workspace_hash:
                    issues.append(
                        {
                            "code": "workspace_hash_mismatch",
                            "message": (
                                f"duplicate workspace group {index} record "
                                f"{record_index} hash must match group"
                            ),
                        }
                    )
                cache_record = record.get("evaluation_cache")
                if cache_record is not None and not isinstance(cache_record, dict):
                    issues.append(
                        {
                            "code": "invalid_evaluation_cache_record",
                            "message": (
                                f"duplicate workspace group {index} record "
                                f"{record_index} evaluation_cache must be an object"
                            ),
                        }
                    )
                elif isinstance(cache_record, dict):
                    if cache_record.get("cache_hit") is True:
                        program_id = record.get("program_id")
                        if isinstance(program_id, str):
                            cache_hit_ids.append(program_id)
                        if not _is_sha256_hex(cache_record.get("cache_key_sha256")):
                            issues.append(
                                {
                                    "code": "invalid_cache_key_hash",
                                    "message": (
                                        f"duplicate workspace group {index} record "
                                        f"{record_index} cache key is invalid"
                                    ),
                                }
                            )
        group_cache_hit_ids = group.get("cache_hit_program_ids")
        if not isinstance(group_cache_hit_ids, list) or any(
            not isinstance(program_id, str) or not program_id
            for program_id in group_cache_hit_ids
        ):
            issues.append(
                {
                    "code": "invalid_cache_hit_program_ids",
                    "message": (
                        f"duplicate workspace group {index} cache hit ids are invalid"
                    ),
                }
            )
    if report.get("records_truncated") is not True:
        if report.get("duplicate_workspace_group_count") != len(groups):
            issues.append(
                {
                    "code": "invalid_duplicate_group_count",
                    "message": (
                        "duplicate_workspace_group_count must match group records"
                    ),
                }
            )
    duplicate_generated_ids = _unique_in_order(duplicate_generated_ids)
    cache_hit_ids = _unique_in_order(cache_hit_ids)
    if report.get("duplicate_generated_program_ids_truncated") is not True:
        if report.get("duplicate_generated_program_ids") != duplicate_generated_ids:
            issues.append(
                {
                    "code": "invalid_duplicate_generated_ids",
                    "message": (
                        "duplicate_generated_program_ids must match group records"
                    ),
                }
            )
    if report.get("duplicate_generated_candidate_count") != len(duplicate_generated_ids):
        issues.append(
            {
                "code": "invalid_duplicate_generated_count",
                "message": (
                    "duplicate_generated_candidate_count must match group records"
                ),
            }
        )
    if report.get("evaluation_cache_hit_program_ids_truncated") is not True:
        if report.get("evaluation_cache_hit_program_ids") != cache_hit_ids:
            issues.append(
                {
                    "code": "invalid_cache_hit_program_ids",
                    "message": (
                        "evaluation_cache_hit_program_ids must match group records"
                    ),
                }
            )
    if report.get("evaluation_cache_hit_count") != len(cache_hit_ids):
        issues.append(
            {
                "code": "invalid_cache_hit_count",
                "message": "evaluation_cache_hit_count must match group records",
            }
        )
    store_count = report.get("evaluation_cache_store_count")
    if isinstance(store_count, bool) or not isinstance(store_count, int) or store_count < 0:
        issues.append(
            {
                "code": "invalid_cache_store_count",
                "message": "evaluation_cache_store_count must be a non-negative integer",
            }
        )
    policy = report.get("evaluation_cache_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_evaluation_cache_policy",
                "message": "evaluation_cache_policy must be an object",
            }
        )
    else:
        if policy.get("pre_evaluation_duplicate_skip") is not True:
            issues.append(
                {
                    "code": "invalid_duplicate_skip_policy",
                    "message": "current duplicate skip policy must be true",
                }
            )
        if policy.get("evaluation_result_reuse") is not True:
            issues.append(
                {
                    "code": "invalid_result_reuse_policy",
                    "message": "current evaluation result reuse policy must be true",
                }
            )
        if policy.get("cache_storage") != "run_local_memory":
            issues.append(
                {
                    "code": "invalid_cache_storage",
                    "message": "cache storage must be run_local_memory",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "duplicate-work policy report must not claim cache parity",
            }
        )
    return {
        "schema": "libreevolve.duplicate_work_policy_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _sampling_balance_report(
    startup_manifest: Mapping[str, object],
    programs: list[Program],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    generated_records = [
        _sampling_balance_candidate_record(program)
        for program in programs
        if _program_candidate_type(program) == "generated"
    ]
    parent_strategy_counts: dict[str, int] = {}
    inspiration_strategy_counts: dict[str, int] = {}
    inspiration_source_counts: dict[str, int] = {}
    inspiration_selected_total = 0
    metric_target_counts: dict[str, int] = {}
    frontier_decision_count = 0
    lineage_decision_count = 0
    generation_records: dict[int, dict] = {}
    for record in generated_records:
        parent_strategy = record["parent_strategy"]
        _increment_count(parent_strategy_counts, parent_strategy)
        inspiration_strategy = record["inspiration_strategy"]
        _increment_count(inspiration_strategy_counts, inspiration_strategy)
        _increment_count(inspiration_source_counts, record["inspiration_strategy_source"])
        selected_count = record["inspiration_selected_count"]
        inspiration_selected_total += selected_count
        for metric in record["parent_target_metrics"]:
            _increment_count(metric_target_counts, metric)
        for metric in record["inspiration_target_metrics"]:
            _increment_count(metric_target_counts, metric)
        if record["parent_frontier"]:
            frontier_decision_count += 1
        if record["inspiration_frontier"]:
            frontier_decision_count += 1
        if record["parent_lineage"]:
            lineage_decision_count += 1
        if record["inspiration_lineage"]:
            lineage_decision_count += 1
        generation = record["loop_generation_index"]
        generation_record = generation_records.setdefault(
            generation,
            {
                "loop_generation_index": generation,
                "candidate_count": 0,
                "parent_strategy_counts": {},
                "inspiration_strategy_counts": {},
                "inspiration_selected_total": 0,
            },
        )
        generation_record["candidate_count"] += 1
        _increment_count(generation_record["parent_strategy_counts"], parent_strategy)
        _increment_count(
            generation_record["inspiration_strategy_counts"],
            inspiration_strategy,
        )
        generation_record["inspiration_selected_total"] += selected_count
    configured_parent_strategy = str(config.get("parent_selection_strategy", "mixed"))
    configured_inspiration_strategy = str(config.get("inspiration_strategy", "mixed"))
    explore_ratio = _sampling_balance_float(config.get("explore_ratio"))
    mixed_parent_decision_count = 0
    if configured_parent_strategy == "mixed":
        mixed_parent_decision_count = sum(
            parent_strategy_counts.get(strategy, 0)
            for strategy in ("explore", "exploit")
        )
    report = {
        "schema": "libreevolve.sampling_balance_report.v1",
        "source": "history_program_metadata_parent_and_inspiration_selection",
        "configured_parent_selection_strategy": configured_parent_strategy,
        "configured_explore_ratio": explore_ratio,
        "configured_inspiration_strategy": configured_inspiration_strategy,
        "generated_candidate_count": len(generated_records),
        "parent_strategy_counts": dict(sorted(parent_strategy_counts.items())),
        "inspiration_strategy_counts": dict(sorted(inspiration_strategy_counts.items())),
        "inspiration_strategy_source_counts": dict(
            sorted(inspiration_source_counts.items())
        ),
        "mixed_parent_decision_count": mixed_parent_decision_count,
        "mixed_parent_explore_count": parent_strategy_counts.get("explore", 0)
        if configured_parent_strategy == "mixed"
        else 0,
        "mixed_parent_exploit_count": parent_strategy_counts.get("exploit", 0)
        if configured_parent_strategy == "mixed"
        else 0,
        "inspiration_requested_total": sum(
            record["inspiration_requested_count"] for record in generated_records
        ),
        "inspiration_selected_total": inspiration_selected_total,
        "metric_target_counts": dict(sorted(metric_target_counts.items())),
        "frontier_selection_decision_count": frontier_decision_count,
        "lineage_selection_decision_count": lineage_decision_count,
        "generation_records": [
            generation_records[index]
            for index in sorted(generation_records)
        ][:100],
        "generation_records_limit": 100,
        "generation_records_truncated": len(generation_records) > 100,
        "sample_records": generated_records[:100],
        "sample_records_limit": 100,
        "sample_records_truncated": len(generated_records) > 100,
        "balance_policy": {
            "schema": "libreevolve.sampling_balance_policy.v1",
            "parent_decision_source": "metadata.parent_selection.strategy",
            "inspiration_decision_source": "metadata.inspiration_selection.strategy",
            "mixed_parent_policy": (
                "config.explore_ratio_drives_explore_vs_exploit_decisions"
            ),
            "calibration_status": "observed_current_run_counts_not_equal_budget_ablation",
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_grade_sampling_balance": False,
            "observed_decision_counts": bool(generated_records),
            "remaining_gap": [
                "equal_budget_sampling_strategy_comparison",
                "per_strategy_score_improvement_analysis",
                "diversity_retention_effect_analysis",
                "cross_run_sampling_balance_calibration",
            ],
        },
    }
    report["validation"] = validate_sampling_balance_report(report)
    return report


def _sampling_balance_candidate_record(program: Program) -> dict:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    parent = (
        metadata.get("parent_selection")
        if isinstance(metadata.get("parent_selection"), Mapping)
        else {}
    )
    inspiration = (
        metadata.get("inspiration_selection")
        if isinstance(metadata.get("inspiration_selection"), Mapping)
        else {}
    )
    loop_generation_index = metadata.get("loop_generation_index")
    if (
        isinstance(loop_generation_index, bool)
        or not isinstance(loop_generation_index, int)
    ):
        loop_generation_index = program.generation
    return {
        "program_id": program.id,
        "generation": program.generation,
        "loop_generation_index": loop_generation_index,
        "parent_id": program.parent_id,
        "parent_strategy": _sampling_balance_label(parent.get("strategy")),
        "parent_target_metrics": _sampling_balance_target_metrics(parent),
        "parent_frontier": isinstance(parent.get("frontier_size"), int),
        "parent_lineage": isinstance(parent.get("lineage_root_id"), str),
        "inspiration_strategy": _sampling_balance_label(inspiration.get("strategy")),
        "inspiration_strategy_source": _sampling_balance_label(
            inspiration.get("strategy_source")
        ),
        "inspiration_requested_count": _sampling_balance_int(
            inspiration.get("requested_count")
        ),
        "inspiration_selected_count": _sampling_balance_int(
            inspiration.get("selected_count")
        ),
        "inspiration_target_metrics": _sampling_balance_target_metrics(inspiration),
        "inspiration_frontier": isinstance(inspiration.get("frontier_size"), int),
        "inspiration_lineage": isinstance(inspiration.get("lineages"), list),
    }


def _program_candidate_type(program: Program) -> str:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    value = metadata.get("candidate_type")
    return value if isinstance(value, str) and value else "seed"


def _sampling_balance_label(value: object) -> str:
    return value if isinstance(value, str) and value else "unknown"


def _sampling_balance_int(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        return 0
    return max(0, value)


def _sampling_balance_float(value: object) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    numeric = float(value)
    return numeric if math.isfinite(numeric) else None


def _sampling_balance_target_metrics(selection: Mapping[str, object]) -> list[str]:
    metrics: list[str] = []
    target = selection.get("target_metric")
    if isinstance(target, str) and target:
        metrics.append(target)
    targets = selection.get("target_metrics")
    if isinstance(targets, list):
        for record in targets:
            if not isinstance(record, Mapping):
                continue
            metric = record.get("metric")
            if isinstance(metric, str) and metric:
                metrics.append(metric)
    return _unique_in_order(metrics)


def _increment_count(counts: dict[str, int], key: str) -> None:
    counts[key] = counts.get(key, 0) + 1


def validate_sampling_balance_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.sampling_balance_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "sampling-balance report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "configured_parent_selection_strategy",
        "configured_explore_ratio",
        "configured_inspiration_strategy",
        "generated_candidate_count",
        "parent_strategy_counts",
        "inspiration_strategy_counts",
        "inspiration_strategy_source_counts",
        "mixed_parent_decision_count",
        "mixed_parent_explore_count",
        "mixed_parent_exploit_count",
        "inspiration_requested_total",
        "inspiration_selected_total",
        "metric_target_counts",
        "frontier_selection_decision_count",
        "lineage_selection_decision_count",
        "generation_records",
        "generation_records_limit",
        "generation_records_truncated",
        "sample_records",
        "sample_records_limit",
        "sample_records_truncated",
        "balance_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"sampling-balance report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.sampling_balance_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "sampling-balance report schema is unsupported",
            }
        )
    if (
        report.get("source")
        != "history_program_metadata_parent_and_inspiration_selection"
    ):
        issues.append(
            {
                "code": "invalid_source",
                "message": "sampling-balance report source is unsupported",
            }
        )
    sample_records = report.get("sample_records")
    if not isinstance(sample_records, list):
        issues.append(
            {"code": "invalid_sample_records", "message": "sample_records must be a list"}
        )
        sample_records = []
    parent_counts = report.get("parent_strategy_counts")
    if not isinstance(parent_counts, dict):
        issues.append(
            {
                "code": "invalid_parent_strategy_counts",
                "message": "parent_strategy_counts must be an object",
            }
        )
        parent_counts = {}
    inspiration_counts = report.get("inspiration_strategy_counts")
    if not isinstance(inspiration_counts, dict):
        issues.append(
            {
                "code": "invalid_inspiration_strategy_counts",
                "message": "inspiration_strategy_counts must be an object",
            }
        )
        inspiration_counts = {}
    requested_total = 0
    selected_total = 0
    observed_parent_counts: dict[str, int] = {}
    observed_inspiration_counts: dict[str, int] = {}
    for index, record in enumerate(sample_records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_sample_record",
                    "message": f"sample record {index} must be an object",
                }
            )
            continue
        if not isinstance(record.get("program_id"), str) or not record.get("program_id"):
            issues.append(
                {
                    "code": "invalid_program_id",
                    "message": f"sample record {index} program_id is invalid",
                }
            )
        parent_strategy = record.get("parent_strategy")
        inspiration_strategy = record.get("inspiration_strategy")
        if not isinstance(parent_strategy, str) or not parent_strategy:
            issues.append(
                {
                    "code": "invalid_parent_strategy",
                    "message": f"sample record {index} parent_strategy is invalid",
                }
            )
            parent_strategy = "unknown"
        if not isinstance(inspiration_strategy, str) or not inspiration_strategy:
            issues.append(
                {
                    "code": "invalid_inspiration_strategy",
                    "message": f"sample record {index} inspiration_strategy is invalid",
                }
            )
            inspiration_strategy = "unknown"
        _increment_count(observed_parent_counts, parent_strategy)
        _increment_count(observed_inspiration_counts, inspiration_strategy)
        requested = record.get("inspiration_requested_count")
        selected = record.get("inspiration_selected_count")
        if isinstance(requested, bool) or not isinstance(requested, int) or requested < 0:
            issues.append(
                {
                    "code": "invalid_requested_count",
                    "message": f"sample record {index} requested count is invalid",
                }
            )
            requested = 0
        if isinstance(selected, bool) or not isinstance(selected, int) or selected < 0:
            issues.append(
                {
                    "code": "invalid_selected_count",
                    "message": f"sample record {index} selected count is invalid",
                }
            )
            selected = 0
        requested_total += requested
        selected_total += selected
    if report.get("sample_records_truncated") is not True:
        if report.get("generated_candidate_count") != len(sample_records):
            issues.append(
                {
                    "code": "invalid_generated_candidate_count",
                    "message": "generated_candidate_count must match sample records",
                }
            )
        if dict(sorted(observed_parent_counts.items())) != parent_counts:
            issues.append(
                {
                    "code": "invalid_parent_strategy_count_values",
                    "message": "parent_strategy_counts must match sample records",
                }
            )
        if dict(sorted(observed_inspiration_counts.items())) != inspiration_counts:
            issues.append(
                {
                    "code": "invalid_inspiration_strategy_count_values",
                    "message": "inspiration_strategy_counts must match sample records",
                }
            )
        if report.get("inspiration_requested_total") != requested_total:
            issues.append(
                {
                    "code": "invalid_requested_total",
                    "message": "inspiration_requested_total must match sample records",
                }
            )
        if report.get("inspiration_selected_total") != selected_total:
            issues.append(
                {
                    "code": "invalid_selected_total",
                    "message": "inspiration_selected_total must match sample records",
                }
            )
    for field in (
        "mixed_parent_decision_count",
        "mixed_parent_explore_count",
        "mixed_parent_exploit_count",
        "frontier_selection_decision_count",
        "lineage_selection_decision_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    ratio = report.get("configured_explore_ratio")
    if ratio is not None and (
        isinstance(ratio, bool)
        or not isinstance(ratio, (int, float))
        or not math.isfinite(float(ratio))
        or not 0.0 <= float(ratio) <= 1.0
    ):
        issues.append(
            {
                "code": "invalid_configured_explore_ratio",
                "message": "configured_explore_ratio must be null or [0, 1]",
            }
        )
    if not isinstance(report.get("balance_policy"), dict):
        issues.append(
            {
                "code": "invalid_balance_policy",
                "message": "balance_policy must be an object",
            }
        )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "sampling-balance report must not claim calibration parity",
            }
        )
    return {
        "schema": "libreevolve.sampling_balance_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _automated_evaluator_scope_report(
    startup_manifest: Mapping[str, object],
    programs: list[Program],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    evaluator_sources = (
        problem.get("evaluator_sources")
        if isinstance(problem.get("evaluator_sources"), list)
        else []
    )
    eval_stages = (
        config.get("eval_stages")
        if isinstance(config.get("eval_stages"), list)
        else []
    )
    llm_feedback = (
        config.get("llm_feedback")
        if isinstance(config.get("llm_feedback"), list)
        else []
    )
    runtime = _automated_evaluator_runtime_summary(programs)
    evaluator_records = _automated_evaluator_records(evaluator_sources, eval_stages)
    report = {
        "schema": "libreevolve.automated_evaluator_scope_report.v1",
        "source": "startup_manifest_and_runtime_history",
        "automated_evaluator_available": bool(evaluator_records),
        "evaluator_record_count": len(evaluator_records),
        "evaluator_records": evaluator_records,
        "configured_stage_count": len(eval_stages),
        "configured_llm_feedback_count": len(llm_feedback),
        "runtime_summary": runtime,
        "machine_feedback_policy": {
            "schema": "libreevolve.machine_feedback_scope_policy.v1",
            "candidate_validity_owner": "deterministic_evaluator_cascade",
            "candidate_score_owner": "declared_evaluator_metrics_and_plugin_composition",
            "llm_feedback_role": "post_evaluator_optional_grader_not_primary_validity_gate",
            "manual_experiment_role": "not_supported_for_candidate_admission",
            "manual_experiment_candidate_feedback": False,
            "llm_only_idea_review_candidate_feedback": False,
            "transition_to_executable_code_required": True,
        },
        "manual_experiment_boundary": {
            "status": "excluded_from_current_candidate_evaluation_scope",
            "reason": (
                "candidate admission requires evaluator execution metadata and "
                "does not accept manual experiment outcomes as primary feedback"
            ),
        },
        "llm_only_idea_feedback_boundary": {
            "status": (
                "post_evaluator_feedback_only"
                if llm_feedback
                else "not_configured"
            ),
            "configured_count": len(llm_feedback),
            "runtime_record_count": runtime["llm_feedback_record_count"],
            "primary_validity_gate": False,
        },
        "environment_readiness": {
            "problem_local_evaluator_sources": len(evaluator_sources),
            "configured_evaluator_stages": len(eval_stages),
            "runtime_evaluated_candidate_count": runtime["evaluated_program_count"],
            "runtime_valid_candidate_count": runtime["valid_count"],
            "robust_environment_fixture": False,
            "manual_experiment_fixture": False,
            "environment_scaling_evidence": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_automated_evaluator_scope": bool(evaluator_records),
            "manual_experiment_exclusion_recorded": True,
            "llm_only_feedback_boundary_recorded": True,
            "remaining_gap": [
                "benchmark_environment_readiness_fixtures",
                "manual_experiment_to_code_transition_policy",
                "llm_only_idea_feedback_stage_contract",
                "robust_evaluator_environment_scaling_evidence",
            ],
        },
    }
    report["validation"] = validate_automated_evaluator_scope_report(report)
    return report


def _qualitative_feedback_policy_report(
    startup_manifest: Mapping[str, object],
    programs: list[Program],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    llm_feedback = (
        config.get("llm_feedback")
        if isinstance(config.get("llm_feedback"), list)
        else []
    )
    runtime_counts = _qualitative_feedback_runtime_counts(programs)
    records = [
        _qualitative_feedback_policy_record(index, grader, runtime_counts)
        for index, grader in enumerate(llm_feedback)
        if isinstance(grader, Mapping)
    ]
    configured_policy_count = sum(1 for record in records if record["configured"])
    complete_policy_count = sum(
        1 for record in records if record["complete_for_current_policy"] is True
    )
    report = {
        "schema": "libreevolve.qualitative_feedback_policy_report.v1",
        "source": "startup_manifest_config_and_runtime_history",
        "configured_llm_feedback_count": len(llm_feedback),
        "configured_qualitative_policy_count": configured_policy_count,
        "complete_policy_count": complete_policy_count,
        "observed_feedback_record_count": sum(runtime_counts.values()),
        "records": records,
        "policy": {
            "schema": "libreevolve.qualitative_feedback_policy.v1",
            "criterion_metadata_required_for_claim": True,
            "evaluator_gap_rationale_required_for_claim": True,
            "rubric_or_prompt_hash_required_for_claim": True,
            "score_or_discard_intent_required_for_claim": True,
            "calibration_or_task_suite_required_for_claim": True,
            "prompt_history_linkage": "evaluation.metadata.llm_feedback",
            "paper_claim_ready": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_qualitative_feedback_criteria": complete_policy_count > 0,
            "reason": (
                "qualitative feedback criteria can now be declared and observed, "
                "but calibration/task-suite evidence and prompt-history audits "
                "are not yet sufficient for AlphaEvolve-style qualitative "
                "feedback claims"
            ),
            "remaining_gap": [
                "calibration_or_task_suite_linkage",
                "prompt_history_row_linkage",
                "criterion_quality_ablation",
            ],
        },
    }
    report["validation"] = validate_qualitative_feedback_policy_report(report)
    return report


def _qualitative_feedback_runtime_counts(programs: list[Program]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        metadata = evaluation.get("metadata") if isinstance(evaluation.get("metadata"), dict) else {}
        records = metadata.get("llm_feedback")
        if not isinstance(records, list):
            continue
        for record in records:
            if not isinstance(record, Mapping):
                continue
            name = record.get("name")
            if isinstance(name, str):
                counts[name] = counts.get(name, 0) + 1
    return counts


def _qualitative_feedback_policy_record(
    index: int,
    grader: Mapping[str, object],
    runtime_counts: Mapping[str, int],
) -> dict:
    name = str(grader.get("name", f"feedback_{index}"))
    metric = grader.get("metric", f"llm_{name}")
    criterion = grader.get("criterion", name)
    description = grader.get("criterion_description")
    rationale = grader.get("evaluator_gap_rationale")
    rubric = grader.get("rubric")
    prompt = grader.get("prompt")
    intent = grader.get("feedback_intent")
    if not isinstance(intent, str):
        if _finite_json_number(grader.get("weight")) and grader.get("min_score") is not None:
            intent = "score_and_discard"
        elif grader.get("min_score") is not None:
            intent = "discard"
        else:
            intent = "score"
    configured = any(
        key in grader
        for key in (
            "criterion",
            "criterion_description",
            "evaluator_gap_rationale",
            "rubric",
            "feedback_intent",
            "calibration_report_id",
        )
    )
    required_fields = {
        "criterion_description": isinstance(description, str) and bool(description.strip()),
        "evaluator_gap_rationale": isinstance(rationale, str) and bool(rationale.strip()),
        "rubric_or_prompt": (
            isinstance(rubric, str)
            and bool(rubric.strip())
            or isinstance(prompt, str)
            and bool(prompt.strip())
        ),
        "feedback_intent": intent in {"score", "discard", "score_and_discard"},
        "metric_linkage": isinstance(metric, str) and bool(metric),
    }
    calibration_report_id = grader.get("calibration_report_id")
    return {
        "feedback_id": f"llm_feedback:{name}",
        "configured_index": index,
        "configured": configured,
        "criterion": criterion if isinstance(criterion, str) else name,
        "criterion_description_present": required_fields["criterion_description"],
        "evaluator_gap_rationale_present": required_fields["evaluator_gap_rationale"],
        "rubric_sha256": _text_sha256(rubric if isinstance(rubric, str) else None),
        "prompt_sha256": _text_sha256(prompt if isinstance(prompt, str) else None),
        "feedback_intent": intent,
        "metric": metric if isinstance(metric, str) else None,
        "objective_metric": grader.get("objective_metric") is True,
        "calibration_report_id": (
            calibration_report_id if isinstance(calibration_report_id, str) else None
        ),
        "required_fields_present": required_fields,
        "complete_for_current_policy": all(required_fields.values()),
        "runtime_record_count": int(runtime_counts.get(name, 0)),
        "prompt_feedback_linkage": "evaluation.metadata.llm_feedback",
    }


def _text_sha256(value: str | None) -> str | None:
    if not value:
        return None
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _automated_evaluator_records(
    evaluator_sources: list,
    eval_stages: list,
) -> list[dict]:
    records: list[dict] = []
    if eval_stages:
        source_by_stage = _evaluator_source_by_stage(evaluator_sources)
        for index, stage in enumerate(eval_stages):
            if not isinstance(stage, Mapping):
                continue
            name = str(stage.get("name", f"stage_{index}"))
            mode = str(stage.get("mode", "external_validator"))
            source = source_by_stage.get((index, name), {})
            records.append(
                {
                    "evaluator_id": f"stage:{name}",
                    "stage_index": index,
                    "stage_name": name,
                    "mode": mode,
                    "automated": True,
                    "manual_experiment": False,
                    "candidate_feedback_channel": "machine_evaluator_execution",
                    "source": _evaluator_oracle_source_ref(source),
                }
            )
    else:
        source = _default_evaluator_source(evaluator_sources)
        records.append(
            {
                "evaluator_id": "evaluator:default",
                "stage_index": None,
                "stage_name": None,
                "mode": "external_validator",
                "automated": True,
                "manual_experiment": False,
                "candidate_feedback_channel": "machine_evaluator_execution",
                "source": _evaluator_oracle_source_ref(source),
            }
        )
    return records


def _automated_evaluator_runtime_summary(programs: list[Program]) -> dict:
    evaluated_program_count = 0
    generated_evaluated_count = 0
    valid_count = 0
    invalid_count = 0
    configured_stage_result_count = 0
    llm_feedback_record_count = 0
    manual_feedback_record_count = 0
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        if not evaluation:
            continue
        evaluated_program_count += 1
        if _program_candidate_type(program) == "generated":
            generated_evaluated_count += 1
        if evaluation.get("is_valid") is True:
            valid_count += 1
        elif evaluation.get("is_valid") is False:
            invalid_count += 1
        metadata = (
            evaluation.get("metadata")
            if isinstance(evaluation.get("metadata"), Mapping)
            else {}
        )
        configured = metadata.get("configured_stage_results")
        if isinstance(configured, list):
            configured_stage_result_count += sum(
                1 for item in configured if isinstance(item, Mapping)
            )
        feedback = metadata.get("llm_feedback")
        if isinstance(feedback, list):
            llm_feedback_record_count += sum(
                1 for item in feedback if isinstance(item, Mapping)
            )
        manual = metadata.get("manual_feedback")
        if isinstance(manual, list):
            manual_feedback_record_count += sum(
                1 for item in manual if isinstance(item, Mapping)
            )
    return {
        "evaluated_program_count": evaluated_program_count,
        "generated_evaluated_count": generated_evaluated_count,
        "valid_count": valid_count,
        "invalid_count": invalid_count,
        "configured_stage_result_count": configured_stage_result_count,
        "llm_feedback_record_count": llm_feedback_record_count,
        "manual_feedback_record_count": manual_feedback_record_count,
        "manual_feedback_primary_gate_count": 0,
    }


def validate_qualitative_feedback_policy_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.qualitative_feedback_policy_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "qualitative feedback policy report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "configured_llm_feedback_count",
        "configured_qualitative_policy_count",
        "complete_policy_count",
        "observed_feedback_record_count",
        "records",
        "policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "qualitative feedback policy report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.qualitative_feedback_policy_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "qualitative feedback policy report schema is unsupported",
            }
        )
    if report.get("source") != "startup_manifest_config_and_runtime_history":
        issues.append(
            {
                "code": "invalid_source",
                "message": "qualitative feedback policy report source is unsupported",
            }
        )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append(
            {
                "code": "invalid_records",
                "message": "qualitative feedback policy records must be a list",
            }
        )
        records = []
    configured = 0
    complete = 0
    observed = 0
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_record",
                    "message": f"qualitative feedback policy record {index} must be an object",
                }
            )
            continue
        if not isinstance(record.get("feedback_id"), str) or not record.get("feedback_id"):
            issues.append(
                {
                    "code": "invalid_feedback_id",
                    "message": f"qualitative feedback policy record {index} feedback_id must be text",
                }
            )
        if record.get("configured") is True:
            configured += 1
        if record.get("complete_for_current_policy") is True:
            complete += 1
        runtime_count = record.get("runtime_record_count")
        if isinstance(runtime_count, int) and not isinstance(runtime_count, bool) and runtime_count >= 0:
            observed += runtime_count
        else:
            issues.append(
                {
                    "code": "invalid_runtime_record_count",
                    "message": f"qualitative feedback policy record {index} runtime count must be non-negative",
                }
            )
        if not isinstance(record.get("required_fields_present"), dict):
            issues.append(
                {
                    "code": "invalid_required_fields_present",
                    "message": f"qualitative feedback policy record {index} required_fields_present must be an object",
                }
            )
    _validate_report_count(
        report,
        "configured_llm_feedback_count",
        len(records),
        issues,
    )
    _validate_report_count(
        report,
        "configured_qualitative_policy_count",
        configured,
        issues,
    )
    _validate_report_count(report, "complete_policy_count", complete, issues)
    _validate_report_count(
        report,
        "observed_feedback_record_count",
        observed,
        issues,
    )
    policy = report.get("policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_policy",
                "message": "qualitative feedback policy must be an object",
            }
        )
    else:
        if policy.get("schema") != "libreevolve.qualitative_feedback_policy.v1":
            issues.append(
                {
                    "code": "invalid_policy_schema",
                    "message": "qualitative feedback policy schema is unsupported",
                }
            )
        if policy.get("paper_claim_ready") is not False:
            issues.append(
                {
                    "code": "qualitative_feedback_overclaim",
                    "message": "qualitative feedback policy must not claim paper readiness",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "claim_ready_overclaim",
                "message": "qualitative feedback report must not claim AlphaEvolve readiness",
            }
        )
    return {
        "schema": "libreevolve.qualitative_feedback_policy_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def validate_automated_evaluator_scope_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.automated_evaluator_scope_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "automated evaluator scope report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "automated_evaluator_available",
        "evaluator_record_count",
        "evaluator_records",
        "configured_stage_count",
        "configured_llm_feedback_count",
        "runtime_summary",
        "machine_feedback_policy",
        "manual_experiment_boundary",
        "llm_only_idea_feedback_boundary",
        "environment_readiness",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "automated evaluator scope report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.automated_evaluator_scope_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "automated evaluator scope report schema is unsupported",
            }
        )
    if report.get("source") != "startup_manifest_and_runtime_history":
        issues.append(
            {
                "code": "invalid_source",
                "message": "automated evaluator scope report source is unsupported",
            }
        )
    records = report.get("evaluator_records")
    if not isinstance(records, list):
        issues.append(
            {"code": "invalid_evaluator_records", "message": "evaluator_records must be a list"}
        )
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_evaluator_record",
                    "message": f"evaluator record {index} must be an object",
                }
            )
            continue
        if not isinstance(record.get("evaluator_id"), str) or not record.get("evaluator_id"):
            issues.append(
                {
                    "code": "invalid_evaluator_id",
                    "message": f"evaluator record {index} evaluator_id is invalid",
                }
            )
        if record.get("automated") is not True:
            issues.append(
                {
                    "code": "invalid_automated_flag",
                    "message": f"evaluator record {index} must be automated",
                }
            )
        if record.get("manual_experiment") is not False:
            issues.append(
                {
                    "code": "invalid_manual_experiment_flag",
                    "message": (
                        f"evaluator record {index} must not be manual experiment"
                    ),
                }
            )
    if report.get("evaluator_record_count") != len(records):
        issues.append(
            {
                "code": "invalid_evaluator_record_count",
                "message": "evaluator_record_count must match evaluator_records",
            }
        )
    if report.get("automated_evaluator_available") != bool(records):
        issues.append(
            {
                "code": "invalid_automated_evaluator_available",
                "message": "automated_evaluator_available must match evaluator_records",
            }
        )
    runtime = report.get("runtime_summary")
    if not isinstance(runtime, dict):
        issues.append(
            {"code": "invalid_runtime_summary", "message": "runtime_summary must be an object"}
        )
        runtime = {}
    for field in (
        "evaluated_program_count",
        "generated_evaluated_count",
        "valid_count",
        "invalid_count",
        "configured_stage_result_count",
        "llm_feedback_record_count",
        "manual_feedback_record_count",
        "manual_feedback_primary_gate_count",
    ):
        value = runtime.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"runtime_summary.{field} must be a non-negative integer",
                }
            )
    policy = report.get("machine_feedback_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_machine_feedback_policy",
                "message": "machine_feedback_policy must be an object",
            }
        )
    else:
        if policy.get("manual_experiment_candidate_feedback") is not False:
            issues.append(
                {
                    "code": "invalid_manual_feedback_policy",
                    "message": "manual experiment candidate feedback must be false",
                }
            )
        if policy.get("llm_only_idea_review_candidate_feedback") is not False:
            issues.append(
                {
                    "code": "invalid_llm_only_feedback_policy",
                    "message": "LLM-only idea review candidate feedback must be false",
                }
            )
        if policy.get("transition_to_executable_code_required") is not True:
            issues.append(
                {
                    "code": "invalid_transition_policy",
                    "message": "transition to executable code must be required",
                }
            )
    manual_boundary = report.get("manual_experiment_boundary")
    if (
        not isinstance(manual_boundary, dict)
        or manual_boundary.get("status")
        != "excluded_from_current_candidate_evaluation_scope"
    ):
        issues.append(
            {
                "code": "invalid_manual_boundary",
                "message": "manual experiment boundary is invalid",
            }
        )
    llm_boundary = report.get("llm_only_idea_feedback_boundary")
    if not isinstance(llm_boundary, dict):
        issues.append(
            {
                "code": "invalid_llm_feedback_boundary",
                "message": "llm_only_idea_feedback_boundary must be an object",
            }
        )
    elif llm_boundary.get("primary_validity_gate") is not False:
        issues.append(
            {
                "code": "invalid_llm_feedback_primary_gate",
                "message": "LLM feedback must not be primary validity gate",
            }
        )
    readiness = report.get("environment_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_environment_readiness",
                "message": "environment_readiness must be an object",
            }
        )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "automated evaluator scope report must not claim full readiness",
            }
        )
    return {
        "schema": "libreevolve.automated_evaluator_scope_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _programmatic_representation_boundary_report(
    startup_manifest: Mapping[str, object],
    programs: list[Program],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    problem = (
        startup_manifest.get("problem")
        if isinstance(startup_manifest.get("problem"), Mapping)
        else {}
    )
    objective_schema = (
        problem.get("objective_schema")
        if isinstance(problem.get("objective_schema"), Mapping)
        else {}
    )
    metric_names = _programmatic_boundary_metric_names(objective_schema)
    records = _programmatic_boundary_records(programs)
    proposal_field_counts = {field: 0 for field in ("idea", "rationale", "hypothesis")}
    natural_language_proposal_count = 0
    generated_candidate_count = 0
    executable_generated_count = 0
    evaluated_generated_count = 0
    valid_generated_count = 0
    llm_feedback_record_count = 0
    max_generation = 0
    for program in programs:
        max_generation = max(max_generation, program.generation)
        if _program_candidate_type(program) != "generated":
            continue
        generated_candidate_count += 1
        if isinstance(program.code, str) and program.code:
            executable_generated_count += 1
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        if evaluation:
            evaluated_generated_count += 1
            if evaluation.get("is_valid") is True:
                valid_generated_count += 1
            metadata = (
                evaluation.get("metadata")
                if isinstance(evaluation.get("metadata"), Mapping)
                else {}
            )
            feedback = metadata.get("llm_feedback")
            if isinstance(feedback, list):
                llm_feedback_record_count += sum(
                    1 for item in feedback if isinstance(item, Mapping)
                )
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        proposal = (
            metadata.get("proposal")
            if isinstance(metadata.get("proposal"), Mapping)
            else {}
        )
        captured_any = False
        for field in proposal_field_counts:
            value = proposal.get(field)
            if isinstance(value, str) and value:
                proposal_field_counts[field] += 1
                captured_any = True
        if captured_any:
            natural_language_proposal_count += 1
    report = {
        "schema": "libreevolve.programmatic_representation_boundary_report.v1",
        "source": "startup_manifest_and_runtime_history",
        "candidate_representation": {
            "kind": "executable_code_workspace",
            "primary_language_policy": "python_primary_text_workspace",
            "natural_language_candidate": False,
            "generated_candidate_count": generated_candidate_count,
            "executable_generated_count": executable_generated_count,
        },
        "natural_language_artifacts": {
            "role": "proposal_metadata_context_not_candidate_representation",
            "capture_configured": config.get("capture_proposal_metadata") is True,
            "proposal_record_count": natural_language_proposal_count,
            "proposal_field_counts": proposal_field_counts,
            "candidate_code_contains_proposal_preamble": False,
        },
        "programmatic_evaluation_criteria": {
            "role": "declared_evaluator_metrics_and_validity_gate",
            "metric_names": metric_names,
            "metric_count": len(metric_names),
            "evaluated_generated_count": evaluated_generated_count,
            "valid_generated_count": valid_generated_count,
            "primary_validity_gate": "deterministic_evaluator_cascade",
        },
        "feedback_boundary": {
            "llm_feedback_record_count": llm_feedback_record_count,
            "llm_feedback_role": "post_evaluator_optional_grader_not_candidate_representation",
            "llm_feedback_primary_validity_gate": False,
        },
        "runtime_step_scope": {
            "max_generation_observed": max_generation,
            "long_horizon_evidence": False,
            "scope": "current_run_generation_count_only",
        },
        "boundary_policy": {
            "schema": "libreevolve.programmatic_representation_boundary_policy.v1",
            "candidate_representation_owner": "executable_code_workspace",
            "natural_language_hypothesis_role": "context_metadata_only",
            "evaluation_criteria_owner": "programmatic_evaluator_metrics",
            "natural_language_criteria_primary_gate": False,
            "transition_from_hypothesis_to_code_required": True,
        },
        "sample_records": records[:50],
        "records_truncated": len(records) > 50,
        "claim_ready": False,
        "claim_readiness": {
            "representation_boundary_recorded": True,
            "natural_language_hypothesis_separated_from_candidate": True,
            "programmatic_evaluation_criteria_recorded": bool(metric_names),
            "hallucination_resistance_measured": False,
            "long_horizon_evolution_measured": False,
            "ai_coscientist_bridge_contract": False,
            "remaining_gap": [
                "hallucination_risk_measurement",
                "long_horizon_step_count_evidence",
                "natural_language_hypothesis_to_programmatic_evaluation_bridge",
                "ai_coscientist_style_hypothesis_stage_contract",
            ],
        },
    }
    report["validation"] = validate_programmatic_representation_boundary_report(report)
    return report


def _programmatic_boundary_metric_names(objective_schema: Mapping[str, object]) -> list[str]:
    metrics = objective_schema.get("metrics")
    names: list[str] = []
    if isinstance(metrics, list):
        for metric in metrics:
            if not isinstance(metric, Mapping):
                continue
            name = metric.get("name")
            if isinstance(name, str) and name:
                names.append(name)
    primary = objective_schema.get("primary_metric")
    if isinstance(primary, str) and primary:
        names.insert(0, primary)
    return _unique_in_order(names)


def _programmatic_boundary_records(programs: list[Program]) -> list[dict]:
    records: list[dict] = []
    for program in programs:
        if _program_candidate_type(program) != "generated":
            continue
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        proposal = (
            metadata.get("proposal")
            if isinstance(metadata.get("proposal"), Mapping)
            else {}
        )
        proposal_fields = [
            field
            for field in ("idea", "rationale", "hypothesis")
            if isinstance(proposal.get(field), str) and proposal.get(field)
        ]
        records.append(
            {
                "program_id": program.id,
                "generation": program.generation,
                "candidate_representation": "executable_code_workspace",
                "candidate_type": "generated",
                "workspace_file_count": len(program.files),
                "primary_file": program.primary_file,
                "proposal_fields_present": proposal_fields,
                "natural_language_hypothesis_is_candidate": False,
                "evaluator_is_valid": evaluation.get("is_valid"),
                "evaluation_criteria_source": "programmatic_evaluator_metrics",
            }
        )
    records.sort(key=lambda record: (record["generation"], record["program_id"]))
    return records


def validate_programmatic_representation_boundary_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.programmatic_representation_boundary_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "programmatic representation boundary report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "candidate_representation",
        "natural_language_artifacts",
        "programmatic_evaluation_criteria",
        "feedback_boundary",
        "runtime_step_scope",
        "boundary_policy",
        "sample_records",
        "records_truncated",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "programmatic representation boundary report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.programmatic_representation_boundary_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "programmatic representation boundary report schema is unsupported",
            }
        )
    if report.get("source") != "startup_manifest_and_runtime_history":
        issues.append(
            {
                "code": "invalid_source",
                "message": "programmatic representation boundary report source is unsupported",
            }
        )
    representation = report.get("candidate_representation")
    if not isinstance(representation, dict):
        issues.append(
            {
                "code": "invalid_candidate_representation",
                "message": "candidate_representation must be an object",
            }
        )
        representation = {}
    if representation.get("kind") != "executable_code_workspace":
        issues.append(
            {
                "code": "invalid_candidate_representation_kind",
                "message": "candidate representation kind must be executable_code_workspace",
            }
        )
    if representation.get("natural_language_candidate") is not False:
        issues.append(
            {
                "code": "invalid_natural_language_candidate_flag",
                "message": "natural-language hypotheses must not be candidate programs",
            }
        )
    artifacts = report.get("natural_language_artifacts")
    if not isinstance(artifacts, dict):
        issues.append(
            {
                "code": "invalid_natural_language_artifacts",
                "message": "natural_language_artifacts must be an object",
            }
        )
        artifacts = {}
    if artifacts.get("role") != "proposal_metadata_context_not_candidate_representation":
        issues.append(
            {
                "code": "invalid_natural_language_role",
                "message": "natural-language artifacts must be context metadata only",
            }
        )
    field_counts = artifacts.get("proposal_field_counts")
    if not isinstance(field_counts, dict):
        issues.append(
            {
                "code": "invalid_proposal_field_counts",
                "message": "proposal_field_counts must be an object",
            }
        )
    else:
        for field in ("idea", "rationale", "hypothesis"):
            value = field_counts.get(field)
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                issues.append(
                    {
                        "code": f"invalid_{field}_count",
                        "message": f"proposal_field_counts.{field} must be non-negative integer",
                    }
                )
    criteria = report.get("programmatic_evaluation_criteria")
    if not isinstance(criteria, dict):
        issues.append(
            {
                "code": "invalid_programmatic_evaluation_criteria",
                "message": "programmatic_evaluation_criteria must be an object",
            }
        )
        criteria = {}
    if criteria.get("role") != "declared_evaluator_metrics_and_validity_gate":
        issues.append(
            {
                "code": "invalid_evaluation_criteria_role",
                "message": "evaluation criteria role is unsupported",
            }
        )
    if not isinstance(criteria.get("metric_names"), list):
        issues.append(
            {
                "code": "invalid_metric_names",
                "message": "metric_names must be a list",
            }
        )
    feedback = report.get("feedback_boundary")
    if not isinstance(feedback, dict):
        issues.append(
            {
                "code": "invalid_feedback_boundary",
                "message": "feedback_boundary must be an object",
            }
        )
    elif feedback.get("llm_feedback_primary_validity_gate") is not False:
        issues.append(
            {
                "code": "invalid_feedback_validity_gate",
                "message": "LLM feedback must not be the primary validity gate",
            }
        )
    policy = report.get("boundary_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_boundary_policy",
                "message": "boundary_policy must be an object",
            }
        )
    else:
        if policy.get("natural_language_criteria_primary_gate") is not False:
            issues.append(
                {
                    "code": "invalid_natural_language_gate",
                    "message": "natural-language criteria must not be the primary gate",
                }
            )
        if policy.get("transition_from_hypothesis_to_code_required") is not True:
            issues.append(
                {
                    "code": "invalid_hypothesis_transition",
                    "message": "hypothesis-to-code transition must be required",
                }
            )
    records = report.get("sample_records")
    if not isinstance(records, list):
        issues.append(
            {"code": "invalid_sample_records", "message": "sample_records must be a list"}
        )
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_sample_record",
                    "message": f"sample record {index} must be an object",
                }
            )
            continue
        if record.get("candidate_representation") != "executable_code_workspace":
            issues.append(
                {
                    "code": "invalid_sample_representation",
                    "message": f"sample record {index} representation is unsupported",
                }
            )
        if record.get("natural_language_hypothesis_is_candidate") is not False:
            issues.append(
                {
                    "code": "invalid_sample_hypothesis_boundary",
                    "message": f"sample record {index} hypothesis boundary is invalid",
                }
            )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("hallucination_resistance_measured") is not False:
            issues.append(
                {
                    "code": "invalid_hallucination_claim",
                    "message": "hallucination resistance must not be claimed as measured",
                }
            )
        if readiness.get("long_horizon_evolution_measured") is not False:
            issues.append(
                {
                    "code": "invalid_long_horizon_claim",
                    "message": "long-horizon evolution must not be claimed as measured",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "representation boundary report must not claim full readiness",
            }
        )
    return {
        "schema": "libreevolve.programmatic_representation_boundary_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _mutation_operator_boundary_report(
    startup_manifest: Mapping[str, object],
    programs: list[Program],
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    generated = [
        program for program in programs if _program_candidate_type(program) == "generated"
    ]
    mode_counts: dict[str, int] = {}
    surface_counts: dict[str, int] = {}
    proposal_family_counts: dict[str, int] = {}
    records = []
    for program in generated:
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        mode = _mutation_operator_mode(metadata.get("mutation_mode"))
        _increment_count(mode_counts, mode)
        payload = metadata.get("diff")
        surfaces = _mutation_operator_payload_surfaces(payload, mode)
        for surface in surfaces:
            _increment_count(surface_counts, surface)
        proposal = (
            metadata.get("proposal")
            if isinstance(metadata.get("proposal"), Mapping)
            else {}
        )
        family = _mutation_operator_family_from_proposal(proposal)
        _increment_count(proposal_family_counts, family)
        records.append(
            {
                "program_id": program.id,
                "generation": program.generation,
                "mutation_mode": mode,
                "payload_surfaces": surfaces,
                "operator_family_source": "not_declared",
                "operator_family": family,
                "llm_constructed_operator_family": False,
                "adaptive_operator_selection": False,
                "prompt_program_id": metadata.get("prompt_program_id"),
                "proposal_fields_present": _mutation_operator_proposal_fields(proposal),
                "evaluator_is_valid": (
                    program.evaluation.get("is_valid")
                    if isinstance(program.evaluation, dict)
                    else None
                ),
            }
        )
    records.sort(key=lambda record: (record["generation"], record["program_id"]))
    report = {
        "schema": "libreevolve.mutation_operator_boundary_report.v1",
        "source": "startup_manifest_and_runtime_history",
        "configured_mutation_mode": _mutation_operator_mode(
            config.get("mutation_mode")
        ),
        "generated_candidate_count": len(generated),
        "mutation_mode_counts": dict(sorted(mode_counts.items())),
        "payload_surface_counts": dict(sorted(surface_counts.items())),
        "proposal_operator_family_counts": dict(sorted(proposal_family_counts.items())),
        "edit_grammar_policy": {
            "schema": "libreevolve.fixed_edit_grammar_policy.v1",
            "fixed_local_parser_surfaces": [
                "search_replace_diff",
                "full_replacement",
                "file_sections",
                "block_sections",
                "topology_commands",
                "static_or_binary_sections",
            ],
            "mutation_applier": "apply_workspace_mutation",
            "run_wide_mutation_mode": True,
            "adaptive_diff_full_selection": False,
            "llm_constructed_operator_families": False,
            "operator_family_scoring": False,
        },
        "strategy_boundary": {
            "higher_level_strategy_role": "proposal_text_unclassified",
            "operator_family_source": "not_declared_or_selected",
            "task_or_failure_aware_operator_construction": False,
            "benchmark_operator_telemetry": False,
        },
        "sample_records": records[:50],
        "records_truncated": len(records) > 50,
        "claim_ready": False,
        "claim_readiness": {
            "edit_payload_grammar_reported": True,
            "fixed_parser_boundary_recorded": True,
            "llm_constructed_operator_family_reported": False,
            "adaptive_operator_selection_reported": False,
            "operator_family_benchmark_telemetry": False,
            "remaining_gap": [
                "operator_family_declaration_schema",
                "proposal_level_operator_family_provenance",
                "task_or_failure_aware_operator_construction",
                "adaptive_operator_family_selection",
                "operator_family_benchmark_telemetry",
            ],
        },
    }
    report["validation"] = validate_mutation_operator_boundary_report(report)
    return report


def _mutation_operator_mode(value: object) -> str:
    return value if isinstance(value, str) and value else "unknown"


def _mutation_operator_payload_surfaces(payload: object, mode: str) -> list[str]:
    if not isinstance(payload, str) or not payload:
        return ["missing_payload"]
    surfaces: list[str] = []
    canonical_search = ("<" * 7) + " SEARCH"
    canonical_replace = (">" * 7) + " REPLACE"
    if (
        ("<<<SEARCH" in payload and ">>>REPLACE" in payload)
        or (canonical_search in payload and canonical_replace in payload)
    ):
        surfaces.append("search_replace_diff")
    if "<<<FILE" in payload and ">>>FILE" in payload:
        surfaces.append("file_sections")
    if "<<<BLOCK" in payload and ">>>BLOCK" in payload:
        surfaces.append("block_sections")
    if _mutation_operator_has_topology_command(payload):
        surfaces.append("topology_commands")
    if "<<<FILE STATIC" in payload or "<<<FILE BINARY" in payload:
        surfaces.append("static_or_binary_sections")
    if not surfaces and mode == "full":
        surfaces.append("full_replacement")
    if not surfaces:
        surfaces.append("unclassified_payload")
    return _unique_in_order(surfaces)


def _mutation_operator_has_topology_command(payload: str) -> bool:
    markers = (
        "<<<FILE DELETE ",
        "<<<FILE MOVE ",
        "<<<FILE RENAME ",
        "<<<FILE PRIMARY ",
    )
    return any(marker in payload for marker in markers)


def _mutation_operator_family_from_proposal(proposal: Mapping[str, object]) -> str:
    if not proposal:
        return "not_declared"
    return "proposal_text_unclassified"


def _mutation_operator_proposal_fields(proposal: Mapping[str, object]) -> list[str]:
    return [
        field
        for field in ("idea", "rationale", "hypothesis")
        if isinstance(proposal.get(field), str) and proposal.get(field)
    ]


def validate_mutation_operator_boundary_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.mutation_operator_boundary_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "mutation operator boundary report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "configured_mutation_mode",
        "generated_candidate_count",
        "mutation_mode_counts",
        "payload_surface_counts",
        "proposal_operator_family_counts",
        "edit_grammar_policy",
        "strategy_boundary",
        "sample_records",
        "records_truncated",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "mutation operator boundary report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.mutation_operator_boundary_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "mutation operator boundary report schema is unsupported",
            }
        )
    if report.get("source") != "startup_manifest_and_runtime_history":
        issues.append(
            {
                "code": "invalid_source",
                "message": "mutation operator boundary report source is unsupported",
            }
        )
    for field in ("generated_candidate_count",):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    for field in (
        "mutation_mode_counts",
        "payload_surface_counts",
        "proposal_operator_family_counts",
    ):
        value = report.get(field)
        if not isinstance(value, dict):
            issues.append(
                {"code": f"invalid_{field}", "message": f"{field} must be an object"}
            )
            continue
        for key, count in value.items():
            if not isinstance(key, str) or not key:
                issues.append(
                    {
                        "code": f"invalid_{field}_key",
                        "message": f"{field} keys must be non-empty strings",
                    }
                )
            if isinstance(count, bool) or not isinstance(count, int) or count < 0:
                issues.append(
                    {
                        "code": f"invalid_{field}_count",
                        "message": f"{field} values must be non-negative integers",
                    }
                )
    policy = report.get("edit_grammar_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_edit_grammar_policy",
                "message": "edit_grammar_policy must be an object",
            }
        )
        policy = {}
    if policy.get("run_wide_mutation_mode") is not True:
        issues.append(
            {
                "code": "invalid_run_wide_mutation_mode",
                "message": "current report must record run-wide mutation mode",
            }
        )
    for field in (
        "adaptive_diff_full_selection",
        "llm_constructed_operator_families",
        "operator_family_scoring",
    ):
        if policy.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"edit_grammar_policy.{field} must be false",
                }
            )
    strategy = report.get("strategy_boundary")
    if not isinstance(strategy, dict):
        issues.append(
            {
                "code": "invalid_strategy_boundary",
                "message": "strategy_boundary must be an object",
            }
        )
        strategy = {}
    for field in (
        "task_or_failure_aware_operator_construction",
        "benchmark_operator_telemetry",
    ):
        if strategy.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"strategy_boundary.{field} must be false",
                }
            )
    records = report.get("sample_records")
    if not isinstance(records, list):
        issues.append(
            {"code": "invalid_sample_records", "message": "sample_records must be a list"}
        )
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_sample_record",
                    "message": f"sample record {index} must be an object",
                }
            )
            continue
        if record.get("llm_constructed_operator_family") is not False:
            issues.append(
                {
                    "code": "invalid_sample_operator_family_claim",
                    "message": f"sample record {index} must not claim LLM operator construction",
                }
            )
        if record.get("adaptive_operator_selection") is not False:
            issues.append(
                {
                    "code": "invalid_sample_adaptive_selection_claim",
                    "message": f"sample record {index} must not claim adaptive selection",
                }
            )
        if not isinstance(record.get("payload_surfaces"), list):
            issues.append(
                {
                    "code": "invalid_sample_payload_surfaces",
                    "message": f"sample record {index} payload_surfaces must be a list",
                }
            )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
        readiness = {}
    for field in (
        "llm_constructed_operator_family_reported",
        "adaptive_operator_selection_reported",
        "operator_family_benchmark_telemetry",
    ):
        if readiness.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"claim_readiness.{field} must be false",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "mutation operator boundary report must not claim full readiness",
            }
        )
    return {
        "schema": "libreevolve.mutation_operator_boundary_report.v1",
        "ok": not issues,
        "issues": issues,
    }


_CONSISTENCY_FILE_SECTION_HEADER_RE = re.compile(r"(?m)^<<<FILE[ \t]*(.*?)\n")
_CONSISTENCY_BLOCK_SECTION_HEADER_RE = re.compile(r"(?m)^<<<BLOCK[ \t]*(.*?)\n")
_PROMPT_EXAMPLE_FILE_SECTION_RE = re.compile(
    r"^<<<FILE[ \t]*(.*?)\n(.*?)^>>>FILE[ \t]*(?:\n|$)",
    re.DOTALL | re.MULTILINE,
)
_PROMPT_CURRENT_BLOCK_SECTION_RE = re.compile(
    r"^<<<BLOCK[ \t]*(.*?)\n(.*?)\n^>>>BLOCK[ \t]*(?:\n|$)",
    re.DOTALL | re.MULTILINE,
)
_PROMPT_EXAMPLE_SKELETON_RE = re.compile(
    r"(?s)def\s+[A-Za-z_][A-Za-z0-9_]*\s*\(\s*\)\s*:\s*return\s+1"
    r".*?def\s+[A-Za-z_][A-Za-z0-9_]*\s*\(\s*\)\s*:\s*return\s+2"
)
_PYTHON_BUILTIN_NAMES = frozenset(dir(builtins)) | {"True", "False", "None"}
_PYTHON_IMPLICIT_NAMES = frozenset({"self", "cls"})


def _mutation_consistency_report(programs: list[Program]) -> dict:
    parent_by_id = {program.id: program for program in programs}
    generated = [
        program for program in programs if _program_candidate_type(program) == "generated"
    ]
    all_records = [
        _mutation_consistency_record(program, parent_by_id.get(program.parent_id))
        for program in generated
    ]
    records = [
        record
        for record in all_records
        if record.get("edit_summary", {}).get("multi_edit") is True
    ]
    status_counts: dict[str, int] = {}
    mode_counts: dict[str, int] = {}
    unresolved_count = 0
    python_scan_count = 0
    for record in records:
        _increment_count(status_counts, str(record.get("candidate_status") or "unknown"))
        _increment_count(mode_counts, str(record.get("mutation_mode") or "unknown"))
        symbol_summary = record.get("symbol_summary")
        if isinstance(symbol_summary, Mapping):
            if symbol_summary.get("language") == "python":
                python_scan_count += 1
            if symbol_summary.get("unresolved_reference_count", 0):
                unresolved_count += 1
    report = {
        "schema": "libreevolve.mutation_consistency_report.v1",
        "source": "runtime_history_mutation_payloads_and_candidate_workspaces",
        "generated_candidate_count": len(generated),
        "multi_edit_candidate_count": len(records),
        "python_symbol_scan_candidate_count": python_scan_count,
        "unresolved_reference_candidate_count": unresolved_count,
        "candidate_status_counts": dict(sorted(status_counts.items())),
        "mutation_mode_counts": dict(sorted(mode_counts.items())),
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "diagnostic_policy": {
            "schema": "libreevolve.mutation_consistency_policy.v1",
            "scope": "current_run_generated_multi_edit_candidates",
            "multi_edit_definition": (
                "more_than_one_structured_diff_file_or_block_edit_unit"
            ),
            "symbol_scan_policy": (
                "best_effort_python_ast_defined_imported_loaded_name_comparison"
            ),
            "companion_edit_policy": "cochange_links_are_diagnostic_not_required",
            "acceptance_policy": "diagnostic_only_not_archive_gate",
        },
        "claim_ready": False,
        "claim_readiness": {
            "multi_edit_candidates_identified": bool(records),
            "changed_file_or_block_ids_recorded": bool(records),
            "python_symbol_reference_scan": python_scan_count > 0,
            "evaluator_failure_taxonomy_linked": bool(records),
            "semantic_consistency_proven": False,
            "hard_acceptance_gate": False,
            "remaining_gap": [
                "language_aware_scope_resolution",
                "config_resource_dependency_models",
                "required_companion_edit_inference",
                "cross_file_dataflow_or_import_resolution",
                "benchmark_calibrated_consistency_failures",
            ],
        },
    }
    report["validation"] = validate_mutation_consistency_report(report)
    return report


def _mutation_consistency_record(program: Program, parent: Program | None) -> dict:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    prompt_diagnostics = (
        metadata.get("prompt_diagnostics")
        if isinstance(metadata.get("prompt_diagnostics"), Mapping)
        else {}
    )
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), Mapping)
        else {}
    )
    evaluation = program.evaluation if isinstance(program.evaluation, Mapping) else {}
    payload = metadata.get("diff")
    payload_text = payload if isinstance(payload, str) else ""
    mode = str(metadata.get("mutation_mode") or "unknown")
    edit_summary = _mutation_consistency_edit_summary(
        payload_text,
        mode,
        program.primary_file,
    )
    parent_workspace = parent.workspace() if parent is not None else None
    symbol_summary = _mutation_consistency_symbol_summary(
        parent_workspace,
        program.workspace(),
    )
    failure_taxonomy = _mutation_consistency_failure_taxonomy(
        evaluation,
        symbol_summary,
    )
    candidate_status = (
        "accepted_history"
        if admission.get("admitted") is True
        else "rejected_history"
    )
    return {
        "candidate_id": program.id,
        "candidate_status": candidate_status,
        "generation": program.generation,
        "parent_id": program.parent_id,
        "prompt_program_id": metadata.get("prompt_program_id"),
        "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
        "mutation_mode": mode,
        "payload_sha256": hashlib.sha256(payload_text.encode("utf-8")).hexdigest(),
        "edit_summary": edit_summary,
        "cochange_links": _mutation_consistency_cochange_links(edit_summary),
        "symbol_summary": symbol_summary,
        "failure_taxonomy": failure_taxonomy,
        "admission": {
            "admitted": admission.get("admitted"),
            "reason": admission.get("reason"),
            "sampling_eligible": admission.get("sampling_eligible"),
        },
        "evaluation": {
            "is_valid": evaluation.get("is_valid"),
            "error": evaluation.get("error"),
        },
    }


def _mutation_consistency_edit_summary(
    payload: str,
    mode: str,
    primary_file: str,
) -> dict:
    diff_blocks = parse_diff_blocks(payload) if payload else []
    file_headers = [
        header.strip()
        for header in _CONSISTENCY_FILE_SECTION_HEADER_RE.findall(payload)
    ]
    block_headers = [
        header.strip() or "block_0"
        for header in _CONSISTENCY_BLOCK_SECTION_HEADER_RE.findall(payload)
    ]
    changed_files = _mutation_consistency_changed_files(file_headers, primary_file)
    if diff_blocks and primary_file not in changed_files:
        changed_files.insert(0, primary_file)
    topology_count = sum(
        1
        for header in file_headers
        if _mutation_consistency_file_command(header)
        in {"DELETE", "MOVE", "RENAME", "PRIMARY"}
    )
    edit_unit_count = len(diff_blocks) + len(file_headers) + len(block_headers)
    return {
        "mutation_surfaces": _mutation_operator_payload_surfaces(payload, mode),
        "search_replace_block_count": len(diff_blocks),
        "file_section_count": len(file_headers),
        "block_section_count": len(block_headers),
        "topology_command_count": topology_count,
        "edit_unit_count": edit_unit_count,
        "multi_edit": edit_unit_count > 1,
        "changed_files": changed_files[:50],
        "changed_files_truncated": len(changed_files) > 50,
        "changed_blocks": _unique_in_order(block_headers)[:50],
        "changed_blocks_truncated": len(set(block_headers)) > 50,
    }


def _mutation_consistency_changed_files(
    file_headers: list[str],
    primary_file: str,
) -> list[str]:
    files: list[str] = []
    for header in file_headers:
        command = _mutation_consistency_file_command(header)
        raw = header
        if command == "PATH":
            raw = header.partition(" ")[2].strip()
        elif command in {"STATIC", "BINARY", "DELETE", "PRIMARY"}:
            raw = header.partition(" ")[2].strip()
        elif command in {"MOVE", "RENAME"}:
            source, _sep, target = header.partition(" ")[2].partition("->")
            files.extend([source.strip(), target.strip()])
            continue
        if raw:
            files.append(raw)
    if not files and primary_file:
        files.append(primary_file)
    return _unique_in_order(
        [
            _mutation_consistency_safe_label(path)
            for path in files
            if isinstance(path, str) and path.strip()
        ]
    )


def _mutation_consistency_file_command(header: str) -> str:
    command = header.strip().split(" ", 1)[0].upper() if header.strip() else ""
    return command if command in {
        "PATH",
        "STATIC",
        "BINARY",
        "DELETE",
        "MOVE",
        "RENAME",
        "PRIMARY",
    } else ""


def _mutation_consistency_safe_label(value: str, max_chars: int = 160) -> str:
    redacted = redact_sensitive_text(value.strip())
    if len(redacted) <= max_chars:
        return redacted
    return redacted[: max_chars - 14].rstrip() + "\n...[truncated]"


def _mutation_consistency_cochange_links(edit_summary: Mapping[str, object]) -> list[dict]:
    labels: list[str] = []
    for path in edit_summary.get("changed_files", []):
        if isinstance(path, str):
            labels.append(f"file:{path}")
    for block in edit_summary.get("changed_blocks", []):
        if isinstance(block, str):
            labels.append(f"block:{block}")
    links: list[dict] = []
    unique_labels = _unique_in_order(labels)
    for left_index, left in enumerate(unique_labels[:10]):
        for right in unique_labels[left_index + 1 : 10]:
            links.append(
                {
                    "source": left,
                    "target": right,
                    "relationship": "same_mutation_payload",
                }
            )
    return links[:25]


def _mutation_consistency_symbol_summary(
    parent_workspace: CandidateWorkspace | None,
    candidate_workspace: CandidateWorkspace,
) -> dict:
    parent_symbols = (
        _mutation_consistency_workspace_symbols(parent_workspace)
        if parent_workspace is not None
        else _empty_python_symbol_inventory()
    )
    candidate_symbols = _mutation_consistency_workspace_symbols(candidate_workspace)
    candidate_available = (
        candidate_symbols["defined_symbols"] | candidate_symbols["imported_symbols"]
    )
    parent_available = parent_symbols["defined_symbols"] | parent_symbols["imported_symbols"]
    unresolved = sorted(
        candidate_symbols["referenced_symbols"]
        - candidate_available
        - _PYTHON_BUILTIN_NAMES
        - _PYTHON_IMPLICIT_NAMES
    )
    introduced = sorted(candidate_available - parent_available)
    return {
        "schema": "libreevolve.python_symbol_consistency_scan.v1",
        "language": "python",
        "scan_policy": "best_effort_ast_names_no_type_or_import_resolution",
        "scanned_files": candidate_symbols["scanned_files"][:50],
        "scanned_files_truncated": len(candidate_symbols["scanned_files"]) > 50,
        "syntax_errors": candidate_symbols["syntax_errors"][:25],
        "syntax_errors_truncated": len(candidate_symbols["syntax_errors"]) > 25,
        "introduced_symbols": introduced[:50],
        "introduced_symbols_truncated": len(introduced) > 50,
        "referenced_symbols": sorted(candidate_symbols["referenced_symbols"])[:50],
        "referenced_symbols_truncated": len(candidate_symbols["referenced_symbols"]) > 50,
        "unresolved_references": unresolved[:50],
        "unresolved_references_truncated": len(unresolved) > 50,
        "unresolved_reference_count": len(unresolved),
        "builtin_and_implicit_names_excluded": True,
    }


def _empty_python_symbol_inventory() -> dict:
    return {
        "scanned_files": [],
        "syntax_errors": [],
        "defined_symbols": set(),
        "imported_symbols": set(),
        "referenced_symbols": set(),
    }


def _mutation_consistency_workspace_symbols(workspace: CandidateWorkspace) -> dict:
    inventory = _empty_python_symbol_inventory()
    for path, text in sorted(workspace.files.items()):
        if not path.endswith(".py") or not isinstance(text, str):
            continue
        inventory["scanned_files"].append(path)
        try:
            tree = ast.parse(text, filename=path)
        except SyntaxError as exc:
            inventory["syntax_errors"].append(
                {
                    "path": path,
                    "lineno": exc.lineno,
                    "offset": exc.offset,
                    "message": _mutation_consistency_safe_label(exc.msg),
                }
            )
            continue
        visitor = _PythonSymbolVisitor()
        visitor.visit(tree)
        inventory["defined_symbols"].update(visitor.defined)
        inventory["imported_symbols"].update(visitor.imported)
        inventory["referenced_symbols"].update(visitor.referenced)
    return inventory


class _PythonSymbolVisitor(ast.NodeVisitor):
    def __init__(self) -> None:
        self.defined: set[str] = set()
        self.imported: set[str] = set()
        self.referenced: set[str] = set()

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self.defined.add(node.name)
        self._visit_arguments(node.args)
        self.generic_visit(node)

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
        self.visit_FunctionDef(node)

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        self.defined.add(node.name)
        self.generic_visit(node)

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            self.imported.add(alias.asname or alias.name.split(".", 1)[0])

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        for alias in node.names:
            if alias.name == "*":
                continue
            self.imported.add(alias.asname or alias.name)

    def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load):
            self.referenced.add(node.id)
        elif isinstance(node.ctx, (ast.Store, ast.Param)):
            self.defined.add(node.id)

    def visit_arg(self, node: ast.arg) -> None:
        self.defined.add(node.arg)

    def _visit_arguments(self, node: ast.arguments) -> None:
        for arg in (
            list(node.posonlyargs)
            + list(node.args)
            + list(node.kwonlyargs)
            + ([node.vararg] if node.vararg is not None else [])
            + ([node.kwarg] if node.kwarg is not None else [])
        ):
            self.visit(arg)


def _mutation_consistency_failure_taxonomy(
    evaluation: Mapping[str, object],
    symbol_summary: Mapping[str, object],
) -> dict:
    metadata = evaluation.get("metadata") if isinstance(evaluation.get("metadata"), Mapping) else {}
    diff_error = metadata.get("diff_error") if isinstance(metadata, Mapping) else None
    diff_reason = (
        diff_error.get("reason")
        if isinstance(diff_error, Mapping)
        and isinstance(diff_error.get("reason"), str)
        else None
    )
    if diff_reason:
        category = "mutation_application_failure"
    elif symbol_summary.get("syntax_errors"):
        category = "python_syntax_scan_failure"
    elif symbol_summary.get("unresolved_reference_count", 0):
        category = "symbol_consistency_diagnostic"
    elif evaluation.get("is_valid") is False:
        category = "evaluator_rejection"
    else:
        category = "none_observed"
    return {
        "category": category,
        "diff_error_reason": diff_reason,
        "evaluation_is_valid": evaluation.get("is_valid"),
        "evaluation_error": evaluation.get("error"),
    }


def validate_mutation_consistency_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.mutation_consistency_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "mutation consistency report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "multi_edit_candidate_count",
        "python_symbol_scan_candidate_count",
        "unresolved_reference_candidate_count",
        "candidate_status_counts",
        "mutation_mode_counts",
        "records",
        "records_limit",
        "records_truncated",
        "diagnostic_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"mutation consistency report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.mutation_consistency_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "mutation consistency report schema is unsupported",
            }
        )
    if report.get("source") != "runtime_history_mutation_payloads_and_candidate_workspaces":
        issues.append(
            {
                "code": "invalid_source",
                "message": "mutation consistency report source is unsupported",
            }
        )
    for field in (
        "generated_candidate_count",
        "multi_edit_candidate_count",
        "python_symbol_scan_candidate_count",
        "unresolved_reference_candidate_count",
        "records_limit",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {"code": "invalid_record", "message": f"record {index} must be an object"}
            )
            continue
        if not isinstance(record.get("candidate_id"), str):
            issues.append(
                {
                    "code": "invalid_candidate_id",
                    "message": f"record {index} candidate_id must be a string",
                }
            )
        edit_summary = record.get("edit_summary")
        if not isinstance(edit_summary, dict) or edit_summary.get("multi_edit") is not True:
            issues.append(
                {
                    "code": "invalid_edit_summary",
                    "message": f"record {index} must describe a multi-edit payload",
                }
            )
        symbol_summary = record.get("symbol_summary")
        if not isinstance(symbol_summary, dict):
            issues.append(
                {
                    "code": "invalid_symbol_summary",
                    "message": f"record {index} symbol_summary must be an object",
                }
            )
        elif symbol_summary.get("schema") != "libreevolve.python_symbol_consistency_scan.v1":
            issues.append(
                {
                    "code": "invalid_symbol_summary_schema",
                    "message": f"record {index} symbol summary schema is unsupported",
                }
            )
        if not isinstance(record.get("failure_taxonomy"), dict):
            issues.append(
                {
                    "code": "invalid_failure_taxonomy",
                    "message": f"record {index} failure_taxonomy must be an object",
                }
            )
    if report.get("records_truncated") is not True:
        if report.get("multi_edit_candidate_count") != len(records):
            issues.append(
                {
                    "code": "invalid_record_count",
                    "message": "multi-edit count must match records when not truncated",
                }
            )
    if not isinstance(report.get("diagnostic_policy"), dict):
        issues.append(
            {
                "code": "invalid_diagnostic_policy",
                "message": "diagnostic_policy must be an object",
            }
        )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "claim_ready_overclaim",
                "message": "mutation consistency report must not claim full readiness",
            }
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        for field in ("semantic_consistency_proven", "hard_acceptance_gate"):
            if readiness.get(field) is not False:
                issues.append(
                    {
                        "code": f"{field}_overclaim",
                        "message": f"{field} must remain false",
                    }
                )
    return {
        "schema": "libreevolve.mutation_consistency_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _prompt_example_copy_report(programs: list[Program]) -> dict:
    inventory = _prompt_example_inventory()
    records = [
        _prompt_example_copy_record(program, inventory)
        for program in programs
        if _prompt_current_binding_is_generated(program)
    ]
    copied_records = [
        record for record in records if record["copy_signal_count"] > 0
    ]
    enabled_records = [
        record for record in records if record["prompt_example_enabled"] is True
    ]
    status_counts: dict[str, int] = {}
    copied_status_counts: dict[str, int] = {}
    mode_counts: dict[str, int] = {}
    normalized_signal_count = 0
    skeleton_signal_count = 0
    for record in records:
        status = str(record.get("candidate_status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        mode = str(record.get("mutation_mode") or "unknown")
        mode_counts[mode] = mode_counts.get(mode, 0) + 1
        if record["copy_signal_count"] > 0:
            copied_status_counts[status] = copied_status_counts.get(status, 0) + 1
        normalized_signal_count += int(record.get("normalized_copy_signal_count") or 0)
        skeleton_signal_count += int(record.get("format_skeleton_signal_count") or 0)
    report = {
        "schema": "libreevolve.prompt_example_copy_report.v1",
        "source": "runtime_history_prompt_diagnostics_and_mutation_payloads",
        "inventory": inventory,
        "generated_candidate_count": len(records),
        "prompt_example_enabled_count": len(enabled_records),
        "copied_example_candidate_count": len(copied_records),
        "normalized_copy_signal_count": normalized_signal_count,
        "format_skeleton_signal_count": skeleton_signal_count,
        "candidate_status_counts": dict(sorted(status_counts.items())),
        "copied_candidate_status_counts": dict(sorted(copied_status_counts.items())),
        "mutation_mode_counts": dict(sorted(mode_counts.items())),
        "records": copied_records[:50],
        "records_limit": 50,
        "records_truncated": len(copied_records) > 50,
        "diagnostic_policy": {
            "inventory_scope": "built_in_mutation_instruction_example_sentinels",
            "match_policy": (
                "exact_substring_plus_normalized_region_and_format_skeleton_signals"
            ),
            "acceptance_policy": "diagnostic_only_not_a_hard_rejection",
            "prompt_example_disabled_policy": (
                "record_include_flag_when_prompt_context_policy_disables_example"
            ),
        },
        "claim_ready": False,
        "claim_readiness": {
            "prompt_example_inventory_versioned": True,
            "copied_sentinel_detection": True,
            "normalized_region_detection": normalized_signal_count > 0,
            "format_skeleton_detection": skeleton_signal_count > 0,
            "diff_full_workspace_payloads_scanned": True,
            "hard_acceptance_gate": False,
            "semantic_example_copy_detection": False,
            "remaining_gap": [
                "hard_rejection_or_configurable_acceptance_policy",
                "semantic_or_renamed_example_copy_detection_beyond_format_skeletons",
                "custom_prompt_template_example_inventory",
                "configured_prompt_template_example_inventories",
            ],
        },
    }
    report["validation"] = validate_prompt_example_copy_report(report)
    return report


def _prompt_example_inventory() -> dict:
    sentinels = [
        {
            "label": "example_function_signature",
            "text": "def foo():",
        },
        {
            "label": "example_search_return",
            "text": "return 1",
        },
        {
            "label": "example_replace_return",
            "text": "return 2",
        },
        {
            "label": "example_do_not_copy_notice",
            "text": "Example format (do NOT copy this",
        },
    ]
    records = [
        {
            "label": item["label"],
            "sha256": hashlib.sha256(item["text"].encode("utf-8")).hexdigest(),
            "chars": len(item["text"]),
            "preview": item["text"],
        }
        for item in sentinels
    ]
    return {
        "schema": "libreevolve.prompt_example_inventory.v1",
        "source": "built_in_mutation_instruction_example",
        "example_id": "default_diff_format_example:v1",
        "include_flag": "prompt_context_policy.mutation_instruction_include_example",
        "sentinel_count": len(records),
        "sentinels": records,
    }


def _prompt_example_copy_record(program: Program, inventory: Mapping[str, object]) -> dict:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    prompt_diagnostics = (
        metadata.get("prompt_diagnostics")
        if isinstance(metadata.get("prompt_diagnostics"), Mapping)
        else {}
    )
    context_policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), Mapping)
        else {}
    )
    payload = metadata.get("diff")
    payload_text = payload if isinstance(payload, str) else ""
    copied = _prompt_example_copied_sentinels(payload_text, inventory)
    normalized = _prompt_example_normalized_copy_signals(payload_text, inventory)
    skeletons = _prompt_example_format_skeleton_signals(payload_text)
    copy_signal_count = len(copied) + len(normalized) + len(skeletons)
    return {
        "candidate_id": program.id,
        "candidate_status": (
            "accepted_history"
            if admission.get("admitted") is True
            else "rejected_history"
        ),
        "generation": program.generation,
        "parent_id": program.parent_id,
        "prompt_program_id": metadata.get("prompt_program_id"),
        "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
        "mutation_mode": metadata.get("mutation_mode"),
        "payload_sha256": hashlib.sha256(payload_text.encode("utf-8")).hexdigest(),
        "payload_surface": _mutation_operator_payload_surfaces(
            payload_text,
            str(metadata.get("mutation_mode") or "unknown"),
        ),
        "prompt_example_enabled": context_policy.get(
            "mutation_instruction_include_example"
        ),
        "copy_signal_count": copy_signal_count,
        "copied_example_sentinel_count": len(copied),
        "copied_example_sentinels": copied,
        "normalized_copy_signal_count": len(normalized),
        "normalized_copy_signals": normalized,
        "format_skeleton_signal_count": len(skeletons),
        "format_skeleton_signals": skeletons,
        "admission": {
            "admitted": admission.get("admitted"),
            "reason": admission.get("reason"),
        },
    }


def _prompt_example_copied_sentinels(
    payload_text: str,
    inventory: Mapping[str, object],
) -> list[dict]:
    copied: list[dict] = []
    sentinels = inventory.get("sentinels")
    if not isinstance(sentinels, list):
        return copied
    for sentinel in sentinels:
        if not isinstance(sentinel, Mapping):
            continue
        preview = sentinel.get("preview")
        if not isinstance(preview, str) or not preview:
            continue
        if preview not in payload_text:
            continue
        copied.append(
            {
                "label": sentinel.get("label"),
                "sha256": sentinel.get("sha256"),
                "match_policy": "exact_substring",
            }
        )
    return copied


def _prompt_example_payload_regions(payload_text: str) -> list[dict]:
    regions = []
    for index, match in enumerate(_PROMPT_EXAMPLE_FILE_SECTION_RE.finditer(payload_text)):
        header = match.group(1).strip()
        regions.append(
            {
                "label": f"file_section:{index}",
                "surface": "file_section_body",
                "header": _mutation_consistency_safe_label(header),
                "text": match.group(2),
            }
        )
    if regions:
        return regions
    regions.append(
        {
            "label": "entire_payload",
            "surface": "payload",
            "text": payload_text,
        }
    )
    return regions


def _prompt_example_normalized_copy_signals(
    payload_text: str,
    inventory: Mapping[str, object],
) -> list[dict]:
    signals: list[dict] = []
    sentinels = inventory.get("sentinels")
    if not isinstance(sentinels, list):
        return signals
    regions = _prompt_example_payload_regions(payload_text)
    seen: set[tuple[object, object]] = set()
    for sentinel in sentinels:
        if not isinstance(sentinel, Mapping):
            continue
        preview = sentinel.get("preview")
        if not isinstance(preview, str) or not preview:
            continue
        normalized_preview = _prompt_example_normalized_text(preview)
        if not normalized_preview:
            continue
        for region in regions:
            region_text = region.get("text")
            if not isinstance(region_text, str):
                continue
            if normalized_preview not in _prompt_example_normalized_text(region_text):
                continue
            key = (sentinel.get("label"), region.get("label"))
            if key in seen:
                continue
            seen.add(key)
            signals.append(
                {
                    "label": sentinel.get("label"),
                    "sha256": sentinel.get("sha256"),
                    "match_policy": "normalized_alnum_substring",
                    "region": region.get("label"),
                    "surface": region.get("surface"),
                    **(
                        {"section_header": region["header"]}
                        if isinstance(region.get("header"), str)
                        else {}
                    ),
                }
            )
    return signals[:50]


def _prompt_example_format_skeleton_signals(payload_text: str) -> list[dict]:
    signals: list[dict] = []
    for region in _prompt_example_payload_regions(payload_text):
        region_text = region.get("text")
        if not isinstance(region_text, str):
            continue
        if _PROMPT_EXAMPLE_SKELETON_RE.search(region_text) is None:
            continue
        signals.append(
            {
                "label": "example_def_return_1_to_2_skeleton",
                "match_policy": "format_skeleton_regex",
                "region": region.get("label"),
                "surface": region.get("surface"),
                **(
                    {"section_header": region["header"]}
                    if isinstance(region.get("header"), str)
                    else {}
                ),
            }
        )
    return signals[:25]


def _prompt_example_normalized_text(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9_]+", "", value).lower()


def validate_prompt_example_copy_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.prompt_example_copy_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "prompt example copy report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "inventory",
        "generated_candidate_count",
        "prompt_example_enabled_count",
        "copied_example_candidate_count",
        "normalized_copy_signal_count",
        "format_skeleton_signal_count",
        "candidate_status_counts",
        "copied_candidate_status_counts",
        "mutation_mode_counts",
        "records",
        "records_limit",
        "records_truncated",
        "diagnostic_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"prompt example copy report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.prompt_example_copy_report.v1":
        issues.append({"code": "invalid_schema", "message": "prompt example copy report schema is unsupported"})
    if report.get("source") != "runtime_history_prompt_diagnostics_and_mutation_payloads":
        issues.append({"code": "invalid_source", "message": "prompt example copy report source is unsupported"})
    for field in (
        "generated_candidate_count",
        "prompt_example_enabled_count",
        "copied_example_candidate_count",
        "normalized_copy_signal_count",
        "format_skeleton_signal_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append({"code": f"invalid_{field}", "message": f"{field} must be a non-negative integer"})
    inventory = report.get("inventory")
    if not isinstance(inventory, dict):
        issues.append({"code": "invalid_inventory", "message": "inventory must be an object"})
    else:
        if inventory.get("schema") != "libreevolve.prompt_example_inventory.v1":
            issues.append({"code": "invalid_inventory_schema", "message": "inventory schema is unsupported"})
        sentinels = inventory.get("sentinels")
        if not isinstance(sentinels, list) or not sentinels:
            issues.append({"code": "invalid_inventory_sentinels", "message": "inventory must include sentinels"})
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append({"code": "invalid_record", "message": f"record {index} must be an object"})
            continue
        count = record.get("copied_example_sentinel_count")
        sentinels = record.get("copied_example_sentinels")
        normalized_count = record.get("normalized_copy_signal_count")
        normalized = record.get("normalized_copy_signals")
        skeleton_count = record.get("format_skeleton_signal_count")
        skeletons = record.get("format_skeleton_signals")
        total_count = record.get("copy_signal_count")
        for field, value in (
            ("copy_signal_count", total_count),
            ("normalized_copy_signal_count", normalized_count),
            ("format_skeleton_signal_count", skeleton_count),
        ):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                issues.append(
                    {
                        "code": f"invalid_{field}",
                        "message": f"record {index} {field} must be non-negative",
                    }
                )
        if isinstance(count, bool) or not isinstance(count, int) or count < 1:
            if not (
                isinstance(total_count, int)
                and not isinstance(total_count, bool)
                and total_count > 0
            ):
                issues.append({"code": "invalid_copied_count", "message": f"record {index} copied count must be positive"})
        if not isinstance(sentinels, list) or len(sentinels) != count:
            issues.append({"code": "invalid_copied_sentinels", "message": f"record {index} copied sentinels must match count"})
        if not isinstance(normalized, list) or len(normalized) != normalized_count:
            issues.append({"code": "invalid_normalized_signals", "message": f"record {index} normalized signals must match count"})
        if not isinstance(skeletons, list) or len(skeletons) != skeleton_count:
            issues.append({"code": "invalid_skeleton_signals", "message": f"record {index} skeleton signals must match count"})
        if (
            isinstance(total_count, int)
            and isinstance(count, int)
            and isinstance(normalized_count, int)
            and isinstance(skeleton_count, int)
            and total_count != count + normalized_count + skeleton_count
        ):
            issues.append({"code": "invalid_copy_signal_count", "message": f"record {index} copy signal count must equal signal totals"})
    if report.get("records_truncated") is not True:
        if report.get("copied_example_candidate_count") != len(records):
            issues.append({"code": "invalid_record_count", "message": "copied count must match records when not truncated"})
    if not isinstance(report.get("diagnostic_policy"), dict):
        issues.append({"code": "invalid_diagnostic_policy", "message": "diagnostic_policy must be an object"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "prompt example copy report must not claim full readiness"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    else:
        for field in ("hard_acceptance_gate", "semantic_example_copy_detection"):
            if readiness.get(field) is not False:
                issues.append({"code": f"{field}_overclaim", "message": f"{field} must remain false"})
    return {
        "schema": "libreevolve.prompt_example_copy_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _natural_language_preamble_report(programs: list[Program]) -> dict:
    generated = [
        program
        for program in programs
        if isinstance(program.metadata, Mapping)
        and program.metadata.get("candidate_type") == "generated"
    ]
    records = [
        _natural_language_preamble_record(program)
        for program in generated
        if _natural_language_preamble_metadata(program)
    ]
    status_counts: dict[str, int] = {}
    mode_counts: dict[str, int] = {}
    structured_plus_preamble_count = 0
    for record in records:
        status = str(record.get("candidate_status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        mode = str(record.get("mutation_mode") or "unknown")
        mode_counts[mode] = mode_counts.get(mode, 0) + 1
        if record.get("structured_proposal_fields"):
            structured_plus_preamble_count += 1
    report = {
        "schema": "libreevolve.natural_language_preamble_report.v1",
        "source": "runtime_history_explanatory_preamble_metadata",
        "generated_candidate_count": len(generated),
        "preamble_record_count": len(records),
        "structured_proposal_plus_preamble_count": structured_plus_preamble_count,
        "candidate_status_counts": dict(sorted(status_counts.items())),
        "mutation_mode_counts": dict(sorted(mode_counts.items())),
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "preamble_policy": {
            "accepted_position": "leading_text_before_first_mutation_marker_only",
            "structured_metadata_interop": (
                "blank_line_separated_structured_metadata_then_freeform_capture"
            ),
            "interleaved_or_trailing_prose": (
                "rejected_by_consumed_text_validation"
            ),
            "raw_full_replacement_policy": "unsupported_without_structured_marker",
            "redaction_policy": "secret_redacted_and_bounded_preview",
        },
        "claim_ready": False,
        "claim_readiness": {
            "bounded_freeform_preamble_capture": bool(records),
            "diff_file_block_leading_preamble_supported": True,
            "interleaved_or_trailing_prose_rejected": True,
            "arbitrary_unparsed_rationale_accepted": False,
            "remaining_gap": [
                "configurable_preamble_policy_controls",
                "semantic_rationale_quality_scoring",
                "full_replacement_preamble_disambiguation",
                "cross_run_preamble_table",
            ],
        },
    }
    report["validation"] = validate_natural_language_preamble_report(report)
    return report


def _natural_language_preamble_metadata(program: Program) -> Mapping[str, object]:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    preamble = metadata.get("explanatory_preamble")
    if isinstance(preamble, Mapping) and preamble:
        return preamble
    return {}


def _natural_language_preamble_record(program: Program) -> dict:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    preamble = _natural_language_preamble_metadata(program)
    proposal = (
        metadata.get("proposal")
        if isinstance(metadata.get("proposal"), Mapping)
        else {}
    )
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), Mapping)
        else {}
    )
    evaluation = program.evaluation if isinstance(program.evaluation, Mapping) else {}
    payload = metadata.get("diff")
    payload_text = payload if isinstance(payload, str) else ""
    candidate_status = (
        "accepted_history"
        if admission.get("admitted") is True
        else "rejected_history"
    )
    return {
        "candidate_id": program.id,
        "candidate_status": candidate_status,
        "generation": program.generation,
        "parent_id": program.parent_id,
        "prompt_program_id": metadata.get("prompt_program_id"),
        "prompt_sha256": (
            metadata.get("prompt_diagnostics", {}).get("prompt_sha256")
            if isinstance(metadata.get("prompt_diagnostics"), Mapping)
            else None
        ),
        "mutation_mode": metadata.get("mutation_mode"),
        "payload_sha256": hashlib.sha256(payload_text.encode("utf-8")).hexdigest(),
        "preamble": dict(preamble),
        "structured_proposal_fields": sorted(
            field
            for field in ("idea", "rationale", "hypothesis")
            if isinstance(proposal.get(field), str) and proposal.get(field)
        ),
        "admission": {
            "admitted": admission.get("admitted"),
            "reason": admission.get("reason"),
            "sampling_eligible": admission.get("sampling_eligible"),
        },
        "evaluation": {
            "is_valid": evaluation.get("is_valid"),
            "error": evaluation.get("error"),
        },
    }


def validate_natural_language_preamble_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.natural_language_preamble_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "natural language preamble report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "preamble_record_count",
        "structured_proposal_plus_preamble_count",
        "candidate_status_counts",
        "mutation_mode_counts",
        "records",
        "records_limit",
        "records_truncated",
        "preamble_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"natural language preamble report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.natural_language_preamble_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "natural language preamble report schema is unsupported",
            }
        )
    if report.get("source") != "runtime_history_explanatory_preamble_metadata":
        issues.append(
            {
                "code": "invalid_source",
                "message": "natural language preamble report source is unsupported",
            }
        )
    for field in (
        "generated_candidate_count",
        "preamble_record_count",
        "structured_proposal_plus_preamble_count",
        "records_limit",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {"code": "invalid_record", "message": f"record {index} must be an object"}
            )
            continue
        preamble = record.get("preamble")
        if not isinstance(preamble, dict):
            issues.append(
                {
                    "code": "invalid_record_preamble",
                    "message": f"record {index} preamble must be an object",
                }
            )
            continue
        if preamble.get("schema") != "libreevolve.explanatory_preamble.v1":
            issues.append(
                {
                    "code": "invalid_record_preamble_schema",
                    "message": f"record {index} preamble schema is unsupported",
                }
            )
        if preamble.get("policy") != "bounded_redacted_leading_preamble_only":
            issues.append(
                {
                    "code": "invalid_record_preamble_policy",
                    "message": f"record {index} preamble policy is unsupported",
                }
            )
        if not _is_sha256_hex(preamble.get("sha256")):
            issues.append(
                {
                    "code": "invalid_record_preamble_hash",
                    "message": f"record {index} preamble sha256 is invalid",
                }
            )
    if report.get("records_truncated") is not True:
        if report.get("preamble_record_count") != len(records):
            issues.append(
                {
                    "code": "invalid_record_count",
                    "message": "preamble count must match records when not truncated",
                }
            )
    for field in ("candidate_status_counts", "mutation_mode_counts"):
        if not isinstance(report.get(field), dict):
            issues.append(
                {"code": f"invalid_{field}", "message": f"{field} must be an object"}
            )
    if not isinstance(report.get("preamble_policy"), dict):
        issues.append(
            {"code": "invalid_preamble_policy", "message": "preamble_policy must be an object"}
        )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "claim_ready_overclaim",
                "message": "natural language preamble report must not claim full readiness",
            }
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("arbitrary_unparsed_rationale_accepted") is not False:
            issues.append(
                {
                    "code": "arbitrary_rationale_overclaim",
                    "message": "arbitrary_unparsed_rationale_accepted must be false",
                }
            )
    return {
        "schema": "libreevolve.natural_language_preamble_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _prompt_current_binding_report(
    programs: list[Program],
    run_dir: Path,
    startup_manifest: Mapping[str, object],
) -> dict:
    parent_by_id = {program.id: program for program in programs}
    history_indexes = _prompt_current_history_join_indexes(run_dir)
    records = [
        _prompt_current_binding_record(
            program,
            parent_by_id.get(program.parent_id),
            history_indexes,
        )
        for program in programs
        if _prompt_current_binding_is_generated(program)
    ]
    table_rows = _prompt_current_binding_table_rows(
        records,
        startup_manifest,
    )
    table_export = _write_prompt_current_binding_table(run_dir, table_rows)
    mode_counts: dict[str, int] = {}
    status_counts: dict[str, int] = {}
    exact_match_count = 0
    truncated_prompt_current_count = 0
    omitted_path_count = 0
    evolve_block_match_count = 0
    file_section_record_count = 0
    full_mode_target_record_count = 0
    history_join_count = 0
    prompt_history_score_join_count = 0
    for record in records:
        mode = str(record.get("mutation_mode") or "unknown")
        mode_counts[mode] = mode_counts.get(mode, 0) + 1
        status = str(record.get("candidate_status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        binding = record.get("mutation_binding")
        if isinstance(binding, Mapping) and binding.get("all_search_blocks_match_once") is True:
            exact_match_count += 1
        if isinstance(binding, Mapping):
            section_records = binding.get("file_section_records")
            if isinstance(section_records, list):
                file_section_record_count += len(section_records)
            full_target_records = binding.get("full_mode_target_records")
            if isinstance(full_target_records, list):
                full_mode_target_record_count += len(full_target_records)
            for match in binding.get("match_records", []):
                if not isinstance(match, Mapping):
                    continue
                scope = match.get("evolve_block_scope")
                if isinstance(scope, Mapping) and scope.get("scope") == "evolve_block":
                    evolve_block_match_count += 1
        prompt_current = record.get("prompt_current_program")
        if isinstance(prompt_current, Mapping):
            if prompt_current.get("parent_code_truncated") is True:
                truncated_prompt_current_count += 1
            omitted = prompt_current.get("omitted_path_count")
            if isinstance(omitted, int) and not isinstance(omitted, bool):
                omitted_path_count += omitted
        history_join = record.get("history_join")
        if isinstance(history_join, Mapping):
            candidate_history = history_join.get("candidate_history")
            if (
                isinstance(candidate_history, Mapping)
                and candidate_history.get("line_number") is not None
            ):
                history_join_count += 1
            prompt_history = history_join.get("prompt_history")
            if (
                isinstance(prompt_history, Mapping)
                and prompt_history.get("score_line_number") is not None
            ):
                prompt_history_score_join_count += 1
    report = {
        "schema": "libreevolve.prompt_current_binding_report.v1",
        "source": "runtime_history_prompt_diagnostics_parent_workspace_mutation_payload_and_jsonl_row_indexes",
        "generated_candidate_count": len(records),
        "binding_record_count": len(records),
        "mutation_mode_counts": dict(sorted(mode_counts.items())),
        "candidate_status_counts": dict(sorted(status_counts.items())),
        "exact_diff_binding_count": exact_match_count,
        "evolve_block_match_count": evolve_block_match_count,
        "file_section_record_count": file_section_record_count,
        "full_mode_target_record_count": full_mode_target_record_count,
        "history_join_count": history_join_count,
        "prompt_history_score_join_count": prompt_history_score_join_count,
        "cross_run_binding_table_record_count": table_export["record_count"],
        "truncated_prompt_current_count": truncated_prompt_current_count,
        "omitted_prompt_current_path_total": omitted_path_count,
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "binding_policy": {
            "prompt_current_source": "prompt_diagnostics.parent_code_policy",
            "mutation_target_source": "selected_parent.workspace_at_mutation_time",
            "diff_match_policy": "primary_file_exact_SEARCH_match_counts_for_non_file_section_diff_payloads",
            "evolve_block_scope_policy": "normalized_SEARCH_span_mapped_to_parent_evolve_block_when_exactly_inside_block_content",
            "full_mode_policy": "primary_file_or_named_evolve_block_target_spans_recorded_without_SEARCH_match_claim",
            "workspace_section_policy": "file_section_payloads_record_per_section_target_and_full_file_span_records",
            "file_section_span_policy": "file_section_targets_record_parent_and_candidate_full_file_spans_when_available",
            "history_join_policy": "candidate_history_rows_joined_to_prompt_history_add_and_score_rows_by_program_id",
            "cross_run_table_policy": "stable_jsonl_rows_with_run_id_prompt_ids_candidate_ids_hashes_and_joined_runtime_row_numbers",
            "llm_call_source": "candidate.metadata.llm_calls",
        },
        "cross_run_binding_table": table_export,
        "claim_ready": False,
        "claim_readiness": {
            "prompt_current_hashes_recorded": any(
                _prompt_current_has_hashes(record) for record in records
            ),
            "parent_workspace_hash_recorded": any(
                _is_sha256_hex(record.get("parent_workspace_sha256"))
                for record in records
            ),
            "candidate_workspace_hash_recorded": any(
                _is_sha256_hex(record.get("candidate_workspace_sha256"))
                for record in records
            ),
            "diff_exact_match_spans_recorded": exact_match_count > 0,
            "evolve_block_inner_span_mapping": evolve_block_match_count > 0,
            "workspace_file_section_span_records": file_section_record_count > 0,
            "full_mode_target_spans_or_block_ids": full_mode_target_record_count > 0,
            "prompt_history_row_join": (
                history_join_count > 0 and prompt_history_score_join_count > 0
            ),
            "cross_run_binding_table": table_export["record_count"] > 0,
            "full_alphaevolve_current_program_provenance": False,
            "remaining_gap": [],
        },
    }
    report["validation"] = validate_prompt_current_binding_report(report)
    return report


def _prompt_current_binding_is_generated(program: Program) -> bool:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    return metadata.get("candidate_type") == "generated"


def _prompt_current_binding_table_rows(
    records: list[dict],
    startup_manifest: Mapping[str, object],
) -> list[dict]:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    run_id = config.get("run_id") if isinstance(config.get("run_id"), str) else None
    problem_name = (
        config.get("problem_name")
        if isinstance(config.get("problem_name"), str)
        else None
    )
    rows: list[dict] = []
    for record_index, record in enumerate(records):
        if not isinstance(record, Mapping):
            continue
        binding = (
            record.get("mutation_binding")
            if isinstance(record.get("mutation_binding"), Mapping)
            else {}
        )
        prompt_current = (
            record.get("prompt_current_program")
            if isinstance(record.get("prompt_current_program"), Mapping)
            else {}
        )
        history_join = (
            record.get("history_join")
            if isinstance(record.get("history_join"), Mapping)
            else {}
        )
        rows.append(
            {
                "schema": "libreevolve.prompt_current_binding_table_row.v1",
                "row_index": record_index,
                "run_id": run_id,
                "problem_name": problem_name,
                "candidate_id": record.get("candidate_id"),
                "candidate_status": record.get("candidate_status"),
                "generation": record.get("generation"),
                "parent_id": record.get("parent_id"),
                "prompt_program_id": record.get("prompt_program_id"),
                "prompt_sha256": record.get("prompt_sha256"),
                "prompt_sha256_scope": record.get("prompt_sha256_scope"),
                "mutation_mode": record.get("mutation_mode"),
                "mutation_payload_sha256": record.get("mutation_payload_sha256"),
                "parent_workspace_sha256": record.get("parent_workspace_sha256"),
                "candidate_workspace_sha256": record.get("candidate_workspace_sha256"),
                "prompt_current": {
                    "primary_file": prompt_current.get("primary_file"),
                    "parent_code_original_sha256": prompt_current.get(
                        "parent_code_original_sha256"
                    ),
                    "parent_code_rendered_sha256": prompt_current.get(
                        "parent_code_rendered_sha256"
                    ),
                    "parent_code_truncated": prompt_current.get(
                        "parent_code_truncated"
                    ),
                    "rendered_paths": prompt_current.get("rendered_paths", []),
                    "omitted_path_count": prompt_current.get("omitted_path_count"),
                },
                "history_join": _prompt_current_binding_table_history_join(
                    history_join
                ),
                "binding": _prompt_current_binding_table_binding_summary(binding),
                "evaluation": record.get("evaluation_link"),
                "admission": record.get("admission_link"),
            }
        )
    return rows


def _prompt_current_binding_table_history_join(history_join: Mapping[str, object]) -> dict:
    candidate_history = history_join.get("candidate_history")
    prompt_history = history_join.get("prompt_history")
    candidate_failure_history = history_join.get("candidate_failure_history")
    return {
        "candidate_history_stream": (
            candidate_history.get("stream")
            if isinstance(candidate_history, Mapping)
            else None
        ),
        "candidate_history_line_number": (
            candidate_history.get("line_number")
            if isinstance(candidate_history, Mapping)
            else None
        ),
        "candidate_failure_history_line_number": (
            candidate_failure_history.get("line_number")
            if isinstance(candidate_failure_history, Mapping)
            else None
        ),
        "prompt_history_add_line_number": (
            prompt_history.get("add_line_number")
            if isinstance(prompt_history, Mapping)
            else None
        ),
        "prompt_history_score_line_number": (
            prompt_history.get("score_line_number")
            if isinstance(prompt_history, Mapping)
            else None
        ),
        "prompt_history_score_line_numbers": (
            prompt_history.get("score_line_numbers", [])
            if isinstance(prompt_history, Mapping)
            else []
        ),
    }


def _prompt_current_binding_table_binding_summary(binding: Mapping[str, object]) -> dict:
    match_records = (
        binding.get("match_records")
        if isinstance(binding.get("match_records"), list)
        else []
    )
    file_section_records = (
        binding.get("file_section_records")
        if isinstance(binding.get("file_section_records"), list)
        else []
    )
    full_target_records = (
        binding.get("full_mode_target_records")
        if isinstance(binding.get("full_mode_target_records"), list)
        else []
    )
    return {
        "mode_policy": binding.get("mode_policy"),
        "payload_surfaces": binding.get("payload_surfaces", []),
        "target_path": binding.get("target_path"),
        "all_search_blocks_match_once": binding.get("all_search_blocks_match_once"),
        "search_block_count": binding.get("search_block_count"),
        "diff_match_count": len(match_records),
        "evolve_block_scope_count": sum(
            1
            for match in match_records
            if isinstance(match, Mapping)
            and isinstance(match.get("evolve_block_scope"), Mapping)
            and match["evolve_block_scope"].get("scope") == "evolve_block"
        ),
        "file_section_count": binding.get("file_section_count", len(file_section_records)),
        "full_mode_target_count": binding.get(
            "full_mode_target_count",
            len(full_target_records),
        ),
        "file_section_targets": [
            {
                "operation": section.get("operation"),
                "target_path": section.get("target_path"),
                "target_span_policy": section.get("target_span_policy"),
            }
            for section in file_section_records[:25]
            if isinstance(section, Mapping)
        ],
        "full_mode_targets": [
            {
                "target_scope": target.get("target_scope"),
                "target_path": target.get("target_path"),
                "block_name": target.get("block_name"),
                "target_span_policy": target.get("target_span_policy"),
            }
            for target in full_target_records[:25]
            if isinstance(target, Mapping)
        ],
    }


def _write_prompt_current_binding_table(run_dir: Path, rows: list[dict]) -> dict:
    table_path = run_dir / "prompt_current_binding_table.jsonl"
    if not rows:
        return {
            "schema": "libreevolve.prompt_current_binding_table_export.v1",
            "path": "prompt_current_binding_table.jsonl",
            "record_schema": PROMPT_CURRENT_BINDING_TABLE_RECORD_SCHEMA,
            "record_count": 0,
            "exists": False,
            "sha256": None,
            "cross_run_policy": "rows_are_safe_to_concatenate_across_run_directories_by_run_id",
        }
    lines = [
        strict_json_dumps(
            versioned_record(PROMPT_CURRENT_BINDING_TABLE_RECORD_SCHEMA, row)
        )
        for row in rows
    ]
    text = "\n".join(lines) + "\n"
    table_path.write_text(text, encoding="utf-8")
    return {
        "schema": "libreevolve.prompt_current_binding_table_export.v1",
        "path": "prompt_current_binding_table.jsonl",
        "record_schema": PROMPT_CURRENT_BINDING_TABLE_RECORD_SCHEMA,
        "record_count": len(rows),
        "exists": True,
        "sha256": hashlib.sha256(text.encode("utf-8")).hexdigest(),
        "cross_run_policy": "rows_are_safe_to_concatenate_across_run_directories_by_run_id",
    }


def _prompt_current_history_join_indexes(run_dir: Path) -> dict:
    history_rows: dict[str, dict] = {}
    failure_rows: dict[str, dict] = {}
    evaluator_result_rows: dict[str, dict] = {}
    prompt_add_rows: dict[str, dict] = {}
    prompt_score_rows_by_candidate: dict[str, list[dict]] = {}

    history_path = run_dir / "history.jsonl"
    if history_path.exists():
        for line_number, record in enumerate(
            iter_strict_jsonl_objects(history_path, stream_name="history.jsonl"),
            start=1,
        ):
            program_id = record.get("id")
            if isinstance(program_id, str):
                history_rows[program_id] = {
                    "stream": "history.jsonl",
                    "line_number": line_number,
                    "program_id": program_id,
                    "record_schema": record.get("record_schema"),
                }

    failure_path = run_dir / "failure_history.jsonl"
    if failure_path.exists():
        for line_number, record in enumerate(
            iter_strict_jsonl_objects(
                failure_path,
                stream_name="failure_history.jsonl",
            ),
            start=1,
        ):
            program_id = record.get("program_id")
            if isinstance(program_id, str):
                failure_rows[program_id] = {
                    "stream": "failure_history.jsonl",
                    "line_number": line_number,
                    "program_id": program_id,
                    "record_schema": record.get("record_schema"),
                    "admission_reason": record.get("admission_reason"),
                }

    evaluator_results_path = run_dir / "evaluator_results.jsonl"
    if evaluator_results_path.exists():
        for line_number, record in enumerate(
            iter_strict_jsonl_objects(
                evaluator_results_path,
                stream_name="evaluator_results.jsonl",
            ),
            start=1,
        ):
            candidate_id = record.get("candidate_id")
            if isinstance(candidate_id, str):
                evaluator_result_rows[candidate_id] = {
                    "stream": "evaluator_results.jsonl",
                    "line_number": line_number,
                    "candidate_id": candidate_id,
                    "row_id": record.get("row_id"),
                    "record_schema": record.get("record_schema"),
                    "is_valid": record.get("is_valid"),
                    "score": record.get("score"),
                    "evaluator_mode": record.get("evaluator_mode"),
                    "execution_output": record.get("execution_output"),
                    "stage_summary_io": record.get("stage_summary_io"),
                }

    prompt_path = run_dir / "prompt_history.jsonl"
    if prompt_path.exists():
        for line_number, record in enumerate(
            iter_strict_jsonl_objects(
                prompt_path,
                stream_name="prompt_history.jsonl",
            ),
            start=1,
        ):
            event = record.get("event")
            program_record = record.get("program")
            if not isinstance(program_record, Mapping):
                continue
            prompt_id = program_record.get("id")
            if not isinstance(prompt_id, str):
                continue
            prompt_row = {
                "stream": "prompt_history.jsonl",
                "line_number": line_number,
                "event": event,
                "prompt_program_id": prompt_id,
                "record_schema": record.get("record_schema"),
            }
            if event == "add":
                prompt_add_rows.setdefault(prompt_id, prompt_row)
            elif event == "score":
                metadata = program_record.get("metadata")
                candidate_id = (
                    metadata.get("last_program_id")
                    if isinstance(metadata, Mapping)
                    else None
                )
                if isinstance(candidate_id, str):
                    score_row = dict(prompt_row)
                    score_row["candidate_id"] = candidate_id
                    prompt_score_rows_by_candidate.setdefault(candidate_id, []).append(
                        score_row
                    )

    return {
        "candidate_history_by_id": history_rows,
        "candidate_failure_history_by_id": failure_rows,
        "evaluator_result_by_candidate_id": evaluator_result_rows,
        "prompt_add_by_id": prompt_add_rows,
        "prompt_scores_by_candidate_id": prompt_score_rows_by_candidate,
    }


def _prompt_current_history_join_record(
    candidate_id: str,
    prompt_program_id: object,
    history_indexes: Mapping[str, object],
) -> dict:
    candidate_history_by_id = history_indexes.get("candidate_history_by_id")
    candidate_failure_history_by_id = history_indexes.get(
        "candidate_failure_history_by_id"
    )
    prompt_add_by_id = history_indexes.get("prompt_add_by_id")
    prompt_scores_by_candidate_id = history_indexes.get(
        "prompt_scores_by_candidate_id"
    )
    candidate_history = (
        candidate_history_by_id.get(candidate_id)
        if isinstance(candidate_history_by_id, Mapping)
        else None
    )
    candidate_failure_history = (
        candidate_failure_history_by_id.get(candidate_id)
        if isinstance(candidate_failure_history_by_id, Mapping)
        else None
    )
    prompt_add = (
        prompt_add_by_id.get(prompt_program_id)
        if isinstance(prompt_program_id, str) and isinstance(prompt_add_by_id, Mapping)
        else None
    )
    score_rows = (
        prompt_scores_by_candidate_id.get(candidate_id, [])
        if isinstance(prompt_scores_by_candidate_id, Mapping)
        else []
    )
    score_rows = [row for row in score_rows if isinstance(row, Mapping)]
    score_line_numbers = [
        row.get("line_number")
        for row in score_rows
        if isinstance(row.get("line_number"), int)
        and not isinstance(row.get("line_number"), bool)
    ]
    prompt_history: dict[str, object] = {
        "stream": "prompt_history.jsonl",
        "prompt_program_id": prompt_program_id if isinstance(prompt_program_id, str) else None,
        "add_line_number": (
            prompt_add.get("line_number") if isinstance(prompt_add, Mapping) else None
        ),
        "score_line_number": score_line_numbers[-1] if score_line_numbers else None,
        "score_line_numbers": score_line_numbers[:25],
        "score_line_numbers_truncated": len(score_line_numbers) > 25,
    }
    return {
        "schema": "libreevolve.prompt_current_history_join.v1",
        "candidate_id": candidate_id,
        "join_policy": "history_jsonl_candidate_id_and_prompt_history_score_metadata_last_program_id",
        "candidate_history": (
            dict(candidate_history) if isinstance(candidate_history, Mapping) else None
        ),
        "candidate_failure_history": (
            dict(candidate_failure_history)
            if isinstance(candidate_failure_history, Mapping)
            else None
        ),
        "prompt_history": prompt_history,
        "candidate_history_joined": isinstance(candidate_history, Mapping),
        "prompt_history_add_joined": isinstance(prompt_add, Mapping),
        "prompt_history_score_joined": bool(score_line_numbers),
    }


def _prompt_current_binding_record(
    program: Program,
    parent: Program | None,
    history_indexes: Mapping[str, object],
) -> dict:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    prompt_diagnostics = (
        metadata.get("prompt_diagnostics")
        if isinstance(metadata.get("prompt_diagnostics"), Mapping)
        else {}
    )
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), Mapping)
        else {}
    )
    evaluation = program.evaluation if isinstance(program.evaluation, Mapping) else {}
    llm_calls = metadata.get("llm_calls") if isinstance(metadata.get("llm_calls"), list) else []
    parent_workspace = parent.workspace() if parent is not None else None
    payload = metadata.get("diff")
    mode = str(metadata.get("mutation_mode") or "unknown")
    candidate_status = (
        "accepted_history"
        if admission.get("admitted") is True
        else "rejected_history"
    )
    return {
        "candidate_id": program.id,
        "candidate_status": candidate_status,
        "generation": program.generation,
        "parent_id": program.parent_id,
        "prompt_program_id": metadata.get("prompt_program_id"),
        "history_join": _prompt_current_history_join_record(
            program.id,
            metadata.get("prompt_program_id"),
            history_indexes,
        ),
        "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
        "prompt_sha256_scope": prompt_diagnostics.get("prompt_sha256_scope"),
        "llm_call_ids": [
            call.get("id")
            for call in llm_calls
            if isinstance(call, Mapping) and isinstance(call.get("id"), str)
        ],
        "mutation_mode": mode,
        "mutation_payload_sha256": hashlib.sha256(
            str(payload or "").encode("utf-8")
        ).hexdigest(),
        "parent_workspace_sha256": (
            _workspace_sha256(parent_workspace) if parent_workspace is not None else None
        ),
        "candidate_workspace_sha256": _workspace_sha256(program.workspace()),
        "prompt_current_program": _prompt_current_program_record(
            prompt_diagnostics,
            parent_workspace,
        ),
        "mutation_binding": _prompt_current_mutation_binding(
            parent_workspace,
            program.workspace(),
            payload,
            mode,
        ),
        "evaluation_link": {
            "is_valid": evaluation.get("is_valid"),
            "fitness": program.fitness,
            "error": evaluation.get("error"),
        },
        "admission_link": {
            "admitted": admission.get("admitted"),
            "reason": admission.get("reason"),
            "sampling_eligible": admission.get("sampling_eligible"),
        },
    }


def _prompt_current_program_record(
    prompt_diagnostics: Mapping[str, object],
    parent_workspace: CandidateWorkspace | None,
) -> dict:
    policy = (
        prompt_diagnostics.get("parent_code_policy")
        if isinstance(prompt_diagnostics.get("parent_code_policy"), Mapping)
        else {}
    )
    path_policy = (
        policy.get("path_policy")
        if isinstance(policy.get("path_policy"), Mapping)
        else {}
    )
    rendered_paths = [
        path for path in path_policy.get("rendered_paths", []) if isinstance(path, str)
    ]
    omitted_paths = [
        path for path in path_policy.get("omitted_paths", []) if isinstance(path, str)
    ]
    parent_file_hashes = []
    if parent_workspace is not None:
        for path in rendered_paths[:25]:
            content = parent_workspace.files.get(path)
            if isinstance(content, str):
                parent_file_hashes.append(
                    {
                        "path": path,
                        "sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(),
                        "chars": len(content),
                    }
                )
    return {
        "policy_schema": policy.get("schema"),
        "parent_code_original_sha256": policy.get("original_sha256"),
        "parent_code_rendered_sha256": policy.get("rendered_sha256"),
        "parent_code_original_chars": policy.get("original_chars"),
        "parent_code_rendered_chars": policy.get("rendered_chars"),
        "parent_code_truncated": policy.get("truncated"),
        "path_policy_schema": path_policy.get("schema"),
        "path_policy_source": path_policy.get("source"),
        "primary_file": path_policy.get("primary_file")
        if isinstance(path_policy.get("primary_file"), str)
        else (parent_workspace.primary_file if parent_workspace is not None else None),
        "rendered_paths": rendered_paths[:25],
        "rendered_paths_truncated": len(rendered_paths) > 25,
        "omitted_path_count": len(omitted_paths),
        "omitted_paths": omitted_paths[:25],
        "omitted_paths_truncated": len(omitted_paths) > 25,
        "rendered_parent_file_hashes": parent_file_hashes,
        "rendered_parent_file_hashes_truncated": len(rendered_paths) > 25,
    }


def _prompt_current_mutation_binding(
    parent_workspace: CandidateWorkspace | None,
    candidate_workspace: CandidateWorkspace,
    payload: object,
    mode: str,
) -> dict:
    if parent_workspace is None:
        return {
            "mode_policy": "parent_workspace_unavailable",
            "all_search_blocks_match_once": False,
            "search_block_count": 0,
            "match_records": [],
        }
    if not isinstance(payload, str) or not payload:
        return {
            "mode_policy": "missing_or_non_text_payload",
            "all_search_blocks_match_once": False,
            "search_block_count": 0,
            "match_records": [],
        }
    surfaces = _mutation_operator_payload_surfaces(payload, mode)
    if "file_sections" in surfaces:
        section_records = _prompt_current_file_section_records(
            parent_workspace,
            candidate_workspace,
            payload,
        )
        return {
            "mode_policy": "workspace_file_section_payload_span_records",
            "payload_surfaces": surfaces,
            "all_search_blocks_match_once": False,
            "search_block_count": 0,
            "match_records": [],
            "file_section_count": len(section_records),
            "file_section_records": section_records[:50],
            "file_section_records_truncated": len(section_records) > 50,
        }
    if mode == "full":
        full_target_records = _prompt_current_full_mode_target_records(
            parent_workspace,
            candidate_workspace,
            payload,
        )
        return {
            "mode_policy": "full_mode_target_span_records",
            "payload_surfaces": surfaces,
            "target_path": parent_workspace.primary_file,
            "all_search_blocks_match_once": False,
            "search_block_count": 0,
            "match_records": [],
            "full_mode_target_count": len(full_target_records),
            "full_mode_target_records": full_target_records[:25],
            "full_mode_target_records_truncated": len(full_target_records) > 25,
        }
    if mode != "diff":
        return {
            "mode_policy": "unsupported_mutation_mode_for_binding_spans",
            "payload_surfaces": surfaces,
            "all_search_blocks_match_once": False,
            "search_block_count": 0,
            "match_records": [],
        }
    blocks = parse_diff_blocks(payload)
    target_path = parent_workspace.primary_file
    target_text = parent_workspace.files.get(target_path, "")
    match_records = [
        _prompt_current_search_match_record(target_path, target_text, search)
        for search, _replace in blocks
    ]
    return {
        "mode_policy": "diff_primary_file_exact_search_match",
        "payload_surfaces": surfaces,
        "target_path": target_path,
        "search_block_count": len(blocks),
        "all_search_blocks_match_once": bool(blocks)
        and all(record["match_count"] == 1 for record in match_records),
        "match_records": match_records[:25],
        "match_records_truncated": len(match_records) > 25,
    }


def _prompt_current_file_section_records(
    parent_workspace: CandidateWorkspace | None,
    candidate_workspace: CandidateWorkspace,
    payload: str,
) -> list[dict]:
    records: list[dict] = []
    for index, match in enumerate(_PROMPT_EXAMPLE_FILE_SECTION_RE.finditer(payload)):
        header = match.group(1).strip()
        body = match.group(2)
        section = _prompt_current_file_section_target(header)
        record = {
            "section_index": index,
            "header": _mutation_consistency_safe_label(header),
            "operation": section["operation"],
            "body_sha256": hashlib.sha256(body.encode("utf-8")).hexdigest(),
            "body_chars": len(body),
            "target_span_policy": section["target_span_policy"],
        }
        if section.get("target_path"):
            target_path = str(section["target_path"])
            record["target_path"] = target_path
            record["parent_file"] = _prompt_current_file_span_record(
                parent_workspace.files.get(target_path)
                if parent_workspace is not None
                else None
            )
            record["candidate_file"] = _prompt_current_file_span_record(
                candidate_workspace.files.get(target_path)
            )
        if section.get("source_path"):
            source_path = str(section["source_path"])
            record["source_path"] = source_path
            record["source_parent_file"] = _prompt_current_file_span_record(
                parent_workspace.files.get(source_path)
                if parent_workspace is not None
                else None
            )
            record["source_candidate_file"] = _prompt_current_file_span_record(
                candidate_workspace.files.get(source_path)
            )
        if section.get("destination_path"):
            destination_path = str(section["destination_path"])
            record["destination_path"] = destination_path
            record["destination_parent_file"] = _prompt_current_file_span_record(
                parent_workspace.files.get(destination_path)
                if parent_workspace is not None
                else None
            )
            record["destination_candidate_file"] = _prompt_current_file_span_record(
                candidate_workspace.files.get(destination_path)
            )
        records.append(record)
    return records


def _prompt_current_full_mode_target_records(
    parent_workspace: CandidateWorkspace,
    candidate_workspace: CandidateWorkspace,
    payload: str,
) -> list[dict]:
    target_path = parent_workspace.primary_file
    parent_text = parent_workspace.files.get(target_path, "")
    candidate_text = candidate_workspace.files.get(target_path, "")
    parent_blocks = extract_evolve_blocks(parent_text)
    candidate_blocks = extract_evolve_blocks(candidate_text)
    normalized_payload = _prompt_current_strip_outer_markdown_fence(payload)
    block_sections = [
        (match.group(1).strip(), match.group(2))
        for match in _PROMPT_CURRENT_BLOCK_SECTION_RE.finditer(normalized_payload)
    ]
    if block_sections:
        parent_by_name = {
            block.name: (index, block)
            for index, block in enumerate(parent_blocks)
        }
        candidate_by_name = {
            block.name: (index, block) for index, block in enumerate(candidate_blocks)
        }
        records: list[dict] = []
        for section_index, (name, body) in enumerate(block_sections):
            parent_index, parent_block = parent_by_name.get(name, (None, None))
            candidate_index, candidate_block = candidate_by_name.get(
                name,
                (None, None),
            )
            record = {
                "target_index": section_index,
                "target_path": target_path,
                "target_scope": "evolve_block",
                "block_name": _mutation_consistency_safe_label(name),
                "block_section_body_sha256": hashlib.sha256(
                    body.encode("utf-8")
                ).hexdigest(),
                "block_section_body_chars": len(body),
                "target_span_policy": "named_block_section_targets_parent_evolve_block_content_span",
                "parent_block": _prompt_current_block_span_record(
                    parent_block,
                    parent_index,
                ),
                "candidate_block": _prompt_current_block_span_record(
                    candidate_block,
                    candidate_index,
                ),
            }
            records.append(record)
        return records

    if len(parent_blocks) == 1:
        candidate_block = (
            candidate_blocks[0]
            if (
                len(candidate_blocks) == 1
                and candidate_blocks[0].name == parent_blocks[0].name
            )
            else None
        )
        return [
            {
                "target_index": 0,
                "target_path": target_path,
                "target_scope": "evolve_block",
                "block_name": _mutation_consistency_safe_label(parent_blocks[0].name),
                "target_span_policy": "single_parent_evolve_block_content_span",
                "parent_block": _prompt_current_block_span_record(
                    parent_blocks[0],
                    0,
                ),
                "candidate_block": _prompt_current_block_span_record(
                    candidate_block,
                    0 if candidate_block is not None else None,
                ),
            }
        ]

    if parent_blocks:
        return [
            {
                "target_index": 0,
                "target_path": target_path,
                "target_scope": "ambiguous_evolve_blocks",
                "target_span_policy": "multiple_parent_evolve_blocks_require_named_block_sections",
                "parent_block_count": len(parent_blocks),
                "candidate_block_count": len(candidate_blocks),
            }
        ]

    return [
        {
            "target_index": 0,
            "target_path": target_path,
            "target_scope": "whole_file",
            "target_span_policy": "whole_primary_file_replacement",
            "parent_file": _prompt_current_file_span_record(parent_text),
            "candidate_file": _prompt_current_file_span_record(candidate_text),
        }
    ]


def _prompt_current_block_span_record(
    block: object,
    block_index: int | None,
) -> dict:
    if block is None:
        return {
            "exists": False,
            "block_index": block_index,
            "block_name": None,
            "outer_span": None,
            "content_span": None,
            "content_sha256": None,
            "content_chars": 0,
        }
    content = getattr(block, "content", "")
    if not isinstance(content, str):
        content = ""
    return {
        "exists": True,
        "block_index": block_index,
        "block_name": _mutation_consistency_safe_label(
            str(getattr(block, "name", ""))
        ),
        "outer_span": [
            int(getattr(block, "start", 0)),
            int(getattr(block, "end", 0)),
        ],
        "content_span": [
            int(getattr(block, "content_start", 0)),
            int(getattr(block, "content_end", 0)),
        ],
        "content_sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(),
        "content_chars": len(content),
    }


def _prompt_current_strip_outer_markdown_fence(text: str) -> str:
    normalized = text.replace("\r\n", "\n").replace("\r", "\n")
    stripped = normalized.strip()
    if not stripped.startswith("```"):
        return normalized
    lines = stripped.splitlines()
    if len(lines) < 2 or not lines[-1].strip().startswith("```"):
        return normalized
    return "\n".join(lines[1:-1])


def _prompt_current_file_section_target(header: str) -> dict:
    command = _mutation_consistency_file_command(header)
    if command == "PATH":
        return {
            "operation": "edit",
            "target_path": _mutation_consistency_safe_label(
                header.partition(" ")[2].strip()
            ),
            "target_span_policy": "full_file_replacement_section",
        }
    if command in {"STATIC", "BINARY"}:
        return {
            "operation": command.lower(),
            "target_path": _mutation_consistency_safe_label(
                header.partition(" ")[2].strip()
            ),
            "target_span_policy": "static_or_binary_section_no_text_span_claim",
        }
    if command == "DELETE":
        return {
            "operation": "delete",
            "target_path": _mutation_consistency_safe_label(
                header.partition(" ")[2].strip()
            ),
            "target_span_policy": "delete_section_removes_full_file",
        }
    if command in {"MOVE", "RENAME"}:
        source, _sep, destination = header.partition(" ")[2].partition("->")
        return {
            "operation": "move",
            "source_path": _mutation_consistency_safe_label(source.strip()),
            "destination_path": _mutation_consistency_safe_label(destination.strip()),
            "target_span_policy": "move_section_retargets_full_file",
        }
    if command == "PRIMARY":
        return {
            "operation": "primary",
            "target_path": _mutation_consistency_safe_label(
                header.partition(" ")[2].strip()
            ),
            "target_span_policy": "primary_selection_no_text_span_claim",
        }
    return {
        "operation": "edit",
        "target_path": _mutation_consistency_safe_label(header),
        "target_span_policy": "full_file_replacement_section",
    }


def _prompt_current_file_span_record(content: object) -> dict:
    if not isinstance(content, str):
        return {
            "exists": False,
            "sha256": None,
            "chars": 0,
            "normalized_full_file_span": None,
        }
    normalized = content.replace("\r\n", "\n").replace("\r", "\n")
    return {
        "exists": True,
        "sha256": hashlib.sha256(content.encode("utf-8")).hexdigest(),
        "chars": len(content),
        "normalized_chars": len(normalized),
        "normalized_full_file_span": [0, len(normalized)],
    }


def _prompt_current_search_match_record(
    target_path: str,
    target_text: str,
    search: str,
) -> dict:
    normalized_target = target_text.replace("\r\n", "\n").replace("\r", "\n")
    normalized_search = search.replace("\r\n", "\n").replace("\r", "\n")
    match_count = normalized_target.count(normalized_search) if normalized_search else 0
    start = normalized_target.find(normalized_search) if match_count == 1 else -1
    span = [start, start + len(normalized_search)] if start >= 0 else None
    return {
        "target_path": target_path,
        "search_sha256": hashlib.sha256(search.encode("utf-8")).hexdigest(),
        "search_chars": len(search),
        "match_count": match_count,
        "normalized_span": span,
        "evolve_block_scope": _prompt_current_evolve_block_scope(
            target_path,
            normalized_target,
            span,
        ),
    }


def _prompt_current_evolve_block_scope(
    target_path: str,
    normalized_target: str,
    span: list[int] | None,
) -> dict:
    if span is None:
        return {
            "scope": "unmatched_or_ambiguous",
            "target_path": target_path,
        }
    blocks = extract_evolve_blocks(normalized_target)
    if not blocks:
        return {
            "scope": "whole_file",
            "target_path": target_path,
        }
    start, end = span
    for index, block in enumerate(blocks):
        if start >= block.content_start and end <= block.content_end:
            return {
                "scope": "evolve_block",
                "target_path": target_path,
                "block_name": block.name,
                "block_index": index,
                "block_outer_span": [block.start, block.end],
                "block_content_span": [block.content_start, block.content_end],
                "search_span_in_block": [
                    start - block.content_start,
                    end - block.content_start,
                ],
            }
    return {
        "scope": "outside_evolve_block",
        "target_path": target_path,
    }


def _prompt_current_has_hashes(record: Mapping[str, object]) -> bool:
    prompt_current = record.get("prompt_current_program")
    if not isinstance(prompt_current, Mapping):
        return False
    return _is_sha256_hex(prompt_current.get("parent_code_original_sha256")) and (
        _is_sha256_hex(prompt_current.get("parent_code_rendered_sha256"))
    )


def validate_prompt_current_binding_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.prompt_current_binding_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "prompt-current binding report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "binding_record_count",
        "mutation_mode_counts",
        "candidate_status_counts",
        "exact_diff_binding_count",
        "evolve_block_match_count",
        "file_section_record_count",
        "full_mode_target_record_count",
        "history_join_count",
        "prompt_history_score_join_count",
        "cross_run_binding_table_record_count",
        "truncated_prompt_current_count",
        "omitted_prompt_current_path_total",
        "records",
        "records_limit",
        "records_truncated",
        "binding_policy",
        "cross_run_binding_table",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"prompt-current binding report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.prompt_current_binding_report.v1":
        issues.append({"code": "invalid_schema", "message": "prompt-current binding report schema is unsupported"})
    if (
        report.get("source")
        != "runtime_history_prompt_diagnostics_parent_workspace_mutation_payload_and_jsonl_row_indexes"
    ):
        issues.append({"code": "invalid_source", "message": "prompt-current binding report source is unsupported"})
    for field in (
        "generated_candidate_count",
        "binding_record_count",
        "exact_diff_binding_count",
        "evolve_block_match_count",
        "file_section_record_count",
        "full_mode_target_record_count",
        "history_join_count",
        "prompt_history_score_join_count",
        "cross_run_binding_table_record_count",
        "truncated_prompt_current_count",
        "omitted_prompt_current_path_total",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append({"code": f"invalid_{field}", "message": f"{field} must be a non-negative integer"})
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append({"code": "invalid_record", "message": f"record {index} must be an object"})
            continue
        if not isinstance(record.get("candidate_id"), str):
            issues.append({"code": "invalid_candidate_id", "message": f"record {index} candidate_id must be a string"})
        if record.get("candidate_status") not in {"accepted_history", "rejected_history"}:
            issues.append({"code": "invalid_candidate_status", "message": f"record {index} candidate_status is invalid"})
        if not _is_sha256_hex(record.get("candidate_workspace_sha256")):
            issues.append({"code": "invalid_candidate_workspace_hash", "message": f"record {index} candidate workspace hash is invalid"})
        binding = record.get("mutation_binding")
        if not isinstance(binding, dict):
            issues.append({"code": "invalid_mutation_binding", "message": f"record {index} mutation_binding must be an object"})
        else:
            match_records = binding.get("match_records")
            if isinstance(match_records, list):
                for match_index, match in enumerate(match_records):
                    if not isinstance(match, dict):
                        continue
                    scope = match.get("evolve_block_scope")
                    if not isinstance(scope, dict):
                        issues.append(
                            {
                                "code": "invalid_evolve_block_scope",
                                "message": (
                                    f"record {index} match {match_index} "
                                    "evolve_block_scope must be an object"
                                ),
                            }
                        )
                    elif scope.get("scope") not in {
                        "evolve_block",
                        "whole_file",
                        "outside_evolve_block",
                        "unmatched_or_ambiguous",
                    }:
                        issues.append(
                            {
                                "code": "invalid_evolve_block_scope_value",
                                "message": (
                                    f"record {index} match {match_index} "
                                    "evolve_block_scope.scope is invalid"
                                ),
                            }
                        )
            section_records = binding.get("file_section_records")
            if isinstance(section_records, list):
                for section_index, section in enumerate(section_records):
                    if not isinstance(section, dict):
                        issues.append(
                            {
                                "code": "invalid_file_section_record",
                                "message": (
                                    f"record {index} file section {section_index} "
                                    "must be an object"
                                ),
                            }
                        )
                        continue
                    if isinstance(section.get("section_index"), bool) or not isinstance(section.get("section_index"), int):
                        issues.append(
                            {
                                "code": "invalid_file_section_index",
                                "message": (
                                    f"record {index} file section {section_index} "
                                    "section_index must be an integer"
                                ),
                            }
                        )
                    if section.get("operation") not in {
                        "edit",
                        "delete",
                        "move",
                        "primary",
                        "static",
                        "binary",
                    }:
                        issues.append(
                            {
                                "code": "invalid_file_section_operation",
                                "message": (
                                    f"record {index} file section {section_index} "
                                    "operation is invalid"
                                ),
                            }
                        )
                    for file_field in (
                        "parent_file",
                        "candidate_file",
                        "source_parent_file",
                        "source_candidate_file",
                        "destination_parent_file",
                        "destination_candidate_file",
                    ):
                        file_record = section.get(file_field)
                        if file_record is not None and not isinstance(
                            file_record,
                            dict,
                        ):
                            issues.append(
                                {
                                    "code": "invalid_file_span_record",
                                    "message": (
                                        f"record {index} file section {section_index} "
                                        f"{file_field} must be an object"
                                    ),
                                }
                            )
            full_target_records = binding.get("full_mode_target_records")
            if isinstance(full_target_records, list):
                for target_index, target in enumerate(full_target_records):
                    if not isinstance(target, dict):
                        issues.append(
                            {
                                "code": "invalid_full_mode_target_record",
                                "message": (
                                    f"record {index} full target {target_index} "
                                    "must be an object"
                                ),
                            }
                        )
                        continue
                    if target.get("target_scope") not in {
                        "whole_file",
                        "evolve_block",
                        "ambiguous_evolve_blocks",
                    }:
                        issues.append(
                            {
                                "code": "invalid_full_mode_target_scope",
                                "message": (
                                    f"record {index} full target {target_index} "
                                    "target_scope is invalid"
                                ),
                            }
                        )
                    for target_field in (
                        "parent_file",
                        "candidate_file",
                        "parent_block",
                        "candidate_block",
                    ):
                        target_record = target.get(target_field)
                        if target_record is not None and not isinstance(
                            target_record,
                            dict,
                        ):
                            issues.append(
                                {
                                    "code": "invalid_full_mode_target_span_record",
                                    "message": (
                                        f"record {index} full target {target_index} "
                                        f"{target_field} must be an object"
                                    ),
                                }
                            )
        prompt_current = record.get("prompt_current_program")
        if not isinstance(prompt_current, dict):
            issues.append({"code": "invalid_prompt_current_program", "message": f"record {index} prompt_current_program must be an object"})
        history_join = record.get("history_join")
        if not isinstance(history_join, dict):
            issues.append(
                {
                    "code": "invalid_history_join",
                    "message": f"record {index} history_join must be an object",
                }
            )
        else:
            if history_join.get("schema") != "libreevolve.prompt_current_history_join.v1":
                issues.append(
                    {
                        "code": "invalid_history_join_schema",
                        "message": f"record {index} history_join schema is unsupported",
                    }
                )
            for field in ("candidate_history", "candidate_failure_history"):
                row = history_join.get(field)
                if row is not None and not isinstance(row, dict):
                    issues.append(
                        {
                            "code": "invalid_history_join_row",
                            "message": f"record {index} {field} must be an object or null",
                        }
                    )
            prompt_history = history_join.get("prompt_history")
            if not isinstance(prompt_history, dict):
                issues.append(
                    {
                        "code": "invalid_prompt_history_join",
                        "message": (
                            f"record {index} history_join.prompt_history "
                            "must be an object"
                        ),
                    }
                )
    if report.get("records_truncated") is not True:
        if report.get("binding_record_count") != len(records):
            issues.append({"code": "invalid_record_count", "message": "binding_record_count must match records when not truncated"})
    if not isinstance(report.get("binding_policy"), dict):
        issues.append({"code": "invalid_binding_policy", "message": "binding_policy must be an object"})
    cross_run_table = report.get("cross_run_binding_table")
    if not isinstance(cross_run_table, dict):
        issues.append(
            {
                "code": "invalid_cross_run_binding_table",
                "message": "cross_run_binding_table must be an object",
            }
        )
    elif (
        cross_run_table.get("record_schema")
        != PROMPT_CURRENT_BINDING_TABLE_RECORD_SCHEMA
    ):
        issues.append(
            {
                "code": "invalid_cross_run_binding_table_schema",
                "message": "cross_run_binding_table record schema is unsupported",
            }
        )
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "prompt-current binding report must not claim full AlphaEvolve provenance"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    elif readiness.get("full_alphaevolve_current_program_provenance") is not False:
        issues.append({"code": "current_program_provenance_overclaim", "message": "full current-program provenance must remain false"})
    return {
        "schema": "libreevolve.prompt_current_binding_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _primary_prompt_instruction_report(programs: list[Program]) -> dict:
    program_by_id = {program.id: program for program in programs}
    records = [
        _primary_prompt_instruction_record(program, program_by_id)
        for program in programs
        if _prompt_current_binding_is_generated(program)
    ]
    target_link_count = sum(
        1
        for record in records
        if isinstance(record.get("target_solution"), Mapping)
        and _is_sha256_hex(record["target_solution"].get("workspace_sha256"))
    )
    instruction_hash_count = sum(
        1
        for record in records
        if isinstance(record.get("instruction_block"), Mapping)
        and _is_sha256_hex(record["instruction_block"].get("instruction_text_sha256"))
    )
    inspiration_context_record_count = sum(
        1
        for record in records
        if record.get("sampled_prior_solution_count", 0) > 1
    )
    telemetry_join_count = sum(
        1
        for record in records
        if isinstance(record.get("provider_message_role_placement"), Mapping)
        and record["provider_message_role_placement"].get("mutation_call_joined")
        is True
    )
    remaining_gap = []
    if records and target_link_count != len(records):
        remaining_gap.append("target_solution_workspace_hashes")
    if records and instruction_hash_count != len(records):
        remaining_gap.append("mutation_instruction_hashes")
    if records and inspiration_context_record_count == 0:
        remaining_gap.append("sampled_prior_inspiration_solution_roles")
    report = {
        "schema": "libreevolve.primary_prompt_instruction_report.v1",
        "source": (
            "generated_program_metadata_prompt_diagnostics_parent_and_"
            "inspiration_selection"
        ),
        "generated_candidate_count": len(records),
        "prompt_record_count": len(records),
        "target_solution_link_count": target_link_count,
        "instruction_hash_count": instruction_hash_count,
        "inspiration_context_record_count": inspiration_context_record_count,
        "telemetry_join_count": telemetry_join_count,
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "provider_message_policy": {
            "mutation_scheduler_role": "mutation",
            "provider_payload_shape": "serialized_single_prompt_string",
            "role_separated_system_developer_user_messages": False,
            "role_separated_message_support": "unsupported_current_backends",
        },
        "ingredient_policy": {
            "target_solution_source": "program.parent_id_workspace_at_mutation_time",
            "supporting_solution_source": (
                "metadata.inspiration_selection.selected_program_ids"
            ),
            "instruction_source": (
                "PromptSampler._render_mutation_instructions_section_budget_hash"
            ),
            "prompt_role_source": (
                "metadata.llm_calls.role_when_available_else_loop_mutation_role"
            ),
            "required_channels": [
                "task",
                "parent_code",
                "mutation_instructions",
            ],
            "optional_supporting_channels": [
                "inspirations",
                "parent_feedback",
                "parent_score",
                "parent_metrics",
                "context",
                "extra_context",
                "recent_failures",
            ],
        },
        "claim_ready": bool(records) and not remaining_gap,
        "claim_readiness": {
            "prompt_records_present": bool(records),
            "target_solution_hashes_recorded": bool(records)
            and target_link_count == len(records),
            "instruction_hashes_recorded": bool(records)
            and instruction_hash_count == len(records),
            "sampled_solution_roles_recorded": bool(records),
            "supporting_inspiration_roles_observed": (
                inspiration_context_record_count > 0
            ),
            "provider_message_role_placement_recorded": bool(records),
            "role_separated_provider_messages_supported": False,
            "full_alphaevolve_primary_prompt_parity": False,
            "remaining_gap": remaining_gap,
        },
    }
    report["validation"] = validate_primary_prompt_instruction_report(report)
    return report


def _primary_prompt_instruction_record(
    program: Program,
    program_by_id: Mapping[str, Program],
) -> dict:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    prompt_diagnostics = (
        metadata.get("prompt_diagnostics")
        if isinstance(metadata.get("prompt_diagnostics"), Mapping)
        else {}
    )
    prompt_context_policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    section_hashes = _prompt_section_hashes(prompt_diagnostics)
    section_names = set(section_hashes)
    parent = (
        program_by_id.get(program.parent_id)
        if isinstance(program.parent_id, str)
        else None
    )
    inspiration_selection = (
        metadata.get("inspiration_selection")
        if isinstance(metadata.get("inspiration_selection"), Mapping)
        else {}
    )
    selected_inspiration_ids = [
        item
        for item in inspiration_selection.get("selected_program_ids", [])
        if isinstance(item, str)
    ]
    prior_solutions = []
    if parent is not None:
        prior_solutions.append(
            _primary_prompt_solution_role_record(
                parent,
                role="target",
                ordinal=0,
                prompt_visible="parent_code" in section_names,
            )
        )
    elif isinstance(program.parent_id, str):
        prior_solutions.append(
            _primary_prompt_missing_solution_role_record(
                program.parent_id,
                role="target",
                ordinal=0,
            )
        )
    for ordinal, inspiration_id in enumerate(selected_inspiration_ids, start=1):
        inspiration = program_by_id.get(inspiration_id)
        if inspiration is None:
            prior_solutions.append(
                _primary_prompt_missing_solution_role_record(
                    inspiration_id,
                    role="inspiration",
                    ordinal=ordinal,
                )
            )
        else:
            prior_solutions.append(
                _primary_prompt_solution_role_record(
                    inspiration,
                    role="inspiration",
                    ordinal=ordinal,
                    prompt_visible=True,
                )
            )
    llm_calls = (
        [
            call
            for call in metadata.get("llm_calls", [])
            if isinstance(call, Mapping) and call.get("role") == "mutation"
        ]
        if isinstance(metadata.get("llm_calls"), list)
        else []
    )
    call_ids = [
        call.get("id")
        for call in llm_calls
        if isinstance(call.get("id"), str) and call.get("id")
    ]
    required_channels = [
        _primary_prompt_channel_record(name, section_hashes, required=True)
        for name in ("task", "parent_code", "mutation_instructions")
    ]
    required_channels.append(
        _primary_prompt_channel_record(
            "inspirations",
            section_hashes,
            required=False,
            omission_reason=(
                "no_inspiration_programs_selected"
                if not selected_inspiration_ids
                else None
            ),
        )
    )
    mutation_mode = metadata.get("mutation_mode")
    return {
        "candidate_id": program.id,
        "candidate_status": _prompt_prior_candidate_status(program),
        "generation": program.generation,
        "prompt_program_id": (
            metadata.get("prompt_program_id")
            if isinstance(metadata.get("prompt_program_id"), str)
            else None
        ),
        "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
        "prompt_sha256_scope": prompt_diagnostics.get("prompt_sha256_scope"),
        "target_solution": prior_solutions[0] if prior_solutions else None,
        "sampled_prior_solutions": prior_solutions[:51],
        "sampled_prior_solution_count": len(prior_solutions),
        "sampled_prior_solution_ids": [
            record["program_id"]
            for record in prior_solutions
            if isinstance(record.get("program_id"), str)
        ][:50],
        "selected_inspiration_ids": selected_inspiration_ids[:50],
        "selected_inspiration_ids_truncated": len(selected_inspiration_ids) > 50,
        "instruction_block": {
            "instruction_policy_id": "PromptSampler._render_mutation_instructions",
            "mutation_instruction_variant": prompt_context_policy.get(
                "mutation_instruction_variant"
            ),
            "mutation_instruction_include_example": prompt_context_policy.get(
                "mutation_instruction_include_example"
            ),
            "instruction_text_sha256": section_hashes.get("mutation_instructions"),
            "instruction_text_retention": "hash_only_section_budget",
            "instruction_text_role": "serialized_single_prompt_section",
        },
        "provider_message_role_placement": {
            "mutation_call_joined": bool(call_ids),
            "mutation_call_ids": call_ids[:10],
            "scheduler_role": "mutation",
            "provider_payload_shape": "serialized_single_prompt_string",
            "system_message": "not_role_separated",
            "developer_message": "not_role_separated",
            "user_message": "serialized_prompt_payload",
            "role_separated_messages_supported": False,
        },
        "edit_scope_constraints": {
            "mutation_mode": mutation_mode if isinstance(mutation_mode, str) else None,
            "mutation_mode_source": "candidate.metadata.mutation_mode",
            "proposal_metadata_enabled": prompt_context_policy.get(
                "proposal_metadata_enabled"
            ),
        },
        "required_channel_records": required_channels,
        "required_channels_present": all(
            channel["present"]
            for channel in required_channels
            if channel["required"]
        ),
    }


def _prompt_section_hashes(prompt_diagnostics: Mapping[str, object]) -> dict[str, str]:
    section_budget = prompt_diagnostics.get("section_budget")
    sections = (
        section_budget.get("sections")
        if isinstance(section_budget, Mapping)
        else None
    )
    hashes: dict[str, str] = {}
    if not isinstance(sections, list):
        return hashes
    for section in sections:
        if not isinstance(section, Mapping):
            continue
        name = section.get("name")
        sha = section.get("sha256")
        if isinstance(name, str) and _is_sha256_hex(sha):
            hashes[name] = sha
    return hashes


def _primary_prompt_solution_role_record(
    program: Program,
    *,
    role: str,
    ordinal: int,
    prompt_visible: bool,
) -> dict:
    return {
        "program_id": program.id,
        "role": role,
        "ordinal": ordinal,
        "generation": program.generation,
        "workspace_sha256": _workspace_sha256(program.workspace()),
        "source_hash_scope": "candidate_workspace",
        "prompt_visible": prompt_visible,
        "missing": False,
    }


def _primary_prompt_missing_solution_role_record(
    program_id: str,
    *,
    role: str,
    ordinal: int,
) -> dict:
    return {
        "program_id": program_id,
        "role": role,
        "ordinal": ordinal,
        "generation": None,
        "workspace_sha256": None,
        "source_hash_scope": "missing_runtime_program_record",
        "prompt_visible": False,
        "missing": True,
    }


def _primary_prompt_channel_record(
    name: str,
    section_hashes: Mapping[str, str],
    *,
    required: bool,
    omission_reason: str | None = None,
) -> dict:
    present = name in section_hashes
    return {
        "name": name,
        "required": required,
        "present": present,
        "section_sha256": section_hashes.get(name),
        "omission_reason": None if present else omission_reason,
    }


def validate_primary_prompt_instruction_report(report: object) -> dict:
    issues: list[dict] = []
    schema = "libreevolve.primary_prompt_instruction_report.v1"
    if not isinstance(report, dict):
        return {
            "schema": schema,
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "primary prompt instruction report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "prompt_record_count",
        "target_solution_link_count",
        "instruction_hash_count",
        "inspiration_context_record_count",
        "telemetry_join_count",
        "records",
        "records_limit",
        "records_truncated",
        "provider_message_policy",
        "ingredient_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"primary prompt report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != schema:
        issues.append(
            {"code": "invalid_schema", "message": "unsupported primary prompt schema"}
        )
    expected_source = (
        "generated_program_metadata_prompt_diagnostics_parent_and_"
        "inspiration_selection"
    )
    if report.get("source") != expected_source:
        issues.append(
            {"code": "invalid_source", "message": "unsupported primary prompt source"}
        )
    for field in (
        "generated_candidate_count",
        "prompt_record_count",
        "target_solution_link_count",
        "instruction_hash_count",
        "inspiration_context_record_count",
        "telemetry_join_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    _validate_report_count(report, "prompt_record_count", len(records), issues)
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {"code": "invalid_record", "message": f"record {index} must be an object"}
            )
            continue
        if not isinstance(record.get("candidate_id"), str) or not record.get("candidate_id"):
            issues.append(
                {"code": "invalid_candidate_id", "message": f"record {index} candidate_id is invalid"}
            )
        if record.get("candidate_status") not in {
            "accepted_history",
            "rejected_history",
        }:
            issues.append(
                {"code": "invalid_candidate_status", "message": f"record {index} status is invalid"}
            )
        if not _is_sha256_hex(record.get("prompt_sha256")):
            issues.append(
                {"code": "invalid_prompt_hash", "message": f"record {index} prompt hash is invalid"}
            )
        target = record.get("target_solution")
        if not isinstance(target, Mapping):
            issues.append(
                {"code": "invalid_target_solution", "message": f"record {index} target_solution must be an object"}
            )
        else:
            if target.get("role") != "target":
                issues.append(
                    {"code": "invalid_target_role", "message": f"record {index} target role is invalid"}
                )
            if not _is_sha256_hex(target.get("workspace_sha256")):
                issues.append(
                    {"code": "invalid_target_hash", "message": f"record {index} target workspace hash is invalid"}
                )
        sampled = record.get("sampled_prior_solutions")
        if not isinstance(sampled, list) or not sampled:
            issues.append(
                {"code": "invalid_sampled_prior_solutions", "message": f"record {index} sampled prior solutions are invalid"}
            )
        else:
            roles = [
                item.get("role")
                for item in sampled
                if isinstance(item, Mapping)
            ]
            if "target" not in roles:
                issues.append(
                    {"code": "missing_target_sampled_solution", "message": f"record {index} must include target sampled solution"}
                )
            for role in roles:
                if role not in {"target", "inspiration"}:
                    issues.append(
                        {"code": "invalid_sampled_solution_role", "message": f"record {index} sampled solution role is invalid"}
                    )
        instruction = record.get("instruction_block")
        if not isinstance(instruction, Mapping):
            issues.append(
                {"code": "invalid_instruction_block", "message": f"record {index} instruction_block must be an object"}
            )
        else:
            if instruction.get("instruction_policy_id") != "PromptSampler._render_mutation_instructions":
                issues.append(
                    {"code": "invalid_instruction_policy", "message": f"record {index} instruction policy is invalid"}
                )
            if not _is_sha256_hex(instruction.get("instruction_text_sha256")):
                issues.append(
                    {"code": "invalid_instruction_hash", "message": f"record {index} instruction hash is invalid"}
                )
        placement = record.get("provider_message_role_placement")
        if not isinstance(placement, Mapping):
            issues.append(
                {"code": "invalid_provider_message_role_placement", "message": f"record {index} provider placement must be an object"}
            )
        else:
            if placement.get("provider_payload_shape") != "serialized_single_prompt_string":
                issues.append(
                    {"code": "invalid_provider_payload_shape", "message": f"record {index} provider payload shape is invalid"}
                )
            if placement.get("role_separated_messages_supported") is not False:
                issues.append(
                    {"code": "role_separated_messages_overclaim", "message": f"record {index} must not overclaim role-separated provider messages"}
                )
        channels = record.get("required_channel_records")
        if not isinstance(channels, list):
            issues.append(
                {"code": "invalid_required_channel_records", "message": f"record {index} channel records must be a list"}
            )
        else:
            by_name = {
                channel.get("name"): channel
                for channel in channels
                if isinstance(channel, Mapping)
            }
            for name in ("task", "parent_code", "mutation_instructions"):
                channel = by_name.get(name)
                if not isinstance(channel, Mapping) or channel.get("present") is not True:
                    issues.append(
                        {"code": "missing_required_prompt_channel", "message": f"record {index} missing required prompt channel {name}"}
                    )
    policy = report.get("provider_message_policy")
    if not isinstance(policy, Mapping):
        issues.append(
            {"code": "invalid_provider_message_policy", "message": "provider_message_policy must be an object"}
        )
    elif policy.get("role_separated_system_developer_user_messages") is not False:
        issues.append(
            {"code": "provider_message_policy_overclaim", "message": "provider message policy must not claim role-separated messages"}
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append(
            {"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"}
        )
    else:
        if readiness.get("role_separated_provider_messages_supported") is not False:
            issues.append(
                {"code": "role_separated_readiness_overclaim", "message": "role-separated provider messages must remain unsupported"}
            )
        if readiness.get("full_alphaevolve_primary_prompt_parity") is not False:
            issues.append(
                {"code": "full_primary_prompt_parity_overclaim", "message": "full AlphaEvolve primary prompt parity must remain false"}
            )
        remaining_gap = readiness.get("remaining_gap")
        claim_ready = report.get("claim_ready")
        if not isinstance(remaining_gap, list):
            issues.append(
                {"code": "invalid_remaining_gap", "message": "remaining_gap must be a list"}
            )
        elif claim_ready != (bool(records) and not remaining_gap):
            issues.append(
                {"code": "claim_ready_mismatch", "message": "claim_ready must match records and remaining_gap"}
            )
    return {"schema": schema, "ok": not issues, "issues": issues}


def _stochastic_prompt_format_distribution_report(
    programs: list[Program],
    startup_manifest: Mapping[str, object],
) -> dict:
    option_sets = _stochastic_prompt_format_option_sets(startup_manifest)
    generated = [
        program for program in programs if _prompt_current_binding_is_generated(program)
    ]
    records = [
        record
        for program in generated
        for record in _stochastic_prompt_format_records(program, option_sets)
    ]
    prompt_ids = {
        record.get("prompt_program_id")
        for record in records
        if isinstance(record.get("prompt_program_id"), str)
    }
    option_names = sorted(
        {
            record.get("marker_name")
            for record in records
            if isinstance(record.get("marker_name"), str)
        }
    )
    selected_hash_match_count = sum(
        1
        for record in records
        if record.get("selected_text_sha256")
        == record.get("selected_alternative", {}).get("text_sha256")
    )
    prompt_call_link_count = sum(
        1
        for record in records
        if isinstance(record.get("prompt_program_id"), str)
        and _is_sha256_hex(record.get("prompt_sha256"))
    )
    report = {
        "schema": "libreevolve.stochastic_prompt_format_distribution_report.v1",
        "source": "startup_manifest_prompt_format_options_and_prompt_diagnostics",
        "generated_candidate_count": len(generated),
        "formatted_prompt_record_count": len(records),
        "option_set_count": len(option_sets),
        "option_set_names": sorted(option_sets),
        "prompt_program_count": len(prompt_ids),
        "marker_name_count": len(option_names),
        "marker_names": option_names,
        "selected_hash_match_count": selected_hash_match_count,
        "prompt_call_link_count": prompt_call_link_count,
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "config_source_policy": {
            "source": "startup_manifest.config.prompt_format_options",
            "external_config_file": "not_recorded",
            "effective_config_boundary": "inline_or_resolved_effective_config",
            "text_retention": "manifest_prompt_format_options_metadata_hashes",
        },
        "rng_boundary": {
            "rng_owner": "run_local_framework_random",
            "selection_policy": "weighted_run_rng_reuse_by_marker_name",
            "replay_surface": "runtime.rng_snapshot_after_run",
            "provider_outputs": "outside_rng_replay_boundary",
        },
        "claim_ready": bool(records),
        "claim_readiness": {
            "formatted_prompt_records_present": bool(records),
            "option_distributions_recorded": bool(records),
            "selected_alternative_hashes_joined": bool(records)
            and selected_hash_match_count == len(records),
            "prompt_call_linkage_recorded": bool(records)
            and prompt_call_link_count == len(records),
            "rng_boundary_recorded": True,
            "separate_config_file_source_recorded": False,
            "human_authored_alternatives_certified": False,
            "full_alphaevolve_stochastic_formatting_parity": False,
            "remaining_gap": [],
        },
    }
    report["validation"] = validate_stochastic_prompt_format_distribution_report(
        report
    )
    return report


def _stochastic_prompt_format_option_sets(
    startup_manifest: Mapping[str, object],
) -> dict[str, dict]:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    options = (
        config.get("prompt_format_options")
        if isinstance(config.get("prompt_format_options"), Mapping)
        else {}
    )
    metadata = (
        config.get("prompt_format_options_metadata")
        if isinstance(config.get("prompt_format_options_metadata"), Mapping)
        else {}
    )
    result: dict[str, dict] = {}
    for name, alternatives in options.items():
        if not isinstance(name, str) or not isinstance(alternatives, list):
            continue
        metadata_items = metadata.get(name) if isinstance(metadata, Mapping) else None
        if not isinstance(metadata_items, list):
            metadata_items = []
        weights: list[float] = []
        normalized_alternatives: list[dict] = []
        for index, alternative in enumerate(alternatives):
            if isinstance(alternative, Mapping):
                weight = alternative.get("weight", 1.0)
            else:
                weight = 1.0
            if isinstance(weight, bool) or not isinstance(weight, (int, float)):
                continue
            numeric_weight = float(weight)
            if not math.isfinite(numeric_weight) or numeric_weight <= 0.0:
                continue
            weights.append(numeric_weight)
            item_metadata = (
                metadata_items[index]
                if index < len(metadata_items)
                and isinstance(metadata_items[index], Mapping)
                else {}
            )
            normalized_alternatives.append(
                {
                    "index": index,
                    "weight": numeric_weight,
                    "text_sha256": item_metadata.get("sha256"),
                    "text_chars": item_metadata.get("chars"),
                    "text_retention": item_metadata.get("retention"),
                    "text_redacted": item_metadata.get("redacted"),
                }
            )
        total_weight = sum(weights)
        for alternative in normalized_alternatives:
            alternative["probability"] = (
                alternative["weight"] / total_weight if total_weight > 0 else None
            )
        result[name] = {
            "option_set_id": f"prompt_format_options.{name}",
            "marker_name": name,
            "config_source": "startup_manifest.config.prompt_format_options",
            "source_kind": "inline_or_effective_config",
            "alternative_count": len(normalized_alternatives),
            "total_weight": total_weight,
            "distribution_sha256": hashlib.sha256(
                strict_json_dumps(
                    [
                        {
                            "index": item["index"],
                            "weight": item["weight"],
                            "text_sha256": item["text_sha256"],
                        }
                        for item in normalized_alternatives
                    ]
                ).encode("utf-8")
            ).hexdigest(),
            "alternatives": normalized_alternatives,
        }
    return result


def _stochastic_prompt_format_records(
    program: Program,
    option_sets: Mapping[str, dict],
) -> list[dict]:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    prompt_diagnostics = (
        metadata.get("prompt_diagnostics")
        if isinstance(metadata.get("prompt_diagnostics"), Mapping)
        else {}
    )
    formatting = (
        prompt_diagnostics.get("stochastic_formatting")
        if isinstance(prompt_diagnostics.get("stochastic_formatting"), Mapping)
        else {}
    )
    selections = (
        formatting.get("selections")
        if isinstance(formatting.get("selections"), list)
        else []
    )
    records: list[dict] = []
    for selection in selections:
        if not isinstance(selection, Mapping):
            continue
        name = selection.get("name")
        option_set = option_sets.get(name) if isinstance(name, str) else None
        alternatives = (
            option_set.get("alternatives")
            if isinstance(option_set, Mapping)
            else []
        )
        choice_index = selection.get("choice_index")
        selected_alternative = None
        if (
            isinstance(choice_index, int)
            and not isinstance(choice_index, bool)
            and isinstance(alternatives, list)
            and 0 <= choice_index < len(alternatives)
        ):
            selected_alternative = alternatives[choice_index]
        records.append(
            {
                "candidate_id": program.id,
                "candidate_status": _prompt_prior_candidate_status(program),
                "generation": program.generation,
                "prompt_program_id": (
                    metadata.get("prompt_program_id")
                    if isinstance(metadata.get("prompt_program_id"), str)
                    else None
                ),
                "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
                "prompt_sha256_scope": prompt_diagnostics.get("prompt_sha256_scope"),
                "marker_syntax": formatting.get("marker_syntax"),
                "selection_policy": formatting.get("selection_policy"),
                "marker_name": name,
                "option_set_id": (
                    option_set.get("option_set_id")
                    if isinstance(option_set, Mapping)
                    else None
                ),
                "config_source": (
                    option_set.get("config_source")
                    if isinstance(option_set, Mapping)
                    else None
                ),
                "source_kind": (
                    option_set.get("source_kind")
                    if isinstance(option_set, Mapping)
                    else None
                ),
                "distribution_sha256": (
                    option_set.get("distribution_sha256")
                    if isinstance(option_set, Mapping)
                    else None
                ),
                "alternatives": alternatives if isinstance(alternatives, list) else [],
                "choice_index": choice_index,
                "selected_text_sha256": selection.get("text_sha256"),
                "selected_weight": selection.get("weight"),
                "selected_alternative": selected_alternative,
                "weight_source": selection.get("weight_source"),
                "weight_override_source": (
                    "prompt_context_policy.prompt_format_weights"
                    if selection.get("weight_source") == "prompt_context_policy"
                    else "prompt_format_options"
                ),
                "occurrences": selection.get("occurrences"),
                "rng_boundary": "run_local_framework_random",
                "prompt_linkage": {
                    "prompt_program_id": metadata.get("prompt_program_id"),
                    "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
                    "llm_call_ids": _mutation_call_ids(metadata),
                },
            }
        )
    return records


def _mutation_call_ids(metadata: Mapping[str, object]) -> list[str]:
    calls = metadata.get("llm_calls")
    if not isinstance(calls, list):
        return []
    return [
        call.get("id")
        for call in calls
        if isinstance(call, Mapping)
        and call.get("role") == "mutation"
        and isinstance(call.get("id"), str)
    ][:10]


def validate_stochastic_prompt_format_distribution_report(report: object) -> dict:
    issues: list[dict] = []
    schema = "libreevolve.stochastic_prompt_format_distribution_report.v1"
    if not isinstance(report, dict):
        return {
            "schema": schema,
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "stochastic prompt-format report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "formatted_prompt_record_count",
        "option_set_count",
        "option_set_names",
        "prompt_program_count",
        "marker_name_count",
        "marker_names",
        "selected_hash_match_count",
        "prompt_call_link_count",
        "records",
        "records_limit",
        "records_truncated",
        "config_source_policy",
        "rng_boundary",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"stochastic prompt-format report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != schema:
        issues.append({"code": "invalid_schema", "message": "unsupported schema"})
    if (
        report.get("source")
        != "startup_manifest_prompt_format_options_and_prompt_diagnostics"
    ):
        issues.append({"code": "invalid_source", "message": "unsupported source"})
    for field in (
        "generated_candidate_count",
        "formatted_prompt_record_count",
        "option_set_count",
        "prompt_program_count",
        "marker_name_count",
        "selected_hash_match_count",
        "prompt_call_link_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    _validate_report_count(report, "formatted_prompt_record_count", len(records), issues)
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {"code": "invalid_record", "message": f"record {index} must be an object"}
            )
            continue
        if not isinstance(record.get("candidate_id"), str):
            issues.append(
                {"code": "invalid_candidate_id", "message": f"record {index} candidate_id is invalid"}
            )
        if not _is_sha256_hex(record.get("prompt_sha256")):
            issues.append(
                {"code": "invalid_prompt_hash", "message": f"record {index} prompt hash is invalid"}
            )
        if not _is_sha256_hex(record.get("distribution_sha256")):
            issues.append(
                {"code": "invalid_distribution_hash", "message": f"record {index} distribution hash is invalid"}
            )
        alternatives = record.get("alternatives")
        if not isinstance(alternatives, list) or not alternatives:
            issues.append(
                {"code": "invalid_alternatives", "message": f"record {index} alternatives must be non-empty"}
            )
            alternatives = []
        probability_total = 0.0
        for alt_index, alternative in enumerate(alternatives):
            if not isinstance(alternative, Mapping):
                issues.append(
                    {"code": "invalid_alternative", "message": f"record {index} alternative {alt_index} must be an object"}
                )
                continue
            if alternative.get("index") != alt_index:
                issues.append(
                    {"code": "invalid_alternative_index", "message": f"record {index} alternative index mismatch"}
                )
            if not _is_sha256_hex(alternative.get("text_sha256")):
                issues.append(
                    {"code": "invalid_alternative_text_hash", "message": f"record {index} alternative hash is invalid"}
                )
            probability = alternative.get("probability")
            if (
                isinstance(probability, bool)
                or not isinstance(probability, (int, float))
                or not math.isfinite(float(probability))
                or float(probability) <= 0.0
            ):
                issues.append(
                    {"code": "invalid_alternative_probability", "message": f"record {index} alternative probability is invalid"}
                )
            else:
                probability_total += float(probability)
        if alternatives and not math.isclose(probability_total, 1.0, rel_tol=1e-9, abs_tol=1e-9):
            issues.append(
                {
                    "code": "invalid_probability_total",
                    "message": f"record {index} normalized probabilities must sum to 1",
                }
            )
        selected = record.get("selected_alternative")
        choice_index = record.get("choice_index")
        if not isinstance(selected, Mapping):
            issues.append(
                {"code": "invalid_selected_alternative", "message": f"record {index} selected alternative is invalid"}
            )
        else:
            if selected.get("index") != choice_index:
                issues.append(
                    {"code": "selected_choice_index_mismatch", "message": f"record {index} selected index mismatch"}
                )
            if selected.get("text_sha256") != record.get("selected_text_sha256"):
                issues.append(
                    {"code": "selected_hash_mismatch", "message": f"record {index} selected hash must match option set"}
                )
        if record.get("selection_policy") != "weighted_run_rng_reuse_by_marker_name":
            issues.append(
                {"code": "invalid_selection_policy", "message": f"record {index} selection policy is unsupported"}
            )
        if record.get("rng_boundary") != "run_local_framework_random":
            issues.append(
                {"code": "invalid_rng_boundary", "message": f"record {index} rng boundary is unsupported"}
            )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append(
            {"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"}
        )
    else:
        if readiness.get("separate_config_file_source_recorded") is not False:
            issues.append(
                {"code": "separate_config_source_overclaim", "message": "separate config file source must remain false"}
            )
        if readiness.get("human_authored_alternatives_certified") is not False:
            issues.append(
                {"code": "human_authorship_overclaim", "message": "human authorship certification must remain false"}
            )
        if readiness.get("full_alphaevolve_stochastic_formatting_parity") is not False:
            issues.append(
                {"code": "stochastic_formatting_parity_overclaim", "message": "full AlphaEvolve stochastic formatting parity must remain false"}
            )
        if report.get("claim_ready") != bool(records):
            issues.append(
                {"code": "claim_ready_mismatch", "message": "claim_ready must reflect formatted records"}
            )
    return {"schema": schema, "ok": not issues, "issues": issues}


def _prompt_prior_score_provenance_report(
    programs: list[Program],
    run_dir: Path,
    startup_manifest: Mapping[str, object],
) -> dict:
    program_by_id = {program.id: program for program in programs}
    history_indexes = _prompt_current_history_join_indexes(run_dir)
    generated = [
        program for program in programs if _prompt_current_binding_is_generated(program)
    ]
    records = [
        _prompt_prior_score_provenance_record(
            program,
            program_by_id,
            history_indexes,
        )
        for program in generated
    ]
    table_rows = _prompt_prior_score_table_rows(records, startup_manifest)
    table_export = _write_prompt_prior_score_table(run_dir, table_rows)
    score_record_count = sum(len(record["score_records"]) for record in records)
    target_score_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("role") == "target"
    )
    inspiration_score_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("role") == "inspiration"
    )
    evaluator_join_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("evaluator_result_joined") is True
    )
    history_join_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("history_joined") is True
    )
    omitted_or_truncated_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("prompt_visible") is not True
    )
    score_field_record_count = sum(
        score.get("score_display", {}).get("field_record_count", 0)
        for record in records
        for score in record["score_records"]
        if isinstance(score.get("score_display"), Mapping)
    )
    omitted_or_truncated_score_field_count = sum(
        score.get("score_display", {}).get("omitted_or_truncated_field_count", 0)
        for record in records
        for score in record["score_records"]
        if isinstance(score.get("score_display"), Mapping)
    )
    execution_result_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("execution_result_display", {}).get("has_source_execution_result")
        is True
    )
    prompt_visible_execution_result_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("execution_result_display", {}).get("prompt_visible") is True
    )
    execution_result_evaluator_join_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("execution_result_display", {}).get("evaluator_result_joined")
        is True
    )
    stage_summary_io_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("stage_summary_io_display", {}).get("has_source_stage_io")
        is True
    )
    prompt_visible_stage_summary_io_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("stage_summary_io_display", {}).get("prompt_visible") is True
    )
    stage_summary_io_evaluator_join_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("stage_summary_io_display", {}).get("has_source_stage_io") is True
        and score.get("stage_summary_io_display", {}).get("evaluator_result_joined")
        is True
    )
    feedback_section_policy_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if isinstance(score.get("feedback_section_display"), Mapping)
    )
    feedback_section_global_policy_count = sum(
        1
        for record in records
        for score in record["score_records"]
        if score.get("feedback_section_display", {}).get("global_cap_chars")
        == PROMPT_FEEDBACK_GLOBAL_MAX_CHARS
    )
    report = {
        "schema": "libreevolve.prompt_prior_score_provenance_report.v1",
        "source": "runtime_history_prompt_diagnostics_parent_and_inspiration_selection",
        "generated_candidate_count": len(generated),
        "prompt_record_count": len(records),
        "score_record_count": score_record_count,
        "target_score_record_count": target_score_count,
        "inspiration_score_record_count": inspiration_score_count,
        "history_join_count": history_join_count,
        "evaluator_result_join_count": evaluator_join_count,
        "omitted_or_truncated_score_record_count": omitted_or_truncated_count,
        "score_field_record_count": score_field_record_count,
        "omitted_or_truncated_score_field_count": (
            omitted_or_truncated_score_field_count
        ),
        "execution_result_record_count": execution_result_count,
        "prompt_visible_execution_result_record_count": (
            prompt_visible_execution_result_count
        ),
        "execution_result_evaluator_join_count": (
            execution_result_evaluator_join_count
        ),
        "stage_summary_io_record_count": stage_summary_io_count,
        "prompt_visible_stage_summary_io_record_count": (
            prompt_visible_stage_summary_io_count
        ),
        "stage_summary_io_evaluator_join_count": (
            stage_summary_io_evaluator_join_count
        ),
        "feedback_section_policy_record_count": feedback_section_policy_count,
        "feedback_section_global_policy_record_count": (
            feedback_section_global_policy_count
        ),
        "cross_run_prompt_score_table_record_count": table_export["record_count"],
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "score_policy": {
            "target_score_source": "parent_program_fitness_rendered_as_parent_score",
            "target_metric_source": "parent_program_metrics_rendered_as_parent_metrics",
            "inspiration_score_source": "selected_inspiration_program_fitness_and_metrics_rendered_in_inspiration_headers",
            "history_join_policy": "candidate_ids_joined_to_history_jsonl_or_failure_history_jsonl_and_evaluator_results_jsonl",
            "displayed_aggregate_policy": "stored_program_fitness_as_prompt_visible_normalized_fitness",
            "average_score_policy": "alphaevolve_average_score_display_alias_for_stored_program_fitness",
            "raw_metric_policy": "finite_non_boolean_program_metrics",
            "score_display_policy": "aggregate_and_metric_field_visibility_records_from_prompt_context_policy_and_prompt_section_budget",
            "execution_result_source": "evaluation_stdout_stderr_error_fields_rendered_by_parent_feedback_or_inspiration_feedback",
            "execution_result_field_policy": "prompt_context_policy_execution_output_fields_and_caps_with_redacted_bounded_previews",
            "stage_summary_io_source": "evaluation_stage_stdout_stderr_error_fields_rendered_by_stage_summary_io",
            "stage_summary_io_policy": "prompt_context_policy_stage_summary_fields_io_and_execution_output_fields_with_caps",
            "feedback_section_policy": "prompt_context_policy_feedback_sections_order_section_caps_and_fixed_global_feedback_cap",
            "cross_run_table_policy": "stable_jsonl_rows_with_run_id_problem_prompt_candidate_score_source_metric_and_runtime_join_fields",
        },
        "cross_run_prompt_score_table": table_export,
        "claim_ready": False,
        "claim_readiness": {
            "target_scores_joined": target_score_count > 0
            and target_score_count == len(records),
            "history_rows_joined": score_record_count > 0
            and history_join_count == score_record_count,
            "evaluator_rows_joined": score_record_count > 0
            and evaluator_join_count == score_record_count,
            "prompt_visible_score_rows": score_record_count > 0
            and omitted_or_truncated_count == 0,
            "score_omission_and_truncation_policy": score_record_count > 0,
            "average_score_formula_parity": score_record_count > 0,
            "execution_result_text_display_attribution": (
                execution_result_count > 0
                and execution_result_evaluator_join_count == execution_result_count
            ),
            "stage_summary_io_display_attribution": (
                stage_summary_io_count > 0
                and stage_summary_io_evaluator_join_count == stage_summary_io_count
            ),
            "feedback_section_global_truncation_policy": (
                score_record_count > 0
                and feedback_section_global_policy_count == score_record_count
            ),
            "cross_run_prompt_score_table": table_export["record_count"] > 0,
            "full_alphaevolve_rendered_evaluation_result_provenance": False,
            "remaining_gap": [],
        },
    }
    report["validation"] = validate_prompt_prior_score_provenance_report(report)
    return report


def _prompt_prior_score_table_rows(
    records: list[dict],
    startup_manifest: Mapping[str, object],
) -> list[dict]:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    run_id = config.get("run_id") if isinstance(config.get("run_id"), str) else None
    problem_name = (
        config.get("problem_name")
        if isinstance(config.get("problem_name"), str)
        else None
    )
    rows: list[dict] = []
    for prompt_record in records:
        if not isinstance(prompt_record, Mapping):
            continue
        for score in prompt_record.get("score_records", []):
            if not isinstance(score, Mapping):
                continue
            execution_display = (
                score.get("execution_result_display")
                if isinstance(score.get("execution_result_display"), Mapping)
                else {}
            )
            stage_summary_io = (
                score.get("stage_summary_io_display")
                if isinstance(score.get("stage_summary_io_display"), Mapping)
                else {}
            )
            feedback_section_display = (
                score.get("feedback_section_display")
                if isinstance(score.get("feedback_section_display"), Mapping)
                else {}
            )
            score_display = (
                score.get("score_display")
                if isinstance(score.get("score_display"), Mapping)
                else {}
            )
            rows.append(
                {
                    "schema": "libreevolve.prompt_prior_score_table_row.v1",
                    "run_id": run_id,
                    "problem_name": problem_name,
                    "candidate_id": prompt_record.get("candidate_id"),
                    "candidate_status": prompt_record.get("candidate_status"),
                    "candidate_generation": prompt_record.get("generation"),
                    "prompt_program_id": prompt_record.get("prompt_program_id"),
                    "prompt_sha256": prompt_record.get("prompt_sha256"),
                    "prompt_sha256_scope": prompt_record.get("prompt_sha256_scope"),
                    "parent_id": prompt_record.get("parent_id"),
                    "score_role": score.get("role"),
                    "score_ordinal": score.get("ordinal"),
                    "score_program_id": score.get("program_id"),
                    "score_candidate_type": score.get("candidate_type"),
                    "score_generation": score.get("generation"),
                    "source_hash": score.get("source_hash"),
                    "prompt_visible": score.get("prompt_visible"),
                    "prompt_visibility_source": score.get("prompt_visibility_source"),
                    "omission_reason": score.get("omission_reason"),
                    "displayed_aggregate_score": score.get(
                        "displayed_aggregate_score"
                    ),
                    "displayed_aggregate_formula": score.get(
                        "displayed_aggregate_formula"
                    ),
                    "displayed_average_score": score.get(
                        "displayed_average_score"
                    ),
                    "displayed_average_score_formula": score.get(
                        "displayed_average_score_formula"
                    ),
                    "displayed_average_score_text": score.get(
                        "displayed_average_score_text"
                    ),
                    "metric_names": list(score.get("metric_names", []))
                    if isinstance(score.get("metric_names"), list)
                    else [],
                    "raw_metrics": dict(score.get("raw_metrics", {}))
                    if isinstance(score.get("raw_metrics"), Mapping)
                    else {},
                    "score_display": _prompt_prior_score_table_score_display(
                        score_display
                    ),
                    "history_join": _prompt_prior_score_table_history_join(score),
                    "evaluator_result": _prompt_prior_score_table_evaluator_join(
                        score
                    ),
                    "execution_result": (
                        _prompt_prior_score_table_execution_result(
                            execution_display
                        )
                    ),
                    "stage_summary_io": (
                        _prompt_prior_score_table_stage_summary_io(
                            stage_summary_io
                        )
                    ),
                    "feedback_section_display": (
                        _prompt_prior_score_table_feedback_section_display(
                            feedback_section_display
                        )
                    ),
                }
            )
    return rows


def _prompt_prior_score_table_history_join(score: Mapping[str, object]) -> dict:
    history_row = score.get("history_row")
    return {
        "joined": score.get("history_joined") is True,
        "stream": (
            history_row.get("stream") if isinstance(history_row, Mapping) else None
        ),
        "line_number": (
            history_row.get("line_number")
            if isinstance(history_row, Mapping)
            else None
        ),
        "record_schema": (
            history_row.get("record_schema")
            if isinstance(history_row, Mapping)
            else None
        ),
    }


def _prompt_prior_score_table_evaluator_join(score: Mapping[str, object]) -> dict:
    evaluator_result = score.get("evaluator_result")
    return {
        "joined": score.get("evaluator_result_joined") is True,
        "stream": (
            evaluator_result.get("stream")
            if isinstance(evaluator_result, Mapping)
            else None
        ),
        "line_number": (
            evaluator_result.get("line_number")
            if isinstance(evaluator_result, Mapping)
            else None
        ),
        "row_id": (
            evaluator_result.get("row_id")
            if isinstance(evaluator_result, Mapping)
            else None
        ),
        "score": (
            evaluator_result.get("score")
            if isinstance(evaluator_result, Mapping)
            else None
        ),
        "is_valid": (
            evaluator_result.get("is_valid")
            if isinstance(evaluator_result, Mapping)
            else None
        ),
    }


def _prompt_prior_score_table_score_display(display: Mapping[str, object]) -> dict:
    fields = (
        display.get("fields")
        if isinstance(display.get("fields"), list)
        else []
    )
    return {
        "prompt_visible": display.get("prompt_visible") is True,
        "field_record_count": display.get("field_record_count"),
        "omitted_or_truncated_field_count": display.get(
            "omitted_or_truncated_field_count"
        ),
        "visible_fields": [
            field.get("field_id")
            for field in fields
            if isinstance(field, Mapping) and field.get("prompt_visible") is True
        ],
        "omitted_fields": [
            {
                "field_id": field.get("field_id"),
                "omission_reason": field.get("omission_reason"),
            }
            for field in fields
            if isinstance(field, Mapping) and field.get("prompt_visible") is False
        ],
        "truncated_fields": [
            field.get("field_id")
            for field in fields
            if isinstance(field, Mapping) and field.get("truncated") is True
        ],
    }


def _prompt_prior_score_table_execution_result(display: Mapping[str, object]) -> dict:
    field_records = (
        display.get("field_records")
        if isinstance(display.get("field_records"), list)
        else []
    )
    visible_field_hashes = {
        str(field.get("field")): field.get("display_sha256")
        for field in field_records
        if isinstance(field, Mapping)
        and field.get("prompt_visible") is True
        and isinstance(field.get("field"), str)
    }
    omitted_fields = [
        {
            "field": field.get("field"),
            "omission_reason": field.get("omission_reason"),
        }
        for field in field_records
        if isinstance(field, Mapping) and field.get("prompt_visible") is False
    ]
    return {
        "has_source_execution_result": (
            display.get("has_source_execution_result") is True
        ),
        "prompt_visible": display.get("prompt_visible") is True,
        "source_fields": list(display.get("source_fields", []))
        if isinstance(display.get("source_fields"), list)
        else [],
        "selected_fields": list(display.get("selected_fields", []))
        if isinstance(display.get("selected_fields"), list)
        else [],
        "prompt_visible_fields": list(display.get("prompt_visible_fields", []))
        if isinstance(display.get("prompt_visible_fields"), list)
        else [],
        "visible_field_display_sha256": visible_field_hashes,
        "omitted_fields": omitted_fields,
        "omission_reason": display.get("omission_reason"),
        "evaluator_result_joined": display.get("evaluator_result_joined") is True,
    }


def _prompt_prior_score_table_stage_summary_io(display: Mapping[str, object]) -> dict:
    stage_records = (
        display.get("stage_records")
        if isinstance(display.get("stage_records"), list)
        else []
    )
    visible_stage_summaries = []
    for stage in stage_records:
        if not isinstance(stage, Mapping):
            continue
        visible_stage_summaries.append(
            {
                "stage_index": stage.get("stage_index"),
                "stage_name": stage.get("stage_name"),
                "prompt_visible": stage.get("prompt_visible") is True,
                "prompt_visible_fields": list(stage.get("prompt_visible_fields", []))
                if isinstance(stage.get("prompt_visible_fields"), list)
                else [],
                "stage_io_display_sha256": stage.get("stage_io_display_sha256"),
                "omission_reason": stage.get("omission_reason"),
            }
        )
    return {
        "has_source_stage_io": display.get("has_source_stage_io") is True,
        "prompt_visible": display.get("prompt_visible") is True,
        "source_stage_count": display.get("source_stage_count"),
        "rendered_stage_count": display.get("rendered_stage_count"),
        "visible_stage_count": display.get("visible_stage_count"),
        "stage_records": visible_stage_summaries,
        "evaluator_result_joined": display.get("evaluator_result_joined") is True,
    }


def _prompt_prior_score_table_feedback_section_display(
    display: Mapping[str, object],
) -> dict:
    section_records = (
        display.get("section_records")
        if isinstance(display.get("section_records"), list)
        else []
    )
    return {
        "prompt_visible": display.get("prompt_visible") is True,
        "global_cap_chars": display.get("global_cap_chars"),
        "global_cap_applied": display.get("global_cap_applied") is True,
        "source_section_count": display.get("source_section_count"),
        "visible_section_count": display.get("visible_section_count"),
        "selected_sections": list(display.get("selected_sections", []))
        if isinstance(display.get("selected_sections"), list)
        else [],
        "section_order": list(display.get("section_order", []))
        if isinstance(display.get("section_order"), list)
        else [],
        "section_caps": dict(display.get("section_caps", {}))
        if isinstance(display.get("section_caps"), Mapping)
        else {},
        "visible_sections": [
            section.get("name")
            for section in section_records
            if isinstance(section, Mapping)
            and section.get("prompt_visible") is True
        ],
        "suppressed_sections": [
            {
                "name": section.get("name"),
                "omission_reason": section.get("omission_reason"),
            }
            for section in section_records
            if isinstance(section, Mapping)
            and section.get("prompt_visible") is False
            and section.get("has_source") is True
        ],
        "section_truncation": [
            {
                "name": section.get("name"),
                "cap_chars": section.get("cap_chars"),
                "section_cap_applied": section.get("section_cap_applied") is True,
            }
            for section in section_records
            if isinstance(section, Mapping)
            and section.get("section_cap_applied") is True
        ],
    }


def _write_prompt_prior_score_table(run_dir: Path, rows: list[dict]) -> dict:
    table_path = run_dir / "prompt_prior_score_table.jsonl"
    if not rows:
        return {
            "schema": "libreevolve.prompt_prior_score_table_export.v1",
            "path": "prompt_prior_score_table.jsonl",
            "record_schema": PROMPT_PRIOR_SCORE_TABLE_RECORD_SCHEMA,
            "record_count": 0,
            "exists": False,
            "sha256": None,
            "cross_run_policy": "rows_are_safe_to_concatenate_across_run_directories_by_run_id",
        }
    lines = [
        strict_json_dumps(
            versioned_record(PROMPT_PRIOR_SCORE_TABLE_RECORD_SCHEMA, row)
        )
        for row in rows
    ]
    text = "\n".join(lines) + "\n"
    table_path.write_text(text, encoding="utf-8")
    return {
        "schema": "libreevolve.prompt_prior_score_table_export.v1",
        "path": "prompt_prior_score_table.jsonl",
        "record_schema": PROMPT_PRIOR_SCORE_TABLE_RECORD_SCHEMA,
        "record_count": len(rows),
        "exists": True,
        "sha256": hashlib.sha256(text.encode("utf-8")).hexdigest(),
        "cross_run_policy": "rows_are_safe_to_concatenate_across_run_directories_by_run_id",
    }


def _prompt_prior_score_provenance_record(
    program: Program,
    program_by_id: Mapping[str, Program],
    history_indexes: Mapping[str, object],
) -> dict:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    prompt_diagnostics = (
        metadata.get("prompt_diagnostics")
        if isinstance(metadata.get("prompt_diagnostics"), Mapping)
        else {}
    )
    inspiration_selection = (
        metadata.get("inspiration_selection")
        if isinstance(metadata.get("inspiration_selection"), Mapping)
        else {}
    )
    prompt_program_id = metadata.get("prompt_program_id")
    selected_inspiration_ids = [
        item
        for item in inspiration_selection.get("selected_program_ids", [])
        if isinstance(item, str)
    ]
    score_records: list[dict] = []
    parent = (
        program_by_id.get(program.parent_id)
        if isinstance(program.parent_id, str)
        else None
    )
    if parent is not None:
        score_records.append(
            _prompt_prior_score_record(
                parent,
                role="target",
                prompt_visible=True,
                prompt_visibility_source="parent_score_and_parent_metrics_template_fields",
                prompt_diagnostics=prompt_diagnostics,
                history_indexes=history_indexes,
                ordinal=0,
            )
        )
    for ordinal, inspiration_id in enumerate(selected_inspiration_ids, start=1):
        inspiration = program_by_id.get(inspiration_id)
        if inspiration is None:
            score_records.append(
                _missing_prompt_prior_score_record(
                    inspiration_id,
                    role="inspiration",
                    ordinal=ordinal,
                )
            )
            continue
        score_records.append(
            _prompt_prior_score_record(
                inspiration,
                role="inspiration",
                prompt_visible=_inspiration_prompt_visible(
                    prompt_diagnostics,
                    ordinal - 1,
                    len(selected_inspiration_ids),
                ),
                prompt_visibility_source="prompt_diagnostics.inspiration_policy",
                prompt_diagnostics=prompt_diagnostics,
                history_indexes=history_indexes,
                ordinal=ordinal,
            )
        )
    return {
        "candidate_id": program.id,
        "candidate_status": _prompt_prior_candidate_status(program),
        "generation": program.generation,
        "prompt_program_id": prompt_program_id if isinstance(prompt_program_id, str) else None,
        "prompt_sha256": prompt_diagnostics.get("prompt_sha256"),
        "prompt_sha256_scope": prompt_diagnostics.get("prompt_sha256_scope"),
        "parent_id": program.parent_id,
        "selected_inspiration_ids": selected_inspiration_ids[:50],
        "selected_inspiration_ids_truncated": len(selected_inspiration_ids) > 50,
        "score_records": score_records[:51],
        "score_records_truncated": len(score_records) > 51,
    }


def _prompt_prior_score_record(
    source_program: Program,
    *,
    role: str,
    prompt_visible: bool,
    prompt_visibility_source: str,
    prompt_diagnostics: Mapping[str, object],
    history_indexes: Mapping[str, object],
    ordinal: int,
) -> dict:
    history_row = _prompt_prior_history_row(source_program.id, history_indexes)
    evaluator_row = _prompt_prior_evaluator_row(source_program.id, history_indexes)
    metrics = {
        str(name): _paper_metric_table_number(value)
        for name, value in sorted(source_program.metrics.items())
        if isinstance(name, str)
        and isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    }
    aggregate = _finite_json_number(source_program.fitness)
    average_score_text = _prompt_prior_average_score_display_text(aggregate)
    return {
        "role": role,
        "ordinal": ordinal,
        "program_id": source_program.id,
        "candidate_type": _program_candidate_type(source_program),
        "generation": source_program.generation,
        "prompt_visible": prompt_visible,
        "prompt_visibility_source": prompt_visibility_source,
        "omission_reason": None if prompt_visible else "not_rendered_by_prompt_policy",
        "source_hash": _workspace_sha256(source_program.workspace()),
        "displayed_aggregate_score": aggregate,
        "displayed_aggregate_formula": "program.fitness",
        "displayed_average_score": aggregate,
        "displayed_average_score_formula": "program.fitness",
        "displayed_average_score_text": average_score_text,
        "displayed_average_score_sha256": (
            hashlib.sha256(average_score_text.encode("utf-8")).hexdigest()
            if average_score_text is not None
            else None
        ),
        "displayed_average_score_policy": (
            "alphaevolve_average_score_alias_for_normalized_program_fitness"
        ),
        "raw_metrics": metrics,
        "metric_names": sorted(metrics),
        "score_display": _prompt_prior_score_display_record(
            source_program,
            role=role,
            prompt_visible=prompt_visible,
            prompt_diagnostics=prompt_diagnostics,
            metrics=metrics,
            aggregate=aggregate,
        ),
        "history_joined": isinstance(history_row, Mapping),
        "history_row": dict(history_row) if isinstance(history_row, Mapping) else None,
        "evaluator_result_joined": isinstance(evaluator_row, Mapping),
        "evaluator_result": dict(evaluator_row) if isinstance(evaluator_row, Mapping) else None,
        "execution_result_display": _prompt_prior_execution_result_display_record(
            source_program,
            role=role,
            prompt_visible=prompt_visible,
            prompt_diagnostics=prompt_diagnostics,
            evaluator_row=evaluator_row,
        ),
        "stage_summary_io_display": _prompt_prior_stage_summary_io_display_record(
            source_program,
            role=role,
            prompt_visible=prompt_visible,
            prompt_diagnostics=prompt_diagnostics,
            evaluator_row=evaluator_row,
        ),
        "feedback_section_display": _prompt_prior_feedback_section_display_record(
            source_program,
            role=role,
            prompt_visible=prompt_visible,
            prompt_diagnostics=prompt_diagnostics,
        ),
    }


