def _prompt_prior_score_display_record(
    source_program: Program,
    *,
    role: str,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
    metrics: Mapping[str, object],
    aggregate: float | None,
) -> dict:
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    metric_names = sorted(name for name in metrics if isinstance(name, str))
    metric_selection = _prompt_prior_metric_selection(role, policy, metric_names)
    metric_caps = (
        _prompt_prior_policy_int_mapping(
            policy,
            "parent_metrics_max_chars_by_name",
            allowed=set(metric_names) | set(metric_selection["configured_names"]),
        )
        if role == "target"
        else {}
    )
    aggregate_surface = _prompt_prior_score_surface_status(
        role,
        "aggregate",
        prompt_visible=prompt_visible,
        prompt_diagnostics=prompt_diagnostics,
    )
    metric_surface = _prompt_prior_score_surface_status(
        role,
        "metrics",
        prompt_visible=prompt_visible,
        prompt_diagnostics=prompt_diagnostics,
    )
    average_score_text = _prompt_prior_average_score_display_text(aggregate)
    fields = [
        _prompt_prior_score_field_record(
            "average_score",
            display_label="average_score",
            raw_value=aggregate,
            raw_text=average_score_text,
            prompt_visible=aggregate_surface["visible"] and aggregate is not None,
            prompt_visibility_source=aggregate_surface["source"],
            omission_reason=(
                None
                if aggregate_surface["visible"] and aggregate is not None
                else aggregate_surface["omission_reason"]
                or "average_score_not_finite"
            ),
            cap_chars=None,
        ),
        _prompt_prior_score_field_record(
            "aggregate_score",
            display_label="fitness",
            raw_value=aggregate,
            raw_text=None if aggregate is None else f"{float(aggregate):.4f}",
            prompt_visible=aggregate_surface["visible"] and aggregate is not None,
            prompt_visibility_source=aggregate_surface["source"],
            omission_reason=(
                None
                if aggregate_surface["visible"] and aggregate is not None
                else aggregate_surface["omission_reason"]
                or "aggregate_score_not_finite"
            ),
            cap_chars=None,
        )
    ]
    for metric_name in metric_names:
        selected = metric_name in metric_selection["selected_names"]
        cap = metric_caps.get(metric_name)
        raw_text = _prompt_prior_metric_display_text(metric_name, metrics[metric_name])
        visible = (
            metric_surface["visible"]
            and selected
            and cap != 0
            and bool(raw_text)
        )
        omission_reason = None
        if not visible:
            if metric_surface["visible"] is not True:
                omission_reason = metric_surface["omission_reason"]
            elif not selected:
                omission_reason = metric_selection["omission_reason"]
            elif cap == 0:
                omission_reason = "metric_suppressed_by_parent_metrics_cap"
            else:
                omission_reason = "metric_display_text_empty"
        fields.append(
            _prompt_prior_score_field_record(
                f"metric:{metric_name}",
                display_label=metric_name,
                raw_value=metrics[metric_name],
                raw_text=raw_text,
                prompt_visible=visible,
                prompt_visibility_source=metric_surface["source"],
                omission_reason=omission_reason,
                cap_chars=cap,
            )
        )
    omitted_or_truncated = sum(
        1
        for field in fields
        if field["prompt_visible"] is not True or field["truncated"] is True
    )
    return {
        "schema": "libreevolve.prompt_prior_score_display.v1",
        "source": "prompt_context_policy_parent_score_parent_metrics_and_inspiration_headers",
        "role": role,
        "prompt_visible": any(field["prompt_visible"] is True for field in fields),
        "metric_selection_policy": metric_selection,
        "metric_caps": metric_caps,
        "field_record_count": len(fields),
        "omitted_or_truncated_field_count": omitted_or_truncated,
        "fields": fields,
    }


def _prompt_prior_average_score_display_text(value: object) -> str | None:
    if value is None:
        return None
    return f"average_score={float(value):.4f}"


def _prompt_prior_metric_selection(
    role: str,
    policy: Mapping[str, object],
    metric_names: list[str],
) -> dict:
    if role != "target":
        return {
            "source": "inspiration_headers_render_all_available_metric_names",
            "configured_names": [],
            "selected_names": list(metric_names),
            "omitted_names": [],
            "omission_reason": None,
        }
    configured = policy.get("parent_metric_names")
    if not isinstance(configured, list):
        return {
            "source": "default_all_parent_metric_names",
            "configured_names": [],
            "selected_names": list(metric_names),
            "omitted_names": [],
            "omission_reason": None,
        }
    configured_names = [name for name in configured if isinstance(name, str)]
    selected = [name for name in metric_names if name in set(configured_names)]
    omitted = [name for name in metric_names if name not in set(configured_names)]
    return {
        "source": "prompt_context_policy.parent_metric_names",
        "configured_names": configured_names,
        "selected_names": selected,
        "omitted_names": omitted,
        "omission_reason": "metric_not_selected_by_parent_metric_names",
    }


def _prompt_prior_score_surface_status(
    role: str,
    field_group: str,
    *,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
) -> dict:
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    disabled = set(_prompt_prior_policy_list(policy, "disabled_sections", default=[]))
    if role == "target":
        section_name = "parent_score" if field_group == "aggregate" else "parent_metrics"
        source = f"{section_name}_template_field"
    else:
        section_name = "inspirations"
        source = "inspiration_header_fitness_and_metrics"
    if not prompt_visible:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "score_source_not_prompt_visible",
        }
    if section_name in disabled:
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_disabled_by_prompt_context_policy",
        }
    if not _prompt_prior_section_budget_has_rendered(
        prompt_diagnostics,
        section_name,
    ):
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_not_rendered_by_prompt_template",
        }
    return {"visible": True, "source": source, "omission_reason": None}


def _prompt_prior_score_field_record(
    field_id: str,
    *,
    display_label: str,
    raw_value: object,
    raw_text: str | None,
    prompt_visible: bool,
    prompt_visibility_source: str,
    omission_reason: str | None,
    cap_chars: int | None,
) -> dict:
    display_text = None
    display_sha256 = None
    truncated = False
    if raw_text is not None and prompt_visible:
        display_text = raw_text
        if isinstance(cap_chars, int) and not isinstance(cap_chars, bool):
            truncated = len(display_text) > cap_chars
            display_text = _prompt_execution_output_truncate(display_text, cap_chars)
        display_sha256 = hashlib.sha256(
            display_text.encode("utf-8", errors="replace")
        ).hexdigest()
    return {
        "field_id": field_id,
        "display_label": display_label,
        "raw_value": raw_value,
        "raw_text_sha256": hashlib.sha256(
            str(raw_text).encode("utf-8", errors="replace")
        ).hexdigest()
        if raw_text is not None
        else None,
        "cap_chars": cap_chars,
        "prompt_visible": prompt_visible,
        "prompt_visibility_source": prompt_visibility_source,
        "omission_reason": omission_reason,
        "truncated": truncated,
        "display_text": display_text,
        "display_chars": len(display_text) if display_text is not None else 0,
        "display_sha256": display_sha256,
    }


def _prompt_prior_metric_display_text(name: str, value: object) -> str:
    if isinstance(value, float):
        value_text = f"{value:g}"
    else:
        value_text = str(value)
    return f"{name}={value_text}"


def _prompt_prior_execution_result_display_record(
    source_program: Program,
    *,
    role: str,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
    evaluator_row: Mapping[str, object] | None,
) -> dict:
    evaluation = (
        source_program.evaluation
        if isinstance(source_program.evaluation, Mapping)
        else {}
    )
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    selected_fields = _prompt_prior_policy_list(
        policy,
        "execution_output_fields",
        default=list(_PROMPT_EXECUTION_OUTPUT_FIELDS),
    )
    field_caps = _prompt_prior_policy_int_mapping(
        policy,
        "execution_output_max_chars_by_field",
        allowed=set(_PROMPT_EXECUTION_OUTPUT_FIELDS),
    )
    surface = _prompt_prior_feedback_surface_status(
        role,
        prompt_visible=prompt_visible,
        prompt_diagnostics=prompt_diagnostics,
    )
    source_fields = [
        field
        for field in _PROMPT_EXECUTION_OUTPUT_FIELDS
        if _prompt_execution_output_raw_text(evaluation.get(field)) is not None
    ]
    visible_stdout = _prompt_execution_output_field_visible(
        evaluation,
        "stdout",
        selected_fields=selected_fields,
        field_caps=field_caps,
        surface_visible=surface["visible"],
    )
    visible_stderr = _prompt_execution_output_field_visible(
        evaluation,
        "stderr",
        selected_fields=selected_fields,
        field_caps=field_caps,
        surface_visible=surface["visible"],
    )
    stdout_or_stderr_visible = visible_stdout or visible_stderr
    field_records = []
    for field in _PROMPT_EXECUTION_OUTPUT_FIELDS:
        field_visible = _prompt_execution_output_field_visible(
            evaluation,
            field,
            selected_fields=selected_fields,
            field_caps=field_caps,
            surface_visible=surface["visible"],
            suppress_error=field == "error" and stdout_or_stderr_visible,
        )
        field_records.append(
            _prompt_execution_output_field_record(
                evaluation.get(field),
                field=field,
                selected=field in selected_fields,
                prompt_visible=field_visible,
                field_cap_chars=field_caps.get(field),
                omission_reason=_prompt_execution_output_omission_reason(
                    evaluation.get(field),
                    field,
                    selected_fields=selected_fields,
                    field_caps=field_caps,
                    surface=surface,
                    suppress_error=field == "error"
                    and stdout_or_stderr_visible,
                ),
            )
        )
    visible_fields = [
        record["field"]
        for record in field_records
        if record["prompt_visible"] is True
    ]
    display_omission_reason = surface["omission_reason"]
    if not visible_fields and display_omission_reason is None:
        display_omission_reason = "no_selected_execution_output_fields_rendered"
    return {
        "schema": "libreevolve.prompt_prior_execution_result_display.v1",
        "source": "evaluation_stdout_stderr_error_fields",
        "role": role,
        "prompt_visible": bool(visible_fields),
        "prompt_visibility_source": surface["source"],
        "omission_reason": None if visible_fields else display_omission_reason,
        "has_source_execution_result": bool(source_fields),
        "source_fields": source_fields,
        "selected_fields": selected_fields,
        "field_caps": field_caps,
        "prompt_visible_fields": visible_fields,
        "field_records": field_records,
        "evaluator_result_joined": isinstance(evaluator_row, Mapping),
        "evaluator_result": (
            dict(evaluator_row) if isinstance(evaluator_row, Mapping) else None
        ),
    }


def _prompt_prior_stage_summary_io_display_record(
    source_program: Program,
    *,
    role: str,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
    evaluator_row: Mapping[str, object] | None,
) -> dict:
    evaluation = (
        source_program.evaluation
        if isinstance(source_program.evaluation, Mapping)
        else {}
    )
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    selected_fields = _prompt_prior_policy_list(
        policy,
        "execution_output_fields",
        default=list(_PROMPT_EXECUTION_OUTPUT_FIELDS),
    )
    output_field_caps = _prompt_prior_policy_int_mapping(
        policy,
        "execution_output_max_chars_by_field",
        allowed=set(_PROMPT_EXECUTION_OUTPUT_FIELDS),
    )
    stage_fields = _prompt_prior_policy_list(
        policy,
        "stage_summary_fields",
        default=list(_PROMPT_STAGE_SUMMARY_FIELDS),
    )
    stage_caps = _prompt_prior_policy_int_mapping(
        policy,
        "stage_summary_max_chars_by_field",
        allowed=set(_PROMPT_STAGE_SUMMARY_FIELDS),
    )
    surface = _prompt_prior_stage_summary_surface_status(
        role,
        prompt_visible=prompt_visible,
        prompt_diagnostics=prompt_diagnostics,
        stage_fields=stage_fields,
    )
    stages = evaluation.get("stages") if isinstance(evaluation, Mapping) else None
    source_stages = [stage for stage in stages if isinstance(stage, Mapping)] if isinstance(stages, list) else []
    rendered_stages = source_stages[-_PROMPT_STAGE_SUMMARY_MAX_ITEMS:]
    stage_records = [
        _prompt_prior_stage_summary_io_stage_record(
            stage,
            stage_index=max(0, len(source_stages) - len(rendered_stages)) + index,
            selected_fields=selected_fields,
            output_field_caps=output_field_caps,
            stage_io_cap=stage_caps.get("io"),
            surface=surface,
        )
        for index, stage in enumerate(rendered_stages)
    ]
    source_stage_io_count = sum(
        1 for stage in stage_records if stage["has_source_stage_io"] is True
    )
    visible_stage_count = sum(
        1 for stage in stage_records if stage["prompt_visible"] is True
    )
    display_omission_reason = surface["omission_reason"]
    if visible_stage_count == 0 and display_omission_reason is None:
        display_omission_reason = "no_selected_stage_summary_io_fields_rendered"
    return {
        "schema": "libreevolve.prompt_prior_stage_summary_io_display.v1",
        "source": "evaluation_stage_stdout_stderr_error_fields",
        "role": role,
        "prompt_visible": visible_stage_count > 0,
        "prompt_visibility_source": surface["source"],
        "omission_reason": None if visible_stage_count > 0 else display_omission_reason,
        "has_source_stage_io": source_stage_io_count > 0,
        "source_stage_count": len(source_stages),
        "rendered_stage_count": len(rendered_stages),
        "visible_stage_count": visible_stage_count,
        "selected_fields": selected_fields,
        "stage_summary_fields": stage_fields,
        "execution_output_field_caps": output_field_caps,
        "stage_summary_field_caps": stage_caps,
        "stage_records": stage_records,
        "evaluator_result_joined": isinstance(evaluator_row, Mapping),
        "evaluator_result": (
            dict(evaluator_row) if isinstance(evaluator_row, Mapping) else None
        ),
    }


def _prompt_prior_stage_summary_io_stage_record(
    stage: Mapping[str, object],
    *,
    stage_index: int,
    selected_fields: list[str],
    output_field_caps: Mapping[str, int],
    stage_io_cap: int | None,
    surface: Mapping[str, object],
) -> dict:
    visible_stdout = _prompt_execution_output_field_visible(
        stage,
        "stdout",
        selected_fields=selected_fields,
        field_caps=output_field_caps,
        surface_visible=surface["visible"],
    )
    visible_stderr = _prompt_execution_output_field_visible(
        stage,
        "stderr",
        selected_fields=selected_fields,
        field_caps=output_field_caps,
        surface_visible=surface["visible"],
    )
    stdout_or_stderr_visible = visible_stdout or visible_stderr
    field_records = []
    for field in _PROMPT_EXECUTION_OUTPUT_FIELDS:
        field_visible = _prompt_execution_output_field_visible(
            stage,
            field,
            selected_fields=selected_fields,
            field_caps=output_field_caps,
            surface_visible=surface["visible"],
            suppress_error=field == "error" and stdout_or_stderr_visible,
        )
        field_records.append(
            _prompt_execution_output_field_record(
                stage.get(field),
                field=field,
                selected=field in selected_fields,
                prompt_visible=field_visible,
                field_cap_chars=output_field_caps.get(field),
                omission_reason=_prompt_execution_output_omission_reason(
                    stage.get(field),
                    field,
                    selected_fields=selected_fields,
                    field_caps=output_field_caps,
                    surface=surface,
                    suppress_error=field == "error" and stdout_or_stderr_visible,
                ),
            )
        )
    visible_fields = [
        record["field"]
        for record in field_records
        if record["prompt_visible"] is True
    ]
    stage_io_text = _prompt_stage_io_display_text(field_records)
    stage_io_raw_chars = len(stage_io_text)
    stage_io_truncated = False
    if stage_io_text and isinstance(stage_io_cap, int) and not isinstance(stage_io_cap, bool):
        stage_io_truncated = len(stage_io_text) > stage_io_cap
        stage_io_text = _prompt_execution_output_truncate(stage_io_text, stage_io_cap)
    stage_io_sha256 = (
        hashlib.sha256(stage_io_text.encode("utf-8", errors="replace")).hexdigest()
        if stage_io_text
        else None
    )
    omission_reason = None
    if not visible_fields:
        reason = surface.get("omission_reason")
        omission_reason = (
            str(reason)
            if isinstance(reason, str) and reason
            else "no_selected_stage_summary_io_fields_rendered"
        )
    return {
        "stage_index": stage_index,
        "stage_name": stage.get("name"),
        "has_source_stage_io": any(record["raw_present"] for record in field_records),
        "prompt_visible": bool(visible_fields),
        "prompt_visible_fields": visible_fields,
        "omission_reason": omission_reason,
        "field_records": field_records,
        "stage_io_display_text": stage_io_text if visible_fields else None,
        "stage_io_display_chars": len(stage_io_text) if visible_fields else 0,
        "stage_io_raw_chars": stage_io_raw_chars,
        "stage_io_truncated": stage_io_truncated,
        "stage_io_display_sha256": stage_io_sha256 if visible_fields else None,
    }


def _prompt_stage_io_display_text(field_records: list[dict]) -> str:
    lines = []
    for field in field_records:
        if field.get("prompt_visible") is not True:
            continue
        display = field.get("display_text")
        if isinstance(display, str) and display:
            lines.append(f"  {field.get('field')}={display}")
    return "\n".join(lines)


def _prompt_prior_feedback_section_display_record(
    source_program: Program,
    *,
    role: str,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
) -> dict:
    evaluation = (
        source_program.evaluation
        if isinstance(source_program.evaluation, Mapping)
        else {}
    )
    metadata = (
        evaluation.get("metadata")
        if isinstance(evaluation.get("metadata"), Mapping)
        else {}
    )
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    selected_sections = _prompt_prior_policy_list(
        policy,
        "feedback_sections",
        default=sorted(PROMPT_CONTEXT_POLICY_FEEDBACK_SECTIONS),
    )
    section_order = _prompt_prior_feedback_section_order(policy)
    section_caps = _prompt_prior_policy_int_mapping(
        policy,
        "feedback_section_max_chars_by_name",
        allowed=set(PROMPT_CONTEXT_POLICY_FEEDBACK_SECTIONS),
    )
    section_name = "parent_feedback" if role == "target" else "inspirations"
    surface = _prompt_prior_feedback_channel_surface_status(
        role,
        prompt_visible=prompt_visible,
        prompt_diagnostics=prompt_diagnostics,
    )
    source_sections = _prompt_prior_feedback_source_sections(
        source_program,
        evaluation,
        metadata,
    )
    records = []
    selected = set(selected_sections)
    ordered_names = [
        name
        for name in section_order
        if name in PROMPT_CONTEXT_POLICY_FEEDBACK_SECTIONS
    ]
    for name in ordered_names:
        has_source = name in source_sections
        cap = section_caps.get(name)
        visible = surface["visible"] and name in selected and has_source and cap != 0
        omission_reason = None
        if not visible:
            if surface["visible"] is not True:
                omission_reason = surface["omission_reason"]
            elif name not in selected:
                omission_reason = "feedback_section_not_selected_by_prompt_context_policy"
            elif not has_source:
                omission_reason = "feedback_section_has_no_source_content"
            elif cap == 0:
                omission_reason = "feedback_section_suppressed_by_prompt_context_policy_cap"
        records.append(
            {
                "name": name,
                "selected": name in selected,
                "order_index": len(records),
                "has_source": has_source,
                "source": source_sections.get(name),
                "cap_chars": cap,
                "section_cap_configured": cap is not None,
                "section_cap_applied": (
                    isinstance(cap, int) and not isinstance(cap, bool) and cap >= 0
                ),
                "prompt_visible": visible,
                "omission_reason": omission_reason,
            }
        )
    visible_sections = [
        record["name"] for record in records if record["prompt_visible"] is True
    ]
    rendered_section_budget = _prompt_prior_section_budget_record(
        prompt_diagnostics,
        section_name,
    )
    global_cap_applied = False
    if rendered_section_budget is not None:
        chars = rendered_section_budget.get("chars")
        global_cap_applied = (
            isinstance(chars, int)
            and not isinstance(chars, bool)
            and chars >= PROMPT_FEEDBACK_GLOBAL_MAX_CHARS
        )
    return {
        "schema": "libreevolve.prompt_prior_feedback_section_display.v1",
        "source": "prompt_context_policy_feedback_sections_order_caps_and_global_feedback_cap",
        "role": role,
        "prompt_visible": bool(visible_sections),
        "prompt_visibility_source": surface["source"],
        "omission_reason": None
        if visible_sections
        else surface["omission_reason"] or "no_feedback_sections_rendered",
        "feedback_template_section": section_name,
        "feedback_template_section_budget": rendered_section_budget,
        "selected_sections": selected_sections,
        "section_order": ordered_names,
        "section_caps": section_caps,
        "global_cap_chars": PROMPT_FEEDBACK_GLOBAL_MAX_CHARS,
        "global_cap_policy": "fixed_prompt_feedback_text_chars_after_section_caps",
        "global_cap_applied": global_cap_applied,
        "source_section_count": len(source_sections),
        "visible_section_count": len(visible_sections),
        "section_records": records,
    }


def _prompt_prior_feedback_section_order(
    policy: Mapping[str, object],
) -> list[str]:
    configured = _prompt_prior_policy_list(
        policy,
        "feedback_section_order",
        default=list(PROMPT_CONTEXT_POLICY_FEEDBACK_SECTION_ORDER),
    )
    seen = set()
    ordered = []
    for name in configured + list(PROMPT_CONTEXT_POLICY_FEEDBACK_SECTION_ORDER):
        if name in PROMPT_CONTEXT_POLICY_FEEDBACK_SECTIONS and name not in seen:
            ordered.append(name)
            seen.add(name)
    return ordered


def _prompt_prior_feedback_source_sections(
    source_program: Program,
    evaluation: Mapping[str, object],
    metadata: Mapping[str, object],
) -> dict[str, str]:
    sections: dict[str, str] = {}
    proposal = (
        source_program.metadata.get("proposal")
        if isinstance(source_program.metadata, Mapping)
        else None
    )
    if isinstance(proposal, Mapping) and proposal:
        sections["proposal"] = "program.metadata.proposal"
    stages = evaluation.get("stages")
    if isinstance(stages, list) and any(isinstance(stage, Mapping) for stage in stages):
        sections["stage_summary"] = "evaluation.stages"
    if any(
        _prompt_execution_output_raw_text(evaluation.get(field)) is not None
        for field in _PROMPT_EXECUTION_OUTPUT_FIELDS
    ):
        sections["execution_output"] = "evaluation.stdout_stderr_error"
    if isinstance(metadata.get("attempts"), list) and metadata.get("attempts"):
        sections["sample_retry_diagnostics"] = "evaluation.metadata.attempts"
    if isinstance(metadata.get("artifacts"), list) and metadata.get("artifacts"):
        sections["validator_artifacts"] = "evaluation.metadata.artifacts"
    if _prompt_prior_has_validator_diagnostic_source(metadata):
        sections["validator_diagnostics"] = "evaluation.metadata.validator_diagnostics"
    if (
        isinstance(metadata.get("program_outputs"), list)
        and metadata.get("program_outputs")
    ):
        sections["program_outputs"] = "evaluation.metadata.program_outputs"
    if isinstance(metadata.get("llm_feedback"), list) and metadata.get("llm_feedback"):
        sections["llm_grader_feedback"] = "evaluation.metadata.llm_feedback"
    return sections


def _prompt_prior_has_validator_diagnostic_source(
    metadata: Mapping[str, object],
) -> bool:
    diagnostic_keys = {
        "configured_stage_results",
        "diagnostic_output",
        "evaluator_dependency_policy",
        "malformed_metrics",
        "materialization_error",
        "metric_aggregation",
        "metric_bound_diagnostics",
        "syntax_errors",
        "timeout_cleanup",
        "validator_boundary",
        "validator_env",
        "validator_resource_limit",
        "stdin",
    }
    return any(key in metadata for key in diagnostic_keys)


def _prompt_prior_feedback_channel_surface_status(
    role: str,
    *,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
) -> dict:
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    disabled = set(_prompt_prior_policy_list(policy, "disabled_sections", default=[]))
    section_name = "parent_feedback" if role == "target" else "inspirations"
    source = (
        "parent_feedback_template_field"
        if role == "target"
        else "inspiration_feedback_template_field"
    )
    if not prompt_visible:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "score_source_not_prompt_visible",
        }
    if section_name in disabled:
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_disabled_by_prompt_context_policy",
        }
    if not _prompt_prior_section_budget_has_rendered(
        prompt_diagnostics,
        section_name,
    ):
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_not_rendered_by_prompt_template",
        }
    return {"visible": True, "source": source, "omission_reason": None}


def _prompt_prior_section_budget_record(
    prompt_diagnostics: Mapping[str, object],
    section_name: str,
) -> dict | None:
    section_budget = (
        prompt_diagnostics.get("section_budget")
        if isinstance(prompt_diagnostics.get("section_budget"), Mapping)
        else {}
    )
    sections = section_budget.get("sections")
    if not isinstance(sections, list):
        return None
    for section in sections:
        if not isinstance(section, Mapping):
            continue
        if section.get("name") != section_name:
            continue
        return {
            "name": section.get("name"),
            "chars": section.get("chars"),
            "rendered_estimate_chars": section.get("rendered_estimate_chars"),
            "occurrences": section.get("occurrences"),
            "sha256": section.get("sha256"),
        }
    return None


def _prompt_prior_feedback_surface_status(
    role: str,
    *,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
) -> dict:
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    disabled = set(_prompt_prior_policy_list(policy, "disabled_sections", default=[]))
    feedback_sections = set(
        _prompt_prior_policy_list(
            policy,
            "feedback_sections",
            default=[
                "proposal",
                "stage_summary",
                "execution_output",
                "sample_retry_diagnostics",
                "validator_artifacts",
                "validator_diagnostics",
                "program_outputs",
                "llm_grader_feedback",
            ],
        )
    )
    section_name = "parent_feedback" if role == "target" else "inspirations"
    source = (
        "parent_feedback_execution_output_section"
        if role == "target"
        else "inspiration_feedback_execution_output_section"
    )
    if not prompt_visible:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "score_source_not_prompt_visible",
        }
    if section_name in disabled:
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_disabled_by_prompt_context_policy",
        }
    if "execution_output" not in feedback_sections:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "execution_output_feedback_section_disabled",
        }
    if not _prompt_prior_section_budget_has_rendered(
        prompt_diagnostics,
        section_name,
    ):
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_not_rendered_by_prompt_template",
        }
    return {"visible": True, "source": source, "omission_reason": None}


def _prompt_prior_stage_summary_surface_status(
    role: str,
    *,
    prompt_visible: bool,
    prompt_diagnostics: Mapping[str, object],
    stage_fields: list[str],
) -> dict:
    policy = (
        prompt_diagnostics.get("prompt_context_policy")
        if isinstance(prompt_diagnostics.get("prompt_context_policy"), Mapping)
        else {}
    )
    disabled = set(_prompt_prior_policy_list(policy, "disabled_sections", default=[]))
    feedback_sections = set(
        _prompt_prior_policy_list(
            policy,
            "feedback_sections",
            default=[
                "proposal",
                "stage_summary",
                "execution_output",
                "sample_retry_diagnostics",
                "validator_artifacts",
                "validator_diagnostics",
                "program_outputs",
                "llm_grader_feedback",
            ],
        )
    )
    section_name = "parent_feedback" if role == "target" else "inspirations"
    source = (
        "parent_feedback_stage_summary_io"
        if role == "target"
        else "inspiration_feedback_stage_summary_io"
    )
    if not prompt_visible:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "score_source_not_prompt_visible",
        }
    if section_name in disabled:
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_disabled_by_prompt_context_policy",
        }
    if "stage_summary" not in feedback_sections:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "stage_summary_feedback_section_disabled",
        }
    if "io" not in stage_fields:
        return {
            "visible": False,
            "source": source,
            "omission_reason": "stage_summary_io_field_not_selected",
        }
    if not _prompt_prior_section_budget_has_rendered(
        prompt_diagnostics,
        section_name,
    ):
        return {
            "visible": False,
            "source": source,
            "omission_reason": f"{section_name}_not_rendered_by_prompt_template",
        }
    return {"visible": True, "source": source, "omission_reason": None}


def _prompt_prior_section_budget_has_rendered(
    prompt_diagnostics: Mapping[str, object],
    section_name: str,
) -> bool:
    section_budget = (
        prompt_diagnostics.get("section_budget")
        if isinstance(prompt_diagnostics.get("section_budget"), Mapping)
        else {}
    )
    sections = section_budget.get("sections")
    if not isinstance(sections, list):
        return False
    for section in sections:
        if not isinstance(section, Mapping):
            continue
        if section.get("name") != section_name:
            continue
        chars = section.get("chars")
        occurrences = section.get("occurrences")
        return (
            isinstance(chars, int)
            and not isinstance(chars, bool)
            and chars > 0
            and isinstance(occurrences, int)
            and not isinstance(occurrences, bool)
            and occurrences > 0
        )
    return False


def _prompt_execution_output_field_visible(
    evaluation: Mapping[str, object],
    field: str,
    *,
    selected_fields: list[str],
    field_caps: Mapping[str, int],
    surface_visible: bool,
    suppress_error: bool = False,
) -> bool:
    if not surface_visible or field not in selected_fields or suppress_error:
        return False
    if field_caps.get(field) == 0:
        return False
    return _prompt_execution_output_raw_text(evaluation.get(field)) is not None


def _prompt_execution_output_omission_reason(
    value: object,
    field: str,
    *,
    selected_fields: list[str],
    field_caps: Mapping[str, int],
    surface: Mapping[str, object],
    suppress_error: bool = False,
) -> str | None:
    if field not in selected_fields:
        return "field_not_selected_by_prompt_context_policy"
    if field_caps.get(field) == 0:
        return "field_suppressed_by_prompt_context_policy_cap"
    if _prompt_execution_output_raw_text(value) is None:
        return "empty_or_missing_execution_output_field"
    if suppress_error:
        return "error_field_suppressed_when_stdout_or_stderr_visible"
    if surface.get("visible") is not True:
        reason = surface.get("omission_reason")
        return str(reason) if isinstance(reason, str) and reason else None
    return None


def _prompt_execution_output_field_record(
    value: object,
    *,
    field: str,
    selected: bool,
    prompt_visible: bool,
    field_cap_chars: int | None,
    omission_reason: str | None,
) -> dict:
    raw = _prompt_execution_output_raw_text(value)
    max_chars = (
        field_cap_chars
        if isinstance(field_cap_chars, int)
        and not isinstance(field_cap_chars, bool)
        else _PROMPT_EXECUTION_OUTPUT_DEFAULT_FIELD_CHARS
    )
    display_text = None
    display_sha256 = None
    display_chars = 0
    redacted = False
    truncated = False
    raw_sha256 = None
    raw_chars = 0
    if raw is not None:
        raw_sha256 = hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()
        raw_chars = len(raw)
        redacted_text = redact_sensitive_text(raw)
        redacted = redacted_text != raw
        truncated = len(redacted_text) > max_chars
        if prompt_visible:
            display_text = _prompt_execution_output_truncate(
                redacted_text,
                max_chars,
            ).replace("\n", "\\n")
            display_sha256 = hashlib.sha256(
                display_text.encode("utf-8", errors="replace")
            ).hexdigest()
            display_chars = len(display_text)
    return {
        "field": field,
        "selected": selected,
        "field_cap_chars": field_cap_chars,
        "raw_present": raw is not None,
        "raw_chars": raw_chars,
        "raw_sha256": raw_sha256,
        "redacted": redacted,
        "truncated": truncated,
        "prompt_visible": prompt_visible,
        "omission_reason": omission_reason,
        "display_text": display_text,
        "display_chars": display_chars,
        "display_sha256": display_sha256,
    }


def _prompt_execution_output_raw_text(value: object) -> str | None:
    if value is None:
        return None
    text = str(value).replace("\r\n", "\n").strip()
    return text or None


def _prompt_execution_output_truncate(text: str, max_chars: int) -> str:
    if len(text) <= max_chars:
        return text
    notice = f"...[truncated {len(text) - max_chars} chars]"
    keep = max(0, max_chars - len(notice))
    return text[:keep] + notice


def _prompt_prior_policy_list(
    policy: Mapping[str, object],
    field: str,
    *,
    default: list[str],
) -> list[str]:
    value = policy.get(field)
    if not isinstance(value, list):
        return list(default)
    return [item for item in value if isinstance(item, str)]


def _prompt_prior_policy_int_mapping(
    policy: Mapping[str, object],
    field: str,
    *,
    allowed: set[str],
) -> dict[str, int]:
    value = policy.get(field)
    if not isinstance(value, Mapping):
        return {}
    return {
        str(key): item
        for key, item in value.items()
        if isinstance(key, str)
        and key in allowed
        and isinstance(item, int)
        and not isinstance(item, bool)
        and item >= 0
    }


def _prompt_prior_history_row(
    program_id: str,
    history_indexes: Mapping[str, object],
) -> Mapping[str, object] | None:
    candidate_history_by_id = history_indexes.get("candidate_history_by_id")
    if isinstance(candidate_history_by_id, Mapping):
        row = candidate_history_by_id.get(program_id)
        if isinstance(row, Mapping):
            return row
    candidate_failure_history_by_id = history_indexes.get(
        "candidate_failure_history_by_id"
    )
    if isinstance(candidate_failure_history_by_id, Mapping):
        row = candidate_failure_history_by_id.get(program_id)
        if isinstance(row, Mapping):
            return row
    return None


def _prompt_prior_evaluator_row(
    program_id: str,
    history_indexes: Mapping[str, object],
) -> Mapping[str, object] | None:
    evaluator_result_by_candidate_id = history_indexes.get(
        "evaluator_result_by_candidate_id"
    )
    if isinstance(evaluator_result_by_candidate_id, Mapping):
        row = evaluator_result_by_candidate_id.get(program_id)
        if isinstance(row, Mapping):
            return row
    return None


def _inspiration_prompt_visible(
    prompt_diagnostics: Mapping[str, object],
    index: int,
    selected_count: int,
) -> bool:
    inspiration_policy = (
        prompt_diagnostics.get("inspiration_policy")
        if isinstance(prompt_diagnostics.get("inspiration_policy"), Mapping)
        else {}
    )
    if inspiration_policy.get("rendered_count_source") == "disabled_section":
        return False
    rendered_count = inspiration_policy.get("rendered_count")
    if isinstance(rendered_count, int) and not isinstance(rendered_count, bool):
        return index < max(0, rendered_count)
    return selected_count > 0


def _prompt_prior_candidate_status(program: Program) -> str:
    metadata = program.metadata if isinstance(program.metadata, Mapping) else {}
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), Mapping)
        else {}
    )
    if admission.get("admitted") is True:
        return "accepted_history"
    if metadata.get("candidate_status") == "llm_mutation_failed":
        return "llm_mutation_failed"
    return "rejected_history"


def validate_prompt_prior_score_provenance_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.prompt_prior_score_provenance_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "prompt prior-score report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "prompt_record_count",
        "score_record_count",
        "target_score_record_count",
        "inspiration_score_record_count",
        "history_join_count",
        "evaluator_result_join_count",
        "omitted_or_truncated_score_record_count",
        "score_field_record_count",
        "omitted_or_truncated_score_field_count",
        "execution_result_record_count",
        "prompt_visible_execution_result_record_count",
        "execution_result_evaluator_join_count",
        "stage_summary_io_record_count",
        "prompt_visible_stage_summary_io_record_count",
        "stage_summary_io_evaluator_join_count",
        "feedback_section_policy_record_count",
        "feedback_section_global_policy_record_count",
        "cross_run_prompt_score_table_record_count",
        "records",
        "records_limit",
        "records_truncated",
        "score_policy",
        "cross_run_prompt_score_table",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"prompt prior-score report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.prompt_prior_score_provenance_report.v1":
        issues.append({"code": "invalid_schema", "message": "prompt prior-score report schema is unsupported"})
    if (
        report.get("source")
        != "runtime_history_prompt_diagnostics_parent_and_inspiration_selection"
    ):
        issues.append({"code": "invalid_source", "message": "prompt prior-score report source is unsupported"})
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    score_record_count = 0
    target_score_count = 0
    inspiration_score_count = 0
    history_join_count = 0
    evaluator_join_count = 0
    omitted_count = 0
    score_field_count = 0
    omitted_or_truncated_score_field_count = 0
    execution_result_count = 0
    prompt_visible_execution_result_count = 0
    execution_result_evaluator_join_count = 0
    stage_summary_io_count = 0
    prompt_visible_stage_summary_io_count = 0
    stage_summary_io_evaluator_join_count = 0
    feedback_section_policy_count = 0
    feedback_section_global_policy_count = 0
    for record_index, record in enumerate(records):
        if not isinstance(record, Mapping):
            issues.append({"code": "invalid_record", "message": f"record {record_index} must be an object"})
            continue
        if not isinstance(record.get("candidate_id"), str) or not record.get("candidate_id"):
            issues.append({"code": "invalid_candidate_id", "message": f"record {record_index} candidate_id is invalid"})
        if record.get("candidate_status") not in {
            "accepted_history",
            "rejected_history",
            "llm_mutation_failed",
        }:
            issues.append({"code": "invalid_candidate_status", "message": f"record {record_index} candidate_status is invalid"})
        if record.get("prompt_sha256") is not None and not _is_sha256_hex(record.get("prompt_sha256")):
            issues.append({"code": "invalid_prompt_hash", "message": f"record {record_index} prompt hash is invalid"})
        scores = record.get("score_records")
        if not isinstance(scores, list):
            issues.append({"code": "invalid_score_records", "message": f"record {record_index} score_records must be a list"})
            scores = []
        for score_index, score in enumerate(scores):
            if not isinstance(score, Mapping):
                issues.append({"code": "invalid_score_record", "message": f"record {record_index} score {score_index} must be an object"})
                continue
            score_record_count += 1
            role = score.get("role")
            if role == "target":
                target_score_count += 1
            elif role == "inspiration":
                inspiration_score_count += 1
            else:
                issues.append({"code": "invalid_score_role", "message": f"record {record_index} score {score_index} role is invalid"})
            if not isinstance(score.get("program_id"), str) or not score.get("program_id"):
                issues.append({"code": "invalid_score_program", "message": f"record {record_index} score {score_index} program_id is invalid"})
            if score.get("source_hash") is not None and not _is_sha256_hex(score.get("source_hash")):
                issues.append({"code": "invalid_score_source_hash", "message": f"record {record_index} score {score_index} source hash is invalid"})
            if score.get("displayed_aggregate_formula") != "program.fitness":
                issues.append({"code": "invalid_score_formula", "message": f"record {record_index} score {score_index} formula is invalid"})
            if score.get("displayed_aggregate_score") is not None and not isinstance(score.get("displayed_aggregate_score"), (int, float)):
                issues.append({"code": "invalid_displayed_score", "message": f"record {record_index} score {score_index} displayed score must be numeric or null"})
            if score.get("displayed_average_score_formula") != "program.fitness":
                issues.append({"code": "invalid_average_score_formula", "message": f"record {record_index} score {score_index} average_score formula is invalid"})
            if score.get("displayed_average_score") != score.get("displayed_aggregate_score"):
                issues.append({"code": "average_score_mismatch", "message": f"record {record_index} score {score_index} average_score must match displayed aggregate score"})
            average_text = score.get("displayed_average_score_text")
            average_hash = score.get("displayed_average_score_sha256")
            if score.get("displayed_average_score") is None:
                if average_text is not None or average_hash is not None:
                    issues.append({"code": "invalid_null_average_score_display", "message": f"record {record_index} score {score_index} null average_score must not have display text or hash"})
            else:
                expected_average_text = _prompt_prior_average_score_display_text(
                    score.get("displayed_average_score")
                )
                if average_text != expected_average_text:
                    issues.append({"code": "average_score_text_mismatch", "message": f"record {record_index} score {score_index} average_score text is invalid"})
                if (
                    not _is_sha256_hex(average_hash)
                    or average_hash
                    != hashlib.sha256(
                        str(average_text).encode("utf-8")
                    ).hexdigest()
                ):
                    issues.append({"code": "invalid_average_score_hash", "message": f"record {record_index} score {score_index} average_score hash is invalid"})
            if (
                score.get("displayed_average_score_policy")
                != "alphaevolve_average_score_alias_for_normalized_program_fitness"
            ):
                issues.append({"code": "invalid_average_score_policy", "message": f"record {record_index} score {score_index} average_score policy is invalid"})
            metrics = score.get("raw_metrics")
            if not isinstance(metrics, Mapping):
                issues.append({"code": "invalid_raw_metrics", "message": f"record {record_index} score {score_index} raw_metrics must be an object"})
                metrics = {}
            for metric_name, value in metrics.items():
                if not isinstance(metric_name, str) or not metric_name:
                    issues.append({"code": "invalid_metric_name", "message": f"record {record_index} score {score_index} metric name is invalid"})
                if value is not None and not isinstance(value, (int, float)):
                    issues.append({"code": "invalid_metric_value", "message": f"record {record_index} score {score_index} metric value is invalid"})
            if score.get("metric_names") != sorted(metrics):
                issues.append({"code": "metric_names_mismatch", "message": f"record {record_index} score {score_index} metric_names must match raw_metrics"})
            score_display = score.get("score_display")
            if not isinstance(score_display, Mapping):
                issues.append({"code": "invalid_score_display", "message": f"record {record_index} score {score_index} score_display must be an object"})
            else:
                if score_display.get("schema") != "libreevolve.prompt_prior_score_display.v1":
                    issues.append({"code": "invalid_score_display_schema", "message": f"record {record_index} score {score_index} score_display schema is unsupported"})
                fields = score_display.get("fields")
                if not isinstance(fields, list):
                    issues.append({"code": "invalid_score_display_fields", "message": f"record {record_index} score {score_index} score_display.fields must be a list"})
                    fields = []
                score_field_count += len(fields)
                observed_omitted_or_truncated = 0
                for field_index, field in enumerate(fields):
                    if not isinstance(field, Mapping):
                        issues.append({"code": "invalid_score_display_field", "message": f"record {record_index} score {score_index} display field {field_index} must be an object"})
                        continue
                    if not isinstance(field.get("field_id"), str) or not field.get("field_id"):
                        issues.append({"code": "invalid_score_display_field_id", "message": f"record {record_index} score {score_index} display field id is invalid"})
                    if field.get("prompt_visible") is True:
                        if not isinstance(field.get("display_text"), str):
                            issues.append({"code": "missing_score_display_text", "message": f"record {record_index} score {score_index} visible score field needs display text"})
                        if not _is_sha256_hex(field.get("display_sha256")):
                            issues.append({"code": "invalid_score_display_hash", "message": f"record {record_index} score {score_index} visible score field needs display hash"})
                        if field.get("omission_reason") is not None:
                            issues.append({"code": "visible_score_field_has_omission", "message": f"record {record_index} score {score_index} visible score field must not have omission reason"})
                    elif field.get("prompt_visible") is False:
                        observed_omitted_or_truncated += 1
                        if not isinstance(field.get("omission_reason"), str) or not field.get("omission_reason"):
                            issues.append({"code": "missing_score_field_omission", "message": f"record {record_index} score {score_index} omitted score field needs reason"})
                    else:
                        issues.append({"code": "invalid_score_field_prompt_visible", "message": f"record {record_index} score {score_index} score field prompt_visible must be boolean"})
                    if field.get("truncated") is True:
                        observed_omitted_or_truncated += 1
                    elif field.get("truncated") is not False:
                        issues.append({"code": "invalid_score_field_truncated", "message": f"record {record_index} score {score_index} score field truncated must be boolean"})
                omitted_or_truncated_score_field_count += observed_omitted_or_truncated
                if score_display.get("field_record_count") != len(fields):
                    issues.append({"code": "score_display_field_count_mismatch", "message": f"record {record_index} score {score_index} score display field count is invalid"})
                if score_display.get("omitted_or_truncated_field_count") != observed_omitted_or_truncated:
                    issues.append({"code": "score_display_omitted_count_mismatch", "message": f"record {record_index} score {score_index} score display omitted/truncated count is invalid"})
            if score.get("prompt_visible") is True:
                if score.get("omission_reason") is not None:
                    issues.append({"code": "visible_score_has_omission", "message": f"record {record_index} score {score_index} visible score must not have omission reason"})
            elif score.get("prompt_visible") is False:
                omitted_count += 1
                if not isinstance(score.get("omission_reason"), str) or not score.get("omission_reason"):
                    issues.append({"code": "missing_score_omission_reason", "message": f"record {record_index} score {score_index} omitted score needs reason"})
            else:
                issues.append({"code": "invalid_prompt_visible", "message": f"record {record_index} score {score_index} prompt_visible must be boolean"})
            if score.get("history_joined") is True:
                history_join_count += 1
                if not isinstance(score.get("history_row"), Mapping):
                    issues.append({"code": "invalid_history_row", "message": f"record {record_index} score {score_index} history_row must be an object"})
            elif score.get("history_joined") is not False:
                issues.append({"code": "invalid_history_join_flag", "message": f"record {record_index} score {score_index} history_joined must be boolean"})
            if score.get("evaluator_result_joined") is True:
                evaluator_join_count += 1
                evaluator_result = score.get("evaluator_result")
                if not isinstance(evaluator_result, Mapping):
                    issues.append({"code": "invalid_evaluator_result", "message": f"record {record_index} score {score_index} evaluator_result must be an object"})
                elif evaluator_result.get("stream") != "evaluator_results.jsonl":
                    issues.append({"code": "invalid_evaluator_stream", "message": f"record {record_index} score {score_index} evaluator stream is invalid"})
            elif score.get("evaluator_result_joined") is not False:
                issues.append({"code": "invalid_evaluator_join_flag", "message": f"record {record_index} score {score_index} evaluator_result_joined must be boolean"})
            execution_display = score.get("execution_result_display")
            if not isinstance(execution_display, Mapping):
                issues.append({"code": "invalid_execution_result_display", "message": f"record {record_index} score {score_index} execution_result_display must be an object"})
            else:
                if execution_display.get("schema") != "libreevolve.prompt_prior_execution_result_display.v1":
                    issues.append({"code": "invalid_execution_result_display_schema", "message": f"record {record_index} score {score_index} execution display schema is unsupported"})
                if execution_display.get("has_source_execution_result") is True:
                    execution_result_count += 1
                elif execution_display.get("has_source_execution_result") is not False:
                    issues.append({"code": "invalid_execution_result_source_flag", "message": f"record {record_index} score {score_index} execution source flag must be boolean"})
                if execution_display.get("prompt_visible") is True:
                    prompt_visible_execution_result_count += 1
                elif execution_display.get("prompt_visible") is not False:
                    issues.append({"code": "invalid_execution_result_prompt_visible", "message": f"record {record_index} score {score_index} execution prompt_visible must be boolean"})
                if execution_display.get("evaluator_result_joined") is True:
                    execution_result_evaluator_join_count += 1
                    execution_evaluator = execution_display.get("evaluator_result")
                    if not isinstance(execution_evaluator, Mapping):
                        issues.append({"code": "invalid_execution_result_evaluator_row", "message": f"record {record_index} score {score_index} execution evaluator row must be an object"})
                    elif execution_evaluator.get("stream") != "evaluator_results.jsonl":
                        issues.append({"code": "invalid_execution_result_evaluator_stream", "message": f"record {record_index} score {score_index} execution evaluator stream is invalid"})
                elif execution_display.get("evaluator_result_joined") is not False:
                    issues.append({"code": "invalid_execution_result_evaluator_join", "message": f"record {record_index} score {score_index} execution evaluator join flag must be boolean"})
                field_records = execution_display.get("field_records")
                if not isinstance(field_records, list):
                    issues.append({"code": "invalid_execution_result_fields", "message": f"record {record_index} score {score_index} execution field_records must be a list"})
                    field_records = []
                visible_fields = []
                for field_index, field_record in enumerate(field_records):
                    if not isinstance(field_record, Mapping):
                        issues.append({"code": "invalid_execution_result_field_record", "message": f"record {record_index} score {score_index} execution field {field_index} must be an object"})
                        continue
                    field_name = field_record.get("field")
                    if field_name not in _PROMPT_EXECUTION_OUTPUT_FIELDS:
                        issues.append({"code": "invalid_execution_result_field_name", "message": f"record {record_index} score {score_index} execution field name is invalid"})
                    if field_record.get("prompt_visible") is True:
                        visible_fields.append(field_name)
                        if not isinstance(field_record.get("display_text"), str):
                            issues.append({"code": "missing_execution_result_display_text", "message": f"record {record_index} score {score_index} visible execution field needs display text"})
                        if field_record.get("omission_reason") is not None:
                            issues.append({"code": "visible_execution_result_has_omission", "message": f"record {record_index} score {score_index} visible execution field must not have omission reason"})
                    elif field_record.get("prompt_visible") is False:
                        if not isinstance(field_record.get("omission_reason"), str) or not field_record.get("omission_reason"):
                            issues.append({"code": "missing_execution_result_omission", "message": f"record {record_index} score {score_index} omitted execution field needs reason"})
                    else:
                        issues.append({"code": "invalid_execution_field_prompt_visible", "message": f"record {record_index} score {score_index} execution field prompt_visible must be boolean"})
                if execution_display.get("prompt_visible_fields") != visible_fields:
                    issues.append({"code": "execution_result_visible_fields_mismatch", "message": f"record {record_index} score {score_index} visible execution fields do not match field records"})
            stage_display = score.get("stage_summary_io_display")
            if not isinstance(stage_display, Mapping):
                issues.append({"code": "invalid_stage_summary_io_display", "message": f"record {record_index} score {score_index} stage_summary_io_display must be an object"})
            else:
                if stage_display.get("schema") != "libreevolve.prompt_prior_stage_summary_io_display.v1":
                    issues.append({"code": "invalid_stage_summary_io_schema", "message": f"record {record_index} score {score_index} stage-summary IO schema is unsupported"})
                if stage_display.get("has_source_stage_io") is True:
                    stage_summary_io_count += 1
                    if stage_display.get("evaluator_result_joined") is True:
                        stage_summary_io_evaluator_join_count += 1
                elif stage_display.get("has_source_stage_io") is not False:
                    issues.append({"code": "invalid_stage_summary_io_source_flag", "message": f"record {record_index} score {score_index} stage-summary IO source flag must be boolean"})
                if stage_display.get("prompt_visible") is True:
                    prompt_visible_stage_summary_io_count += 1
                elif stage_display.get("prompt_visible") is not False:
                    issues.append({"code": "invalid_stage_summary_io_prompt_visible", "message": f"record {record_index} score {score_index} stage-summary IO prompt_visible must be boolean"})
                if stage_display.get("evaluator_result_joined") is True:
                    stage_evaluator = stage_display.get("evaluator_result")
                    if not isinstance(stage_evaluator, Mapping):
                        issues.append({"code": "invalid_stage_summary_io_evaluator_row", "message": f"record {record_index} score {score_index} stage-summary IO evaluator row must be an object"})
                    elif stage_evaluator.get("stream") != "evaluator_results.jsonl":
                        issues.append({"code": "invalid_stage_summary_io_evaluator_stream", "message": f"record {record_index} score {score_index} stage-summary IO evaluator stream is invalid"})
                elif stage_display.get("evaluator_result_joined") is not False:
                    issues.append({"code": "invalid_stage_summary_io_evaluator_join", "message": f"record {record_index} score {score_index} stage-summary IO evaluator join flag must be boolean"})
                stage_records = stage_display.get("stage_records")
                if not isinstance(stage_records, list):
                    issues.append({"code": "invalid_stage_summary_io_stage_records", "message": f"record {record_index} score {score_index} stage_records must be a list"})
                    stage_records = []
                visible_stage_count = 0
                for stage_index, stage_record in enumerate(stage_records):
                    if not isinstance(stage_record, Mapping):
                        issues.append({"code": "invalid_stage_summary_io_stage_record", "message": f"record {record_index} score {score_index} stage {stage_index} must be an object"})
                        continue
                    if stage_record.get("prompt_visible") is True:
                        visible_stage_count += 1
                        if not isinstance(stage_record.get("stage_io_display_text"), str):
                            issues.append({"code": "missing_stage_summary_io_display_text", "message": f"record {record_index} score {score_index} visible stage-summary IO needs display text"})
                        if not _is_sha256_hex(stage_record.get("stage_io_display_sha256")):
                            issues.append({"code": "invalid_stage_summary_io_display_hash", "message": f"record {record_index} score {score_index} visible stage-summary IO needs display hash"})
                        if stage_record.get("omission_reason") is not None:
                            issues.append({"code": "visible_stage_summary_io_has_omission", "message": f"record {record_index} score {score_index} visible stage-summary IO must not have omission reason"})
                    elif stage_record.get("prompt_visible") is False:
                        if not isinstance(stage_record.get("omission_reason"), str) or not stage_record.get("omission_reason"):
                            issues.append({"code": "missing_stage_summary_io_omission", "message": f"record {record_index} score {score_index} omitted stage-summary IO needs reason"})
                    else:
                        issues.append({"code": "invalid_stage_summary_io_stage_visible", "message": f"record {record_index} score {score_index} stage-summary IO prompt_visible must be boolean"})
                if isinstance(stage_display.get("visible_stage_count"), int) and not isinstance(stage_display.get("visible_stage_count"), bool):
                    if stage_display.get("visible_stage_count") != visible_stage_count:
                        issues.append({"code": "stage_summary_io_visible_count_mismatch", "message": f"record {record_index} score {score_index} visible stage count does not match stage records"})
            feedback_display = score.get("feedback_section_display")
            if not isinstance(feedback_display, Mapping):
                issues.append({"code": "invalid_feedback_section_display", "message": f"record {record_index} score {score_index} feedback_section_display must be an object"})
            else:
                feedback_section_policy_count += 1
                if feedback_display.get("schema") != "libreevolve.prompt_prior_feedback_section_display.v1":
                    issues.append({"code": "invalid_feedback_section_schema", "message": f"record {record_index} score {score_index} feedback-section schema is unsupported"})
                if feedback_display.get("global_cap_chars") == PROMPT_FEEDBACK_GLOBAL_MAX_CHARS:
                    feedback_section_global_policy_count += 1
                else:
                    issues.append({"code": "invalid_feedback_section_global_cap", "message": f"record {record_index} score {score_index} feedback global cap is invalid"})
                if feedback_display.get("global_cap_policy") != "fixed_prompt_feedback_text_chars_after_section_caps":
                    issues.append({"code": "invalid_feedback_section_global_policy", "message": f"record {record_index} score {score_index} feedback global cap policy is invalid"})
                if not isinstance(feedback_display.get("global_cap_applied"), bool):
                    issues.append({"code": "invalid_feedback_section_global_cap_applied", "message": f"record {record_index} score {score_index} feedback global cap flag must be boolean"})
                selected_sections = feedback_display.get("selected_sections")
                if not isinstance(selected_sections, list):
                    issues.append({"code": "invalid_feedback_selected_sections", "message": f"record {record_index} score {score_index} selected_sections must be a list"})
                    selected_sections = []
                section_order = feedback_display.get("section_order")
                if not isinstance(section_order, list):
                    issues.append({"code": "invalid_feedback_section_order", "message": f"record {record_index} score {score_index} section_order must be a list"})
                    section_order = []
                section_caps = feedback_display.get("section_caps")
                if not isinstance(section_caps, Mapping):
                    issues.append({"code": "invalid_feedback_section_caps", "message": f"record {record_index} score {score_index} section_caps must be an object"})
                    section_caps = {}
                section_records = feedback_display.get("section_records")
                if not isinstance(section_records, list):
                    issues.append({"code": "invalid_feedback_section_records", "message": f"record {record_index} score {score_index} section_records must be a list"})
                    section_records = []
                visible_section_count = 0
                source_section_count = 0
                seen_feedback_sections = set()
                for section_index, section_record in enumerate(section_records):
                    if not isinstance(section_record, Mapping):
                        issues.append({"code": "invalid_feedback_section_record", "message": f"record {record_index} score {score_index} feedback section {section_index} must be an object"})
                        continue
                    name = section_record.get("name")
                    if name not in PROMPT_CONTEXT_POLICY_FEEDBACK_SECTIONS:
                        issues.append({"code": "invalid_feedback_section_name", "message": f"record {record_index} score {score_index} feedback section name is unsupported"})
                    elif name in seen_feedback_sections:
                        issues.append({"code": "duplicate_feedback_section_name", "message": f"record {record_index} score {score_index} feedback section name is duplicated"})
                    else:
                        seen_feedback_sections.add(name)
                    if not isinstance(section_record.get("selected"), bool):
                        issues.append({"code": "invalid_feedback_section_selected", "message": f"record {record_index} score {score_index} feedback selected flag must be boolean"})
                    if not isinstance(section_record.get("has_source"), bool):
                        issues.append({"code": "invalid_feedback_section_has_source", "message": f"record {record_index} score {score_index} feedback has_source flag must be boolean"})
                    elif section_record.get("has_source") is True:
                        source_section_count += 1
                    if not isinstance(section_record.get("section_cap_configured"), bool):
                        issues.append({"code": "invalid_feedback_section_cap_configured", "message": f"record {record_index} score {score_index} feedback cap-configured flag must be boolean"})
                    if not isinstance(section_record.get("section_cap_applied"), bool):
                        issues.append({"code": "invalid_feedback_section_cap_applied", "message": f"record {record_index} score {score_index} feedback cap-applied flag must be boolean"})
                    if section_record.get("prompt_visible") is True:
                        visible_section_count += 1
                        if section_record.get("omission_reason") is not None:
                            issues.append({"code": "visible_feedback_section_has_omission", "message": f"record {record_index} score {score_index} visible feedback section must not have omission reason"})
                    elif section_record.get("prompt_visible") is False:
                        if not isinstance(section_record.get("omission_reason"), str) or not section_record.get("omission_reason"):
                            issues.append({"code": "missing_feedback_section_omission", "message": f"record {record_index} score {score_index} omitted feedback section needs reason"})
                    else:
                        issues.append({"code": "invalid_feedback_section_prompt_visible", "message": f"record {record_index} score {score_index} feedback prompt_visible must be boolean"})
                if feedback_display.get("visible_section_count") != visible_section_count:
                    issues.append({"code": "feedback_visible_section_count_mismatch", "message": f"record {record_index} score {score_index} visible feedback section count is invalid"})
                if feedback_display.get("source_section_count") != source_section_count:
                    issues.append({"code": "feedback_source_section_count_mismatch", "message": f"record {record_index} score {score_index} source feedback section count is invalid"})
                if feedback_display.get("prompt_visible") is True and visible_section_count == 0:
                    issues.append({"code": "feedback_visible_without_sections", "message": f"record {record_index} score {score_index} feedback display is visible without visible sections"})
                if feedback_display.get("prompt_visible") is False and feedback_display.get("omission_reason") in {None, ""}:
                    issues.append({"code": "missing_feedback_display_omission", "message": f"record {record_index} score {score_index} omitted feedback display needs reason"})
    truncated = report.get("records_truncated") is True
    _validate_prompt_prior_report_count(
        report,
        "prompt_record_count",
        len(records),
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "score_record_count",
        score_record_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "target_score_record_count",
        target_score_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "inspiration_score_record_count",
        inspiration_score_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "history_join_count",
        history_join_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "evaluator_result_join_count",
        evaluator_join_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "omitted_or_truncated_score_record_count",
        omitted_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "score_field_record_count",
        score_field_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "omitted_or_truncated_score_field_count",
        omitted_or_truncated_score_field_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "execution_result_record_count",
        execution_result_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "prompt_visible_execution_result_record_count",
        prompt_visible_execution_result_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "execution_result_evaluator_join_count",
        execution_result_evaluator_join_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "stage_summary_io_record_count",
        stage_summary_io_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "prompt_visible_stage_summary_io_record_count",
        prompt_visible_stage_summary_io_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "stage_summary_io_evaluator_join_count",
        stage_summary_io_evaluator_join_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "feedback_section_policy_record_count",
        feedback_section_policy_count,
        truncated,
        issues,
    )
    _validate_prompt_prior_report_count(
        report,
        "feedback_section_global_policy_record_count",
        feedback_section_global_policy_count,
        truncated,
        issues,
    )
    table_record_count = report.get("cross_run_prompt_score_table_record_count")
    if (
        not isinstance(table_record_count, int)
        or isinstance(table_record_count, bool)
        or table_record_count < 0
    ):
        issues.append(
            {
                "code": "invalid_cross_run_prompt_score_table_record_count",
                "message": "cross_run_prompt_score_table_record_count must be a non-negative integer",
            }
        )
    cross_run_table = report.get("cross_run_prompt_score_table")
    if not isinstance(cross_run_table, Mapping):
        issues.append(
            {
                "code": "invalid_cross_run_prompt_score_table",
                "message": "cross_run_prompt_score_table must be an object",
            }
        )
    else:
        if cross_run_table.get("schema") != "libreevolve.prompt_prior_score_table_export.v1":
            issues.append(
                {
                    "code": "invalid_cross_run_prompt_score_table_schema",
                    "message": "cross_run_prompt_score_table schema is unsupported",
                }
            )
        if (
            cross_run_table.get("record_schema")
            != PROMPT_PRIOR_SCORE_TABLE_RECORD_SCHEMA
        ):
            issues.append(
                {
                    "code": "invalid_cross_run_prompt_score_table_record_schema",
                    "message": "cross_run_prompt_score_table record schema is unsupported",
                }
            )
        if isinstance(table_record_count, int) and not isinstance(
            table_record_count, bool
        ) and cross_run_table.get("record_count") != table_record_count:
            issues.append(
                {
                    "code": "cross_run_prompt_score_table_count_mismatch",
                    "message": "cross_run_prompt_score_table record count must match report count",
                }
            )
    if not isinstance(report.get("score_policy"), Mapping):
        issues.append({"code": "invalid_score_policy", "message": "score_policy must be an object"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "prompt prior-score report must not claim full AlphaEvolve provenance"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    else:
        for field in (
            "target_scores_joined",
            "history_rows_joined",
            "evaluator_rows_joined",
            "prompt_visible_score_rows",
            "score_omission_and_truncation_policy",
            "average_score_formula_parity",
            "execution_result_text_display_attribution",
            "stage_summary_io_display_attribution",
            "feedback_section_global_truncation_policy",
            "cross_run_prompt_score_table",
        ):
            if readiness.get(field) not in {True, False}:
                issues.append({"code": f"invalid_{field}", "message": f"claim_readiness.{field} must be boolean"})
        if readiness.get("full_alphaevolve_rendered_evaluation_result_provenance") is not False:
            issues.append({"code": "rendered_evaluation_result_overclaim", "message": "full rendered-evaluation provenance must remain false"})
    return {
        "schema": "libreevolve.prompt_prior_score_provenance_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _validate_prompt_prior_report_count(
    report: Mapping[str, object],
    field: str,
    observed_retained: int,
    truncated: bool,
    issues: list[dict],
) -> None:
    value = report.get(field)
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        issues.append({"code": f"invalid_{field}", "message": f"{field} must be a non-negative integer"})
    elif truncated:
        if value < observed_retained:
            issues.append({"code": f"{field}_mismatch", "message": f"{field} must cover retained report records"})
    elif value != observed_retained:
        issues.append({"code": f"{field}_mismatch", "message": f"{field} does not match report records"})


def _evaluator_oracle_registry_report(
    db: ProgramDatabase,
    programs: list[Program],
) -> dict:
    manifest = db.startup_manifest_snapshot()
    config = manifest.get("config") if isinstance(manifest.get("config"), Mapping) else {}
    problem = manifest.get("problem") if isinstance(manifest.get("problem"), Mapping) else {}
    objective_schema = db.objective_schema_snapshot()
    eval_stages = config.get("eval_stages") if isinstance(config.get("eval_stages"), list) else []
    evaluator_sources = (
        problem.get("evaluator_sources")
        if isinstance(problem.get("evaluator_sources"), list)
        else []
    )
    llm_feedback = (
        config.get("llm_feedback")
        if isinstance(config.get("llm_feedback"), list)
        else []
    )
    oracles = _evaluator_oracle_records(
        eval_stages,
        evaluator_sources,
        llm_feedback,
        objective_schema,
    )
    report = {
        "schema": "libreevolve.evaluator_oracle_registry.v1",
        "source": "startup_manifest_and_runtime_history",
        "oracle_count": len(oracles),
        "oracles": oracles,
        "metric_ownership": _evaluator_oracle_metric_ownership(
            objective_schema,
            llm_feedback,
            "configured_evaluator_cascade" if eval_stages else "evaluator:default",
        ),
        "merge_policy": _evaluator_oracle_merge_policy(config),
        "arbitration_policy": _evaluator_oracle_arbitration_policy(oracles),
        "runtime_summary": _evaluator_oracle_runtime_summary(programs),
        "disagreement_outcomes": _evaluator_oracle_disagreement_outcomes(
            programs,
            oracles,
        ),
        "prompt_feedback_linkage": {
            "stage_feedback": "evaluation.stages_and_configured_stage_results_rendered_by_prompt_sampler",
            "llm_feedback": "evaluation.metadata.llm_feedback_and_llm_feedback_stages",
            "failure_memory": "failure_history_records_can_render_evaluator_and_stage_summaries",
        },
        "claim_ready": False,
        "claim_readiness": {
            "independent_multi_evaluator_oracle_composition": False,
            "reason": (
                "evaluator and feedback oracle identities are registered, but "
                "LibreEvolve still uses one local cascade evaluator plus "
                "post-hoc synchronous feedback graders rather than a general "
                "independent multi-oracle arbitration contract"
            ),
            "remaining_gap": [
                "independent_oracle_authority_configuration",
                "independent_cross_oracle_disagreement_outcome_evidence",
                "independent_reference_checker_or_statistical_test_oracles",
            ],
        },
    }
    report["validation"] = validate_evaluator_oracle_registry(report)
    return report


def _evaluator_oracle_records(
    eval_stages: list,
    evaluator_sources: list,
    llm_feedback: list,
    objective_schema: dict,
) -> list[dict]:
    records: list[dict] = []
    if eval_stages:
        source_by_stage = _evaluator_source_by_stage(evaluator_sources)
        for index, raw_stage in enumerate(eval_stages):
            if not isinstance(raw_stage, Mapping):
                continue
            name = str(raw_stage.get("name", f"stage_{index}"))
            mode = str(raw_stage.get("mode", "external_validator"))
            source = source_by_stage.get((index, name), {})
            records.append(
                {
                    "oracle_id": f"stage:{name}",
                    "oracle_type": (
                        "candidate_embedded_evaluator"
                        if mode == "embedded_evaluate"
                        else "deterministic_validator"
                    ),
                    "role": "configured_cascade_stage",
                    "authority": "candidate_validity_and_metric_gate",
                    "stage_name": name,
                    "stage_index": index,
                    "input_schema": (
                        "candidate_primary_module.evaluate(eval_inputs)"
                        if mode == "embedded_evaluate"
                        else "evaluate(code, workspace_path, stage)"
                    ),
                    "output_schema": "declared_metrics_plus_boolean_is_valid",
                    "metric_ownership": _evaluator_owned_metric_names(objective_schema),
                    "failure_policy": (
                        "stage_failure_or_threshold_failure_stops_candidate_cascade"
                    ),
                    "prompt_feedback_linkage": "configured_stage_results_and_stage_summaries",
                    "source": _evaluator_oracle_source_ref(source),
                }
            )
    else:
        source = _default_evaluator_source(evaluator_sources)
        records.append(
            {
                "oracle_id": "evaluator:default",
                "oracle_type": "deterministic_validator",
                "role": "default_problem_validator",
                "authority": "candidate_validity_and_metric_gate",
                "input_schema": "evaluate(code)_or_evaluate(code, workspace_path)",
                "output_schema": "declared_metrics_plus_boolean_is_valid",
                "metric_ownership": _evaluator_owned_metric_names(objective_schema),
                "failure_policy": "invalid_evaluation_blocks_database_admission",
                "prompt_feedback_linkage": "evaluation_stages_and_execution_summary",
                "source": _evaluator_oracle_source_ref(source),
            }
        )
    for index, raw_grader in enumerate(llm_feedback):
        if not isinstance(raw_grader, Mapping):
            continue
        name = str(raw_grader.get("name", f"feedback_{index}"))
        metric = raw_grader.get("metric")
        records.append(
            {
                "oracle_id": f"llm_feedback:{name}",
                "oracle_type": "llm_judge",
                "role": "post_evaluator_feedback_grader",
                "authority": (
                    "feedback_metric_and_optional_fitness_composition_not_primary_validity_gate"
                ),
                "input_schema": "candidate_workspace_plus_task_and_evaluator_feedback_prompt",
                "output_schema": "finite_score_and_optional_feedback_text",
                "metric_ownership": [metric] if isinstance(metric, str) else [],
                "failure_policy": str(raw_grader.get("failure_policy", "discard")),
                "prompt_feedback_linkage": "evaluation.metadata.llm_feedback",
                "source": {
                    "configured_feedback_index": index,
                    "metric": metric,
                    "objective_metric": raw_grader.get("objective_metric") is True,
                },
            }
        )
    return records


def _evaluator_source_by_stage(evaluator_sources: list) -> dict[tuple[int, str], Mapping[str, object]]:
    by_stage: dict[tuple[int, str], Mapping[str, object]] = {}
    for source in evaluator_sources:
        if not isinstance(source, Mapping):
            continue
        if source.get("role") != "stage":
            continue
        stage_index = source.get("stage_index")
        stage_name = source.get("stage_name")
        if (
            isinstance(stage_index, int)
            and not isinstance(stage_index, bool)
            and isinstance(stage_name, str)
        ):
            by_stage[(stage_index, stage_name)] = source
    return by_stage


def _default_evaluator_source(evaluator_sources: list) -> Mapping[str, object]:
    for source in evaluator_sources:
        if isinstance(source, Mapping) and source.get("role") == "default":
            return source
    return {}


def _evaluator_oracle_source_ref(source: Mapping[str, object]) -> dict:
    if not source:
        return {"status": "not_available"}
    return {
        "role": source.get("role"),
        "stage_name": source.get("stage_name"),
        "stage_index": source.get("stage_index"),
        "relative_path": source.get("relative_path"),
        "sha256": source.get("sha256"),
        "source_type": source.get("source_type"),
    }


def _evaluator_owned_metric_names(objective_schema: Mapping[str, object]) -> list[str]:
    metrics = objective_schema.get("metrics")
    if not isinstance(metrics, list):
        return []
    names = [
        metric.get("name")
        for metric in metrics
        if isinstance(metric, Mapping) and metric.get("source", "evaluator") == "evaluator"
    ]
    return [name for name in names if isinstance(name, str)]


def _evaluator_oracle_metric_ownership(
    objective_schema: Mapping[str, object],
    llm_feedback: list,
    evaluator_oracle_id: str,
) -> list[dict]:
    feedback_by_metric = {
        grader.get("metric"): str(grader.get("name", f"feedback_{index}"))
        for index, grader in enumerate(llm_feedback)
        if isinstance(grader, Mapping) and isinstance(grader.get("metric"), str)
    }
    ownership: list[dict] = []
    metrics = objective_schema.get("metrics")
    if not isinstance(metrics, list):
        return ownership
    for metric in metrics:
        if not isinstance(metric, Mapping) or not isinstance(metric.get("name"), str):
            continue
        name = metric["name"]
        source = str(metric.get("source", "evaluator"))
        if source == "evaluator":
            oracle_id = evaluator_oracle_id
        elif source == "feedback":
            oracle_id = f"llm_feedback:{feedback_by_metric.get(name, '<unmatched>')}"
        else:
            oracle_id = f"{source}:not_registered_evaluator_oracle"
        ownership.append(
            {
                "metric": name,
                "source": source,
                "primary": metric.get("primary") is True,
                "oracle_id": oracle_id,
                "paper_evaluator_metric": source == "evaluator",
            }
        )
    return ownership


def _evaluator_oracle_merge_policy(config: Mapping[str, object]) -> dict:
    eval_stages = config.get("eval_stages") if isinstance(config.get("eval_stages"), list) else []
    llm_feedback = config.get("llm_feedback") if isinstance(config.get("llm_feedback"), list) else []
    return {
        "schema": "libreevolve.evaluator_oracle_merge_policy.v1",
        "evaluator_policy": (
            "configured_stage_cascade_in_order"
            if eval_stages
            else "single_default_validator"
        ),
        "stage_stop_policy": "first_failed_stage_stops_candidate",
        "validity_policy": "evaluator_is_valid_and_thresholds_gate_admission",
        "llm_feedback_policy": (
            "synchronous_post_evaluator_feedback_graders"
            if llm_feedback
            else "not_configured"
        ),
        "feedback_aggregation_policy": "weighted_delta_after_evaluator_validity",
        "conflict_policy": (
            "no_general_cross_oracle_conflict_arbitration_beyond_configured_order"
        ),
    }


def _evaluator_oracle_arbitration_policy(oracles: list[dict]) -> dict:
    records = [_evaluator_oracle_arbitration_record(oracle) for oracle in oracles]
    independent_count = sum(1 for record in records if record["independent_evidence"])
    reference_count = sum(1 for record in records if record["reference_or_statistical"])
    benchmark_sufficient_count = sum(
        1 for record in records if record["benchmark_sufficiency"] == "claim_sufficient"
    )
    return {
        "schema": "libreevolve.evaluator_oracle_arbitration_policy.v1",
        "authority_matrix": records,
        "conflict_resolution": {
            "validity_owner": "deterministic_evaluator_cascade",
            "score_owner": "declared_metric_source_ownership",
            "stage_disagreement_policy": "ordered_cascade_first_failed_stage_stops_candidate",
            "feedback_disagreement_policy": (
                "post_hoc_feedback_metrics_do_not_override_evaluator_validity"
            ),
            "feedback_can_override_validity": False,
            "general_cross_oracle_vote": "not_implemented",
        },
        "failure_handling": {
            "evaluator_failure_effect": "invalid_evaluation_blocks_database_admission",
            "stage_failure_effect": "stage_failure_or_threshold_failure_stops_candidate",
            "feedback_failure_effect": "configured_ignore_penalize_or_discard_policy",
        },
        "claim_readiness": {
            "independent_evaluator_oracle_arbitration": False,
            "independent_oracle_count": independent_count,
            "reference_or_statistical_oracle_count": reference_count,
            "benchmark_sufficient_oracle_count": benchmark_sufficient_count,
            "remaining_gap": [
                "independent_reference_checker_or_statistical_test_oracles",
                "per_benchmark_oracle_sufficiency_evidence",
                "independent_cross_oracle_disagreement_outcome_records",
            ],
        },
    }


def _evaluator_oracle_arbitration_record(oracle: Mapping[str, object]) -> dict:
    oracle_id = str(oracle.get("oracle_id", "<unknown>"))
    oracle_type = str(oracle.get("oracle_type", "<unknown>"))
    role = str(oracle.get("role", "<unknown>"))
    authority = str(oracle.get("authority", "not_declared"))
    failure_policy = str(oracle.get("failure_policy", "not_declared"))
    reference_or_statistical = oracle_type in {"reference_checker", "statistical_test"}
    independent = reference_or_statistical and role.startswith("independent_")
    if reference_or_statistical:
        sufficiency = "claim_sufficient" if independent else "reference_like_not_independent"
        conflict_role = "independent_reference_or_statistical_check"
    elif oracle_type == "llm_judge":
        sufficiency = "feedback_only_not_validity_sufficient"
        conflict_role = "post_hoc_feedback_no_validity_override"
    elif role == "configured_cascade_stage":
        sufficiency = "local_stage_gate_not_independent_benchmark_sufficient"
        conflict_role = "ordered_stage_gate"
    else:
        sufficiency = "local_validator_gate_not_independent_benchmark_sufficient"
        conflict_role = "primary_local_validity_gate"
    return {
        "oracle_id": oracle_id,
        "oracle_type": oracle_type,
        "role": role,
        "authority": authority,
        "benchmark_sufficiency": sufficiency,
        "conflict_role": conflict_role,
        "failure_effect": failure_policy,
        "metric_ownership": list(oracle.get("metric_ownership", []))
        if isinstance(oracle.get("metric_ownership"), list)
        else [],
        "independent_evidence": independent,
        "reference_or_statistical": reference_or_statistical,
    }


def _evaluator_oracle_runtime_summary(programs: list[Program]) -> dict:
    evaluated_program_count = 0
    valid_count = 0
    invalid_count = 0
    configured_stage_record_count = 0
    llm_feedback_record_count = 0
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        if not evaluation:
            continue
        evaluated_program_count += 1
        if evaluation.get("is_valid") is True:
            valid_count += 1
        elif evaluation.get("is_valid") is False:
            invalid_count += 1
        metadata = evaluation.get("metadata") if isinstance(evaluation.get("metadata"), dict) else {}
        configured = metadata.get("configured_stage_results")
        if isinstance(configured, list):
            configured_stage_record_count += sum(1 for item in configured if isinstance(item, dict))
        feedback = metadata.get("llm_feedback")
        if isinstance(feedback, list):
            llm_feedback_record_count += sum(1 for item in feedback if isinstance(item, dict))
    return {
        "evaluated_program_count": evaluated_program_count,
        "valid_count": valid_count,
        "invalid_count": invalid_count,
        "configured_stage_record_count": configured_stage_record_count,
        "llm_feedback_record_count": llm_feedback_record_count,
    }


def _evaluator_oracle_disagreement_outcomes(
    programs: list[Program],
    oracles: list[dict],
) -> dict:
    feedback_oracles = {
        str(oracle.get("oracle_id"))
        for oracle in oracles
        if oracle.get("oracle_type") == "llm_judge"
    }
    records: list[dict] = []
    candidate_with_feedback_count = 0
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        metadata = (
            evaluation.get("metadata")
            if isinstance(evaluation.get("metadata"), Mapping)
            else {}
        )
        feedback_records = metadata.get("llm_feedback")
        if not isinstance(feedback_records, list) or not feedback_records:
            continue
        candidate_with_feedback_count += 1
        evaluator_valid = _evaluator_valid_before_feedback(evaluation)
        for feedback_index, feedback in enumerate(feedback_records):
            if not isinstance(feedback, Mapping):
                continue
            name = feedback.get("name")
            feedback_oracle_id = (
                f"llm_feedback:{name}"
                if isinstance(name, str) and name
                else f"llm_feedback:<record_{feedback_index}>"
            )
            if feedback_oracle_id not in feedback_oracles:
                feedback_oracle_id = f"{feedback_oracle_id}:not_registered"
            record = _evaluator_feedback_disagreement_record(
                program,
                feedback,
                feedback_index=feedback_index,
                evaluator_valid_before_feedback=evaluator_valid,
                feedback_oracle_id=feedback_oracle_id,
            )
            if record is not None:
                records.append(record)
    disagreement_count = sum(
        1 for record in records if record.get("disagreement_observed") is True
    )
    discard_after_pass_count = sum(
        1
        for record in records
        if record.get("outcome") == "feedback_discard_after_evaluator_pass"
    )
    skipped_invalid_count = sum(
        1
        for record in records
        if record.get("outcome") == "evaluator_invalid_feedback_skipped"
    )
    report = {
        "schema": "libreevolve.evaluator_oracle_disagreement_outcomes.v1",
        "source": "history_evaluation_stages_and_metadata_llm_feedback",
        "records_limit": 100,
        "records_truncated": len(records) > 100,
        "candidate_with_feedback_count": candidate_with_feedback_count,
        "outcome_count": len(records),
        "disagreement_count": disagreement_count,
        "feedback_discard_after_evaluator_pass_count": discard_after_pass_count,
        "evaluator_invalid_feedback_skipped_count": skipped_invalid_count,
        "records": records[:100],
        "policy": {
            "validity_owner": "deterministic_evaluator_cascade",
            "feedback_disagreement_policy": (
                "post_hoc_feedback_discard_can_invalidate_local_candidate_but_"
                "does_not_create_independent_reference_oracle_arbitration"
            ),
            "independent_reference_or_statistical_oracle": False,
        },
        "claim_readiness": {
            "observed_post_hoc_feedback_disagreement_outcomes": disagreement_count > 0,
            "independent_cross_oracle_disagreement_outcomes": False,
            "remaining_gap": [
                "independent_reference_checker_or_statistical_test_oracles",
                "per_benchmark_oracle_sufficiency_evidence",
                "independent_cross_oracle_disagreement_outcome_records",
            ],
        },
    }
    return report


def _evaluator_feedback_disagreement_record(
    program: Program,
    feedback: Mapping[str, object],
    *,
    feedback_index: int,
    evaluator_valid_before_feedback: bool | None,
    feedback_oracle_id: str,
) -> dict | None:
    skipped = feedback.get("skipped") is True
    discard = feedback.get("discard") is True
    error = feedback.get("error")
    final_valid = (
        program.evaluation.get("is_valid")
        if isinstance(program.evaluation, dict)
        else None
    )
    if evaluator_valid_before_feedback is True and discard:
        outcome = "feedback_discard_after_evaluator_pass"
        disagreement = True
        final_effect = (
            "post_hoc_feedback_invalidated_candidate"
            if final_valid is False
            else "feedback_discard_observed_without_final_invalidity"
        )
    elif evaluator_valid_before_feedback is False and skipped:
        outcome = "evaluator_invalid_feedback_skipped"
        disagreement = False
        final_effect = "evaluator_invalidity_preserved"
    elif evaluator_valid_before_feedback is True and not discard and error is None:
        outcome = "feedback_accept_after_evaluator_pass"
        disagreement = False
        final_effect = "evaluator_validity_preserved"
    elif error is not None:
        outcome = "feedback_error_policy_applied"
        disagreement = False
        final_effect = (
            "feedback_failure_policy_changed_validity"
            if final_valid is False and evaluator_valid_before_feedback is True
            else "feedback_failure_policy_no_validity_override"
        )
    else:
        outcome = "feedback_outcome_not_classified"
        disagreement = False
        final_effect = "no_cross_oracle_disagreement_claim"
    name = feedback.get("name")
    return {
        "program_id": program.id,
        "generation": program.generation,
        "candidate_type": (
            program.metadata.get("candidate_type")
            if isinstance(program.metadata, dict)
            else None
        ),
        "feedback_record_index": feedback_index,
        "evaluator_oracle_id": "deterministic_evaluator_cascade",
        "feedback_oracle_id": feedback_oracle_id,
        "feedback_name": name if isinstance(name, str) else None,
        "feedback_metric": (
            feedback.get("metric") if isinstance(feedback.get("metric"), str) else None
        ),
        "evaluator_valid_before_feedback": evaluator_valid_before_feedback,
        "feedback_discard": discard,
        "feedback_skipped": skipped,
        "feedback_error": str(error) if error is not None else None,
        "feedback_normalized_score": (
            float(feedback["normalized_score"])
            if isinstance(feedback.get("normalized_score"), (int, float))
            and not isinstance(feedback.get("normalized_score"), bool)
            and math.isfinite(float(feedback.get("normalized_score")))
            else None
        ),
        "feedback_min_score": (
            float(feedback["min_score"])
            if isinstance(feedback.get("min_score"), (int, float))
            and not isinstance(feedback.get("min_score"), bool)
            and math.isfinite(float(feedback.get("min_score")))
            else None
        ),
        "final_is_valid": final_valid if isinstance(final_valid, bool) else None,
        "outcome": outcome,
        "disagreement_observed": disagreement,
        "final_effect": final_effect,
        "authority_boundary": (
            "post_evaluator_feedback_not_independent_reference_or_statistical_oracle"
        ),
    }


def _evaluator_valid_before_feedback(evaluation: Mapping[str, object]) -> bool | None:
    stages = evaluation.get("stages")
    if not isinstance(stages, list):
        value = evaluation.get("is_valid")
        return value if isinstance(value, bool) else None
    candidate: bool | None = None
    for stage in stages:
        if not isinstance(stage, Mapping):
            continue
        metadata = (
            stage.get("metadata")
            if isinstance(stage.get("metadata"), Mapping)
            else {}
        )
        name = stage.get("name")
        if metadata.get("kind") == "llm_feedback" or (
            isinstance(name, str) and name.startswith("llm_feedback:")
        ):
            break
        metrics = stage.get("metrics") if isinstance(stage.get("metrics"), Mapping) else {}
        metric_valid = metrics.get("is_valid")
        if isinstance(metric_valid, bool):
            candidate = metric_valid
        elif isinstance(stage.get("passed"), bool) and name != "syntax":
            candidate = stage.get("passed")
    return candidate


def _embedded_evaluator_entrypoint_report(
    programs: list[Program],
    startup_manifest: Mapping[str, object],
) -> dict:
    records = []
    external_candidate_count = 0
    embedded_candidate_count = 0
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        metadata = (
            evaluation.get("metadata")
            if isinstance(evaluation.get("metadata"), Mapping)
            else {}
        )
        mode = metadata.get("evaluator_mode")
        if mode == "embedded_evaluate":
            embedded_candidate_count += 1
            records.append(_embedded_entrypoint_record(program, metadata))
        elif mode == "external_validator":
            external_candidate_count += 1
        configured = metadata.get("configured_stage_results")
        if isinstance(configured, list):
            for stage in configured:
                if not isinstance(stage, Mapping):
                    continue
                stage_metadata = (
                    stage.get("metadata")
                    if isinstance(stage.get("metadata"), Mapping)
                    else {}
                )
                if stage_metadata.get("evaluator_mode") == "embedded_evaluate":
                    records.append(
                        _embedded_entrypoint_record(
                            program,
                            stage_metadata,
                            stage_result=stage,
                        )
                    )
    records = _dedupe_embedded_entrypoint_records(records)
    embedded_only_problem_definition = _embedded_only_problem_definition_ready(
        startup_manifest
    )
    has_score_field_causality = any(
        _embedded_entrypoint_record_has_score_field_causality(record)
        for record in records
    )
    has_invocation_trace = any(
        _embedded_entrypoint_record_has_invocation_trace(record)
        for record in records
    )
    remaining_gap = [
        "stronger_callable_isolation_or_build_policy",
    ]
    if not has_invocation_trace:
        remaining_gap.insert(0, "skeleton_to_evolved_block_invocation_trace")
    if not has_score_field_causality:
        remaining_gap.insert(1, "score_field_to_evolved_code_path_causal_attribution")
    if not embedded_only_problem_definition:
        remaining_gap.insert(0, "load_problem_without_external_validate_py")
    report = {
        "schema": "libreevolve.embedded_evaluator_entrypoint_report.v1",
        "source": "runtime_history_evaluation_metadata",
        "embedded_candidate_count": embedded_candidate_count,
        "external_validator_candidate_count": external_candidate_count,
        "embedded_entrypoint_count": len(records),
        "records": records[:50],
        "records_limit": 50,
        "records_truncated": len(records) > 50,
        "entrypoint_contract": {
            "mode": "embedded_evaluate",
            "callable": "evaluate",
            "signature": "evaluate(eval_inputs)",
            "eval_inputs_policy": "json_safe_config_data_hashed_not_retained",
            "dependency_policy": "candidate_primary_module_embedded_evaluate_v1",
            "input_schema": "candidate_primary_module.evaluate(eval_inputs)",
            "output_schema": "declared_metrics_plus_boolean_is_valid",
        },
        "claim_ready": False,
        "claim_readiness": {
            "candidate_owned_evaluate_entrypoint": bool(records),
            "embedded_only_problem_definition": embedded_only_problem_definition,
            "evolved_block_to_score_path_mapping": any(
                _embedded_entrypoint_record_has_block_links(record)
                for record in records
            ),
            "skeleton_to_evolved_block_invocation_trace": has_invocation_trace,
            "score_field_to_evolved_code_path_causal_attribution": (
                has_score_field_causality
            ),
            "remaining_gap": remaining_gap,
        },
    }
    report["validation"] = validate_embedded_evaluator_entrypoint_report(report)
    return report


def _embedded_only_problem_definition_ready(
    startup_manifest: Mapping[str, object],
) -> bool:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    stages = config.get("eval_stages") if isinstance(config, Mapping) else None
    return (
        isinstance(stages, list)
        and bool(stages)
        and all(
            isinstance(stage, Mapping)
            and stage.get("mode") == "embedded_evaluate"
            for stage in stages
        )
    )


def _embedded_entrypoint_record(
    program: Program,
    metadata: Mapping[str, object],
    *,
    stage_result: Mapping[str, object] | None = None,
) -> dict:
    candidate = (
        metadata.get("candidate_evaluator")
        if isinstance(metadata.get("candidate_evaluator"), Mapping)
        else {}
    )
    stage = metadata.get("stage") if isinstance(metadata.get("stage"), Mapping) else {}
    dependency = (
        metadata.get("evaluator_dependency_policy")
        if isinstance(metadata.get("evaluator_dependency_policy"), Mapping)
        else {}
    )
    metric_names = _embedded_entrypoint_metric_names(
        stage_result.get("metrics")
        if isinstance(stage_result, Mapping)
        else program.metrics
    )
    record = {
        "program_id": program.id,
        "generation": program.generation,
        "stage_name": stage.get("name") or (
            stage_result.get("name") if isinstance(stage_result, Mapping) else None
        ),
        "stage_index": stage.get("stage_index"),
        "evaluator_mode": "embedded_evaluate",
        "entrypoint": candidate.get("entrypoint"),
        "callable": candidate.get("callable"),
        "signature": candidate.get("signature"),
        "eval_inputs": copy.deepcopy(candidate.get("eval_inputs"))
        if isinstance(candidate.get("eval_inputs"), Mapping)
        else {},
        "dependency_policy": {
            key: dependency.get(key)
            for key in (
                "policy",
                "allowed_scope",
                "problem_local_dependency_policy",
                "outside_problem_policy",
            )
            if key in dependency
        },
        "passed": stage_result.get("passed")
        if isinstance(stage_result, Mapping)
        else program.evaluation.get("is_valid"),
        "score": _paper_metric_table_number(
            stage_result.get("score") if isinstance(stage_result, Mapping) else program.fitness
        ),
        "metric_names": metric_names,
        "score_field_links": _embedded_score_field_links(program, metric_names),
        "invocation_traces": _embedded_invocation_traces(program),
        "validator_boundary": "temporary_local_subprocess",
        "raw_eval_inputs_retained": (
            candidate.get("eval_inputs", {}).get("retained")
            if isinstance(candidate.get("eval_inputs"), Mapping)
            else None
        ),
    }
    return {key: value for key, value in record.items() if value is not None}


def _embedded_entrypoint_record_has_block_links(record: Mapping[str, object]) -> bool:
    links = record.get("score_field_links")
    if not isinstance(links, list):
        return False
    for link in links:
        if not isinstance(link, Mapping):
            continue
        blocks = link.get("evolved_block_candidates")
        if isinstance(blocks, list) and blocks:
            return True
    return False


def _embedded_entrypoint_record_has_score_field_causality(
    record: Mapping[str, object],
) -> bool:
    links = record.get("score_field_links")
    if not isinstance(links, list):
        return False
    return any(
        isinstance(link, Mapping)
        and link.get("causal_attribution_claimed") is True
        for link in links
    )


def _embedded_entrypoint_record_has_invocation_trace(
    record: Mapping[str, object],
) -> bool:
    traces = record.get("invocation_traces")
    if not isinstance(traces, list):
        return False
    for trace in traces:
        if (
            isinstance(trace, Mapping)
            and isinstance(trace.get("evolved_block_dependencies"), list)
            and bool(trace.get("evolved_block_dependencies"))
        ):
            return True
    return False


def _embedded_score_field_links(
    program: Program,
    metric_names: list[str],
) -> list[dict]:
    if not metric_names:
        return []
    workspace = program.workspace()
    block_candidates = _embedded_workspace_block_candidates(workspace)
    primary_file = workspace.primary_file
    primary_file_sha256 = hashlib.sha256(
        workspace.files[primary_file].encode("utf-8")
    ).hexdigest()
    causal_attributions = _embedded_score_field_causal_attributions(
        workspace,
        metric_names,
        block_candidates,
    )
    links = []
    for metric_name in metric_names:
        causal_attribution = causal_attributions.get(metric_name)
        link = {
            "metric_name": metric_name,
            "link_policy": (
                "static_ast_evaluate_return_dependency_to_evolved_block"
                if isinstance(causal_attribution, Mapping)
                else "candidate_path_candidates_not_causal_attribution"
            ),
            "candidate_primary_file": primary_file,
            "candidate_primary_file_sha256": primary_file_sha256,
            "candidate_path_scope": "materialized_candidate_workspace",
            "evolved_block_candidates": copy.deepcopy(block_candidates),
            "evolved_block_candidate_count": len(block_candidates),
            "causal_attribution_claimed": isinstance(causal_attribution, Mapping),
        }
        if isinstance(causal_attribution, Mapping):
            link["causal_attribution"] = copy.deepcopy(causal_attribution)
        links.append(link)
    return links


def _embedded_invocation_traces(program: Program) -> list[dict]:
    workspace = program.workspace()
    primary_file = workspace.primary_file
    content = workspace.files.get(primary_file)
    if not isinstance(content, str):
        return []
    block_candidates = [
        block
        for block in _embedded_workspace_block_candidates(workspace)
        if block.get("path") == primary_file
    ]
    if not block_candidates:
        return []
    try:
        tree = ast.parse(content)
    except SyntaxError:
        return []
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
    }
    evaluate = functions.get("evaluate")
    if evaluate is None:
        return []
    function_blocks = {
        name: _embedded_blocks_inside_function(node, block_candidates)
        for name, node in functions.items()
    }
    reachable = _embedded_reachable_functions_from_evaluate(evaluate, functions)
    called_functions = []
    block_dependencies: dict[str, dict] = {}
    for name in sorted(reachable, key=lambda item: (reachable[item], item)):
        node = functions[name]
        blocks = function_blocks.get(name, [])
        for block in blocks:
            block_dependencies[block["span_id"]] = block
        called_functions.append(
            {
                "name": name,
                "depth": reachable[name],
                "start_line": int(getattr(node, "lineno", 0)),
                "end_line": int(getattr(node, "end_lineno", getattr(node, "lineno", 0))),
                "evolved_block_dependencies": copy.deepcopy(blocks),
                "evolved_block_dependency_count": len(blocks),
            }
        )
    if not block_dependencies:
        return []
    dependencies = [
        copy.deepcopy(block_dependencies[key])
        for key in sorted(block_dependencies)
    ]
    return [
        {
            "schema": "libreevolve.embedded_evaluator_invocation_trace.v1",
            "method": "static_ast_evaluate_call_graph_to_evolved_blocks",
            "trace_policy": "candidate_primary_file_direct_name_calls_only",
            "candidate_primary_file": primary_file,
            "candidate_primary_file_sha256": hashlib.sha256(
                content.encode("utf-8")
            ).hexdigest(),
            "evaluate_function": {
                "name": "evaluate",
                "start_line": int(getattr(evaluate, "lineno", 0)),
                "end_line": int(getattr(evaluate, "end_lineno", 0)),
            },
            "called_functions": called_functions[:50],
            "called_function_count": len(called_functions),
            "called_functions_truncated": len(called_functions) > 50,
            "evolved_block_dependencies": dependencies[:50],
            "evolved_block_dependency_count": len(dependencies),
            "evolved_block_dependencies_truncated": len(dependencies) > 50,
            "confidence": "static_local_candidate_source_trace",
        }
    ]


def _embedded_reachable_functions_from_evaluate(
    evaluate: ast.FunctionDef,
    functions: Mapping[str, ast.FunctionDef],
) -> dict[str, int]:
    reachable: dict[str, int] = {}
    pending = [
        (name, 1)
        for name in _embedded_called_function_names(evaluate)
        if name in functions and name != "evaluate"
    ]
    while pending:
        name, depth = pending.pop(0)
        previous_depth = reachable.get(name)
        if previous_depth is not None and previous_depth <= depth:
            continue
        reachable[name] = depth
        for called in _embedded_called_function_names(functions[name]):
            if called in functions and called != "evaluate":
                pending.append((called, depth + 1))
    return reachable


def _embedded_score_field_causal_attributions(
    workspace: CandidateWorkspace,
    metric_names: list[str],
    block_candidates: list[dict],
) -> dict[str, dict]:
    primary_file = workspace.primary_file
    content = workspace.files.get(primary_file)
    if not isinstance(content, str) or not metric_names or not block_candidates:
        return {}
    try:
        tree = ast.parse(content)
    except SyntaxError:
        return {}
    functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
    }
    evaluate = functions.get("evaluate")
    if evaluate is None:
        return {}
    function_blocks = {
        name: _embedded_blocks_inside_function(node, block_candidates)
        for name, node in functions.items()
    }
    attributions: dict[str, dict] = {}
    metric_set = set(metric_names)
    for node in ast.walk(evaluate):
        if not isinstance(node, ast.Return) or not isinstance(node.value, ast.Dict):
            continue
        for key, value in zip(node.value.keys, node.value.values):
            if not isinstance(key, ast.Constant) or not isinstance(key.value, str):
                continue
            metric_name = key.value
            if metric_name not in metric_set or metric_name in attributions:
                continue
            dependency = _embedded_metric_dependency_trace(
                value,
                functions,
                function_blocks,
                block_candidates,
            )
            if not dependency["evolved_block_dependencies"]:
                continue
            expression = ast.unparse(value)
            attributions[metric_name] = {
                "schema": "libreevolve.score_field_causal_attribution.v1",
                "method": "static_ast_evaluate_return_metric_dependency_trace",
                "metric_name": metric_name,
                "candidate_primary_file": primary_file,
                "evaluate_function": {
                    "name": "evaluate",
                    "start_line": int(getattr(evaluate, "lineno", 0)),
                    "end_line": int(getattr(evaluate, "end_lineno", 0)),
                },
                "metric_return": {
                    "line": int(getattr(value, "lineno", getattr(node, "lineno", 0))),
                    "expression_sha256": hashlib.sha256(
                        expression.encode("utf-8")
                    ).hexdigest(),
                },
                "dependency_policy": "local_ast_function_calls_to_evolve_blocks_only",
                "dependency_functions": sorted(dependency["dependency_functions"]),
                "evolved_block_dependencies": copy.deepcopy(
                    dependency["evolved_block_dependencies"]
                ),
                "evolved_block_dependency_count": len(
                    dependency["evolved_block_dependencies"]
                ),
                "confidence": "static_local_candidate_source_trace",
            }
    return attributions


def _embedded_blocks_inside_function(
    function: ast.FunctionDef,
    block_candidates: list[dict],
) -> list[dict]:
    start_line = int(getattr(function, "lineno", 0))
    end_line = int(getattr(function, "end_lineno", start_line))
    return [
        block
        for block in block_candidates
        if isinstance(block.get("content_start_line"), int)
        and isinstance(block.get("content_end_line"), int)
        and start_line <= block["content_start_line"] <= end_line
        and start_line <= block["content_end_line"] <= end_line
    ]


def _embedded_metric_dependency_trace(
    expression: ast.AST,
    functions: Mapping[str, ast.FunctionDef],
    function_blocks: Mapping[str, list[dict]],
    block_candidates: list[dict],
) -> dict:
    dependency_functions: set[str] = set()
    block_dependencies: dict[str, dict] = {}
    for block in _embedded_blocks_covering_node(expression, block_candidates):
        block_dependencies[block["span_id"]] = block
    pending = [
        name
        for name in _embedded_called_function_names(expression)
        if name in functions
    ]
    while pending:
        name = pending.pop()
        if name in dependency_functions:
            continue
        dependency_functions.add(name)
        for block in function_blocks.get(name, []):
            block_dependencies[block["span_id"]] = block
        for called in _embedded_called_function_names(functions[name]):
            if called in functions and called not in dependency_functions:
                pending.append(called)
    return {
        "dependency_functions": dependency_functions,
        "evolved_block_dependencies": [
            copy.deepcopy(block_dependencies[key])
            for key in sorted(block_dependencies)
        ],
    }


def _embedded_called_function_names(node: ast.AST) -> list[str]:
    names: list[str] = []
    for child in ast.walk(node):
        if isinstance(child, ast.Call) and isinstance(child.func, ast.Name):
            names.append(child.func.id)
    return names


def _embedded_blocks_covering_node(
    node: ast.AST,
    block_candidates: list[dict],
) -> list[dict]:
    line = getattr(node, "lineno", None)
    if not isinstance(line, int):
        return []
    return [
        block
        for block in block_candidates
        if isinstance(block.get("content_start_line"), int)
        and isinstance(block.get("content_end_line"), int)
        and block["content_start_line"] <= line <= block["content_end_line"]
    ]


def _embedded_workspace_block_candidates(workspace: CandidateWorkspace) -> list[dict]:
    records: list[dict] = []
    for path, content in sorted(workspace.files.items()):
        if not path.endswith(".py"):
            continue
        marker_error = validate_evolve_blocks(content)
        if marker_error is not None:
            continue
        for index, block in enumerate(extract_evolve_blocks(content)):
            records.append(_embedded_block_candidate_record(path, content, block, index))
    return records[:50]


def _embedded_block_candidate_record(
    path: str,
    content: str,
    block: object,
    index: int,
) -> dict:
    name = getattr(block, "name", "") or f"block_{index}"
    span_key = f"{path}:{name}:{index}:{getattr(block, 'start', 0)}:{getattr(block, 'end', 0)}"
    block_content = getattr(block, "content", "")
    return {
        "path": path,
        "span_id": hashlib.sha256(span_key.encode("utf-8")).hexdigest()[:24],
        "name": name,
        "index": index,
        "content_start_line": _line_number_for_offset(
            content,
            getattr(block, "content_start", 0),
        ),
        "content_end_line": _line_number_for_offset(
            content,
            getattr(block, "content_end", 0),
        ),
        "content_sha256": hashlib.sha256(block_content.encode("utf-8")).hexdigest(),
    }


def _embedded_entrypoint_metric_names(metrics: object) -> list[str]:
    if not isinstance(metrics, Mapping):
        return []
    return sorted(
        name
        for name, value in metrics.items()
        if isinstance(name, str)
        and name != "is_valid"
        and isinstance(value, (int, float))
        and not isinstance(value, bool)
    )


def _dedupe_embedded_entrypoint_records(records: list[dict]) -> list[dict]:
    deduped = []
    seen = set()
    for record in records:
        key = (
            record.get("program_id"),
            record.get("stage_name"),
            record.get("stage_index"),
            record.get("entrypoint"),
            record.get("signature"),
        )
        if key in seen:
            continue
        seen.add(key)
        deduped.append(record)
    deduped.sort(
        key=lambda item: (
            int(item.get("generation", 0))
            if isinstance(item.get("generation"), int)
            and not isinstance(item.get("generation"), bool)
            else 0,
            str(item.get("program_id", "")),
            str(item.get("stage_name", "")),
        )
    )
    return deduped


def validate_embedded_evaluator_entrypoint_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.embedded_evaluator_entrypoint_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "embedded evaluator entrypoint report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "embedded_candidate_count",
        "external_validator_candidate_count",
        "embedded_entrypoint_count",
        "records",
        "records_limit",
        "records_truncated",
        "entrypoint_contract",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"embedded evaluator entrypoint report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.embedded_evaluator_entrypoint_report.v1":
        issues.append({"code": "invalid_schema", "message": "embedded evaluator entrypoint report schema is unsupported"})
    if report.get("source") != "runtime_history_evaluation_metadata":
        issues.append({"code": "invalid_source", "message": "embedded evaluator entrypoint report source is unsupported"})
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append({"code": "invalid_record", "message": f"record {index} must be an object"})
            continue
        if not isinstance(record.get("program_id"), str) or not record.get("program_id"):
            issues.append({"code": "invalid_program_id", "message": f"record {index} program_id is invalid"})
        if record.get("evaluator_mode") != "embedded_evaluate":
            issues.append({"code": "invalid_evaluator_mode", "message": f"record {index} evaluator_mode must be embedded_evaluate"})
        if record.get("callable") != "evaluate":
            issues.append({"code": "invalid_callable", "message": f"record {index} callable must be evaluate"})
        if record.get("signature") != "evaluate(eval_inputs)":
            issues.append({"code": "invalid_signature", "message": f"record {index} signature must be evaluate(eval_inputs)"})
        eval_inputs = record.get("eval_inputs")
        if not isinstance(eval_inputs, dict) or eval_inputs.get("schema") != "libreevolve.eval_inputs_provenance.v1":
            issues.append({"code": "invalid_eval_inputs", "message": f"record {index} eval_inputs provenance is invalid"})
        elif eval_inputs.get("retained") is not False:
            issues.append({"code": "eval_inputs_retention_overclaim", "message": f"record {index} eval inputs must remain hashed/not retained"})
        dependency = record.get("dependency_policy")
        if not isinstance(dependency, dict) or dependency.get("policy") != "candidate_primary_module_embedded_evaluate_v1":
            issues.append({"code": "invalid_dependency_policy", "message": f"record {index} dependency policy is invalid"})
        if not isinstance(record.get("metric_names"), list):
            issues.append({"code": "invalid_metric_names", "message": f"record {index} metric_names must be a list"})
        _validate_embedded_score_field_links(record, index, issues)
        _validate_embedded_invocation_traces(record, index, issues)
    if report.get("records_truncated") is not True:
        if report.get("embedded_entrypoint_count") != len(records):
            issues.append({"code": "invalid_entrypoint_count", "message": "embedded_entrypoint_count must match records when not truncated"})
    for field in ("embedded_candidate_count", "external_validator_candidate_count"):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append({"code": f"invalid_{field}", "message": f"{field} must be a non-negative integer"})
    contract = report.get("entrypoint_contract")
    if not isinstance(contract, dict) or contract.get("signature") != "evaluate(eval_inputs)":
        issues.append({"code": "invalid_entrypoint_contract", "message": "entrypoint contract must describe evaluate(eval_inputs)"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "embedded evaluator report must not claim full Figure 3 parity"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    elif not isinstance(readiness.get("embedded_only_problem_definition"), bool):
        issues.append({"code": "invalid_embedded_only_problem_definition", "message": "embedded-only problem definition readiness must be boolean"})
    elif readiness.get("skeleton_to_evolved_block_invocation_trace") not in {True, False}:
        issues.append({"code": "invalid_invocation_trace_readiness", "message": "invocation-trace readiness must be boolean"})
    elif readiness.get("score_field_to_evolved_code_path_causal_attribution") not in {True, False}:
        issues.append({"code": "invalid_score_field_causal_readiness", "message": "score-field causal readiness must be boolean"})
    return {
        "schema": "libreevolve.embedded_evaluator_entrypoint_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _validate_embedded_score_field_links(
    record: Mapping[str, object],
    index: int,
    issues: list[dict],
) -> None:
    metric_names = record.get("metric_names")
    links = record.get("score_field_links")
    if not isinstance(metric_names, list) or not all(
        isinstance(item, str) for item in metric_names
    ):
        metric_names = []
    if not isinstance(links, list):
        issues.append({"code": "invalid_score_field_links", "message": f"record {index} score_field_links must be a list"})
        return
    linked_names: list[str] = []
    for link in links:
        if not isinstance(link, Mapping):
            issues.append({"code": "invalid_score_field_link", "message": f"record {index} score_field_links entries must be objects"})
            continue
        metric_name = link.get("metric_name")
        if not isinstance(metric_name, str):
            issues.append({"code": "invalid_score_field_metric", "message": f"record {index} score field link metric_name is invalid"})
        else:
            linked_names.append(metric_name)
        if link.get("link_policy") != "candidate_path_candidates_not_causal_attribution":
            if link.get("link_policy") != "static_ast_evaluate_return_dependency_to_evolved_block":
                issues.append({"code": "invalid_score_field_link_policy", "message": f"record {index} score field link policy is invalid"})
        if link.get("causal_attribution_claimed") is True:
            _validate_score_field_causal_attribution(link, issues, f"record {index}")
        elif link.get("causal_attribution_claimed") is not False:
            issues.append({"code": "invalid_score_field_causality_flag", "message": f"record {index} score field causal_attribution_claimed must be boolean"})
        elif link.get("causal_attribution") is not None:
            issues.append({"code": "score_field_causality_overclaim", "message": f"record {index} non-causal score field links must not carry attribution evidence"})
        if not isinstance(link.get("candidate_primary_file"), str):
            issues.append({"code": "invalid_score_field_primary_file", "message": f"record {index} score field link primary file is invalid"})
        if not _is_sha256_hex(link.get("candidate_primary_file_sha256")):
            issues.append({"code": "invalid_score_field_primary_hash", "message": f"record {index} score field link primary file hash is invalid"})
        blocks = link.get("evolved_block_candidates")
        if not isinstance(blocks, list):
            issues.append({"code": "invalid_score_field_blocks", "message": f"record {index} score field evolved_block_candidates must be a list"})
            blocks = []
        if link.get("evolved_block_candidate_count") != len(blocks):
            issues.append({"code": "invalid_score_field_block_count", "message": f"record {index} score field block count must match candidates"})
        for block in blocks:
            if not isinstance(block, Mapping):
                issues.append({"code": "invalid_score_field_block", "message": f"record {index} score field block candidates must be objects"})
                continue
            if not isinstance(block.get("path"), str):
                issues.append({"code": "invalid_score_field_block_path", "message": f"record {index} score field block path is invalid"})
            if not isinstance(block.get("span_id"), str) or len(block.get("span_id", "")) != 24:
                issues.append({"code": "invalid_score_field_block_span", "message": f"record {index} score field block span_id is invalid"})
            if not _is_sha256_hex(block.get("content_sha256")):
                issues.append({"code": "invalid_score_field_block_hash", "message": f"record {index} score field block content hash is invalid"})
    if sorted(linked_names) != sorted(metric_names):
        issues.append({"code": "score_field_link_metric_mismatch", "message": f"record {index} score field links must cover metric_names"})


def _validate_embedded_invocation_traces(
    record: Mapping[str, object],
    index: int,
    issues: list[dict],
) -> None:
    traces = record.get("invocation_traces")
    if not isinstance(traces, list):
        issues.append({"code": "invalid_invocation_traces", "message": f"record {index} invocation_traces must be a list"})
        return
    for trace in traces:
        if not isinstance(trace, Mapping):
            issues.append({"code": "invalid_invocation_trace", "message": f"record {index} invocation trace entries must be objects"})
            continue
        if trace.get("schema") != "libreevolve.embedded_evaluator_invocation_trace.v1":
            issues.append({"code": "invalid_invocation_trace_schema", "message": f"record {index} invocation trace schema is invalid"})
        if trace.get("method") != "static_ast_evaluate_call_graph_to_evolved_blocks":
            issues.append({"code": "invalid_invocation_trace_method", "message": f"record {index} invocation trace method is invalid"})
        if trace.get("trace_policy") != "candidate_primary_file_direct_name_calls_only":
            issues.append({"code": "invalid_invocation_trace_policy", "message": f"record {index} invocation trace policy is invalid"})
        if not isinstance(trace.get("candidate_primary_file"), str) or not trace.get("candidate_primary_file"):
            issues.append({"code": "invalid_invocation_trace_primary_file", "message": f"record {index} invocation trace primary file is invalid"})
        if not _is_sha256_hex(trace.get("candidate_primary_file_sha256")):
            issues.append({"code": "invalid_invocation_trace_primary_hash", "message": f"record {index} invocation trace primary file hash is invalid"})
        evaluate = trace.get("evaluate_function")
        if not isinstance(evaluate, Mapping) or evaluate.get("name") != "evaluate":
            issues.append({"code": "invalid_invocation_trace_evaluate", "message": f"record {index} invocation trace evaluate function is invalid"})
        else:
            for field in ("start_line", "end_line"):
                if not isinstance(evaluate.get(field), int) or isinstance(evaluate.get(field), bool) or evaluate.get(field) <= 0:
                    issues.append({"code": "invalid_invocation_trace_evaluate_line", "message": f"record {index} invocation trace evaluate line is invalid"})
        called = trace.get("called_functions")
        if not isinstance(called, list):
            issues.append({"code": "invalid_invocation_trace_functions", "message": f"record {index} invocation trace called_functions must be a list"})
            called = []
        if not isinstance(trace.get("called_function_count"), int) or isinstance(trace.get("called_function_count"), bool) or trace.get("called_function_count") < len(called):
            issues.append({"code": "invalid_invocation_trace_function_count", "message": f"record {index} invocation trace called_function_count is invalid"})
        if trace.get("called_functions_truncated") not in {True, False}:
            issues.append({"code": "invalid_invocation_trace_functions_truncated", "message": f"record {index} invocation trace called_functions_truncated must be boolean"})
        dependency_span_ids = set()
        for function in called:
            if not isinstance(function, Mapping):
                issues.append({"code": "invalid_invocation_trace_function", "message": f"record {index} invocation trace functions must be objects"})
                continue
            if not isinstance(function.get("name"), str) or not function.get("name"):
                issues.append({"code": "invalid_invocation_trace_function_name", "message": f"record {index} invocation trace function name is invalid"})
            if not isinstance(function.get("depth"), int) or isinstance(function.get("depth"), bool) or function.get("depth") <= 0:
                issues.append({"code": "invalid_invocation_trace_function_depth", "message": f"record {index} invocation trace function depth is invalid"})
            for field in ("start_line", "end_line"):
                if not isinstance(function.get(field), int) or isinstance(function.get(field), bool) or function.get(field) <= 0:
                    issues.append({"code": "invalid_invocation_trace_function_line", "message": f"record {index} invocation trace function line is invalid"})
            blocks = function.get("evolved_block_dependencies")
            if not isinstance(blocks, list):
                issues.append({"code": "invalid_invocation_trace_function_blocks", "message": f"record {index} invocation trace function blocks must be a list"})
                blocks = []
            if function.get("evolved_block_dependency_count") != len(blocks):
                issues.append({"code": "invocation_trace_function_block_count_mismatch", "message": f"record {index} invocation trace function block count must match blocks"})
            for block in blocks:
                if isinstance(block, Mapping) and isinstance(block.get("span_id"), str):
                    dependency_span_ids.add(block.get("span_id"))
        dependencies = trace.get("evolved_block_dependencies")
        if not isinstance(dependencies, list) or not dependencies:
            issues.append({"code": "invalid_invocation_trace_dependencies", "message": f"record {index} invocation trace dependencies must be non-empty"})
            dependencies = []
        if not isinstance(trace.get("evolved_block_dependency_count"), int) or isinstance(trace.get("evolved_block_dependency_count"), bool) or trace.get("evolved_block_dependency_count") < len(dependencies):
            issues.append({"code": "invalid_invocation_trace_dependency_count", "message": f"record {index} invocation trace dependency count is invalid"})
        if trace.get("evolved_block_dependencies_truncated") not in {True, False}:
            issues.append({"code": "invalid_invocation_trace_dependencies_truncated", "message": f"record {index} invocation trace dependencies_truncated must be boolean"})
        for dependency in dependencies:
            if not isinstance(dependency, Mapping):
                issues.append({"code": "invalid_invocation_trace_dependency", "message": f"record {index} invocation trace dependencies must be objects"})
                continue
            if not isinstance(dependency.get("span_id"), str) or len(dependency.get("span_id", "")) != 24:
                issues.append({"code": "invalid_invocation_trace_dependency_span", "message": f"record {index} invocation trace dependency span_id is invalid"})
            elif dependency_span_ids and dependency.get("span_id") not in dependency_span_ids:
                issues.append({"code": "invocation_trace_dependency_not_called_function", "message": f"record {index} invocation trace dependency must be linked from a called function"})
            if not isinstance(dependency.get("path"), str) or not dependency.get("path"):
                issues.append({"code": "invalid_invocation_trace_dependency_path", "message": f"record {index} invocation trace dependency path is invalid"})
            if not _is_sha256_hex(dependency.get("content_sha256")):
                issues.append({"code": "invalid_invocation_trace_dependency_hash", "message": f"record {index} invocation trace dependency hash is invalid"})


def _validate_score_field_causal_attribution(
    link: Mapping[str, object],
    issues: list[dict],
    context: str,
) -> None:
    if link.get("link_policy") != "static_ast_evaluate_return_dependency_to_evolved_block":
        issues.append({"code": "invalid_score_field_causal_policy", "message": f"{context} causal score field link policy is invalid"})
    attribution = link.get("causal_attribution")
    if not isinstance(attribution, Mapping):
        issues.append({"code": "invalid_score_field_causal_attribution", "message": f"{context} causal score field attribution must be an object"})
        return
    if attribution.get("schema") != "libreevolve.score_field_causal_attribution.v1":
        issues.append({"code": "invalid_score_field_causal_schema", "message": f"{context} causal score field schema is invalid"})
    if attribution.get("method") != "static_ast_evaluate_return_metric_dependency_trace":
        issues.append({"code": "invalid_score_field_causal_method", "message": f"{context} causal score field method is invalid"})
    if attribution.get("metric_name") != link.get("metric_name"):
        issues.append({"code": "score_field_causal_metric_mismatch", "message": f"{context} causal score field metric must match link metric"})
    if attribution.get("candidate_primary_file") != link.get("candidate_primary_file"):
        issues.append({"code": "score_field_causal_file_mismatch", "message": f"{context} causal score field file must match link file"})
    evaluate = attribution.get("evaluate_function")
    if not isinstance(evaluate, Mapping) or evaluate.get("name") != "evaluate":
        issues.append({"code": "invalid_score_field_causal_evaluate", "message": f"{context} causal score field evaluate function is invalid"})
    else:
        for field in ("start_line", "end_line"):
            if not isinstance(evaluate.get(field), int) or isinstance(evaluate.get(field), bool) or evaluate.get(field) <= 0:
                issues.append({"code": "invalid_score_field_causal_evaluate_line", "message": f"{context} causal score field evaluate line is invalid"})
    metric_return = attribution.get("metric_return")
    if not isinstance(metric_return, Mapping):
        issues.append({"code": "invalid_score_field_causal_return", "message": f"{context} causal score field return evidence is invalid"})
    else:
        if not isinstance(metric_return.get("line"), int) or isinstance(metric_return.get("line"), bool) or metric_return.get("line") <= 0:
            issues.append({"code": "invalid_score_field_causal_return_line", "message": f"{context} causal score field return line is invalid"})
        if not _is_sha256_hex(metric_return.get("expression_sha256")):
            issues.append({"code": "invalid_score_field_causal_return_hash", "message": f"{context} causal score field return hash is invalid"})
    if attribution.get("dependency_policy") != "local_ast_function_calls_to_evolve_blocks_only":
        issues.append({"code": "invalid_score_field_causal_dependency_policy", "message": f"{context} causal score field dependency policy is invalid"})
    if not isinstance(attribution.get("dependency_functions"), list) or not all(
        isinstance(item, str) and item for item in attribution.get("dependency_functions", [])
    ):
        issues.append({"code": "invalid_score_field_causal_dependency_functions", "message": f"{context} causal score field dependency functions are invalid"})
    dependencies = attribution.get("evolved_block_dependencies")
    if not isinstance(dependencies, list) or not dependencies:
        issues.append({"code": "invalid_score_field_causal_dependencies", "message": f"{context} causal score field dependencies must be non-empty"})
        dependencies = []
    if attribution.get("evolved_block_dependency_count") != len(dependencies):
        issues.append({"code": "score_field_causal_dependency_count_mismatch", "message": f"{context} causal score field dependency count must match dependencies"})
    candidate_span_ids = {
        block.get("span_id")
        for block in link.get("evolved_block_candidates", [])
        if isinstance(block, Mapping)
    }
    for dependency in dependencies:
        if not isinstance(dependency, Mapping):
            issues.append({"code": "invalid_score_field_causal_dependency", "message": f"{context} causal score field dependency must be an object"})
            continue
        if dependency.get("span_id") not in candidate_span_ids:
            issues.append({"code": "score_field_causal_dependency_not_candidate", "message": f"{context} causal dependency must reference a candidate evolved block"})
        if not isinstance(dependency.get("path"), str) or not dependency.get("path"):
            issues.append({"code": "invalid_score_field_causal_dependency_path", "message": f"{context} causal dependency path is invalid"})
        if not _is_sha256_hex(dependency.get("content_sha256")):
            issues.append({"code": "invalid_score_field_causal_dependency_hash", "message": f"{context} causal dependency hash is invalid"})


def validate_evaluator_oracle_registry(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.evaluator_oracle_registry.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "oracle registry must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "oracle_count",
        "oracles",
        "metric_ownership",
        "merge_policy",
        "arbitration_policy",
        "runtime_summary",
        "disagreement_outcomes",
        "prompt_feedback_linkage",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"oracle registry missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.evaluator_oracle_registry.v1":
        issues.append({"code": "invalid_schema", "message": "oracle registry schema is unsupported"})
    if report.get("source") != "startup_manifest_and_runtime_history":
        issues.append({"code": "invalid_source", "message": "oracle registry source is unsupported"})
    oracles = report.get("oracles")
    if not isinstance(oracles, list):
        issues.append({"code": "invalid_oracles", "message": "oracles must be a list"})
        oracles = []
    allowed_types = {
        "deterministic_validator",
        "candidate_embedded_evaluator",
        "statistical_test",
        "reference_checker",
        "llm_judge",
    }
    seen_ids: set[str] = set()
    for index, oracle in enumerate(oracles):
        if not isinstance(oracle, dict):
            issues.append({"code": "invalid_oracle", "message": f"oracle {index} must be an object"})
            continue
        oracle_id = oracle.get("oracle_id")
        if not isinstance(oracle_id, str) or not oracle_id:
            issues.append({"code": "invalid_oracle_id", "message": f"oracle {index} id is invalid"})
        elif oracle_id in seen_ids:
            issues.append({"code": "duplicate_oracle_id", "message": f"oracle id {oracle_id!r} is duplicated"})
        else:
            seen_ids.add(oracle_id)
        if oracle.get("oracle_type") not in allowed_types:
            issues.append({"code": "invalid_oracle_type", "message": f"oracle {index} type is invalid"})
        for field in ("role", "authority", "input_schema", "output_schema", "failure_policy", "prompt_feedback_linkage"):
            if not isinstance(oracle.get(field), str) or not oracle.get(field):
                issues.append({"code": "invalid_oracle_field", "message": f"oracle {index} {field} must be a non-empty string"})
        if not isinstance(oracle.get("metric_ownership"), list):
            issues.append({"code": "invalid_oracle_metric_ownership", "message": f"oracle {index} metric ownership must be a list"})
    if report.get("oracle_count") != len(oracles):
        issues.append({"code": "invalid_oracle_count", "message": "oracle_count must match oracles length"})
    ownership = report.get("metric_ownership")
    if not isinstance(ownership, list):
        issues.append({"code": "invalid_metric_ownership", "message": "metric_ownership must be a list"})
    else:
        for index, item in enumerate(ownership):
            if not isinstance(item, dict) or not isinstance(item.get("metric"), str):
                issues.append({"code": "invalid_metric_owner", "message": f"metric ownership {index} is invalid"})
            elif not isinstance(item.get("oracle_id"), str) or not item.get("oracle_id"):
                issues.append({"code": "invalid_metric_owner_oracle", "message": f"metric ownership {index} oracle_id is invalid"})
    merge_policy = report.get("merge_policy")
    if not isinstance(merge_policy, dict) or merge_policy.get("schema") != "libreevolve.evaluator_oracle_merge_policy.v1":
        issues.append({"code": "invalid_merge_policy", "message": "merge_policy is invalid"})
    arbitration_policy = report.get("arbitration_policy")
    if not isinstance(arbitration_policy, dict):
        issues.append({"code": "invalid_arbitration_policy", "message": "arbitration_policy must be an object"})
    else:
        if arbitration_policy.get("schema") != "libreevolve.evaluator_oracle_arbitration_policy.v1":
            issues.append({"code": "invalid_arbitration_policy_schema", "message": "arbitration_policy schema is unsupported"})
        authority_matrix = arbitration_policy.get("authority_matrix")
        if not isinstance(authority_matrix, list):
            issues.append({"code": "invalid_authority_matrix", "message": "arbitration authority_matrix must be a list"})
        else:
            if len(authority_matrix) != len(oracles):
                issues.append({"code": "invalid_authority_matrix_count", "message": "authority_matrix must match oracles length"})
            authority_ids = {
                item.get("oracle_id")
                for item in authority_matrix
                if isinstance(item, dict) and isinstance(item.get("oracle_id"), str)
            }
            if seen_ids and authority_ids != seen_ids:
                issues.append({"code": "invalid_authority_matrix_oracles", "message": "authority_matrix oracle ids must match registered oracles"})
            for index, item in enumerate(authority_matrix):
                if not isinstance(item, dict):
                    issues.append({"code": "invalid_authority_record", "message": f"authority record {index} must be an object"})
                    continue
                for field in ("benchmark_sufficiency", "conflict_role", "failure_effect"):
                    if not isinstance(item.get(field), str) or not item.get(field):
                        issues.append({"code": "invalid_authority_record_field", "message": f"authority record {index} {field} must be non-empty"})
                for field in ("independent_evidence", "reference_or_statistical"):
                    if not isinstance(item.get(field), bool):
                        issues.append({"code": "invalid_authority_record_flag", "message": f"authority record {index} {field} must be boolean"})
        if not isinstance(arbitration_policy.get("conflict_resolution"), dict):
            issues.append({"code": "invalid_arbitration_conflict_resolution", "message": "arbitration conflict_resolution must be an object"})
        if not isinstance(arbitration_policy.get("failure_handling"), dict):
            issues.append({"code": "invalid_arbitration_failure_handling", "message": "arbitration failure_handling must be an object"})
        readiness = arbitration_policy.get("claim_readiness")
        if not isinstance(readiness, dict):
            issues.append({"code": "invalid_arbitration_claim_readiness", "message": "arbitration claim_readiness must be an object"})
        elif readiness.get("independent_evaluator_oracle_arbitration") is not False:
            issues.append({"code": "arbitration_overclaim", "message": "independent evaluator-oracle arbitration must remain false"})
    if not isinstance(report.get("runtime_summary"), dict):
        issues.append({"code": "invalid_runtime_summary", "message": "runtime_summary must be an object"})
    disagreement_outcomes = report.get("disagreement_outcomes")
    if not isinstance(disagreement_outcomes, dict):
        issues.append({"code": "invalid_disagreement_outcomes", "message": "disagreement_outcomes must be an object"})
    else:
        _validate_evaluator_oracle_disagreement_outcomes(
            disagreement_outcomes,
            issues,
        )
    return {
        "schema": "libreevolve.evaluator_oracle_registry.v1",
        "ok": not issues,
        "issues": issues,
    }


def _validate_evaluator_oracle_disagreement_outcomes(
    report: Mapping[str, object],
    issues: list[dict],
) -> None:
    if report.get("schema") != "libreevolve.evaluator_oracle_disagreement_outcomes.v1":
        issues.append(
            {
                "code": "invalid_disagreement_outcomes_schema",
                "message": "disagreement_outcomes schema is unsupported",
            }
        )
    if report.get("source") != "history_evaluation_stages_and_metadata_llm_feedback":
        issues.append(
            {
                "code": "invalid_disagreement_outcomes_source",
                "message": "disagreement_outcomes source is unsupported",
            }
        )
    records = report.get("records")
    if not isinstance(records, list):
        issues.append(
            {
                "code": "invalid_disagreement_records",
                "message": "disagreement_outcomes.records must be a list",
            }
        )
        records = []
    observed_disagreements = 0
    discard_after_pass = 0
    skipped_invalid = 0
    for index, record in enumerate(records):
        if not isinstance(record, Mapping):
            issues.append(
                {
                    "code": "invalid_disagreement_record",
                    "message": f"disagreement record {index} must be an object",
                }
            )
            continue
        for field in (
            "program_id",
            "evaluator_oracle_id",
            "feedback_oracle_id",
            "outcome",
            "final_effect",
            "authority_boundary",
        ):
            if not isinstance(record.get(field), str) or not record.get(field):
                issues.append(
                    {
                        "code": "invalid_disagreement_record_field",
                        "message": f"disagreement record {index} {field} is invalid",
                    }
                )
        for field in (
            "feedback_discard",
            "feedback_skipped",
            "disagreement_observed",
        ):
            if not isinstance(record.get(field), bool):
                issues.append(
                    {
                        "code": "invalid_disagreement_record_flag",
                        "message": f"disagreement record {index} {field} must be boolean",
                    }
                )
        if record.get("disagreement_observed") is True:
            observed_disagreements += 1
        if record.get("outcome") == "feedback_discard_after_evaluator_pass":
            discard_after_pass += 1
            if record.get("evaluator_valid_before_feedback") is not True:
                issues.append(
                    {
                        "code": "invalid_feedback_discard_outcome",
                        "message": "feedback discard disagreement requires prior evaluator validity",
                    }
                )
        if record.get("outcome") == "evaluator_invalid_feedback_skipped":
            skipped_invalid += 1
    truncated = report.get("records_truncated") is True
    if not truncated:
        expected = {
            "outcome_count": len(records),
            "disagreement_count": observed_disagreements,
            "feedback_discard_after_evaluator_pass_count": discard_after_pass,
            "evaluator_invalid_feedback_skipped_count": skipped_invalid,
        }
        for field, value in expected.items():
            if report.get(field) != value:
                issues.append(
                    {
                        "code": f"invalid_{field}",
                        "message": f"{field} must match disagreement records",
                    }
                )
    policy = report.get("policy")
    if not isinstance(policy, Mapping):
        issues.append(
            {
                "code": "invalid_disagreement_policy",
                "message": "disagreement_outcomes.policy must be an object",
            }
        )
    elif policy.get("independent_reference_or_statistical_oracle") is not False:
        issues.append(
            {
                "code": "disagreement_policy_overclaim",
                "message": "disagreement outcomes must not claim independent reference/statistical oracle status",
            }
        )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, Mapping):
        issues.append(
            {
                "code": "invalid_disagreement_claim_readiness",
                "message": "disagreement_outcomes.claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("independent_cross_oracle_disagreement_outcomes") is not False:
            issues.append(
                {
                    "code": "disagreement_outcome_overclaim",
                    "message": "independent disagreement outcomes must remain false",
                }
            )
        remaining = readiness.get("remaining_gap")
        required = {
            "independent_reference_checker_or_statistical_test_oracles",
            "per_benchmark_oracle_sufficiency_evidence",
            "independent_cross_oracle_disagreement_outcome_records",
        }
        if not isinstance(remaining, list) or not required.issubset(
            {item for item in remaining if isinstance(item, str)}
        ):
            issues.append(
                {
                    "code": "missing_disagreement_remaining_gap",
                    "message": "disagreement outcomes must preserve independent oracle remaining gaps",
                }
            )


def _evaluator_workload_report(programs: list[Program]) -> dict:
    stages: dict[str, dict] = {}
    workload_type_counts: dict[str, int] = {}
    configured_candidate_count = 0
    for program in programs:
        evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
        metadata = evaluation.get("metadata") if isinstance(evaluation.get("metadata"), dict) else {}
        configured = metadata.get("configured_stage_results")
        if not isinstance(configured, list):
            continue
        configured_candidate_count += 1
        for stage_index, raw_stage in enumerate(configured):
            if not isinstance(raw_stage, dict):
                continue
            name = str(raw_stage.get("name", f"stage_{stage_index}"))
            workload = _configured_stage_workload(raw_stage)
            workload_type = str(workload.get("type", "simple_check"))
            declared = bool(workload.get("declared"))
            workload_type_counts[workload_type] = workload_type_counts.get(workload_type, 0) + 1
            key = f"{raw_stage.get('stage_index', stage_index)}:{name}"
            stage = stages.setdefault(
                key,
                {
                    "name": name,
                    "stage_index": raw_stage.get("stage_index", stage_index),
                    "workload_type": workload_type,
                    "declaration_source": workload["source"],
                    "declared": declared,
                    "candidate_count": 0,
                    "passed": 0,
                    "failed": 0,
                    "datasets": workload.get("datasets", []),
                    "budget": workload.get("budget", {}),
                    "checkpoint_policy": workload.get("checkpoint_policy", "not_declared"),
                    "score_fields": workload.get("score_fields", []),
                    "artifact_policy": workload.get("artifact_policy", "not_declared"),
                    "seed_count": workload.get("seed_count", 0),
                    "dataset_digest_evidence": _workload_dataset_digest_evidence(
                        workload_type,
                        workload.get("datasets", []),
                    ),
                    "protocol_execution": {
                        "managed_runner": False,
                        "execution_owner": "problem_local_validator",
                        "validator_workload_context": declared,
                        "claim_ready": False,
                    },
                    "_observed_metric_names": set(),
                    "_score_field_complete_count": 0,
                    "_artifact_file_count": 0,
                    "_artifact_sha256_count": 0,
                    "_artifact_paths": set(),
                    "sample_count": 0,
                    "retry_attempts": 0,
                    "subprocess_attempts": 0,
                    "timeout_count": 0,
                    "candidate_ids": [],
                },
            )
            stage["candidate_count"] += 1
            stage["candidate_ids"].append(program.id)
            if raw_stage.get("passed") is True:
                stage["passed"] += 1
            else:
                stage["failed"] += 1
            accounting = evaluation_accounting(raw_stage)
            stage["sample_count"] += int(accounting.get("configured_stage_samples", 0))
            stage["retry_attempts"] += int(accounting.get("retry_attempts", 0))
            stage["subprocess_attempts"] += int(accounting.get("subprocess_attempts", 0))
            stage["timeout_count"] += int(accounting.get("timeout_count", 0))
            _accumulate_workload_runtime_evidence(stage, raw_stage)
    ordered_stages = [
        _finalize_workload_stage_record(record)
        for record in sorted(stages.values(), key=lambda item: (item["stage_index"], item["name"]))
    ]
    declared_workload_stage_count = sum(1 for stage in ordered_stages if stage["declared"])
    protocol_stages = [
        stage
        for stage in ordered_stages
        if stage["declared"] and stage["workload_type"] in {"inner_search", "ml_training"}
    ]
    report = {
        "schema": "libreevolve.evaluator_workload_report.v1",
        "source": "runtime_history_configured_stage_results",
        "configured_candidate_count": configured_candidate_count,
        "stage_count": len(ordered_stages),
        "declared_workload_stage_count": declared_workload_stage_count,
        "workload_type_counts": dict(sorted(workload_type_counts.items())),
        "stages": ordered_stages,
        "workload_protocol_policy": {
            "schema": "libreevolve.evaluator_workload_protocol_policy.v1",
            "managed_inner_search_runner": False,
            "managed_ml_training_runner": False,
            "dataset_digest_check": "reported_from_workload_metadata_not_enforced_for_all_workloads",
            "score_field_linkage": "declared_score_fields_checked_against_returned_metrics",
            "checkpoint_artifact_check": "observed_artifact_records_only",
            "paper_claim_ready": False,
        },
        "protocol_readiness": {
            "declared_protocol_stage_count": len(protocol_stages),
            "dataset_digest_complete_stage_count": sum(
                1
                for stage in protocol_stages
                if stage["dataset_digest_evidence"]["complete"] is True
            ),
            "score_field_linked_stage_count": sum(
                1
                for stage in protocol_stages
                if stage["score_field_linkage"]["complete"] is True
            ),
            "artifact_evidence_stage_count": sum(
                1
                for stage in protocol_stages
                if stage["artifact_evidence"]["file_count"] > 0
            ),
            "managed_runner_stage_count": sum(
                1
                for stage in protocol_stages
                if stage["protocol_execution"]["managed_runner"] is True
            ),
            "claim_ready": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_inner_search_or_ml_training": False,
            "reason": (
                "stage workload metadata is preserved and aggregated, but "
                "LibreEvolve does not yet enforce workload-specific protocol "
                "execution, artifact completeness, or statistical linkage"
            ),
            "remaining_gap": [
                "dataset_and_split_hash_enforcement",
                "training_or_inner_search_protocol_runner",
                "checkpoint_artifact_completeness_checks",
                "score_field_to_artifact_validation",
                "stochastic_re_evaluation_policy",
            ],
        },
    }
    report["validation"] = validate_evaluator_workload_report(report)
    return report


def _proposal_lifecycle_report(
    db: ProgramDatabase,
    programs: list[Program],
) -> dict:
    generated_programs = [
        program
        for program in programs
        if isinstance(program.metadata, dict)
        and program.metadata.get("candidate_type") == "generated"
    ]
    failure_records = db.failure_records_snapshot()
    generated_failures = [
        record
        for record in failure_records
        if isinstance(record, dict)
        and record.get("record_type", "generated") == "generated"
    ]
    failure_by_program_id = {
        record["program_id"]: record
        for record in generated_failures
        if isinstance(record.get("program_id"), str)
    }
    generated_program_ids = {program.id for program in generated_programs}
    lifecycle_records = [
        _proposal_lifecycle_history_record(
            program,
            failure_by_program_id.get(program.id),
        )
        for program in generated_programs
    ] + [
        _proposal_lifecycle_failure_record(record)
        for record in generated_failures
        if record.get("program_id") not in generated_program_ids
    ]
    lifecycle_records.sort(key=_proposal_lifecycle_sort_key)
    accepted_invalid_count = sum(
        1
        for record in lifecycle_records
        if record.get("lifecycle_status") == "accepted_history"
        and record.get("evaluator_is_valid") is not True
    )
    accepted_generated_count = sum(
        1
        for record in lifecycle_records
        if record.get("lifecycle_status") == "accepted_history"
    )
    rejected_generated_count = sum(
        1
        for record in lifecycle_records
        if str(record.get("lifecycle_status", "")).startswith("rejected_")
    )
    evaluation_filtered_count = sum(
        1 for record in lifecycle_records if record.get("execution_filtered") is True
    )
    report = {
        "schema": "libreevolve.proposal_lifecycle_report.v1",
        "source": "history_and_failure_history_records",
        "generated_candidate_count": len(lifecycle_records),
        "accepted_generated_count": accepted_generated_count,
        "rejected_generated_count": rejected_generated_count,
        "execution_filtered_count": evaluation_filtered_count,
        "diff_or_parse_error_count": sum(
            1 for record in lifecycle_records if record.get("diff_error") is not None
        ),
        "invalid_evaluation_count": sum(
            1 for record in lifecycle_records if record.get("evaluator_is_valid") is False
        ),
        "archive_rejected_count": sum(
            1
            for record in lifecycle_records
            if record.get("admission", {}).get("admitted") is False
        ),
        "accepted_invalid_count": accepted_invalid_count,
        "rejection_reasons": _proposal_lifecycle_rejection_reasons(lifecycle_records),
        "records": lifecycle_records[:50],
        "records_truncated": len(lifecycle_records) > 50,
        "feedback_reuse": {
            "failure_record_count": len(failure_records),
            "generated_failure_record_count": len(generated_failures),
            "failure_memory_context_count": len(db.retrieval_failure_context),
            "failure_memory_policy": (
                "bounded_recent_failure_records_rendered_by_prompt_sampler_when_available"
            ),
            "failure_index_source": "runtime.history.failure_index",
            "queryable_failure_fingerprints": True,
        },
        "false_acceptance_review": {
            "status": "not_independently_reviewed",
            "accepted_invalid_count": accepted_invalid_count,
            "policy": (
                "history admission requires evaluator is_valid true before archive "
                "retention, but no independent false-acceptance audit is run"
            ),
        },
        "false_rejection_review": {
            "status": "not_independently_reviewed",
            "policy": (
                "rejected candidates are persisted with bounded diagnostics, but "
                "LibreEvolve does not rerun them through a stronger adjudicator"
            ),
        },
        "claim_ready": False,
        "claim_readiness": {
            "execution_grounded_incorrect_suggestion_filtering": True,
            "independent_false_acceptance_rate": False,
            "independent_false_rejection_rate": False,
            "remaining_gap": [
                "independent_rejudge_of_rejected_candidates",
                "cross_run_proposal_lifecycle_table",
                "audited_false_acceptance_and_false_rejection_rates",
                "semantic_failed_proposal_retrieval_beyond_bounded_recent_memory",
            ],
        },
    }
    report["validation"] = validate_proposal_lifecycle_report(report)
    return report


def _proposal_diversity_report(programs: list[Program]) -> dict:
    generated = [
        program
        for program in programs
        if isinstance(program.metadata, dict)
        and program.metadata.get("candidate_type") == "generated"
    ]
    records = [_proposal_diversity_record(program) for program in generated]
    proposal_records = [
        record for record in records if record["proposal_metadata_captured"]
    ]
    idea_records = [record for record in proposal_records if record["idea_hash"]]
    proposal_hashes = [
        record["proposal_signature_hash"]
        for record in proposal_records
        if record["proposal_signature_hash"]
    ]
    idea_hashes = [record["idea_hash"] for record in idea_records if record["idea_hash"]]
    generation_records = _proposal_diversity_group_records(records, "generation")
    batch_records = _proposal_diversity_batch_records(records)
    report = {
        "schema": "libreevolve.proposal_diversity_report.v1",
        "source": "runtime_history_proposal_metadata",
        "generated_candidate_count": len(generated),
        "proposal_metadata_count": len(proposal_records),
        "idea_record_count": len(idea_records),
        "unique_proposal_signature_count": len(set(proposal_hashes)),
        "duplicate_exact_proposal_count": (
            len(proposal_hashes) - len(set(proposal_hashes))
        ),
        "unique_idea_hash_count": len(set(idea_hashes)),
        "duplicate_exact_idea_count": len(idea_hashes) - len(set(idea_hashes)),
        "generation_records": generation_records,
        "batch_records": batch_records,
        "sample_records": records[:50],
        "records_truncated": len(records) > 50,
        "analysis_policy": {
            "schema": "libreevolve.proposal_diversity_analysis_policy.v1",
            "exact_text_hashes": True,
            "near_duplicate_detection": False,
            "semantic_novelty_scoring": False,
            "idea_family_classification": False,
            "model_quality_attribution": False,
            "benchmark_linkage": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "exact_duplicate_detection": True,
            "batch_level_counts": bool(batch_records),
            "semantic_proposal_diversity": False,
            "idea_novelty_metric": False,
            "model_quality_effect": False,
            "benchmark_attribution": False,
            "remaining_gap": [
                "near_duplicate_proposal_detection",
                "semantic_idea_family_classification",
                "task_output_distance_or_behavioral_novelty",
                "model_or_backend_quality_ablation_linkage",
                "benchmark_level_proposal_diversity_telemetry",
            ],
        },
    }
    report["validation"] = validate_proposal_diversity_report(report)
    return report


def _proposal_diversity_record(program: Program) -> dict:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    proposal = (
        metadata.get("proposal")
        if isinstance(metadata.get("proposal"), Mapping)
        else {}
    )
    fields = _proposal_diversity_fields(proposal)
    batch = _proposal_lifecycle_batch(metadata.get("proposal_batch"))
    idea = proposal.get("idea") if isinstance(proposal.get("idea"), str) else ""
    signature_text = "\n".join(
        f"{field}:{proposal.get(field)}"
        for field in ("idea", "rationale", "hypothesis")
        if isinstance(proposal.get(field), str) and proposal.get(field)
    )
    record = {
        "program_id": program.id,
        "generation": program.generation,
        "loop_generation_index": metadata.get("loop_generation_index"),
        "proposal_batch": batch,
        "proposal_metadata_captured": bool(fields),
        "proposal_fields_present": fields,
        "idea_hash": _proposal_diversity_hash(idea),
        "proposal_signature_hash": _proposal_diversity_hash(signature_text),
        "idea_preview": _proposal_lifecycle_text(idea, 160),
        "backend_idx": metadata.get("backend_idx")
        if isinstance(metadata.get("backend_idx"), int)
        and not isinstance(metadata.get("backend_idx"), bool)
        else None,
        "mutation_mode": metadata.get("mutation_mode")
        if isinstance(metadata.get("mutation_mode"), str)
        else None,
        "evaluator_is_valid": program.evaluation.get("is_valid")
        if isinstance(program.evaluation, dict)
        else None,
    }
    return {key: value for key, value in record.items() if value is not None}


def _proposal_diversity_fields(proposal: Mapping[str, object]) -> list[str]:
    return [
        field
        for field in ("idea", "rationale", "hypothesis")
        if isinstance(proposal.get(field), str) and proposal.get(field)
    ]


def _proposal_diversity_hash(value: object) -> str | None:
    if not isinstance(value, str) or not value:
        return None
    return hashlib.sha256(
        value.strip().encode("utf-8", errors="replace")
    ).hexdigest()


def _proposal_diversity_group_records(records: list[dict], field: str) -> list[dict]:
    groups: dict[object, list[dict]] = {}
    for record in records:
        key = record.get(field)
        if key is None:
            continue
        groups.setdefault(key, []).append(record)
    result = []
    for key, group in sorted(groups.items(), key=lambda item: str(item[0])):
        result.append(_proposal_diversity_group_summary(field, key, group))
    return result


def _proposal_diversity_batch_records(records: list[dict]) -> list[dict]:
    groups: dict[tuple[object, object], list[dict]] = {}
    for record in records:
        batch = (
            record.get("proposal_batch")
            if isinstance(record.get("proposal_batch"), Mapping)
            else {}
        )
        proposal_count = batch.get("proposals_per_generation")
        if proposal_count is None:
            continue
        key = (record.get("loop_generation_index"), proposal_count)
        groups.setdefault(key, []).append(record)
    result = []
    for (loop_generation_index, proposals_per_generation), group in sorted(
        groups.items(), key=lambda item: (str(item[0][0]), str(item[0][1]))
    ):
        summary = _proposal_diversity_group_summary(
            "loop_generation_index",
            loop_generation_index,
            group,
        )
        summary["proposals_per_generation"] = proposals_per_generation
        result.append(summary)
    return result


def _proposal_diversity_group_summary(
    field: str,
    value: object,
    group: list[dict],
) -> dict:
    proposal_hashes = [
        record["proposal_signature_hash"]
        for record in group
        if record.get("proposal_signature_hash")
    ]
    idea_hashes = [
        record["idea_hash"] for record in group if record.get("idea_hash")
    ]
    metadata_count = sum(
        1 for record in group if record.get("proposal_metadata_captured") is True
    )
    return {
        field: value,
        "candidate_count": len(group),
        "proposal_metadata_count": metadata_count,
        "idea_record_count": len(idea_hashes),
        "unique_proposal_signature_count": len(set(proposal_hashes)),
        "duplicate_exact_proposal_count": (
            len(proposal_hashes) - len(set(proposal_hashes))
        ),
        "unique_idea_hash_count": len(set(idea_hashes)),
        "duplicate_exact_idea_count": len(idea_hashes) - len(set(idea_hashes)),
    }


def validate_proposal_diversity_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.proposal_diversity_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "proposal diversity report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "proposal_metadata_count",
        "idea_record_count",
        "unique_proposal_signature_count",
        "duplicate_exact_proposal_count",
        "unique_idea_hash_count",
        "duplicate_exact_idea_count",
        "generation_records",
        "batch_records",
        "sample_records",
        "records_truncated",
        "analysis_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"proposal diversity report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.proposal_diversity_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "proposal diversity report schema is unsupported",
            }
        )
    if report.get("source") != "runtime_history_proposal_metadata":
        issues.append(
            {
                "code": "invalid_source",
                "message": "proposal diversity report source is unsupported",
            }
        )
    for field in (
        "generated_candidate_count",
        "proposal_metadata_count",
        "idea_record_count",
        "unique_proposal_signature_count",
        "duplicate_exact_proposal_count",
        "unique_idea_hash_count",
        "duplicate_exact_idea_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    if (
        isinstance(report.get("unique_idea_hash_count"), int)
        and isinstance(report.get("idea_record_count"), int)
        and report["unique_idea_hash_count"] > report["idea_record_count"]
    ):
        issues.append(
            {
                "code": "invalid_unique_idea_count",
                "message": "unique_idea_hash_count cannot exceed idea_record_count",
            }
        )
    for field in ("generation_records", "batch_records", "sample_records"):
        value = report.get(field)
        if not isinstance(value, list):
            issues.append(
                {"code": f"invalid_{field}", "message": f"{field} must be a list"}
            )
    policy = report.get("analysis_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_analysis_policy",
                "message": "analysis_policy must be an object",
            }
        )
        policy = {}
    if policy.get("exact_text_hashes") is not True:
        issues.append(
            {
                "code": "invalid_exact_text_hash_policy",
                "message": "analysis policy must enable exact text hashes",
            }
        )
    for field in (
        "near_duplicate_detection",
        "semantic_novelty_scoring",
        "idea_family_classification",
        "model_quality_attribution",
        "benchmark_linkage",
    ):
        if policy.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"analysis_policy.{field} must be false",
                }
            )
    records = report.get("sample_records")
    if isinstance(records, list):
        for index, record in enumerate(records):
            if not isinstance(record, dict):
                issues.append(
                    {
                        "code": "invalid_sample_record",
                        "message": f"sample record {index} must be an object",
                    }
                )
                continue
            if not isinstance(record.get("program_id"), str) or not record.get("program_id"):
                issues.append(
                    {
                        "code": "invalid_sample_program_id",
                        "message": f"sample record {index} program_id is invalid",
                    }
                )
            if not isinstance(record.get("proposal_fields_present"), list):
                issues.append(
                    {
                        "code": "invalid_sample_proposal_fields",
                        "message": f"sample record {index} proposal_fields_present must be a list",
                    }
                )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
        readiness = {}
    for field in (
        "semantic_proposal_diversity",
        "idea_novelty_metric",
        "model_quality_effect",
        "benchmark_attribution",
    ):
        if readiness.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"claim_readiness.{field} must be false",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "proposal diversity report must not claim full readiness",
            }
        )
    return {
        "schema": "libreevolve.proposal_diversity_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _proposal_score_report(programs: list[Program]) -> dict:
    generated = [
        program
        for program in programs
        if isinstance(program.metadata, dict)
        and program.metadata.get("candidate_type") == "generated"
    ]
    records = [_proposal_score_record(program) for program in generated]
    proposal_records = [
        record for record in records if record["proposal_metadata_captured"]
    ]
    signature_counts: dict[str, int] = {}
    for record in proposal_records:
        signature = record.get("proposal_signature_hash")
        if isinstance(signature, str) and signature:
            signature_counts[signature] = signature_counts.get(signature, 0) + 1
    seen_signatures: set[str] = set()
    scored_records = []
    for record in proposal_records:
        scored = dict(record)
        signature = scored.get("proposal_signature_hash")
        duplicate = isinstance(signature, str) and signature in seen_signatures
        if isinstance(signature, str):
            seen_signatures.add(signature)
        exact_novelty_score = 0.0 if duplicate else 1.0
        quality_score = _proposal_score_quality_score(scored)
        scored["exact_signature_duplicate"] = duplicate
        scored["signature_occurrence_count"] = (
            signature_counts.get(signature, 0) if isinstance(signature, str) else 0
        )
        scored["outcome_quality_score"] = quality_score
        scored["exact_text_novelty_score"] = exact_novelty_score
        scored["proposal_score"] = round(
            (0.7 * quality_score) + (0.3 * exact_novelty_score),
            6,
        )
        scored_records.append(scored)
    scored_records.sort(
        key=lambda record: (
            -record["proposal_score"],
            -record["outcome_quality_score"],
            record.get("generation", 0),
            str(record.get("program_id", "")),
        )
    )
    duplicate_count = sum(
        1 for record in scored_records if record["exact_signature_duplicate"]
    )
    report = {
        "schema": "libreevolve.proposal_score_report.v1",
        "source": "runtime_history_proposal_metadata_and_candidate_outcomes",
        "generated_candidate_count": len(generated),
        "proposal_metadata_count": len(proposal_records),
        "scored_proposal_count": len(scored_records),
        "unique_proposal_signature_count": len(signature_counts),
        "duplicate_exact_signature_count": duplicate_count,
        "accepted_scored_count": sum(
            1 for record in scored_records if record["evaluator_is_valid"] is True
        ),
        "rejected_scored_count": sum(
            1 for record in scored_records if record["evaluator_is_valid"] is not True
        ),
        "top_records": scored_records[:25],
        "records_truncated": len(scored_records) > 25,
        "scoring_policy": {
            "schema": "libreevolve.proposal_scoring_policy.v1",
            "quality_signal": (
                "candidate_selection_score_else_bounded_fitness_if_evaluator_valid"
            ),
            "quality_weight": 0.7,
            "novelty_signal": "exact_proposal_signature_first_occurrence",
            "novelty_weight": 0.3,
            "semantic_similarity": False,
            "embedding_index": False,
            "calibrated_quality_model": False,
            "cross_run_persistence": False,
            "prompt_selection_integration": False,
        },
        "claim_ready": False,
        "claim_readiness": {
            "versioned_proposal_score_records": True,
            "outcome_linked_quality_signal": bool(scored_records),
            "exact_text_novelty_signal": bool(scored_records),
            "semantic_proposal_index": False,
            "calibrated_quality_model": False,
            "cross_run_proposal_table": False,
            "prompt_or_archive_selection_uses_scores": False,
            "remaining_gap": [
                "semantic_or_embedding_backed_proposal_retrieval",
                "calibrated_proposal_quality_model",
                "cross_run_persisted_proposal_index",
                "prompt_archive_policy_using_proposal_scores",
                "benchmark_linked_proposal_quality_validation",
            ],
        },
    }
    report["validation"] = validate_proposal_score_report(report)
    return report


def _proposal_score_record(program: Program) -> dict:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    proposal = (
        metadata.get("proposal")
        if isinstance(metadata.get("proposal"), Mapping)
        else {}
    )
    fields = _proposal_diversity_fields(proposal)
    idea = proposal.get("idea") if isinstance(proposal.get("idea"), str) else ""
    signature_text = "\n".join(
        f"{field}:{proposal.get(field)}"
        for field in ("idea", "rationale", "hypothesis")
        if isinstance(proposal.get(field), str) and proposal.get(field)
    )
    evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
    record = {
        "program_id": program.id,
        "generation": program.generation,
        "parent_id": program.parent_id,
        "proposal_batch": _proposal_lifecycle_batch(metadata.get("proposal_batch")),
        "proposal_metadata_captured": bool(fields),
        "proposal_fields_present": fields,
        "idea_hash": _proposal_diversity_hash(idea),
        "proposal_signature_hash": _proposal_diversity_hash(signature_text),
        "idea_preview": _proposal_lifecycle_text(idea, 160),
        "backend_idx": metadata.get("backend_idx")
        if isinstance(metadata.get("backend_idx"), int)
        and not isinstance(metadata.get("backend_idx"), bool)
        else None,
        "mutation_mode": metadata.get("mutation_mode")
        if isinstance(metadata.get("mutation_mode"), str)
        else None,
        "evaluator_is_valid": evaluation.get("is_valid"),
        "fitness": _proposal_lifecycle_number(program.fitness),
        "selection_score": _proposal_lifecycle_number(
            metadata.get("selection_score")
        ),
        "admission_reason": (
            metadata.get("archive_admission", {}).get("reason")
            if isinstance(metadata.get("archive_admission"), Mapping)
            else None
        ),
    }
    return {key: value for key, value in record.items() if value is not None}


def _proposal_score_quality_score(record: Mapping[str, object]) -> float:
    if record.get("evaluator_is_valid") is not True:
        return 0.0
    selection_score = record.get("selection_score")
    if (
        isinstance(selection_score, (int, float))
        and not isinstance(selection_score, bool)
        and math.isfinite(float(selection_score))
    ):
        return round(max(0.0, min(1.0, float(selection_score))), 6)
    fitness = record.get("fitness")
    if (
        isinstance(fitness, (int, float))
        and not isinstance(fitness, bool)
        and math.isfinite(float(fitness))
    ):
        return round(max(0.0, min(1.0, float(fitness))), 6)
    return 0.0


def validate_proposal_score_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.proposal_score_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "proposal score report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "proposal_metadata_count",
        "scored_proposal_count",
        "unique_proposal_signature_count",
        "duplicate_exact_signature_count",
        "accepted_scored_count",
        "rejected_scored_count",
        "top_records",
        "records_truncated",
        "scoring_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"proposal score report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.proposal_score_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "proposal score report schema is unsupported",
            }
        )
    if report.get("source") != "runtime_history_proposal_metadata_and_candidate_outcomes":
        issues.append(
            {
                "code": "invalid_source",
                "message": "proposal score report source is unsupported",
            }
        )
    for field in (
        "generated_candidate_count",
        "proposal_metadata_count",
        "scored_proposal_count",
        "unique_proposal_signature_count",
        "duplicate_exact_signature_count",
        "accepted_scored_count",
        "rejected_scored_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    records = report.get("top_records")
    if not isinstance(records, list):
        issues.append(
            {"code": "invalid_top_records", "message": "top_records must be a list"}
        )
        records = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append(
                {
                    "code": "invalid_top_record",
                    "message": f"top record {index} must be an object",
                }
            )
            continue
        for field in (
            "proposal_score",
            "outcome_quality_score",
            "exact_text_novelty_score",
        ):
            value = record.get(field)
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(float(value))
                or not 0.0 <= float(value) <= 1.0
            ):
                issues.append(
                    {
                        "code": f"invalid_{field}",
                        "message": f"top record {index} {field} must be in [0, 1]",
                    }
                )
        if not isinstance(record.get("program_id"), str) or not record.get("program_id"):
            issues.append(
                {
                    "code": "invalid_program_id",
                    "message": f"top record {index} program_id is invalid",
                }
            )
        signature = record.get("proposal_signature_hash")
        if signature is not None and not _is_sha256_hex(signature):
            issues.append(
                {
                    "code": "invalid_signature_hash",
                    "message": f"top record {index} signature hash is invalid",
                }
            )
    if report.get("records_truncated") is not True:
        if report.get("scored_proposal_count") != len(records):
            issues.append(
                {
                    "code": "invalid_scored_count",
                    "message": "scored_proposal_count must match top_records",
                }
            )
    policy = report.get("scoring_policy")
    if not isinstance(policy, dict):
        issues.append(
            {
                "code": "invalid_scoring_policy",
                "message": "scoring_policy must be an object",
            }
        )
        policy = {}
    if policy.get("quality_weight") != 0.7 or policy.get("novelty_weight") != 0.3:
        issues.append(
            {
                "code": "invalid_score_weights",
                "message": "proposal score weights are unsupported",
            }
        )
    for field in (
        "semantic_similarity",
        "embedding_index",
        "calibrated_quality_model",
        "cross_run_persistence",
        "prompt_selection_integration",
    ):
        if policy.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"scoring_policy.{field} must be false",
                }
            )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
        readiness = {}
    for field in (
        "semantic_proposal_index",
        "calibrated_quality_model",
        "cross_run_proposal_table",
        "prompt_or_archive_selection_uses_scores",
    ):
        if readiness.get(field) is not False:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"claim_readiness.{field} must be false",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "invalid_claim_ready",
                "message": "proposal score report must not claim full readiness",
            }
        )
    return {
        "schema": "libreevolve.proposal_score_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _proposal_lifecycle_history_record(
    program: Program,
    failure_record: Mapping[str, object] | None = None,
) -> dict:
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), dict)
        else {}
    )
    admitted = admission.get("admitted") is True
    diff_error = (
        _proposal_lifecycle_text(failure_record.get("diff_error"), 500)
        if isinstance(failure_record, Mapping)
        else None
    )
    evaluator_error = _proposal_lifecycle_text(evaluation.get("error"), 500)
    rejection_reason = (
        _proposal_lifecycle_text(
            failure_record.get("admission_reason")
            or failure_record.get("diff_error")
            or failure_record.get("error"),
            500,
        )
        if isinstance(failure_record, Mapping)
        else _proposal_lifecycle_text(admission.get("reason"), 500)
    )
    execution_filtered = (
        not admitted
        and (
            diff_error is not None
            or evaluation.get("is_valid") is False
            or admission.get("reason") == "invalid_evaluation"
        )
    )
    record = {
        "proposal_id": program.id,
        "parent_id": program.parent_id,
        "generation": program.generation,
        "proposal_batch": _proposal_lifecycle_batch(metadata.get("proposal_batch")),
        "lifecycle_status": (
            "accepted_history" if admitted else "rejected_history"
        ),
        "evaluator_is_valid": evaluation.get("is_valid"),
        "score": _proposal_lifecycle_number(program.fitness),
        "diff_error": diff_error,
        "evaluator_error": evaluator_error,
        "execution_filtered": execution_filtered,
        "admission": _proposal_lifecycle_admission(admission),
        "llm": _proposal_lifecycle_llm_summary(
            metadata.get("llm_calls"),
            metadata.get("backend_idx"),
        ),
        "mutation": _proposal_lifecycle_mutation_summary(
            metadata.get("diff"),
            mutation_mode=metadata.get("mutation_mode"),
        ),
        "proposal_metadata": _proposal_lifecycle_proposal_metadata(
            metadata.get("proposal")
        ),
    }
    if not admitted:
        record["rejection_reason"] = rejection_reason
        record["failure_record_linked"] = isinstance(failure_record, Mapping)
    return record


def _proposal_lifecycle_failure_record(record: dict) -> dict:
    archive_admission = (
        record.get("archive_admission")
        if isinstance(record.get("archive_admission"), dict)
        else {}
    )
    diff_error = _proposal_lifecycle_text(record.get("diff_error"), 500)
    evaluator_error = _proposal_lifecycle_text(record.get("error"), 500)
    is_valid = record.get("is_valid")
    admitted = archive_admission.get("admitted")
    execution_filtered = (
        diff_error is not None
        or is_valid is False
        or record.get("admission_reason") == "invalid_evaluation"
    )
    return {
        "proposal_id": record.get("program_id"),
        "parent_id": record.get("parent_id"),
        "generation": record.get("generation"),
        "proposal_batch": {},
        "lifecycle_status": "rejected_failure_history",
        "evaluator_is_valid": is_valid if isinstance(is_valid, bool) else None,
        "score": _proposal_lifecycle_number(record.get("score")),
        "diff_error": diff_error,
        "evaluator_error": evaluator_error,
        "execution_filtered": execution_filtered,
        "rejection_reason": _proposal_lifecycle_text(
            record.get("admission_reason") or diff_error or evaluator_error,
            500,
        ),
        "admission": _proposal_lifecycle_admission(archive_admission),
        "llm": _proposal_lifecycle_llm_from_failure(record.get("llm")),
        "mutation": _proposal_lifecycle_failure_mutation(record),
        "proposal_metadata": {"captured": False, "fields": []},
    }


def _proposal_lifecycle_batch(value: object) -> dict:
    if not isinstance(value, Mapping):
        return {}
    result: dict = {}
    for field in (
        "policy",
        "proposal_index",
        "proposal_number",
        "proposals_per_generation",
        "loop_proposal_index",
    ):
        item = value.get(field)
        if isinstance(item, (str, int)) and not isinstance(item, bool):
            result[field] = item
    return result


def _proposal_lifecycle_admission(value: Mapping[str, object]) -> dict:
    if not isinstance(value, Mapping):
        return {}
    result: dict = {}
    for field in (
        "admitted",
        "reason",
        "evaluation_is_valid",
        "cell_admitted",
        "elite_retained",
        "search_state_changed",
        "sampling_eligible",
    ):
        item = value.get(field)
        if isinstance(item, (str, bool)):
            result[field] = item
    return result


def _proposal_lifecycle_llm_summary(
    calls: object,
    backend_idx: object = None,
) -> dict:
    summary: dict = {}
    if isinstance(backend_idx, int) and not isinstance(backend_idx, bool):
        summary["backend_idx"] = backend_idx
    if isinstance(calls, list):
        call_records = [
            call_summary
            for call in calls[:5]
            if (call_summary := _proposal_lifecycle_call_summary(call))
        ]
        if call_records:
            summary["calls"] = call_records
            summary["call_count"] = len(calls)
            summary["calls_truncated"] = len(calls) > len(call_records)
    return summary


def _proposal_lifecycle_llm_from_failure(value: object) -> dict:
    if not isinstance(value, Mapping):
        return {}
    summary: dict = {}
    backend_idx = value.get("backend_idx")
    if isinstance(backend_idx, int) and not isinstance(backend_idx, bool):
        summary["backend_idx"] = backend_idx
    calls = value.get("calls")
    if isinstance(calls, list):
        summary["calls"] = [
            call_summary
            for call in calls[:5]
            if (call_summary := _proposal_lifecycle_call_summary(call))
        ]
        call_count = value.get("call_count")
        summary["call_count"] = (
            call_count
            if isinstance(call_count, int) and not isinstance(call_count, bool)
            else len(summary["calls"])
        )
        summary["calls_truncated"] = value.get("calls_truncated") is True
    return summary


def _proposal_lifecycle_call_summary(call: object) -> dict:
    if not isinstance(call, Mapping):
        return {}
    summary: dict = {}
    for field in (
        "id",
        "call_id",
        "role",
        "backend",
        "backend_name",
        "provider",
        "model",
        "status",
        "finish_reason",
        "error",
        "provider_failure_category",
    ):
        value = _proposal_lifecycle_text(call.get(field), 160)
        if value is not None:
            summary[field] = value
    for field in (
        "backend_idx",
        "attempt_index",
        "provider_attempts",
        "prompt_chars",
        "output_chars",
        "total_tokens",
        "cost_microusd",
    ):
        value = call.get(field)
        if isinstance(value, int) and not isinstance(value, bool):
            summary[field] = value
    return summary


def _proposal_lifecycle_mutation_summary(
    value: object,
    *,
    mutation_mode: object = None,
) -> dict:
    summary = {
        "payload_text": isinstance(value, str),
        "payload_type": type(value).__name__,
    }
    if isinstance(mutation_mode, str):
        summary["mutation_mode"] = mutation_mode
    if isinstance(value, str):
        summary["sha256"] = hashlib.sha256(
            value.encode("utf-8", errors="replace")
        ).hexdigest()
        summary["chars"] = len(value)
    return summary


def _proposal_lifecycle_failure_mutation(record: Mapping[str, object]) -> dict:
    summary = {
        "payload_text": record.get("mutation_payload_text"),
        "payload_type": record.get("mutation_payload_type"),
        "sha256": record.get("mutation_sha256"),
        "truncated": record.get("mutation_truncated") is True,
        "source": "failure_history_bounded_mutation_payload",
    }
    return {key: value for key, value in summary.items() if value is not None}


def _proposal_lifecycle_proposal_metadata(value: object) -> dict:
    if not isinstance(value, Mapping):
        return {"captured": False, "fields": []}
    fields = sorted(key for key in value if isinstance(key, str))
    return {
        "captured": bool(fields),
        "fields": fields,
        "text_field_hashes": {
            key: hashlib.sha256(
                str(value[key]).encode("utf-8", errors="replace")
            ).hexdigest()
            for key in fields
            if isinstance(value.get(key), str)
        },
    }


def _proposal_lifecycle_number(value: object) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if not math.isfinite(float(value)):
        return None
    return float(value)


def _proposal_lifecycle_text(value: object, max_chars: int) -> str | None:
    if not isinstance(value, str):
        return None
    redacted = redact_sensitive_text(value)
    if len(redacted) <= max_chars:
        return redacted
    if max_chars <= 3:
        return redacted[:max_chars]
    return redacted[: max_chars - 3] + "..."


def _proposal_lifecycle_sort_key(record: dict) -> tuple:
    generation = record.get("generation")
    if not isinstance(generation, int) or isinstance(generation, bool):
        generation = 10**9
    batch = record.get("proposal_batch") if isinstance(record.get("proposal_batch"), dict) else {}
    loop_index = batch.get("loop_proposal_index")
    if not isinstance(loop_index, int) or isinstance(loop_index, bool):
        loop_index = 10**9
    proposal_id = record.get("proposal_id") if isinstance(record.get("proposal_id"), str) else ""
    return generation, loop_index, proposal_id


def _proposal_lifecycle_rejection_reasons(records: list[dict]) -> dict:
    reasons: dict[str, int] = {}
    for record in records:
        if not str(record.get("lifecycle_status", "")).startswith("rejected_"):
            continue
        reason = record.get("rejection_reason")
        if not isinstance(reason, str) or not reason:
            reason = "unknown"
        reasons[reason] = reasons.get(reason, 0) + 1
    return dict(sorted(reasons.items()))


def validate_proposal_lifecycle_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.proposal_lifecycle_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "proposal lifecycle report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "accepted_generated_count",
        "rejected_generated_count",
        "execution_filtered_count",
        "diff_or_parse_error_count",
        "invalid_evaluation_count",
        "archive_rejected_count",
        "accepted_invalid_count",
        "rejection_reasons",
        "records",
        "records_truncated",
        "feedback_reuse",
        "false_acceptance_review",
        "false_rejection_review",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"proposal lifecycle report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.proposal_lifecycle_report.v1":
        issues.append({"code": "invalid_schema", "message": "proposal lifecycle report schema is unsupported"})
    if report.get("source") != "history_and_failure_history_records":
        issues.append({"code": "invalid_source", "message": "proposal lifecycle report source is unsupported"})
    records = report.get("records")
    if not isinstance(records, list):
        issues.append({"code": "invalid_records", "message": "records must be a list"})
        records = []
    accepted = 0
    rejected = 0
    execution_filtered = 0
    diff_errors = 0
    invalid_eval = 0
    archive_rejected = 0
    accepted_invalid = 0
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            issues.append({"code": "invalid_record", "message": f"record {index} must be an object"})
            continue
        if not isinstance(record.get("proposal_id"), str) or not record.get("proposal_id"):
            issues.append({"code": "invalid_proposal_id", "message": f"record {index} proposal_id is invalid"})
        status = record.get("lifecycle_status")
        if status == "accepted_history":
            accepted += 1
            if record.get("evaluator_is_valid") is not True:
                accepted_invalid += 1
        elif status in {"rejected_history", "rejected_failure_history"}:
            rejected += 1
        else:
            issues.append({"code": "invalid_lifecycle_status", "message": f"record {index} lifecycle_status is invalid"})
        if record.get("execution_filtered") is True:
            execution_filtered += 1
        if record.get("diff_error") is not None:
            diff_errors += 1
        if record.get("evaluator_is_valid") is False:
            invalid_eval += 1
        admission = record.get("admission")
        if isinstance(admission, dict) and admission.get("admitted") is False:
            archive_rejected += 1
        if not isinstance(record.get("mutation"), dict):
            issues.append({"code": "invalid_mutation_summary", "message": f"record {index} mutation summary is invalid"})
        if not isinstance(record.get("llm"), dict):
            issues.append({"code": "invalid_llm_summary", "message": f"record {index} llm summary is invalid"})
    truncated = report.get("records_truncated") is True
    if not truncated:
        expected = accepted + rejected
        if report.get("generated_candidate_count") != expected:
            issues.append({"code": "invalid_generated_count", "message": "generated_candidate_count must match record count"})
        if report.get("accepted_generated_count") != accepted:
            issues.append({"code": "invalid_accepted_count", "message": "accepted_generated_count must match records"})
        if report.get("rejected_generated_count") != rejected:
            issues.append({"code": "invalid_rejected_count", "message": "rejected_generated_count must match records"})
        if report.get("execution_filtered_count") != execution_filtered:
            issues.append({"code": "invalid_filtered_count", "message": "execution_filtered_count must match records"})
        if report.get("diff_or_parse_error_count") != diff_errors:
            issues.append({"code": "invalid_diff_error_count", "message": "diff_or_parse_error_count must match records"})
        if report.get("invalid_evaluation_count") != invalid_eval:
            issues.append({"code": "invalid_evaluation_count", "message": "invalid_evaluation_count must match records"})
        if report.get("archive_rejected_count") != archive_rejected:
            issues.append({"code": "invalid_archive_rejected_count", "message": "archive_rejected_count must match records"})
        if report.get("accepted_invalid_count") != accepted_invalid:
            issues.append({"code": "invalid_accepted_invalid_count", "message": "accepted_invalid_count must match records"})
    if report.get("accepted_invalid_count") not in (0, accepted_invalid):
        issues.append({"code": "accepted_invalid_overclaim", "message": "accepted invalid count is inconsistent"})
    if not isinstance(report.get("feedback_reuse"), dict):
        issues.append({"code": "invalid_feedback_reuse", "message": "feedback_reuse must be an object"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "invalid_claim_ready", "message": "proposal lifecycle report must not claim independent audit readiness"})
    return {
        "schema": "libreevolve.proposal_lifecycle_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _hypothesis_branch_report(
    db: ProgramDatabase,
    programs: list[Program],
) -> dict:
    failure_records = db.failure_records_snapshot()
    failure_by_id = {
        record["program_id"]: record
        for record in failure_records
        if isinstance(record, Mapping)
        and record.get("record_type", "generated") == "generated"
        and isinstance(record.get("program_id"), str)
    }
    branches: dict[str, dict] = {}
    for program in programs:
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        if metadata.get("candidate_type") != "generated":
            continue
        proposal = metadata.get("proposal")
        if not isinstance(proposal, Mapping):
            continue
        branch = _hypothesis_branch_record_for_proposal(proposal)
        if branch is None:
            continue
        branch_record = branches.setdefault(branch["branch_id"], branch)
        _hypothesis_branch_add_program(
            branch_record,
            program,
            failure_by_id.get(program.id),
        )
    finalized = [
        _finalize_hypothesis_branch_record(record)
        for record in branches.values()
    ]
    finalized.sort(key=_hypothesis_branch_sort_key)
    abandonment_count = sum(
        1 for branch in finalized if branch["branch_status"] == "abandoned_evidence"
    )
    report = {
        "schema": "libreevolve.hypothesis_branch_report.v1",
        "source": "history_failure_history_and_proposal_metadata",
        "branch_count": len(finalized),
        "abandoned_branch_count": abandonment_count,
        "active_or_validated_branch_count": sum(
            1
            for branch in finalized
            if branch["branch_status"] == "active_or_validated"
        ),
        "branches": finalized[:50],
        "branches_limit": 50,
        "branches_truncated": len(finalized) > 50,
        "failure_memory_linkage": {
            "failure_record_count": len(failure_records),
            "failure_memory_context_count": len(db.retrieval_failure_context),
            "hypothesis_context_count": len(db.retrieval_hypothesis_context),
            "failure_memory_policy": (
                "bounded_recent_failure_records_rendered_by_prompt_sampler_when_available"
            ),
            "hypothesis_context_policy": (
                "bounded_recent_valid_proposal_hypothesis_context_when_available"
            ),
        },
        "backtracking_policy": {
            "controller_suppression": "not_configured",
            "fallback_target_policy": "inferred_parent_or_alternative_branch_only",
            "resumed_search_outcome_policy": (
                "observed_later_accepted_different_branch_not_causal_proof"
            ),
        },
        "claim_ready": False,
        "claim_readiness": {
            "branch_level_abandonment_evidence": abandonment_count > 0,
            "controller_backtracking_decision": False,
            "redirected_sampling_proof": False,
            "remaining_gap": [
                "explicit_branch_state_machine",
                "controller_suppression_or_retry_policy",
                "fallback_target_selection_event",
                "causal_redirected_sampling_evidence",
                "cross_run_hypothesis_branch_table",
            ],
        },
    }
    report["validation"] = validate_hypothesis_branch_report(report)
    return report


def _hypothesis_branch_record_for_proposal(proposal: Mapping[str, object]) -> dict | None:
    text: dict[str, str] = {}
    for field in ("idea", "hypothesis", "rationale"):
        value = proposal.get(field)
        if isinstance(value, str) and value.strip():
            text[field] = redact_sensitive_text(value.strip())
    if not text:
        return None
    key_payload = json.dumps(text, sort_keys=True, separators=(",", ":"))
    branch_id = "hypothesis-" + hashlib.sha256(
        key_payload.encode("utf-8")
    ).hexdigest()[:16]
    return {
        "branch_id": branch_id,
        "proposal_fields": {
            field: _hypothesis_branch_text_summary(value)
            for field, value in text.items()
        },
        "candidate_ids": [],
        "accepted_candidate_ids": [],
        "rejected_candidate_ids": [],
        "execution_filtered_candidate_ids": [],
        "parent_ids": [],
        "generations": [],
        "rejection_reasons": {},
        "evaluator_errors": {},
        "cascade_stop_reasons": {},
    }


def _hypothesis_branch_text_summary(value: str) -> dict:
    return {
        "policy": "bounded_redacted_branch_text_v1",
        "sha256": hashlib.sha256(value.encode("utf-8")).hexdigest(),
        "chars": len(value),
        "preview": value[:200],
        "preview_chars": min(len(value), 200),
        "truncated": len(value) > 200,
    }


def _hypothesis_branch_add_program(
    branch: dict,
    program: Program,
    failure_record: Mapping[str, object] | None,
) -> None:
    branch["candidate_ids"].append(program.id)
    if program.parent_id is not None:
        branch["parent_ids"].append(program.parent_id)
    branch["generations"].append(program.generation)
    metadata = program.metadata if isinstance(program.metadata, dict) else {}
    admission = (
        metadata.get("archive_admission")
        if isinstance(metadata.get("archive_admission"), Mapping)
        else {}
    )
    evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
    admitted = admission.get("admitted") is True
    if admitted:
        branch["accepted_candidate_ids"].append(program.id)
    else:
        branch["rejected_candidate_ids"].append(program.id)
    execution_filtered = (
        not admitted
        and (
            evaluation.get("is_valid") is False
            or admission.get("reason") == "invalid_evaluation"
            or (
                isinstance(failure_record, Mapping)
                and isinstance(failure_record.get("diff_error"), str)
            )
        )
    )
    if execution_filtered:
        branch["execution_filtered_candidate_ids"].append(program.id)
    reason = None
    if not admitted:
        if isinstance(failure_record, Mapping):
            reason = failure_record.get("admission_reason") or failure_record.get(
                "diff_error"
            )
        reason = reason or admission.get("reason") or "rejected"
        reason = str(reason)
        branch["rejection_reasons"][reason] = branch["rejection_reasons"].get(reason, 0) + 1
    error = evaluation.get("error")
    if isinstance(error, str) and error:
        branch["evaluator_errors"][error] = branch["evaluator_errors"].get(error, 0) + 1
    eval_metadata = (
        evaluation.get("metadata")
        if isinstance(evaluation.get("metadata"), Mapping)
        else {}
    )
    stopped_at = eval_metadata.get("stopped_at")
    if isinstance(stopped_at, str) and stopped_at:
        key = f"stopped_at:{stopped_at}"
        branch["cascade_stop_reasons"][key] = (
            branch["cascade_stop_reasons"].get(key, 0) + 1
        )


def _finalize_hypothesis_branch_record(branch: dict) -> dict:
    candidate_ids = _unique_preserve_order(branch["candidate_ids"])
    accepted_ids = _unique_preserve_order(branch["accepted_candidate_ids"])
    rejected_ids = _unique_preserve_order(branch["rejected_candidate_ids"])
    filtered_ids = _unique_preserve_order(branch["execution_filtered_candidate_ids"])
    parent_ids = _unique_preserve_order(branch["parent_ids"])
    generations = [
        generation
        for generation in branch["generations"]
        if isinstance(generation, int) and not isinstance(generation, bool)
    ]
    rejected_count = len(rejected_ids)
    accepted_count = len(accepted_ids)
    if rejected_count and not accepted_count:
        status = "abandoned_evidence"
        abandonment_reason = (
            "all_observed_candidates_rejected_or_execution_filtered"
            if len(filtered_ids) == rejected_count
            else "all_observed_candidates_rejected"
        )
    elif accepted_count:
        status = "active_or_validated"
        abandonment_reason = None
    else:
        status = "insufficient_evidence"
        abandonment_reason = None
    fallback_target = {
        "type": "parent_program",
        "candidate_ids": parent_ids[:5],
        "policy": "inferred_from_rejected_candidate_parent_ids",
    } if rejected_count else {
        "type": "not_applicable",
        "candidate_ids": [],
        "policy": "no_rejected_candidates",
    }
    return {
        "branch_id": branch["branch_id"],
        "proposal_fields": branch["proposal_fields"],
        "branch_status": status,
        "abandonment_reason": abandonment_reason,
        "candidate_count": len(candidate_ids),
        "accepted_count": accepted_count,
        "rejected_count": rejected_count,
        "execution_filtered_count": len(filtered_ids),
        "candidate_ids": candidate_ids[:25],
        "candidate_ids_truncated": len(candidate_ids) > 25,
        "accepted_candidate_ids": accepted_ids[:25],
        "rejected_candidate_ids": rejected_ids[:25],
        "execution_filtered_candidate_ids": filtered_ids[:25],
        "generation_span": [
            min(generations) if generations else None,
            max(generations) if generations else None,
        ],
        "parent_ids": parent_ids[:10],
        "parent_ids_truncated": len(parent_ids) > 10,
        "rejection_reasons": dict(sorted(branch["rejection_reasons"].items())),
        "evaluator_errors": dict(sorted(branch["evaluator_errors"].items())),
        "cascade_stop_reasons": dict(sorted(branch["cascade_stop_reasons"].items())),
        "fallback_target": fallback_target,
        "suppression_policy": "not_configured",
        "retry_policy": "normal_parent_sampling_can_retry_until_budget_or_archive_state_changes",
        "resumed_search_outcome": {
            "status": "not_causally_tracked",
            "policy": "manifest_report_observes_branch_outcomes_without_controller_redirect_events",
        },
    }


def _unique_preserve_order(values: list) -> list:
    result = []
    seen = set()
    for value in values:
        if not isinstance(value, str) or value in seen:
            continue
        seen.add(value)
        result.append(value)
    return result


def _hypothesis_branch_sort_key(branch: dict) -> tuple:
    status_rank = 0 if branch.get("branch_status") == "abandoned_evidence" else 1
    return (
        status_rank,
        -int(branch.get("rejected_count", 0)),
        -int(branch.get("candidate_count", 0)),
        str(branch.get("branch_id", "")),
    )


def validate_hypothesis_branch_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.hypothesis_branch_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "hypothesis branch report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "branch_count",
        "abandoned_branch_count",
        "active_or_validated_branch_count",
        "branches",
        "branches_limit",
        "branches_truncated",
        "failure_memory_linkage",
        "backtracking_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"hypothesis branch report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.hypothesis_branch_report.v1":
        issues.append({"code": "invalid_schema", "message": "hypothesis branch report schema is unsupported"})
    if report.get("source") != "history_failure_history_and_proposal_metadata":
        issues.append({"code": "invalid_source", "message": "hypothesis branch report source is unsupported"})
    branches = report.get("branches")
    if not isinstance(branches, list):
        issues.append({"code": "invalid_branches", "message": "branches must be a list"})
        branches = []
    abandoned = 0
    active = 0
    for index, branch in enumerate(branches):
        if not isinstance(branch, dict):
            issues.append({"code": "invalid_branch", "message": f"branch {index} must be an object"})
            continue
        branch_id = branch.get("branch_id")
        if not isinstance(branch_id, str) or not re.fullmatch(r"hypothesis-[0-9a-f]{16}", branch_id):
            issues.append({"code": "invalid_branch_id", "message": f"branch {index} id is invalid"})
        status = branch.get("branch_status")
        if status == "abandoned_evidence":
            abandoned += 1
        elif status == "active_or_validated":
            active += 1
        elif status != "insufficient_evidence":
            issues.append({"code": "invalid_branch_status", "message": f"branch {index} status is invalid"})
        candidate_count = branch.get("candidate_count")
        accepted_count = branch.get("accepted_count")
        rejected_count = branch.get("rejected_count")
        filtered_count = branch.get("execution_filtered_count")
        for field, value in (
            ("candidate_count", candidate_count),
            ("accepted_count", accepted_count),
            ("rejected_count", rejected_count),
            ("execution_filtered_count", filtered_count),
        ):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                issues.append({"code": f"invalid_{field}", "message": f"branch {index} {field} must be a non-negative integer"})
        if (
            isinstance(candidate_count, int)
            and isinstance(accepted_count, int)
            and isinstance(rejected_count, int)
            and candidate_count != accepted_count + rejected_count
        ):
            issues.append({"code": "invalid_branch_counts", "message": f"branch {index} accepted/rejected counts must add to candidate_count"})
        if isinstance(filtered_count, int) and isinstance(rejected_count, int) and filtered_count > rejected_count:
            issues.append({"code": "invalid_filtered_count", "message": f"branch {index} filtered count cannot exceed rejected count"})
        if not isinstance(branch.get("proposal_fields"), dict) or not branch["proposal_fields"]:
            issues.append({"code": "invalid_proposal_fields", "message": f"branch {index} must include proposal fields"})
        if not isinstance(branch.get("fallback_target"), dict):
            issues.append({"code": "invalid_fallback_target", "message": f"branch {index} fallback target must be an object"})
    if report.get("branches_truncated") is not True:
        if report.get("branch_count") != len(branches):
            issues.append({"code": "invalid_branch_count", "message": "branch_count must match branches when not truncated"})
        if report.get("abandoned_branch_count") != abandoned:
            issues.append({"code": "invalid_abandoned_count", "message": "abandoned_branch_count must match branches"})
        if report.get("active_or_validated_branch_count") != active:
            issues.append({"code": "invalid_active_count", "message": "active_or_validated_branch_count must match branches"})
    if not isinstance(report.get("failure_memory_linkage"), dict):
        issues.append({"code": "invalid_failure_memory_linkage", "message": "failure_memory_linkage must be an object"})
    policy = report.get("backtracking_policy")
    if not isinstance(policy, dict):
        issues.append({"code": "invalid_backtracking_policy", "message": "backtracking_policy must be an object"})
    elif policy.get("controller_suppression") != "not_configured":
        issues.append({"code": "controller_backtracking_overclaim", "message": "controller suppression must remain not_configured until implemented"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "hypothesis branch report must not claim AlphaEvolve backtracking parity"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    elif readiness.get("controller_backtracking_decision") is not False:
        issues.append({"code": "controller_decision_overclaim", "message": "controller backtracking decision must remain false"})
    return {
        "schema": "libreevolve.hypothesis_branch_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _controller_backtracking_report(
    programs: list[Program],
    hypothesis_branch_report: Mapping[str, object],
) -> dict:
    generated_records = _controller_backtracking_candidate_records(programs)
    branch_lookup = {
        branch["branch_id"]: branch
        for branch in hypothesis_branch_report.get("branches", [])
        if isinstance(branch, Mapping) and isinstance(branch.get("branch_id"), str)
    }
    transitions = _controller_backtracking_state_transitions(
        generated_records,
        branch_lookup,
    )
    redirects = _controller_backtracking_redirect_events(
        generated_records,
        branch_lookup,
    )
    report = {
        "schema": "libreevolve.controller_backtracking_report.v1",
        "source": "runtime_history_parent_selection_and_hypothesis_branch_report",
        "generated_candidate_count": len(generated_records),
        "visible_branch_count": len(branch_lookup),
        "visible_abandoned_branch_count": sum(
            1
            for branch in branch_lookup.values()
            if branch.get("branch_status") == "abandoned_evidence"
        ),
        "branch_state_transition_count": len(transitions),
        "redirect_event_count": len(redirects),
        "branch_state_transitions": transitions[:100],
        "branch_state_transitions_limit": 100,
        "branch_state_transitions_truncated": len(transitions) > 100,
        "redirect_events": redirects[:50],
        "redirect_events_limit": 50,
        "redirect_events_truncated": len(redirects) > 50,
        "policies": {
            "branch_identity": "captured_proposal_text_hash",
            "state_source": "archive_admission_and_failure_history_summary",
            "fallback_target_selection": (
                "observed_later_parent_sampling_after_abandoned_branch"
            ),
            "controller_suppression": "not_configured",
            "retry_policy": "normal_parent_sampling_can_revisit_branch",
            "replay_scope": "current_manifest_history_only",
        },
        "claim_ready": False,
        "claim_readiness": {
            "branch_state_transitions": bool(transitions),
            "observed_redirect_events": bool(redirects),
            "explicit_controller_backtracking_decision": False,
            "suppression_or_retry_policy": False,
            "causal_resumed_search_proof": False,
            "cross_run_branch_table": False,
            "remaining_gap": [
                "controller_owned_branch_state_machine",
                "configured_suppression_or_retry_policy",
                "explicit_fallback_target_selection_event",
                "causal_resumed_search_replay",
                "cross_run_hypothesis_branch_table",
            ],
        },
    }
    report["validation"] = validate_controller_backtracking_report(report)
    return report


def _controller_backtracking_candidate_records(programs: list[Program]) -> list[dict]:
    records: list[dict] = []
    for index, program in enumerate(programs):
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        if metadata.get("candidate_type") != "generated":
            continue
        proposal = metadata.get("proposal")
        if not isinstance(proposal, Mapping):
            continue
        branch = _hypothesis_branch_record_for_proposal(proposal)
        if branch is None:
            continue
        admission = (
            metadata.get("archive_admission")
            if isinstance(metadata.get("archive_admission"), Mapping)
            else {}
        )
        proposal_batch = (
            metadata.get("proposal_batch")
            if isinstance(metadata.get("proposal_batch"), Mapping)
            else {}
        )
        parent_selection = (
            metadata.get("parent_selection")
            if isinstance(metadata.get("parent_selection"), Mapping)
            else {}
        )
        loop_index = proposal_batch.get("loop_proposal_index")
        if isinstance(loop_index, bool) or not isinstance(loop_index, int):
            loop_index = index
        admitted = admission.get("admitted") is True
        records.append(
            {
                "order": loop_index,
                "program_id": program.id,
                "branch_id": branch["branch_id"],
                "parent_id": program.parent_id,
                "generation": program.generation,
                "proposal_index": proposal_batch.get("proposal_index"),
                "admitted": admitted,
                "rejection_reason": None
                if admitted
                else str(admission.get("reason") or "rejected"),
                "parent_strategy": parent_selection.get("strategy"),
            }
        )
    records.sort(key=lambda record: (record["order"], record["program_id"]))
    return records


def _controller_backtracking_state_transitions(
    records: list[dict],
    branch_lookup: Mapping[str, Mapping[str, object]],
) -> list[dict]:
    transitions: list[dict] = []
    opened: set[str] = set()
    last_record_by_branch: dict[str, dict] = {}
    for record in records:
        branch_id = record["branch_id"]
        if branch_id not in opened:
            opened.add(branch_id)
            transitions.append(
                _controller_backtracking_transition(
                    "opened",
                    branch_id,
                    record,
                    from_state="unseen",
                    to_state="exploring",
                    reason="first_observed_candidate_for_branch",
                )
            )
        outcome = "candidate_accepted" if record["admitted"] else "candidate_rejected"
        transitions.append(
            _controller_backtracking_transition(
                outcome,
                branch_id,
                record,
                from_state="exploring",
                to_state="validated_observed"
                if record["admitted"]
                else "rejected_observed",
                reason="archive_admission"
                if record["admitted"]
                else record["rejection_reason"],
            )
        )
        last_record_by_branch[branch_id] = record
    for branch_id, branch in branch_lookup.items():
        if branch.get("branch_status") != "abandoned_evidence":
            continue
        record = last_record_by_branch.get(branch_id)
        if record is None:
            continue
        transitions.append(
            _controller_backtracking_transition(
                "abandoned_evidence",
                branch_id,
                record,
                from_state="rejected_observed",
                to_state="abandoned_evidence",
                reason=str(
                    branch.get("abandonment_reason")
                    or "all_observed_candidates_rejected"
                ),
            )
        )
    transitions.sort(key=lambda item: (item["order"], item["event_type"]))
    return transitions


def _controller_backtracking_transition(
    event_type: str,
    branch_id: str,
    record: Mapping[str, object],
    *,
    from_state: str,
    to_state: str,
    reason: str | None,
) -> dict:
    return {
        "event_type": event_type,
        "branch_id": branch_id,
        "program_id": record.get("program_id"),
        "parent_id": record.get("parent_id"),
        "generation": record.get("generation"),
        "proposal_index": record.get("proposal_index"),
        "order": record.get("order"),
        "from_state": from_state,
        "to_state": to_state,
        "reason": reason or "not_recorded",
        "decision_source": "observed_runtime_history",
    }


def _controller_backtracking_redirect_events(
    records: list[dict],
    branch_lookup: Mapping[str, Mapping[str, object]],
) -> list[dict]:
    records_by_branch: dict[str, list[dict]] = {}
    for record in records:
        records_by_branch.setdefault(record["branch_id"], []).append(record)
    events: list[dict] = []
    for branch_id, branch in branch_lookup.items():
        if branch.get("branch_status") != "abandoned_evidence":
            continue
        source_records = records_by_branch.get(branch_id, [])
        if not source_records:
            continue
        last_record = max(source_records, key=lambda item: item["order"])
        parent_ids = {
            parent_id
            for parent_id in branch.get("parent_ids", [])
            if isinstance(parent_id, str)
        }
        later = next(
            (
                item
                for item in records
                if item["order"] > last_record["order"]
                and item["branch_id"] != branch_id
            ),
            None,
        )
        if later is None:
            continue
        redirect_kind = (
            "fallback_parent_sampled_for_alternative_branch"
            if later.get("parent_id") in parent_ids
            else "alternative_parent_or_branch_sampled"
        )
        event_id_payload = json.dumps(
            [branch_id, last_record["program_id"], later["program_id"]],
            separators=(",", ":"),
        )
        events.append(
            {
                "event_id": "redirect-"
                + hashlib.sha256(event_id_payload.encode("utf-8")).hexdigest()[:16],
                "source_branch_id": branch_id,
                "source_last_candidate_id": last_record["program_id"],
                "source_last_generation": last_record["generation"],
                "selected_candidate_id": later["program_id"],
                "selected_generation": later["generation"],
                "selected_branch_id": later["branch_id"],
                "selected_parent_id": later["parent_id"],
                "selected_parent_strategy": later.get("parent_strategy"),
                "redirect_kind": redirect_kind,
                "evidence_strength": "observed_after_abandoned_branch_not_causal_proof",
                "causal_proof": False,
            }
        )
    events.sort(key=lambda item: item["event_id"])
    return events


def validate_controller_backtracking_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.controller_backtracking_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "controller backtracking report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "generated_candidate_count",
        "visible_branch_count",
        "visible_abandoned_branch_count",
        "branch_state_transition_count",
        "redirect_event_count",
        "branch_state_transitions",
        "branch_state_transitions_limit",
        "branch_state_transitions_truncated",
        "redirect_events",
        "redirect_events_limit",
        "redirect_events_truncated",
        "policies",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"controller backtracking report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.controller_backtracking_report.v1":
        issues.append({"code": "invalid_schema", "message": "controller backtracking report schema is unsupported"})
    if report.get("source") != "runtime_history_parent_selection_and_hypothesis_branch_report":
        issues.append({"code": "invalid_source", "message": "controller backtracking report source is unsupported"})
    for field in (
        "generated_candidate_count",
        "visible_branch_count",
        "visible_abandoned_branch_count",
        "branch_state_transition_count",
        "redirect_event_count",
    ):
        value = report.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append({"code": f"invalid_{field}", "message": f"{field} must be a non-negative integer"})
    transitions = report.get("branch_state_transitions")
    if not isinstance(transitions, list):
        issues.append({"code": "invalid_transitions", "message": "branch_state_transitions must be a list"})
        transitions = []
    redirects = report.get("redirect_events")
    if not isinstance(redirects, list):
        issues.append({"code": "invalid_redirect_events", "message": "redirect_events must be a list"})
        redirects = []
    for index, transition in enumerate(transitions):
        if not isinstance(transition, dict):
            issues.append({"code": "invalid_transition", "message": f"transition {index} must be an object"})
            continue
        if not isinstance(transition.get("branch_id"), str):
            issues.append({"code": "invalid_transition_branch", "message": f"transition {index} must include branch_id"})
        if transition.get("event_type") not in {
            "opened",
            "candidate_accepted",
            "candidate_rejected",
            "abandoned_evidence",
        }:
            issues.append({"code": "invalid_transition_event", "message": f"transition {index} event_type is invalid"})
    for index, event in enumerate(redirects):
        if not isinstance(event, dict):
            issues.append({"code": "invalid_redirect_event", "message": f"redirect {index} must be an object"})
            continue
        event_id = event.get("event_id")
        if not isinstance(event_id, str) or not re.fullmatch(r"redirect-[0-9a-f]{16}", event_id):
            issues.append({"code": "invalid_redirect_id", "message": f"redirect {index} id is invalid"})
        if event.get("causal_proof") is not False:
            issues.append({"code": "redirect_causal_overclaim", "message": f"redirect {index} must not claim causal proof"})
    if report.get("branch_state_transitions_truncated") is not True:
        if report.get("branch_state_transition_count") != len(transitions):
            issues.append({"code": "invalid_transition_count", "message": "transition count must match records when not truncated"})
    if report.get("redirect_events_truncated") is not True:
        if report.get("redirect_event_count") != len(redirects):
            issues.append({"code": "invalid_redirect_count", "message": "redirect count must match records when not truncated"})
    policies = report.get("policies")
    if not isinstance(policies, dict):
        issues.append({"code": "invalid_policies", "message": "policies must be an object"})
    elif policies.get("controller_suppression") != "not_configured":
        issues.append({"code": "controller_suppression_overclaim", "message": "controller suppression must remain not_configured"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "controller backtracking report must not claim AlphaEvolve parity"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    else:
        if readiness.get("explicit_controller_backtracking_decision") is not False:
            issues.append({"code": "controller_decision_overclaim", "message": "explicit controller decision must remain false"})
        if readiness.get("causal_resumed_search_proof") is not False:
            issues.append({"code": "causal_replay_overclaim", "message": "causal resumed-search proof must remain false"})
    return {
        "schema": "libreevolve.controller_backtracking_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _configured_stage_workload(raw_stage: dict) -> dict:
    metadata = raw_stage.get("metadata") if isinstance(raw_stage.get("metadata"), dict) else {}
    stage = metadata.get("stage") if isinstance(metadata.get("stage"), dict) else {}
    workload = stage.get("workload") if isinstance(stage.get("workload"), dict) else None
    source = "stage.workload"
    if workload is None:
        config = stage.get("config") if isinstance(stage.get("config"), dict) else {}
        workload = config.get("workload") if isinstance(config.get("workload"), dict) else None
        source = "stage.config.workload"
    config = stage.get("config") if isinstance(stage.get("config"), dict) else {}
    if workload is None:
        workload = {"type": "simple_check"}
        source = "implicit_simple_check"
    return {
        "type": workload.get("type", "simple_check"),
        "source": source,
        "declared": source != "implicit_simple_check",
        "datasets": copy.deepcopy(workload.get("datasets", []))
        if isinstance(workload.get("datasets"), list)
        else [],
        "budget": copy.deepcopy(workload.get("budget", {}))
        if isinstance(workload.get("budget"), dict)
        else {},
        "checkpoint_policy": workload.get("checkpoint_policy", "not_declared"),
        "score_fields": list(workload.get("score_fields", []))
        if isinstance(workload.get("score_fields"), list)
        else [],
        "artifact_policy": workload.get("artifact_policy", "not_declared"),
        "seed_count": len(config.get("seeds", [])) if isinstance(config.get("seeds"), list) else 0,
    }


def _workload_dataset_digest_evidence(workload_type: str, datasets: object) -> dict:
    dataset_records = datasets if isinstance(datasets, list) else []
    required = workload_type in {"inner_search", "ml_training"}
    dataset_count = sum(1 for dataset in dataset_records if isinstance(dataset, dict))
    sha256_count = sum(
        1
        for dataset in dataset_records
        if isinstance(dataset, dict)
        and isinstance(dataset.get("sha256"), str)
        and len(dataset.get("sha256", "")) == 64
    )
    missing_refs = [
        str(dataset.get("id", f"dataset_{index}"))
        for index, dataset in enumerate(dataset_records)
        if isinstance(dataset, dict) and not isinstance(dataset.get("sha256"), str)
    ]
    complete = (
        dataset_count > 0 and sha256_count == dataset_count
        if required
        else sha256_count == dataset_count
    )
    return {
        "required_for_protocol_claim": required,
        "dataset_count": dataset_count,
        "sha256_count": sha256_count,
        "missing_sha256_dataset_ids": missing_refs[:20],
        "missing_sha256_dataset_ids_truncated": len(missing_refs) > 20,
        "complete": complete,
    }


def _accumulate_workload_runtime_evidence(
    stage: dict,
    raw_stage: Mapping[str, object],
) -> None:
    metrics = raw_stage.get("metrics")
    metric_names = (
        {name for name in metrics if isinstance(name, str)}
        if isinstance(metrics, Mapping)
        else set()
    )
    stage["_observed_metric_names"].update(metric_names)
    score_fields = [
        field for field in stage.get("score_fields", []) if isinstance(field, str)
    ]
    if score_fields and set(score_fields).issubset(metric_names):
        stage["_score_field_complete_count"] += 1
    metadata = raw_stage.get("metadata")
    artifacts = metadata.get("artifacts") if isinstance(metadata, Mapping) else None
    files = artifacts.get("files") if isinstance(artifacts, Mapping) else None
    if not isinstance(files, list):
        return
    for artifact in files:
        if not isinstance(artifact, Mapping):
            continue
        stage["_artifact_file_count"] += 1
        if isinstance(artifact.get("sha256"), str):
            stage["_artifact_sha256_count"] += 1
        path = artifact.get("path")
        if isinstance(path, str) and path:
            stage["_artifact_paths"].add(path)


def _finalize_workload_stage_record(record: dict) -> dict:
    finalized = dict(record)
    observed_metric_names = sorted(finalized.pop("_observed_metric_names", set()))
    score_fields = [
        field for field in finalized.get("score_fields", []) if isinstance(field, str)
    ]
    missing_score_fields = [
        field for field in score_fields if field not in set(observed_metric_names)
    ]
    score_field_complete_count = int(finalized.pop("_score_field_complete_count", 0))
    artifact_file_count = int(finalized.pop("_artifact_file_count", 0))
    artifact_sha256_count = int(finalized.pop("_artifact_sha256_count", 0))
    artifact_paths = sorted(finalized.pop("_artifact_paths", set()))
    finalized["candidate_ids"] = finalized["candidate_ids"][:50]
    finalized["candidate_ids_truncated"] = finalized["candidate_count"] > len(
        finalized["candidate_ids"]
    )
    finalized["score_field_linkage"] = {
        "declared_score_fields": score_fields,
        "observed_metric_names": observed_metric_names,
        "missing_score_fields": missing_score_fields,
        "candidate_count_with_all_score_fields": score_field_complete_count,
        "complete": bool(score_fields)
        and score_field_complete_count == finalized["candidate_count"],
    }
    checkpoint_policy = str(finalized.get("checkpoint_policy", "not_declared"))
    artifact_required = checkpoint_policy == "retained_artifacts" or str(
        finalized.get("artifact_policy", "not_declared")
    ) not in {"", "not_declared", "none"}
    finalized["artifact_evidence"] = {
        "required_for_declared_policy": artifact_required,
        "checkpoint_policy": checkpoint_policy,
        "artifact_policy": finalized.get("artifact_policy", "not_declared"),
        "file_count": artifact_file_count,
        "sha256_count": artifact_sha256_count,
        "sample_paths": artifact_paths[:20],
        "sample_paths_truncated": len(artifact_paths) > 20,
        "completeness_status": (
            "observed"
            if artifact_file_count > 0
            else "missing_retained_artifacts"
            if artifact_required
            else "not_required"
        ),
    }
    return finalized


def validate_evaluator_workload_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.evaluator_workload_report.v1",
            "ok": False,
            "issues": [
                {"code": "invalid_shape", "message": "workload report must be an object"}
            ],
        }
    required = {
        "schema",
        "source",
        "configured_candidate_count",
        "stage_count",
        "declared_workload_stage_count",
        "workload_type_counts",
        "stages",
        "workload_protocol_policy",
        "protocol_readiness",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"workload report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.evaluator_workload_report.v1":
        issues.append({"code": "invalid_schema", "message": "workload report schema is unsupported"})
    if report.get("source") != "runtime_history_configured_stage_results":
        issues.append({"code": "invalid_source", "message": "workload report source is unsupported"})
    stages = report.get("stages")
    if not isinstance(stages, list):
        issues.append({"code": "invalid_stages", "message": "workload report stages must be a list"})
        stages = []
    allowed_types = {"simple_check", "inner_search", "ml_training", "custom"}
    counted = 0
    declared = 0
    type_counts: dict[str, int] = {}
    for index, stage in enumerate(stages):
        if not isinstance(stage, dict):
            issues.append({"code": "invalid_stage", "message": f"workload stage {index} must be an object"})
            continue
        for field in ("name", "stage_index", "workload_type", "candidate_count", "passed", "failed"):
            if field not in stage:
                issues.append({"code": "missing_stage_field", "message": f"workload stage {index} missing {field}"})
        workload_type = stage.get("workload_type")
        if workload_type not in allowed_types:
            issues.append({"code": "invalid_workload_type", "message": f"workload stage {index} has invalid type"})
        candidate_count = stage.get("candidate_count")
        if isinstance(candidate_count, int) and not isinstance(candidate_count, bool):
            counted += candidate_count
            type_counts[str(workload_type)] = type_counts.get(str(workload_type), 0) + candidate_count
            passed = stage.get("passed")
            failed = stage.get("failed")
            if (
                isinstance(passed, int)
                and not isinstance(passed, bool)
                and isinstance(failed, int)
                and not isinstance(failed, bool)
                and candidate_count != passed + failed
            ):
                issues.append({"code": "invalid_stage_counts", "message": f"workload stage {index} counts do not add up"})
        else:
            issues.append({"code": "invalid_candidate_count", "message": f"workload stage {index} candidate_count must be int"})
        if stage.get("declared") is True:
            declared += 1
        if not isinstance(stage.get("datasets"), list):
            issues.append({"code": "invalid_datasets", "message": f"workload stage {index} datasets must be a list"})
        if not isinstance(stage.get("budget"), dict):
            issues.append({"code": "invalid_budget", "message": f"workload stage {index} budget must be an object"})
        if not isinstance(stage.get("score_fields"), list):
            issues.append({"code": "invalid_score_fields", "message": f"workload stage {index} score_fields must be a list"})
        if not isinstance(stage.get("dataset_digest_evidence"), dict):
            issues.append({"code": "invalid_dataset_digest_evidence", "message": f"workload stage {index} dataset_digest_evidence must be an object"})
        if not isinstance(stage.get("score_field_linkage"), dict):
            issues.append({"code": "invalid_score_field_linkage", "message": f"workload stage {index} score_field_linkage must be an object"})
        if not isinstance(stage.get("artifact_evidence"), dict):
            issues.append({"code": "invalid_artifact_evidence", "message": f"workload stage {index} artifact_evidence must be an object"})
        if not isinstance(stage.get("protocol_execution"), dict):
            issues.append({"code": "invalid_protocol_execution", "message": f"workload stage {index} protocol_execution must be an object"})
    if isinstance(report.get("stage_count"), int) and not isinstance(report.get("stage_count"), bool):
        if report["stage_count"] != len(stages):
            issues.append({"code": "invalid_stage_count", "message": "stage_count must equal stages length"})
    else:
        issues.append({"code": "invalid_stage_count", "message": "stage_count must be an int"})
    declared_reported = report.get("declared_workload_stage_count")
    if isinstance(declared_reported, int) and not isinstance(declared_reported, bool):
        if declared_reported != declared:
            issues.append({"code": "invalid_declared_count", "message": "declared workload count mismatch"})
    else:
        issues.append({"code": "invalid_declared_count", "message": "declared workload count must be an int"})
    if isinstance(report.get("workload_type_counts"), dict):
        if report["workload_type_counts"] != dict(sorted(type_counts.items())):
            issues.append({"code": "invalid_type_counts", "message": "workload type counts mismatch"})
    else:
        issues.append({"code": "invalid_type_counts", "message": "workload_type_counts must be an object"})
    protocol_policy = report.get("workload_protocol_policy")
    if not isinstance(protocol_policy, dict):
        issues.append({"code": "invalid_workload_protocol_policy", "message": "workload_protocol_policy must be an object"})
    else:
        if protocol_policy.get("schema") != "libreevolve.evaluator_workload_protocol_policy.v1":
            issues.append({"code": "invalid_workload_protocol_policy_schema", "message": "workload_protocol_policy schema is unsupported"})
        if protocol_policy.get("paper_claim_ready") is not False:
            issues.append({"code": "workload_protocol_overclaim", "message": "workload protocol policy must not claim paper readiness"})
    readiness = report.get("protocol_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_protocol_readiness", "message": "protocol_readiness must be an object"})
    elif readiness.get("claim_ready") is not False:
        issues.append({"code": "workload_protocol_overclaim", "message": "protocol_readiness must not claim paper readiness"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "workload report must not claim AlphaEvolve workload parity"})
    return {
        "schema": "libreevolve.evaluator_workload_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _finalize_cascade_stage_record(record: dict) -> dict:
    finalized = dict(record)
    finalized["candidate_count"] = finalized.pop("entered")
    finalized["promotion_rate"] = (
        finalized["passed"] / finalized["candidate_count"]
        if finalized["candidate_count"]
        else None
    )
    finalized["failure_reasons"] = dict(sorted(finalized["failure_reasons"].items()))
    finalized["candidate_ids"] = finalized["candidate_ids"][:50]
    finalized["candidate_ids_truncated"] = finalized["candidate_count"] > len(
        finalized["candidate_ids"]
    )
    finalized["elapsed_sec"] = round(finalized["elapsed_sec"], 9)
    return finalized


def validate_evaluation_cascade_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.evaluation_cascade_report.v1",
            "ok": False,
            "issues": [{"code": "invalid_shape", "message": "cascade report must be an object"}],
        }
    required = {
        "schema",
        "source",
        "configured_candidate_count",
        "stage_count",
        "stages",
        "candidate_stage_records_limit",
        "candidate_stage_records_truncated",
        "candidate_stage_record_count",
        "candidate_stage_records",
        "denominator_policy",
        "source_identity_summary",
        "main_test_exposure_count",
        "early_prune_count",
        "stop_reasons",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append({"code": "missing_fields", "message": f"cascade report missing fields: {sorted(missing)}"})
    if report.get("schema") != "libreevolve.evaluation_cascade_report.v1":
        issues.append({"code": "invalid_schema", "message": "cascade report schema is unsupported"})
    if report.get("source") != "runtime_history_configured_stage_results":
        issues.append({"code": "invalid_source", "message": "cascade report source is unsupported"})
    stages = report.get("stages")
    if not isinstance(stages, list):
        issues.append({"code": "invalid_stages", "message": "cascade report stages must be a list"})
        stages = []
    if isinstance(report.get("stage_count"), int) and not isinstance(report.get("stage_count"), bool):
        if report["stage_count"] != len(stages):
            issues.append({"code": "stage_count_mismatch", "message": "stage_count must match stages length"})
    for index, stage in enumerate(stages):
        if not isinstance(stage, dict):
            issues.append({"code": "invalid_stage", "message": "cascade stage records must be objects"})
            continue
        for key in ("candidate_count", "passed", "failed"):
            value = stage.get(key)
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                issues.append({"code": "invalid_stage_count", "message": f"stage {index} {key} must be a non-negative integer"})
        if (
            isinstance(stage.get("candidate_count"), int)
            and isinstance(stage.get("passed"), int)
            and isinstance(stage.get("failed"), int)
            and stage["candidate_count"] != stage["passed"] + stage["failed"]
        ):
            issues.append({"code": "stage_count_inconsistent", "message": f"stage {index} counts must balance"})
        if not isinstance(stage.get("source"), dict):
            issues.append({"code": "invalid_stage_source", "message": f"stage {index} source must be an object"})
        if not isinstance(stage.get("difficulty_or_scale"), dict):
            issues.append({"code": "invalid_stage_difficulty", "message": f"stage {index} difficulty_or_scale must be an object"})
    candidate_stage_records = report.get("candidate_stage_records")
    if not isinstance(candidate_stage_records, list):
        issues.append({"code": "invalid_candidate_stage_records", "message": "candidate_stage_records must be a list"})
        candidate_stage_records = []
    record_count = report.get("candidate_stage_record_count")
    record_limit = report.get("candidate_stage_records_limit")
    records_truncated = report.get("candidate_stage_records_truncated")
    if not isinstance(record_count, int) or isinstance(record_count, bool) or record_count < 0:
        issues.append({"code": "invalid_candidate_stage_record_count", "message": "candidate_stage_record_count must be a non-negative integer"})
    if not isinstance(record_limit, int) or isinstance(record_limit, bool) or record_limit < 0:
        issues.append({"code": "invalid_candidate_stage_records_limit", "message": "candidate_stage_records_limit must be a non-negative integer"})
    if not isinstance(records_truncated, bool):
        issues.append({"code": "invalid_candidate_stage_records_truncated", "message": "candidate_stage_records_truncated must be a boolean"})
    if (
        isinstance(record_count, int)
        and not isinstance(record_count, bool)
        and isinstance(records_truncated, bool)
    ):
        if records_truncated is False and len(candidate_stage_records) != record_count:
            issues.append({"code": "candidate_stage_record_count_mismatch", "message": "untruncated candidate_stage_records length must match count"})
        if records_truncated is True and len(candidate_stage_records) > record_count:
            issues.append({"code": "candidate_stage_record_count_mismatch", "message": "truncated candidate_stage_records cannot exceed count"})
    for index, record in enumerate(candidate_stage_records):
        if not isinstance(record, dict):
            issues.append({"code": "invalid_candidate_stage_record", "message": "candidate stage records must be objects"})
            continue
        for key in (
            "program_id",
            "stage_name",
            "history_path",
            "metadata_path",
            "stage_result_id",
        ):
            if not isinstance(record.get(key), str) or not record.get(key):
                issues.append({"code": "invalid_candidate_stage_record_field", "message": f"candidate stage record {index} {key} must be non-empty text"})
        if not isinstance(record.get("accounting"), dict):
            issues.append({"code": "invalid_candidate_stage_accounting", "message": f"candidate stage record {index} accounting must be an object"})
        if not isinstance(record.get("source"), dict):
            issues.append({"code": "invalid_candidate_stage_source", "message": f"candidate stage record {index} source must be an object"})
    denominator_policy = report.get("denominator_policy")
    if not isinstance(denominator_policy, dict):
        issues.append({"code": "invalid_denominator_policy", "message": "denominator_policy must be an object"})
    else:
        if denominator_policy.get("schema") != "libreevolve.evaluation_cascade_denominator_policy.v1":
            issues.append({"code": "invalid_denominator_policy_schema", "message": "denominator_policy schema is unsupported"})
        if denominator_policy.get("paper_claim_ready") is not False:
            issues.append({"code": "cascade_denominator_overclaim", "message": "denominator policy must not claim paper readiness"})
    if not isinstance(report.get("source_identity_summary"), dict):
        issues.append({"code": "invalid_source_identity_summary", "message": "source_identity_summary must be an object"})
    configured = report.get("configured_candidate_count")
    exposure = report.get("main_test_exposure_count")
    early = report.get("early_prune_count")
    if all(isinstance(value, int) and not isinstance(value, bool) for value in (configured, exposure, early)):
        if configured < 0 or exposure < 0 or early < 0 or configured != exposure + early:
            issues.append({"code": "candidate_count_inconsistent", "message": "configured candidate counts must balance"})
    else:
        issues.append({"code": "invalid_candidate_counts", "message": "candidate counts must be non-negative integers"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaimed", "message": "current cascade report must not claim AlphaEvolve readiness"})
    return {
        "schema": "libreevolve.evaluation_cascade_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def validate_cascade_hypothesis_test_policy_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.cascade_hypothesis_test_policy_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "cascade hypothesis-test policy report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "cascade_report_schema",
        "configured_stage_policy_count",
        "observed_stage_count",
        "stage_policies",
        "current_policy",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": (
                    "cascade hypothesis-test policy report missing fields: "
                    f"{sorted(missing)}"
                ),
            }
        )
    if report.get("schema") != "libreevolve.cascade_hypothesis_test_policy_report.v1":
        issues.append(
            {
                "code": "invalid_schema",
                "message": "cascade hypothesis-test policy report schema is unsupported",
            }
        )
    if report.get("source") != "config_eval_stages_and_evaluation_cascade_report":
        issues.append(
            {
                "code": "invalid_source",
                "message": "cascade hypothesis-test policy report source is unsupported",
            }
        )
    if report.get("cascade_report_schema") != "libreevolve.evaluation_cascade_report.v1":
        issues.append(
            {
                "code": "invalid_cascade_report_schema",
                "message": "cascade report schema linkage is unsupported",
            }
        )
    stage_policies = report.get("stage_policies")
    if not isinstance(stage_policies, list):
        issues.append(
            {
                "code": "invalid_stage_policies",
                "message": "stage_policies must be a list",
            }
        )
        stage_policies = []
    if (
        isinstance(report.get("configured_stage_policy_count"), int)
        and not isinstance(report.get("configured_stage_policy_count"), bool)
    ):
        if report["configured_stage_policy_count"] != len(stage_policies):
            issues.append(
                {
                    "code": "stage_policy_count_mismatch",
                    "message": "configured_stage_policy_count must match stage_policies length",
                }
            )
    else:
        issues.append(
            {
                "code": "invalid_stage_policy_count",
                "message": "configured_stage_policy_count must be a non-negative integer",
            }
        )
    for index, stage in enumerate(stage_policies):
        if not isinstance(stage, dict):
            issues.append(
                {
                    "code": "invalid_stage_policy",
                    "message": "stage policy records must be objects",
                }
            )
            continue
        for key in (
            "stage_id",
            "stage_name",
            "stage_role",
            "inferred_role",
            "role_source",
            "promotion_decision_source",
        ):
            if not isinstance(stage.get(key), str) or not stage.get(key):
                issues.append(
                    {
                        "code": "invalid_stage_policy_field",
                        "message": f"stage policy {index} {key} must be non-empty text",
                    }
                )
        allowed_stage_roles = {
            "small_scale_filter",
            "intermediate_filter",
            "main_test",
        }
        if stage.get("inferred_role") not in allowed_stage_roles:
            issues.append(
                {
                    "code": "invalid_stage_role",
                    "message": f"stage policy {index} inferred_role is unsupported",
                }
            )
        if stage.get("stage_role") not in allowed_stage_roles:
            issues.append(
                {
                    "code": "invalid_stage_role",
                    "message": f"stage policy {index} stage_role is unsupported",
                }
            )
        configured_role = stage.get("configured_role")
        if configured_role is not None and configured_role not in allowed_stage_roles:
            issues.append(
                {
                    "code": "invalid_configured_stage_role",
                    "message": f"stage policy {index} configured_role is unsupported",
                }
            )
        role_source = stage.get("role_source")
        if role_source not in {"configured", "inferred_from_stage_order"}:
            issues.append(
                {
                    "code": "invalid_stage_role_source",
                    "message": f"stage policy {index} role_source is unsupported",
                }
            )
        elif role_source == "configured":
            if configured_role != stage.get("stage_role"):
                issues.append(
                    {
                        "code": "configured_stage_role_mismatch",
                        "message": "configured role must match stage_role",
                    }
                )
        elif configured_role is not None:
            issues.append(
                {
                    "code": "configured_stage_role_source_mismatch",
                    "message": "configured_role requires configured role_source",
                }
            )
        statistical_test = stage.get("statistical_test")
        statistical_configured = (
            isinstance(statistical_test, dict)
            and statistical_test.get("configured") is True
        )
        expected_promotion_source = (
            "statistical_hypothesis_test"
            if statistical_configured
            else "fixed_threshold_and_artifact_checks"
        )
        if stage.get("promotion_decision_source") != expected_promotion_source:
            issues.append(
                {
                    "code": "promotion_source_overclaim",
                    "message": (
                        "cascade promotion source must match configured "
                        "hypothesis-test evidence"
                    ),
                }
            )
        if not isinstance(statistical_test, dict):
            issues.append(
                {
                    "code": "invalid_statistical_test",
                    "message": f"stage policy {index} statistical_test must be an object",
                }
            )
            continue
        if statistical_test.get("configured") not in {False, True}:
            issues.append(
                {
                    "code": "invalid_statistical_test_configured",
                    "message": "statistical_test.configured must be boolean",
                }
            )
        for count_field in ("test_count", "passed", "failed"):
            value = statistical_test.get(count_field, 0)
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                issues.append(
                    {
                        "code": "invalid_statistical_test_count",
                        "message": f"statistical_test.{count_field} must be non-negative integer",
                    }
                )
        if (
            isinstance(statistical_test.get("test_count"), int)
            and isinstance(statistical_test.get("passed"), int)
            and isinstance(statistical_test.get("failed"), int)
            and statistical_test["test_count"]
            != statistical_test["passed"] + statistical_test["failed"]
        ):
            issues.append(
                {
                    "code": "statistical_test_count_inconsistent",
                    "message": "statistical test pass/fail counts must balance",
                }
            )
        if statistical_test.get("sequential_stopping") not in {False, True}:
            issues.append(
                {
                    "code": "invalid_sequential_stopping",
                    "message": "statistical_test.sequential_stopping must be boolean",
                }
            )
        sequential_stop_count = statistical_test.get("sequential_stop_count", 0)
        if (
            not isinstance(sequential_stop_count, int)
            or isinstance(sequential_stop_count, bool)
            or sequential_stop_count < 0
        ):
            issues.append(
                {
                    "code": "invalid_sequential_stop_count",
                    "message": "statistical_test.sequential_stop_count must be non-negative integer",
                }
            )
        if statistical_test.get("error_budget_configured") not in {False, True}:
            issues.append(
                {
                    "code": "invalid_error_budget_configured",
                    "message": "statistical_test.error_budget_configured must be boolean",
                }
            )
        for count_field in ("error_budget_passed", "error_budget_failed"):
            value = statistical_test.get(count_field, 0)
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                issues.append(
                    {
                        "code": "invalid_error_budget_count",
                        "message": f"statistical_test.{count_field} must be non-negative integer",
                    }
                )
        false_promotion_budget = statistical_test.get("false_promotion_budget")
        if false_promotion_budget is not None:
            if not isinstance(false_promotion_budget, dict):
                issues.append(
                    {
                        "code": "invalid_false_promotion_budget",
                        "message": "statistical_test.false_promotion_budget must be null or an object",
                    }
                )
            else:
                max_rate = false_promotion_budget.get("max_rate")
                observed_count = false_promotion_budget.get("observed_count")
                if (
                    not isinstance(max_rate, (int, float))
                    or isinstance(max_rate, bool)
                    or max_rate <= 0
                    or max_rate >= 0.5
                ):
                    issues.append(
                        {
                            "code": "invalid_false_promotion_budget_rate",
                            "message": "false_promotion_budget.max_rate must be > 0 and < 0.5",
                        }
                    )
                if (
                    not isinstance(observed_count, int)
                    or isinstance(observed_count, bool)
                    or observed_count < 0
                ):
                    issues.append(
                        {
                            "code": "invalid_false_promotion_budget_count",
                            "message": "false_promotion_budget.observed_count must be non-negative integer",
                        }
                    )
        false_rejection_budget = statistical_test.get("false_rejection_budget")
        if false_rejection_budget is not None:
            if not isinstance(false_rejection_budget, dict):
                issues.append(
                    {
                        "code": "invalid_false_rejection_budget",
                        "message": "statistical_test.false_rejection_budget must be null or an object",
                    }
                )
            else:
                max_rate = false_rejection_budget.get("max_rate")
                min_effect_size = false_rejection_budget.get("min_effect_size")
                observed_count = false_rejection_budget.get("observed_count")
                if (
                    not isinstance(max_rate, (int, float))
                    or isinstance(max_rate, bool)
                    or max_rate <= 0
                    or max_rate >= 1
                ):
                    issues.append(
                        {
                            "code": "invalid_false_rejection_budget_rate",
                            "message": "false_rejection_budget.max_rate must be > 0 and < 1",
                        }
                    )
                if (
                    not isinstance(min_effect_size, (int, float))
                    or isinstance(min_effect_size, bool)
                    or min_effect_size <= 0
                ):
                    issues.append(
                        {
                            "code": "invalid_false_rejection_effect_size",
                            "message": "false_rejection_budget.min_effect_size must be > 0",
                        }
                    )
                if (
                    not isinstance(observed_count, int)
                    or isinstance(observed_count, bool)
                    or observed_count < 0
                ):
                    issues.append(
                        {
                            "code": "invalid_false_rejection_budget_count",
                            "message": "false_rejection_budget.observed_count must be non-negative integer",
                        }
                    )
    current_policy = report.get("current_policy")
    if not isinstance(current_policy, dict):
        issues.append(
            {
                "code": "invalid_current_policy",
                "message": "current_policy must be an object",
            }
        )
    else:
        if (
            current_policy.get("schema")
            != "libreevolve.cascade_promotion_policy_boundary.v1"
        ):
            issues.append(
                {
                    "code": "invalid_current_policy_schema",
                    "message": "current policy schema is unsupported",
                }
            )
        any_statistical_test = any(
            isinstance(stage, dict)
            and isinstance(stage.get("statistical_test"), dict)
            and stage["statistical_test"].get("configured") is True
            for stage in stage_policies
        )
        any_confidence_records = any(
            isinstance(stage, dict)
            and isinstance(stage.get("statistical_test"), dict)
            and isinstance(
                stage["statistical_test"].get("confidence_interval_count", 0),
                int,
            )
            and not isinstance(
                stage["statistical_test"].get("confidence_interval_count", 0),
                bool,
            )
            and stage["statistical_test"].get("confidence_interval_count", 0) > 0
            for stage in stage_policies
        )
        any_p_value_records = any(
            isinstance(stage, dict)
            and isinstance(stage.get("statistical_test"), dict)
            and isinstance(stage["statistical_test"].get("p_value_count", 0), int)
            and not isinstance(
                stage["statistical_test"].get("p_value_count", 0),
                bool,
            )
            and stage["statistical_test"].get("p_value_count", 0) > 0
            for stage in stage_policies
        )
        any_sequential_stopping = any(
            isinstance(stage, dict)
            and isinstance(stage.get("statistical_test"), dict)
            and stage["statistical_test"].get("sequential_stopping") is True
            for stage in stage_policies
        )
        any_false_promotion_budget = any(
            isinstance(stage, dict)
            and isinstance(stage.get("statistical_test"), dict)
            and isinstance(
                stage["statistical_test"].get("false_promotion_budget"), dict
            )
            for stage in stage_policies
        )
        any_false_rejection_budget = any(
            isinstance(stage, dict)
            and isinstance(stage.get("statistical_test"), dict)
            and isinstance(
                stage["statistical_test"].get("false_rejection_budget"), dict
            )
            for stage in stage_policies
        )
        expected_bool_fields = {
            "statistical_hypothesis_tests_supported": any_statistical_test,
            "confidence_intervals_supported": any_confidence_records,
            "p_values_supported": any_p_value_records,
            "sequential_stopping_supported": any_sequential_stopping,
            "false_promotion_budget_supported": any_false_promotion_budget,
            "false_rejection_budget_supported": any_false_rejection_budget,
        }
        for field, expected in expected_bool_fields.items():
            if current_policy.get(field) is not expected:
                issues.append(
                    {
                        "code": f"policy_{field}_mismatch",
                        "message": f"current_policy.{field} must match stage evidence",
                    }
                )
        false_fields = {
            "paper_claim_ready": "policy_paper_claim_ready_overclaim",
        }
        for field, code in false_fields.items():
            if current_policy.get(field) is not False:
                issues.append(
                    {
                        "code": code,
                        "message": f"current_policy.{field} must be false",
                    }
                )
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append(
            {
                "code": "invalid_claim_readiness",
                "message": "claim_readiness must be an object",
            }
        )
    else:
        if readiness.get("alphaevolve_section_2_4_hypothesis_testing") is not False:
            issues.append(
                {
                    "code": "alphaevolve_hypothesis_testing_overclaim",
                    "message": "current cascade policy must not claim Section 2.4 parity",
                }
            )
    if report.get("claim_ready") is not False:
        issues.append(
            {
                "code": "claim_ready_overclaim",
                "message": "current cascade hypothesis-test report must not claim readiness",
            }
        )
    return {
        "schema": "libreevolve.cascade_hypothesis_test_policy_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _distributed_pipeline_topology_report(
    startup_manifest: Mapping[str, object],
    budget: RunBudget,
) -> dict:
    config = (
        startup_manifest.get("config")
        if isinstance(startup_manifest.get("config"), Mapping)
        else {}
    )
    backends = config.get("backends") if isinstance(config.get("backends"), list) else []
    eval_stages = (
        config.get("eval_stages")
        if isinstance(config.get("eval_stages"), list)
        else []
    )
    role_backend_indices = (
        config.get("llm_role_backend_indices")
        if isinstance(config.get("llm_role_backend_indices"), Mapping)
        else {}
    )
    llm_nodes = [
        _pipeline_llm_sampler_node(index, backend, role_backend_indices)
        for index, backend in enumerate(backends)
        if isinstance(backend, Mapping)
    ]
    evaluator_nodes = _pipeline_evaluation_nodes(eval_stages)
    nodes = [
        {
            "node_id": "controller:local",
            "role": "controller",
            "implementation": "single_process_serial_loop",
            "worker_identity": "process_main_thread",
            "async_worker": False,
            "state_source": "runtime.history.controller_state",
        },
        {
            "node_id": "database:local",
            "role": "program_database",
            "implementation": "in_process_program_database",
            "worker_identity": "process_main_thread",
            "async_worker": False,
            "state_source": "history_and_archive_jsonl_artifacts",
        },
        *llm_nodes,
        *evaluator_nodes,
    ]
    blocking_edges = [
        {
            "edge_id": "database_sample_to_controller",
            "from": "database:local",
            "to": "controller:local",
            "dependency": "parent_and_inspiration_sampling",
            "blocking": True,
            "queue": None,
        },
        {
            "edge_id": "controller_to_llm_sampler",
            "from": "controller:local",
            "to": "llm_sampler:*",
            "dependency": "mutation_generation_call",
            "blocking": True,
            "queue": None,
        },
        {
            "edge_id": "controller_to_evaluation_node",
            "from": "controller:local",
            "to": "evaluation_node:*",
            "dependency": "candidate_validation_and_scoring",
            "blocking": True,
            "queue": None,
        },
        {
            "edge_id": "evaluation_to_database_admission",
            "from": "evaluation_node:*",
            "to": "database:local",
            "dependency": "archive_admission_after_evaluation",
            "blocking": True,
            "queue": None,
        },
    ]
    report = {
        "schema": "libreevolve.distributed_pipeline_topology_report.v1",
        "source": "startup_manifest_config_and_runtime_budget",
        "node_count": len(nodes),
        "nodes": nodes,
        "queue_count": 0,
        "queues": [],
        "blocking_edge_count": len(blocking_edges),
        "blocking_edges": blocking_edges,
        "dispatch_policy": {
            "schema": "libreevolve.pipeline_dispatch_policy.v1",
            "controller": "single_process_serial_loop",
            "llm_sampler_dispatch": "inline_blocking_call",
            "evaluation_dispatch": "inline_blocking_local_subprocess",
            "database_admission": "synchronous_after_candidate_evaluation",
            "deterministic_merge_order": "loop_order",
            "asyncio_pipeline": False,
        },
        "throughput_budget_linkage": {
            "budget_source": "runtime.consumed_and_controller_budget_events",
            "generations_completed": budget.generations_completed,
            "evaluations": budget.evaluations,
            "llm_calls": budget.llm_calls,
            "queued_work_accounted": False,
            "worker_fanout_accounted": False,
        },
        "pending_work_checkpoint": {
            "supported": False,
            "queued_proposals": 0,
            "running_proposals": 0,
            "queued_evaluations": 0,
            "running_evaluations": 0,
            "in_flight_llm_calls": 0,
            "state_source": "terminal_controller_state_only",
        },
        "claim_ready": False,
        "claim_readiness": {
            "alphaevolve_async_pipeline_topology": False,
            "controller_sampler_evaluator_roles_named": True,
            "queue_dependency_graph": False,
            "worker_identity_and_fanout": False,
            "pending_work_checkpoint": False,
            "remaining_gap": [
                "async_controller_queues",
                "llm_sampler_worker_identities",
                "evaluation_node_worker_identities",
                "queue_capacities_and_dependency_edges",
                "throughput_budget_dispatch_telemetry",
                "pending_work_checkpoint_state",
            ],
        },
    }
    report["validation"] = validate_distributed_pipeline_topology_report(report)
    return report


def _pipeline_llm_sampler_node(
    index: int,
    backend: Mapping[str, object],
    role_backend_indices: Mapping[str, object],
) -> dict:
    roles = [
        role
        for role, indices in role_backend_indices.items()
        if isinstance(role, str)
        and isinstance(indices, list)
        and index in [item for item in indices if isinstance(item, int)]
    ]
    return {
        "node_id": f"llm_sampler:backend_{index}",
        "role": "llm_sampler",
        "backend_index": index,
        "provider": backend.get("type"),
        "model": backend.get("model"),
        "role_ownership": sorted(roles) if roles else ["default_ensemble_pool"],
        "implementation": "in_process_ensemble_call",
        "worker_identity": "process_main_thread",
        "async_worker": False,
        "queue": None,
    }


def _pipeline_evaluation_nodes(eval_stages: list) -> list[dict]:
    if not eval_stages:
        return [
            {
                "node_id": "evaluation_node:default_validator",
                "role": "evaluation_node",
                "stage_index": None,
                "stage_name": None,
                "mode": "external_validator",
                "implementation": "local_subprocess_validator",
                "worker_identity": "process_main_thread_spawns_subprocess",
                "async_worker": False,
                "queue": None,
            }
        ]
    nodes: list[dict] = []
    for index, stage in enumerate(eval_stages):
        if not isinstance(stage, Mapping):
            continue
        name = str(stage.get("name", f"stage_{index}"))
        nodes.append(
            {
                "node_id": f"evaluation_node:stage_{index}:{name}",
                "role": "evaluation_node",
                "stage_index": index,
                "stage_name": name,
                "mode": str(stage.get("mode", "external_validator")),
                "implementation": (
                    "candidate_embedded_evaluate_subprocess"
                    if stage.get("mode") == "embedded_evaluate"
                    else "local_subprocess_validator"
                ),
                "worker_identity": "process_main_thread_spawns_subprocess",
                "async_worker": False,
                "queue": None,
            }
        )
    return nodes


def validate_distributed_pipeline_topology_report(report: object) -> dict:
    issues: list[dict] = []
    if not isinstance(report, dict):
        return {
            "schema": "libreevolve.distributed_pipeline_topology_report.v1",
            "ok": False,
            "issues": [
                {
                    "code": "invalid_shape",
                    "message": "distributed pipeline topology report must be an object",
                }
            ],
        }
    required = {
        "schema",
        "source",
        "node_count",
        "nodes",
        "queue_count",
        "queues",
        "blocking_edge_count",
        "blocking_edges",
        "dispatch_policy",
        "throughput_budget_linkage",
        "pending_work_checkpoint",
        "claim_ready",
        "claim_readiness",
    }
    missing = required - set(report)
    if missing:
        issues.append(
            {
                "code": "missing_fields",
                "message": f"pipeline topology report missing fields: {sorted(missing)}",
            }
        )
    if report.get("schema") != "libreevolve.distributed_pipeline_topology_report.v1":
        issues.append({"code": "invalid_schema", "message": "pipeline topology schema is unsupported"})
    if report.get("source") != "startup_manifest_config_and_runtime_budget":
        issues.append({"code": "invalid_source", "message": "pipeline topology source is unsupported"})
    nodes = report.get("nodes")
    if not isinstance(nodes, list):
        issues.append({"code": "invalid_nodes", "message": "nodes must be a list"})
        nodes = []
    else:
        for index, node in enumerate(nodes):
            if not isinstance(node, dict):
                issues.append({"code": "invalid_node", "message": f"node {index} must be an object"})
                continue
            if not isinstance(node.get("node_id"), str) or not node.get("node_id"):
                issues.append({"code": "invalid_node_id", "message": f"node {index} must include node_id"})
            if node.get("role") not in {"controller", "program_database", "llm_sampler", "evaluation_node"}:
                issues.append({"code": "invalid_node_role", "message": f"node {index} role is unsupported"})
            if node.get("async_worker") is not False:
                issues.append({"code": "async_worker_overclaim", "message": f"node {index} must not claim async worker support"})
    _validate_report_count(report, "node_count", len(nodes), issues)
    queues = report.get("queues")
    if not isinstance(queues, list):
        issues.append({"code": "invalid_queues", "message": "queues must be a list"})
        queues = []
    _validate_report_count(report, "queue_count", len(queues), issues)
    edges = report.get("blocking_edges")
    if not isinstance(edges, list):
        issues.append({"code": "invalid_edges", "message": "blocking_edges must be a list"})
        edges = []
    else:
        for index, edge in enumerate(edges):
            if not isinstance(edge, dict):
                issues.append({"code": "invalid_edge", "message": f"edge {index} must be an object"})
                continue
            if edge.get("blocking") is not True:
                issues.append({"code": "nonblocking_edge_overclaim", "message": f"edge {index} must remain blocking"})
            if edge.get("queue") is not None:
                issues.append({"code": "queue_edge_overclaim", "message": f"edge {index} must not claim queue linkage"})
    _validate_report_count(report, "blocking_edge_count", len(edges), issues)
    dispatch = report.get("dispatch_policy")
    if not isinstance(dispatch, dict):
        issues.append({"code": "invalid_dispatch_policy", "message": "dispatch_policy must be an object"})
    elif dispatch.get("asyncio_pipeline") is not False:
        issues.append({"code": "async_pipeline_overclaim", "message": "dispatch_policy must not claim asyncio pipeline support"})
    pending = report.get("pending_work_checkpoint")
    if not isinstance(pending, dict):
        issues.append({"code": "invalid_pending_work_checkpoint", "message": "pending_work_checkpoint must be an object"})
    elif pending.get("supported") is not False:
        issues.append({"code": "pending_checkpoint_overclaim", "message": "pending work checkpoint must remain unsupported"})
    if report.get("claim_ready") is not False:
        issues.append({"code": "claim_ready_overclaim", "message": "pipeline topology report must not claim AlphaEvolve readiness"})
    readiness = report.get("claim_readiness")
    if not isinstance(readiness, dict):
        issues.append({"code": "invalid_claim_readiness", "message": "claim_readiness must be an object"})
    elif readiness.get("alphaevolve_async_pipeline_topology") is not False:
        issues.append({"code": "async_topology_overclaim", "message": "claim_readiness must not claim async topology parity"})
    return {
        "schema": "libreevolve.distributed_pipeline_topology_report.v1",
        "ok": not issues,
        "issues": issues,
    }


def _runtime_controller_state(run_dir: Path, budget: RunBudget) -> dict:
    event_stream = _controller_budget_event_stream_summary(
        run_dir / "controller_budget_events.jsonl"
    )
    state = {
        "schema": "libreevolve.controller_state.v1",
        "status": "terminal_synchronous_controller_drained",
        "controller_model": "single_process_serial_loop",
        "resume_scope": "terminal_drained_state_only",
        "pending_work": {
            "queued_proposals": 0,
            "running_proposals": 0,
            "queued_evaluations": 0,
            "running_evaluations": 0,
            "in_flight_llm_calls": 0,
            "pending_archive_admissions": 0,
            "partially_completed_generation": False,
        },
        "terminal": {
            "stop_reason": budget.stop_reason,
            "generations_completed": budget.generations_completed,
            "evaluations": budget.evaluations,
        },
        "event_stream": event_stream,
        "limitations": [
            "synchronous_terminal_snapshot_not_async_queue_checkpoint",
            "no_mid_generation_resume_boundary",
            "provider_outputs_not_replayed",
            "plugin_internal_pending_work_reported_separately",
        ],
    }
    state["validation"] = validate_controller_state_snapshot(state)
    return state


def _controller_budget_event_stream_summary(path: Path) -> dict:
    if not path.exists():
        return {
            "path": path.name,
            "status": "absent",
            "event_count": 0,
            "last_sequence": None,
            "last_kind": None,
            "replay_scope": "budget_counters_only",
        }
    event_count = 0
    last_sequence = None
    last_kind = None
    for event in iter_strict_jsonl_objects(
        path,
        stream_name="controller_budget_events.jsonl",
    ):
        event_count += 1
        last_sequence = event.get("sequence")
        last_kind = event.get("kind")
    return {
        "path": path.name,
        "status": "present",
        "event_count": event_count,
        "last_sequence": last_sequence,
        "last_kind": last_kind,
        "replay_scope": "budget_counters_only",
    }


def _no_candidate_absence_reason(budget: RunBudget) -> str:
    if budget.stop_reason in {
        "max_evaluations",
        "max_evaluator_seconds",
        "max_evaluator_subprocess_attempts",
        "max_evaluator_stage_samples",
        "max_evaluator_retry_attempts",
        "max_evaluator_timeouts",
        "max_evaluator_sample_budget_exhaustions",
        "max_evaluator_stage_budget_exhaustions",
        "max_runtime_seconds",
    }:
        return f"{budget.stop_reason}_before_seed_evaluation"
    if budget.stop_reason == "aborted":
        return "aborted_before_evaluation"
    if budget.stop_reason:
        return f"{budget.stop_reason}_before_evaluation"
    return "no_evaluations_recorded"


def _phase_role(phase: str) -> str | None:
    if "llm_mutation" in phase:
        return "mutation"
    if "llm_critique" in phase:
        return "critique"
    if "llm_feedback" in phase:
        return "feedback"
    if "llm_meta_prompt" in phase:
        return "meta_prompt"
    if "candidate_evaluation" in phase or "seed_evaluation" in phase:
        return "evaluation"
    if "plugin_" in phase:
        return "plugin"
    if "manifest" in phase or "finalization" in phase:
        return "manifest"
    return None


def _validate_problem_for_evolve(problem: Problem, config: Config) -> None:
    validate_direct_task_description(problem.task_description)
    if not problem.initial_programs and not problem.initial_workspaces:
        raise ValueError("Problem must provide at least one initial program or workspace")
    _validate_initial_workspaces_for_evolve(problem, config)
    _validate_inline_seed_programs_for_evolve(problem, config)
    validate_direct_context_files(problem.context_files)


def _validate_initial_workspaces_for_evolve(problem: Problem, config: Config) -> None:
    if not problem.initial_workspaces:
        return
    if not isinstance(problem.initial_workspaces, list):
        raise ValueError(
            "Problem initial_workspaces must be a list of CandidateWorkspace "
            "objects or workspace records"
        )
    normalized_workspaces: list[CandidateWorkspace] = []
    for index, workspace in enumerate(problem.initial_workspaces):
        try:
            normalized = _normalize_direct_initial_workspace(workspace)
            _validate_workspace_size_for_config(normalized, config)
            _validate_workspace_evolve_blocks(index, normalized)
        except ValueError as exc:
            raise ValueError(
                f"Problem initial_workspaces[{index}] is invalid: {exc}"
            ) from exc
        normalized_workspaces.append(normalized)
    problem.initial_workspaces = normalized_workspaces


def _normalize_direct_initial_workspace(workspace: object) -> CandidateWorkspace:
    if isinstance(workspace, CandidateWorkspace):
        return CandidateWorkspace(
            files=dict(workspace.files),
            primary_file=workspace.primary_file,
            allowed_reserved_paths=workspace.allowed_reserved_paths,
            static_files=workspace.static_files,
        )
    if isinstance(workspace, Mapping):
        return CandidateWorkspace.from_dict(dict(workspace))
    raise ValueError("expected CandidateWorkspace or workspace record mapping")


def _validate_workspace_size_for_config(workspace: CandidateWorkspace, config: Config) -> dict:
    return validate_candidate_workspace_limits(
        workspace.files,
        static_files=workspace.static_files,
        max_files=config.max_candidate_workspace_files,
        max_file_chars=config.max_candidate_file_chars,
        max_total_chars=config.max_candidate_total_chars,
        max_static_file_bytes=config.max_candidate_static_file_bytes,
        max_total_static_bytes=config.max_candidate_total_static_bytes,
    )


def _validate_workspace_evolve_blocks(
    index: int, workspace: CandidateWorkspace
) -> None:
    for path, content in workspace.files.items():
        marker_error = validate_evolve_blocks(content)
        if marker_error is not None:
            raise ValueError(
                f"initial_workspaces[{index}].files[{path!r}] has malformed "
                f"evolve-block markers: {marker_error}"
            )


def _validate_inline_seed_programs_for_evolve(problem: Problem, config: Config) -> None:
    if problem.initial_workspaces:
        return
    if not isinstance(problem.initial_programs, list):
        raise ValueError("Problem initial_programs must be a list of seed program strings")
    for index, code in enumerate(problem.initial_programs):
        if not isinstance(code, str):
            raise ValueError(
                f"Problem initial_programs[{index}] must be a seed program string"
            )
        if len(code) > _MAX_DIRECT_INLINE_SEED_CHARS:
            raise ValueError(
                f"Problem initial_programs[{index}] must be at most "
                f"{_MAX_DIRECT_INLINE_SEED_CHARS} characters"
            )
        try:
            code.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ValueError(
                f"Problem initial_programs[{index}] must be UTF-8 encodable"
            ) from exc
        _validate_workspace_size_for_config(CandidateWorkspace.from_code(code), config)
        marker_error = validate_evolve_blocks(code)
        if marker_error is not None:
            raise ValueError(
                f"Problem initial_programs[{index}] has malformed evolve-block "
                f"markers: {marker_error}"
            )


def _validate_plugins_for_evolve(
    plugins: list[object],
    *,
    mutation_capable: bool,
) -> None:
    for index, plugin in enumerate(plugins):
        if isinstance(plugin, PluginBase):
            continue
        identity = _plugin_identity(plugin, index)
        known_hooks = {
            name: getattr(plugin, name, None)
            for name in (
                "on_generation_start",
                "build_extra_context",
                "prompt_context_metadata",
                "on_evaluated",
                "on_generation_end",
                "run_artifacts_metadata",
            )
        }
        non_callable = [
            name for name, value in known_hooks.items()
            if value is not None and not callable(value)
        ]
        if non_callable:
            raise ValueError(
                "Invalid plugin instance "
                f"{identity['instance_id']}: plugin hook(s) must be callable: "
                + ", ".join(sorted(non_callable))
            )
        callable_hooks = {name for name, value in known_hooks.items() if callable(value)}
        required_hooks = (
            {
                "on_generation_start",
                "build_extra_context",
                "on_evaluated",
                "on_generation_end",
            }
            if mutation_capable
            else {"run_artifacts_metadata"}
        )
        missing = sorted(required_hooks - callable_hooks)
        if not missing:
            continue
        if callable_hooks and not mutation_capable:
            continue
        raise ValueError(
            "Invalid plugin instance "
            f"{identity['instance_id']}: expected PluginBase or callable hook protocol; "
            "missing " + ", ".join(missing)
        )


def _seed_workspace_entries(problem: Problem) -> list[tuple[CandidateWorkspace, dict]]:
    if problem.initial_workspaces:
        sources = problem.initial_workspace_sources or []
        return [
            (workspace, _normalize_seed_source(index, sources[index] if index < len(sources) else None))
            for index, workspace in enumerate(problem.initial_workspaces)
        ]
    return [
        (
            CandidateWorkspace.from_code(code),
            {
                "seed_index": index,
                "seed_source_kind": "inline",
            },
        )
        for index, code in enumerate(problem.initial_programs)
    ]


def _deterministic_seed_candidate_id(index: int, workspace: CandidateWorkspace) -> str:
    digest = _workspace_sha256(workspace)[:16]
    return f"candidate-seed-{index}-{digest}"


def _deterministic_generated_candidate_id(
    *,
    generation: int,
    loop_generation_index: int,
    proposal_index: int,
    parent_id: str,
    prompt_program_id: str,
    mutation_text: object,
    workspace: CandidateWorkspace,
) -> str:
    mutation_text_for_hash = _candidate_id_mutation_text(mutation_text)
    payload = {
        "generation": generation,
        "loop_generation_index": loop_generation_index,
        "proposal_index": proposal_index,
        "parent_id": parent_id,
        "prompt_program_id": prompt_program_id,
        "mutation_sha256": hashlib.sha256(
            mutation_text_for_hash.encode("utf-8", errors="replace")
        ).hexdigest(),
        "workspace_sha256": _workspace_sha256(workspace),
    }
    digest = hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()[:16]
    return f"candidate-gen-{generation}-{loop_generation_index}-p{proposal_index}-{digest}"


def _candidate_id_mutation_text(value: object) -> str:
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, sort_keys=True, allow_nan=False, separators=(",", ":"))
    except (TypeError, ValueError):
        return repr(value)


def _evaluation_cache_contract_sha256(
    problem: Problem,
    config: Config,
    evaluator_sources: object,
) -> str:
    stdin_text = config.evaluator_stdin_text
    payload = {
        "schema": "libreevolve.evaluation_cache_contract.v1",
        "problem_name": problem.name,
        "primary_metric": problem.primary_metric,
        "metrics": _evaluation_cache_json_value(problem.metrics),
        "evaluator_sources": _evaluation_cache_json_value(evaluator_sources),
        "eval_stages": _evaluation_cache_json_value(config.eval_stages),
        "validator_network_policy": config.validator_network_policy,
        "validator_env_allowlist": list(config.validator_env_allowlist),
        "evaluator_data_include": list(config.evaluator_data_include),
        "evaluator_data_exclude": list(config.evaluator_data_exclude),
        "evaluator_stdin_text_sha256": (
            hashlib.sha256(stdin_text.encode("utf-8")).hexdigest()
            if isinstance(stdin_text, str)
            else None
        ),
        "evaluator_stdin_file": (
            str(config.evaluator_stdin_file)
            if config.evaluator_stdin_file is not None
            else None
        ),
        "cache_stage": "pre_llm_feedback_evaluator_result",
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _evaluation_cache_json_value(value: object) -> object:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Mapping):
        return {
            str(key): _evaluation_cache_json_value(item)
            for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))
        }
    if isinstance(value, (list, tuple)):
        return [_evaluation_cache_json_value(item) for item in value]
    return repr(value)


def _evaluation_cache_key(
    workspace: CandidateWorkspace,
    evaluator_contract_sha256: str,
    *,
    diff_error: object | None,
) -> dict | None:
    if diff_error is not None:
        return None
    workspace_hash = _workspace_sha256(workspace)
    payload = {
        "schema": "libreevolve.evaluation_cache_key.v1",
        "workspace_sha256": workspace_hash,
        "evaluator_contract_sha256": evaluator_contract_sha256,
        "diff_error": None,
    }
    cache_key_sha256 = hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        "schema": "libreevolve.evaluation_cache_key.v1",
        "cache_key_sha256": cache_key_sha256,
        "workspace_sha256": workspace_hash,
        "evaluator_contract_sha256": evaluator_contract_sha256,
        "diff_error": None,
    }


def _store_evaluation_cache_result(
    cache: dict[str, dict],
    workspace: CandidateWorkspace,
    evaluator_contract_sha256: str,
    result: EvaluationResult,
    *,
    source_program_id: str,
    source_generation: int,
    source_candidate_type: str,
) -> dict:
    key = _evaluation_cache_key(
        workspace,
        evaluator_contract_sha256,
        diff_error=None,
    )
    assert key is not None
    entry = {
        **key,
        "result": copy.deepcopy(result),
        "source_program_id": source_program_id,
        "source_generation": source_generation,
        "source_candidate_type": source_candidate_type,
        "source_fitness": result.fitness,
        "source_metric_names": sorted(result.metrics),
        "source_elapsed_sec": result.elapsed_sec,
    }
    cache[key["cache_key_sha256"]] = entry
    return {
        "schema": "libreevolve.evaluation_cache_record.v1",
        "status": "stored",
        "cache_hit": False,
        "cache_key_sha256": key["cache_key_sha256"],
        "workspace_sha256": key["workspace_sha256"],
        "evaluator_contract_sha256": evaluator_contract_sha256,
        "source_program_id": source_program_id,
        "source_generation": source_generation,
        "source_candidate_type": source_candidate_type,
        "cache_stage": "pre_llm_feedback_evaluator_result",
        "budget_policy": "store_consumed_normal_evaluator_budget",
    }


def _lookup_evaluation_cache_result(
    cache: dict[str, dict],
    workspace: CandidateWorkspace,
    evaluator_contract_sha256: str,
    *,
    diff_error: object | None,
) -> dict | None:
    key = _evaluation_cache_key(
        workspace,
        evaluator_contract_sha256,
        diff_error=diff_error,
    )
    if key is None:
        return None
    return cache.get(key["cache_key_sha256"])


def _evaluation_cache_hit_result(entry: Mapping[str, object]) -> EvaluationResult:
    cached = entry.get("result")
    if not isinstance(cached, EvaluationResult):
        raise RuntimeError("evaluation cache entry is malformed")
    result = copy.deepcopy(cached)
    source_elapsed_sec = result.elapsed_sec
    result.elapsed_sec = 0.0
    for stage in result.stages:
        stage.elapsed_sec = 0.0
    metadata = {
        "schema": "libreevolve.evaluation_cache_record.v1",
        "status": "hit",
        "cache_hit": True,
        "cache_key_sha256": entry["cache_key_sha256"],
        "workspace_sha256": entry["workspace_sha256"],
        "evaluator_contract_sha256": entry["evaluator_contract_sha256"],
        "source_program_id": entry["source_program_id"],
        "source_generation": entry["source_generation"],
        "source_candidate_type": entry["source_candidate_type"],
        "cache_stage": "pre_llm_feedback_evaluator_result",
        "budget_policy": "cache_hit_does_not_consume_evaluator_call_budget",
        "source_elapsed_sec": source_elapsed_sec,
    }
    result.metadata = dict(result.metadata)
    result.metadata["evaluation_cache"] = metadata
    return result


def _evaluation_cache_bypass_metadata(
    workspace: CandidateWorkspace,
    evaluator_contract_sha256: str,
    *,
    reason: str,
) -> dict:
    return {
        "schema": "libreevolve.evaluation_cache_record.v1",
        "status": "bypassed",
        "cache_hit": False,
        "workspace_sha256": _workspace_sha256(workspace),
        "evaluator_contract_sha256": evaluator_contract_sha256,
        "reason": reason,
        "cache_stage": "pre_llm_feedback_evaluator_result",
        "budget_policy": "bypass_consumed_normal_evaluator_budget",
    }


def _evaluation_result_with_cache_metadata(
    result: EvaluationResult,
    metadata: Mapping[str, object],
) -> EvaluationResult:
    updated = copy.deepcopy(result)
    updated.metadata = dict(updated.metadata)
    updated.metadata["evaluation_cache"] = dict(metadata)
    return updated


def _workspace_sha256(workspace: CandidateWorkspace) -> str:
    payload = {
        "primary_file": workspace.primary_file,
        "files": [[path, workspace.files[path]] for path in sorted(workspace.files)],
        "static_files": [dict(item) for item in workspace.static_files],
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _problem_seed_sources(problem: Problem) -> list[dict]:
    if problem.initial_workspaces:
        sources = problem.initial_workspace_sources or []
        return [
            _normalize_seed_source(index, sources[index] if index < len(sources) else None)
            for index, _workspace in enumerate(problem.initial_workspaces)
        ]
    return [
        {
            "seed_index": index,
            "seed_source_kind": "inline",
        }
        for index, _code in enumerate(problem.initial_programs)
    ]


def _problem_seed_skipped(problem: Problem) -> list[dict]:
    return list(getattr(problem, "initial_workspace_skipped", []) or [])


def _problem_seed_policy(problem: Problem) -> dict:
    return dict(getattr(problem, "initial_workspace_policy", {}) or {})


def _problem_formulation_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "formulation_metadata", {}) or {})


def _problem_codebase_integration_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "codebase_integration_metadata", {}) or {})


def _problem_collaborator_feedback_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "collaborator_feedback_metadata", {}) or {})


def _problem_acknowledgement_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "acknowledgement_metadata", {}) or {})


def _problem_paper_author_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "paper_author_metadata", {}) or {})


def _problem_title_page_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "title_page_metadata", {}) or {})


def _problem_system_contribution_metadata(problem: Problem) -> dict:
    return dict(getattr(problem, "system_contribution_metadata", {}) or {})


def _problem_retrieval_query_context(problem: Problem) -> dict:
    context = {
        "task_description": problem.task_description,
        "context_files": dict(getattr(problem, "context_files", {}) or {}),
    }
    local_papers = getattr(problem, "local_papers", None)
    if local_papers is None:
        local_papers = _local_paper_query_context_rows()
    if local_papers:
        context["local_papers"] = local_papers
    return context


def _local_paper_query_context_rows(root: Path | None = None) -> list[dict]:
    root_path = root or Path(__file__).resolve().parents[2]
    manifest_path = root_path / "papers" / "download_manifest.json"
    try:
        raw_rows = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return []
    if not isinstance(raw_rows, list):
        return []
    rows: list[dict] = []
    for raw_row in raw_rows:
        if not isinstance(raw_row, Mapping):
            continue
        row: dict[str, object] = {}
        for key in ("id", "title", "url", "file", "sha256"):
            value = raw_row.get(key)
            if isinstance(value, str) and value:
                row[key] = value
        value = raw_row.get("ok")
        if isinstance(value, bool):
            row["ok"] = value
        value = raw_row.get("bytes")
        if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
            row["bytes"] = value
        if row.get("id") or row.get("title"):
            rows.append(row)
        if len(rows) >= 25:
            break
    return rows


def _normalize_seed_source(index: int, source: dict | None) -> dict:
    return validate_seed_source_record(index, source)


def _build_plugin_context(
    plugins: list[PluginBase],
    parent: Program,
    inspirations: list[Program],
    *,
    config: Config,
    generation: int | None = None,
    phase: str | None = None,
    context_policy: Mapping[str, object] | None = None,
) -> tuple[str, list[dict]]:
    context_entries: list[dict] = []
    records: list[dict] = []
    inspiration_ids = [program.id for program in inspirations]
    prompt_context_policy = validate_prompt_context_policy(context_policy)
    plugin_context_max_chars_by_label = prompt_context_policy[
        "plugin_context_max_chars_by_label"
    ]
    plugin_context_max_chars = prompt_context_policy["plugin_context_max_chars"]
    plugin_context_truncation = prompt_context_policy["plugin_context_truncation"]
    plugin_context_order = prompt_context_policy["plugin_context_order"]
    plugin_context_required_terms = prompt_context_policy[
        "plugin_context_required_terms"
    ]
    plugin_context_excluded_terms = prompt_context_policy[
        "plugin_context_excluded_terms"
    ]
    plugin_context_ranking_terms = prompt_context_policy[
        "plugin_context_ranking_terms"
    ]
    plugin_context_limit = prompt_context_policy["plugin_context_limit"]
    if prompt_context_policy["plugin_context_enabled"] is False:
        return "", [
            _skipped_plugin_context_record(
                plugin,
                index,
                parent=parent,
                inspiration_ids=inspiration_ids,
                config=config,
            )
            for index, plugin in enumerate(plugins)
        ]
    plugin_context_allowlist = set(prompt_context_policy["plugin_context_allowlist"])
    plugin_context_excluded_labels = set(
        prompt_context_policy["plugin_context_excluded_labels"]
    )
    for index, plugin in enumerate(plugins):
        if plugin_context_excluded_labels and _plugin_context_matches_labels(
            plugin,
            index,
            plugin_context_excluded_labels,
        ):
            records.append(
                _skipped_plugin_context_record(
                    plugin,
                    index,
                    parent=parent,
                    inspiration_ids=inspiration_ids,
                    config=config,
                    reason="excluded_by_prompt_context_labels",
                    plugin_context_enabled=True,
                    plugin_context_excluded_labels=sorted(
                        plugin_context_excluded_labels
                    ),
                )
            )
            continue
        if plugin_context_allowlist and not _plugin_context_is_allowlisted(
            plugin, index, plugin_context_allowlist
        ):
            records.append(
                _skipped_plugin_context_record(
                    plugin,
                    index,
                    parent=parent,
                    inspiration_ids=inspiration_ids,
                    config=config,
                    reason="not_selected_by_prompt_context_allowlist",
                    plugin_context_enabled=True,
                    plugin_context_allowlist=sorted(plugin_context_allowlist),
                )
            )
            continue
        rendered = _call_plugin_hook(
            plugin,
            index,
            "build_extra_context",
            parent,
            inspirations,
            generation=generation,
            phase=phase,
            hook_policy="fatal_run_abort",
            parent_id=parent.id,
        )
        if rendered is None:
            text = ""
        elif isinstance(rendered, str):
            text = rendered
        else:
            exc = ValueError(
                f"plugin_context[{index}].build_extra_context must return text or None"
            )
            _annotate_plugin_failure(
                exc,
                plugin,
                index,
                "build_extra_context",
                generation=generation,
                phase=phase,
                hook_policy="fatal_run_abort",
                parent_id=parent.id,
            )
            raise exc
        redacted_text = redact_sensitive_text(text) if text else ""
        policy_max_chars = _plugin_context_policy_max_chars(
            plugin,
            index,
            plugin_context_max_chars_by_label,
        )
        effective_max_chars = min(
            cap
            for cap in (
                _MAX_PLUGIN_CONTEXT_CHARS,
                plugin_context_max_chars,
                policy_max_chars,
            )
            if cap is not None
        )
        safe_text = (
            _bounded_redacted_plugin_context_text(
                text,
                effective_max_chars,
                truncation=plugin_context_truncation,
            )
            if text and effective_max_chars > 0
            else ""
        )
        term_policy = _plugin_context_term_policy(
            safe_text,
            required_terms=plugin_context_required_terms,
            excluded_terms=plugin_context_excluded_terms,
        )
        prompt_visible_text = safe_text if term_policy["selected"] else ""
        prompt_context_text = (
            _render_plugin_context_section(index, plugin, prompt_visible_text)
            if prompt_visible_text
            else ""
        )
        if prompt_context_text:
            prompt_context_text = redact_sensitive_text(prompt_context_text)
        prompt_context_truncated = len(safe_text) < len(redacted_text) if text else False
        retained_context = _retained_plugin_context_text(
            plugin=plugin,
            index=index,
            original_text=text,
            prompt_context_text=prompt_context_text,
            prompt_context_truncated=prompt_context_truncated,
            mode=config.plugin_context_retention_mode,
        )
        record = {
            **_plugin_identity(plugin, index),
            "plugin_spec": _plugin_spec_record(
                plugin, index, config, list(config.plugins)
            ),
            "parent_id": parent.id,
            "inspiration_ids": inspiration_ids,
            "chars": retained_context["stored_chars"],
            "original_chars": len(text),
            "max_chars": effective_max_chars,
            "default_max_chars": _MAX_PLUGIN_CONTEXT_CHARS,
            "policy_global_max_chars": plugin_context_max_chars,
            "policy_max_chars": policy_max_chars,
            "policy_truncation": plugin_context_truncation,
            "context_redacted": redacted_text != text,
            "context_truncated": retained_context["truncated"],
            "prompt_context_chars": len(prompt_context_text),
            "prompt_context_truncated": prompt_context_truncated,
            "prompt_context_content_policy": {
                "schema": "libreevolve.plugin_context_content_policy.v1",
                "max_chars": effective_max_chars,
                "truncation": plugin_context_truncation,
                "selection_policy": (
                    "all_redacted_plugin_context_text"
                    if len(redacted_text) <= effective_max_chars
                    else f"{plugin_context_truncation}_chars_after_redaction"
                ),
            },
            "sha256": retained_context["sha256"] or "",
            "context_retention": {
                key: value
                for key, value in retained_context.items()
                if key != "text"
            },
            "emitted": bool(prompt_visible_text.strip()),
            "context_visibility": _plugin_context_visibility(
                prompt_visible_text,
                term_policy,
            ),
            "metadata_visibility": "none",
        }
        if term_policy["policy"] != "none":
            record["prompt_context_term_policy"] = term_policy
        if retained_context["text"]:
            record["context"] = retained_context["text"]
        if prompt_context_text:
            order_position = _plugin_context_order_position(
                plugin,
                index,
                plugin_context_order,
            )
            order_source = (
                "prompt_context_policy"
                if order_position is not None
                else "config_plugin_order_append"
            )
            record["prompt_context_order"] = {
                "policy": "plugin_context_order_v1",
                "source": order_source,
                "position": order_position,
                "configured_order": list(plugin_context_order),
            }
            context_entries.append(
                {
                    "text": prompt_context_text,
                    "content": prompt_visible_text,
                    "plugin_index": index,
                    "order_position": order_position,
                    "record": record,
                }
            )
        plugin_metadata = _call_optional_plugin_hook(
            plugin,
            index,
            "prompt_context_metadata",
            generation=generation,
            phase=phase,
            hook_policy="fatal_run_abort",
            parent_id=parent.id,
        )
        if plugin_metadata is None:
            pass
        elif not isinstance(plugin_metadata, dict):
            exc = ValueError(
                "prompt_context_metadata must return a mapping, an empty mapping, or None"
            )
            _annotate_plugin_failure(
                exc,
                plugin,
                index,
                "prompt_context_metadata",
                generation=generation,
                phase=phase,
                hook_policy="fatal_run_abort",
                parent_id=parent.id,
            )
            raise exc
        elif plugin_metadata:
            try:
                plugin_metadata = _validate_plugin_metadata(
                    f"plugin_context[{index}].metadata",
                    plugin_metadata,
                )
            except ValueError as exc:
                _annotate_plugin_failure(
                    exc,
                    plugin,
                    index,
                    "prompt_context_metadata",
                    generation=generation,
                    phase=phase,
                    hook_policy="fatal_run_abort",
                    parent_id=parent.id,
                )
                raise
            record["metadata"] = plugin_metadata
            record["metadata_visibility"] = (
                "prompt_visible_context" if record["emitted"] else "provenance_only"
            )
        records.append(record)
    ordered_entries = sorted(
        context_entries,
        key=lambda entry: (
            1 if entry["order_position"] is None else 0,
            entry["order_position"] if entry["order_position"] is not None else 0,
            entry["plugin_index"],
        ),
    )
    if plugin_context_ranking_terms:
        ordered_entries = _rank_plugin_context_entries_by_terms(
            ordered_entries,
            ranking_terms=plugin_context_ranking_terms,
        )
    if plugin_context_limit is None:
        selected_entries = ordered_entries
        omitted_entries: list[dict] = []
    else:
        selected_entries = ordered_entries[:plugin_context_limit]
        omitted_entries = ordered_entries[plugin_context_limit:]
        _apply_plugin_context_limit_policy(
            selected_entries,
            omitted_entries,
            source_limit=plugin_context_limit,
        )
    ordered_contexts = [
        entry["text"]
        for entry in selected_entries
    ]
    return "\n".join(ordered_contexts), records


def _skipped_plugin_context_record(
    plugin: PluginBase,
    index: int,
    *,
    parent: Program,
    inspiration_ids: list[str],
    config: Config,
    reason: str = "disabled_by_prompt_context_policy",
    plugin_context_enabled: bool = False,
    plugin_context_allowlist: list[str] | None = None,
    plugin_context_excluded_labels: list[str] | None = None,
) -> dict:
    retention_policy = reason
    policy = {
        "schema": "libreevolve.plugin_context_policy.v1",
        "plugin_context_enabled": plugin_context_enabled,
        "source": "prompt_context_policy",
    }
    if plugin_context_allowlist is not None:
        policy["plugin_context_allowlist"] = list(plugin_context_allowlist)
        policy["selected"] = False
    if plugin_context_excluded_labels is not None:
        policy["plugin_context_excluded_labels"] = list(
            plugin_context_excluded_labels
        )
        policy["selected"] = False
    return {
        **_plugin_identity(plugin, index),
        "plugin_spec": _plugin_spec_record(
            plugin,
            index,
            config,
            list(config.plugins),
        ),
        "parent_id": parent.id,
        "inspiration_ids": list(inspiration_ids),
        "chars": 0,
        "original_chars": 0,
        "max_chars": _MAX_PLUGIN_CONTEXT_CHARS,
        "context_redacted": False,
        "context_truncated": False,
        "prompt_context_chars": 0,
        "prompt_context_truncated": False,
        "sha256": "",
        "context_retention": {
            "sha256": None,
            "chars": 0,
            "stored_chars": 0,
            "redacted": False,
            "truncated": False,
            "retention_mode": config.plugin_context_retention_mode,
            "retention_policy": retention_policy,
        },
        "emitted": False,
        "context_visibility": reason,
        "metadata_visibility": "none",
        "prompt_context_policy": policy,
    }


def _plugin_context_is_allowlisted(
    plugin: PluginBase,
    index: int,
    allowlist: set[str],
) -> bool:
    return _plugin_context_matches_labels(plugin, index, allowlist)


def _plugin_context_matches_labels(
    plugin: PluginBase,
    index: int,
    labels_to_match: set[str],
) -> bool:
    identity = _plugin_identity(plugin, index)
    labels = {
        identity["plugin"],
        identity["module"],
        identity["class"],
        identity["instance_id"],
    }
    return any(label in labels_to_match for label in labels if isinstance(label, str))


def _plugin_context_order_position(
    plugin: PluginBase,
    index: int,
    ordered_labels: list[str],
) -> int | None:
    if not ordered_labels:
        return None
    identity = _plugin_identity(plugin, index)
    labels = {
        identity["plugin"],
        identity["module"],
        identity["class"],
        identity["instance_id"],
    }
    for position, label in enumerate(ordered_labels):
        if any(candidate == label for candidate in labels if isinstance(candidate, str)):
            return position
    return None


def _plugin_context_policy_max_chars(
    plugin: PluginBase,
    index: int,
    caps_by_label: Mapping[str, int],
) -> int | None:
    if not caps_by_label:
        return None
    identity = _plugin_identity(plugin, index)
    labels = {
        identity["plugin"],
        identity["module"],
        identity["class"],
        identity["instance_id"],
    }
    matches = [
        caps_by_label[label]
        for label in labels
        if isinstance(label, str) and label in caps_by_label
    ]
    return min(matches) if matches else None


def _rank_plugin_context_entries_by_terms(
    entries: list[dict],
    *,
    ranking_terms: list[str],
) -> list[dict]:
    ranked = []
    for original_rank, entry in enumerate(entries, start=1):
        source_terms = {
            match.group(0).lower()
            for match in re.finditer(r"[A-Za-z0-9_]{3,}", str(entry["content"]))
        }
        score = sum(1 for term in ranking_terms if term in source_terms)
        ranked.append((score, original_rank, entry))
    ranked.sort(key=lambda item: (-item[0], item[1]))
    selected_sources = []
    for rank, (score, original_rank, entry) in enumerate(ranked, start=1):
        record = entry["record"]
        record["prompt_context_ranking_policy"] = {
            "schema": "libreevolve.plugin_context_ranking_policy.v1",
            "ranking_policy": "term_overlap_plugin_context_v1",
            "ranking_terms": list(ranking_terms),
            "ranking_terms_sha256": hashlib.sha256(
                " ".join(ranking_terms).encode("utf-8")
            ).hexdigest(),
            "ranking_term_count": len(ranking_terms),
            "candidate_count": len(entries),
            "rank": rank,
            "score": score,
            "previous_rank": original_rank,
        }
        selected_sources.append(
            {
                "plugin_index": int(entry["plugin_index"]),
                "rank": rank,
                "score": score,
                "previous_rank": original_rank,
            }
        )
    ranking_sha256 = hashlib.sha256(
        json.dumps(
            selected_sources,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    for _, _, entry in ranked:
        entry["record"]["prompt_context_ranking_policy"][
            "ranking_sha256"
        ] = ranking_sha256
    return [entry for _, _, entry in ranked]


def _apply_plugin_context_limit_policy(
    selected_entries: list[dict],
    omitted_entries: list[dict],
    *,
    source_limit: int,
) -> None:
    selected_indices = [int(entry["plugin_index"]) for entry in selected_entries]
    omitted_indices = [int(entry["plugin_index"]) for entry in omitted_entries]
    selection_sha256 = hashlib.sha256(
        json.dumps(
            {
                "source_limit": source_limit,
                "selected_plugin_indices": selected_indices,
                "omitted_plugin_indices": omitted_indices,
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    for position, entry in enumerate(selected_entries, start=1):
        record = entry["record"]
        record["prompt_context_limit_policy"] = {
            "schema": "libreevolve.plugin_context_limit_policy.v1",
            "source_limit": source_limit,
            "pre_limit_selected_count": len(selected_entries) + len(omitted_entries),
            "selected_count": len(selected_entries),
            "omitted_count": len(omitted_entries),
            "selected": True,
            "rank": position,
            "selection_sha256": selection_sha256,
        }
    for position, entry in enumerate(omitted_entries, start=len(selected_entries) + 1):
        record = entry["record"]
        record["pre_limit_prompt_context_chars"] = record["prompt_context_chars"]
        record["prompt_context_chars"] = 0
        record["emitted"] = False
        record["context_visibility"] = "not_selected_by_prompt_context_limit"
        if record.get("metadata_visibility") == "prompt_visible_context":
            record["metadata_visibility"] = "provenance_only"
        record["prompt_context_limit_policy"] = {
            "schema": "libreevolve.plugin_context_limit_policy.v1",
            "source_limit": source_limit,
            "pre_limit_selected_count": len(selected_entries) + len(omitted_entries),
            "selected_count": len(selected_entries),
            "omitted_count": len(omitted_entries),
            "selected": False,
            "rank": position,
            "selection_sha256": selection_sha256,
        }


def _plugin_context_term_policy(
    text: str,
    *,
    required_terms: list[str],
    excluded_terms: list[str],
) -> dict:
    terms = {
        match.group(0).lower()
        for match in re.finditer(r"[A-Za-z0-9_]{3,}", text)
    }
    required = set(required_terms)
    excluded = set(excluded_terms)
    missing_required = sorted(required - terms)
    matched_excluded = sorted(excluded.intersection(terms))
    selected = not missing_required and not matched_excluded
    return {
        "schema": "libreevolve.plugin_context_term_policy.v1",
        "policy": (
            "required_excluded_terms_v1"
            if required or excluded
            else "none"
        ),
        "required_terms": list(required_terms),
        "excluded_terms": list(excluded_terms),
        "matched_required_count": len(required) - len(missing_required),
        "missing_required_terms": missing_required,
        "matched_excluded_terms": matched_excluded,
        "selected": selected,
        "selection_sha256": hashlib.sha256(
            json.dumps(
                {
                    "required_terms": list(required_terms),
                    "excluded_terms": list(excluded_terms),
                    "missing_required_terms": missing_required,
                    "matched_excluded_terms": matched_excluded,
                    "selected": selected,
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest(),
    }


def _plugin_context_visibility(prompt_visible_text: str, term_policy: dict) -> str:
    if prompt_visible_text.strip():
        return "prompt_visible"
    if term_policy["policy"] != "none" and not term_policy["selected"]:
        return "not_selected_by_prompt_context_terms"
    return "not_prompt_visible"


def _render_plugin_context_section(index: int, plugin: PluginBase, text: str) -> str:
    identity = _plugin_identity(plugin, index)
    plugin_name = identity["plugin"] or "Plugin"
    module = identity["module"] or "unknown"
    return "\n".join(
        [
            "[PLUGIN CONTEXT]",
            f"Plugin: {plugin_name}",
            f"Module: {module}",
            f"Index: {index}",
            f"Content-Characters: {len(text)}",
            "Content-JSON:",
            json.dumps(text),
        ]
    )


def _plugin_identity(plugin: object, index: int) -> dict:
    return plugin_identity_record(plugin, index)


def _validate_plugin_metadata(path: str, value: object) -> object:
    item_counter = {"count": 0}
    sanitized = _validate_plugin_metadata_value(
        path,
        value,
        item_counter,
        depth=0,
    )
    json_chars = len(
        json.dumps(
            sanitized,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
    )
    if json_chars > _MAX_PLUGIN_METADATA_JSON_CHARS:
        raise ValueError(
            f"{path} metadata JSON exceeds {_MAX_PLUGIN_METADATA_JSON_CHARS} chars"
        )
    return sanitized


def _validate_plugin_metadata_value(
    path: str,
    value: object,
    item_counter: dict[str, int],
    *,
    depth: int,
) -> object:
    if depth > _MAX_PLUGIN_METADATA_DEPTH:
        raise ValueError(
            f"{path} metadata nesting exceeds {_MAX_PLUGIN_METADATA_DEPTH} levels"
        )
    item_counter["count"] += 1
    if item_counter["count"] > _MAX_PLUGIN_METADATA_ITEMS:
        raise ValueError(
            f"{path} metadata item count exceeds {_MAX_PLUGIN_METADATA_ITEMS}"
        )
    if isinstance(value, dict):
        sanitized: dict[str, object] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError(f"{path} keys must be strings")
            if _has_unicode_format_control(key):
                raise ValueError(f"{path}.{key!r} must be a display-safe metadata label")
            safe_key = _safe_plugin_metadata_key(key)
            if safe_key in sanitized:
                safe_key = _plugin_metadata_key_with_hash(key, key)
            sanitized[safe_key] = _validate_plugin_metadata_value(
                f"{path}.{safe_key}",
                item,
                item_counter,
                depth=depth + 1,
            )
        return sanitized
    if isinstance(value, list):
        return [
            _validate_plugin_metadata_value(
                f"{path}[{index}]",
                item,
                item_counter,
                depth=depth + 1,
            )
            for index, item in enumerate(value)
        ]
    if isinstance(value, str):
        if len(value) > _MAX_PLUGIN_METADATA_STRING_CHARS:
            raise ValueError(f"{path} metadata value exceeds {_MAX_PLUGIN_METADATA_STRING_CHARS} chars")
        if _has_unicode_format_control(value):
            raise ValueError(f"{path} must be a display-safe metadata value")
        return redact_sensitive_text(value)
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"{path} metadata value must be finite")
        return value
    raise ValueError(f"{path} metadata value must be JSON-safe")


def _safe_plugin_metadata_key(key: str) -> str:
    redacted = redact_sensitive_text(key)
    if redacted != key and (
        redact_sensitive_text(redacted) != redacted
        or _has_secret_label_word(key)
    ):
        redacted = "redacted_metadata_key"
    bounded = _bounded_plugin_metadata_key(redacted)
    if bounded != key:
        return _plugin_metadata_key_with_hash(bounded, key)
    return bounded


def _bounded_plugin_metadata_key(key: str) -> str:
    if len(key) <= _MAX_PLUGIN_METADATA_KEY_CHARS:
        return key
    suffix = "...<truncated>"
    return key[: _MAX_PLUGIN_METADATA_KEY_CHARS - len(suffix)] + suffix


def _has_secret_label_word(value: str) -> bool:
    normalized = value.lower().replace("-", "_")
    return any(
        word in normalized
        for word in ("api_key", "apikey", "token", "secret", "password")
    )


def _plugin_metadata_key_with_hash(label: str, hash_source: str) -> str:
    digest = hashlib.sha256(hash_source.encode("utf-8")).hexdigest()[:12]
    suffix = f"#sha256:{digest}"
    base_limit = max(1, _MAX_PLUGIN_METADATA_KEY_CHARS - len(suffix))
    base = label if len(label) <= base_limit else label[:base_limit]
    return base + suffix


def _has_unicode_format_control(value: str) -> bool:
    return any(unicodedata.category(ch) == "Cf" for ch in value)


_RETRIEVAL_EVIDENCE_LIMITATIONS = (
    "bounded_redacted_payload_artifacts_not_unbounded_raw_payloads",
    "lexical_grounding_not_semantic_verification",
    "query_overlap_not_learned_semantic_ranking",
    "transport_status_without_tls_certificate_chain_replay",
    "retrieval_context_is_untrusted_non_authoritative_prompt_evidence",
)
_RETRIEVAL_EVIDENCE_OVERCLAIM_FIELDS = {
    "raw_provider_payload_retained": "raw_provider_payload_overclaim",
    "raw_source_payload_retained": "raw_source_payload_overclaim",
    "semantic_source_verification_ready": "semantic_source_verification_overclaim",
    "learned_ranking_ready": "learned_ranking_overclaim",
    "tls_decision_replay_ready": "tls_decision_replay_overclaim",
    "full_retrieval_replay_ready": "full_retrieval_replay_overclaim",
}
_RETRIEVAL_EVIDENCE_COUNT_FIELDS = (
    "event_count",
    "ok_event_count",
    "empty_event_count",
    "error_event_count",
    "source_count",
    "transport_policy_count",
    "payload_artifact_policy_count",
    "payload_artifact_reference_count",
    "stored_payload_artifact_count",
    "source_content_snapshot_count",
    "source_content_trust_policy_count",
    "replayable_source_count",
    "source_grounding_policy_count",
    "lexically_grounded_source_count",
    "source_ranking_provenance_count",
    "evidence_boundary_policy_count",
    "context_audit_policy_count",
    "bounded_context_audit_ready_count",
)


def _non_negative_int(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        return 0
    return value


def _count_retrieval_sources(event: Mapping[str, object]) -> int:
    sources = event.get("sources")
    if not isinstance(sources, list):
        return 0
    return sum(1 for source in sources if isinstance(source, dict))


def _count_source_content_snapshots(event: Mapping[str, object]) -> int:
    sources = event.get("sources")
    if not isinstance(sources, list):
        return 0
    return sum(
        1
        for source in sources
        if isinstance(source, dict)
        and isinstance(source.get("content_snapshot"), dict)
    )


def _retrieval_evidence_coverage(events: list[dict]) -> dict:
    event_count = len(events)
    ok_event_count = sum(1 for event in events if event.get("status") == "ok")
    empty_event_count = sum(1 for event in events if event.get("status") == "empty")
    error_event_count = sum(1 for event in events if event.get("status") == "error")
    source_count = sum(_count_retrieval_sources(event) for event in events)
    payload_artifact_policy_count = sum(
        1 for event in events if isinstance(event.get("payload_artifact_policy"), dict)
    )
    payload_artifact_reference_count = sum(
        len(event.get("payload_artifacts"))
        for event in events
        if isinstance(event.get("payload_artifacts"), list)
    )
    stored_payload_artifact_count = sum(
        _non_negative_int(event["payload_artifact_policy"].get("stored_artifacts"))
        for event in events
        if isinstance(event.get("payload_artifact_policy"), dict)
    )
    source_content_snapshot_count = sum(
        _count_source_content_snapshots(event) for event in events
    )
    source_content_trust_policy_count = sum(
        1
        for event in events
        if isinstance(event.get("source_content_trust_policy"), dict)
    )
    replayable_source_count = sum(
        _non_negative_int(
            event["source_content_trust_policy"].get("replayable_source_count")
        )
        for event in events
        if isinstance(event.get("source_content_trust_policy"), dict)
    )
    source_grounding_policy_count = sum(
        1 for event in events if isinstance(event.get("source_grounding_policy"), dict)
    )
    lexically_grounded_source_count = sum(
        _non_negative_int(
            event["source_grounding_policy"].get("lexically_grounded_source_count")
        )
        for event in events
        if isinstance(event.get("source_grounding_policy"), dict)
    )
    source_ranking_provenance_count = sum(
        1 for event in events if isinstance(event.get("source_ranking"), dict)
    )
    evidence_boundary_policy_count = sum(
        1
        for event in events
        if isinstance(event.get("evidence_boundary_policy"), dict)
    )
    context_audit_policy_count = sum(
        1 for event in events if isinstance(event.get("context_audit_policy"), dict)
    )
    bounded_context_audit_ready_count = sum(
        1
        for event in events
        if isinstance(event.get("context_audit_policy"), dict)
        and event["context_audit_policy"].get("bounded_context_audit_ready") is True
    )
    transport_policy_count = sum(
        1 for event in events if isinstance(event.get("transport_policy"), dict)
    )
    if bounded_context_audit_ready_count or replayable_source_count:
        status = "bounded_replay_evidence"
    elif (
        transport_policy_count
        or source_content_trust_policy_count
        or source_content_snapshot_count
        or source_ranking_provenance_count
        or payload_artifact_policy_count
    ):
        status = "bounded_metadata_or_snapshot_evidence"
    else:
        status = "event_count_only"
    record = {
        "schema": RETRIEVAL_EVIDENCE_COVERAGE_SCHEMA,
        "status": status,
        "event_count": event_count,
        "ok_event_count": ok_event_count,
        "empty_event_count": empty_event_count,
        "error_event_count": error_event_count,
        "source_count": source_count,
        "transport_policy_count": transport_policy_count,
        "payload_artifact_policy_count": payload_artifact_policy_count,
        "payload_artifact_reference_count": payload_artifact_reference_count,
        "stored_payload_artifact_count": stored_payload_artifact_count,
        "source_content_snapshot_count": source_content_snapshot_count,
        "source_content_trust_policy_count": source_content_trust_policy_count,
        "replayable_source_count": replayable_source_count,
        "source_grounding_policy_count": source_grounding_policy_count,
        "lexically_grounded_source_count": lexically_grounded_source_count,
        "source_ranking_provenance_count": source_ranking_provenance_count,
        "evidence_boundary_policy_count": evidence_boundary_policy_count,
        "context_audit_policy_count": context_audit_policy_count,
        "bounded_context_audit_ready_count": bounded_context_audit_ready_count,
        "raw_provider_payload_retained": False,
        "raw_source_payload_retained": False,
        "semantic_source_verification_ready": False,
        "learned_ranking_ready": False,
        "tls_decision_replay_ready": False,
        "full_retrieval_replay_ready": False,
        "limitations": list(_RETRIEVAL_EVIDENCE_LIMITATIONS),
    }
    record["validation"] = validate_retrieval_evidence_coverage(record)
    return record


def validate_retrieval_evidence_coverage(record: object) -> dict:
    """Validate run-level retrieval evidence coverage without overclaiming replay."""
    issues: list[dict[str, str]] = []
    if not isinstance(record, dict):
        return {
            "schema": RETRIEVAL_EVIDENCE_COVERAGE_VALIDATION_SCHEMA,
            "ok": False,
            "coverage_schema": None,
            "event_count": 0,
            "source_count": 0,
            "issues": [
                {
                    "code": "invalid_record",
                    "message": "retrieval evidence coverage must be an object",
                }
            ],
        }
    if record.get("schema") != RETRIEVAL_EVIDENCE_COVERAGE_SCHEMA:
        issues.append(
            {
                "code": "schema_mismatch",
                "message": "retrieval evidence coverage schema is unsupported",
            }
        )
    for field in _RETRIEVAL_EVIDENCE_COUNT_FIELDS:
        value = record.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            issues.append(
                {
                    "code": f"invalid_{field}",
                    "message": f"{field} must be a non-negative integer",
                }
            )
    for field, code in _RETRIEVAL_EVIDENCE_OVERCLAIM_FIELDS.items():
        value = record.get(field)
        if value is not False:
            issues.append(
                {
                    "code": code,
                    "message": f"{field} must remain false until evidence is retained",
                }
            )
    limitations = record.get("limitations")
    if not isinstance(limitations, list):
        limitations = []
        issues.append(
            {
                "code": "invalid_limitations",
                "message": "limitations must list the evidence boundary",
            }
        )
    missing = [
        limitation
        for limitation in _RETRIEVAL_EVIDENCE_LIMITATIONS
        if limitation not in limitations
    ]
    for limitation in missing:
        issues.append(
            {
                "code": "missing_limitation",
                "message": f"missing limitation: {limitation}",
            }
        )
    return {
        "schema": RETRIEVAL_EVIDENCE_COVERAGE_VALIDATION_SCHEMA,
        "ok": not issues,
        "coverage_schema": record.get("schema"),
        "event_count": _non_negative_int(record.get("event_count")),
        "source_count": _non_negative_int(record.get("source_count")),
        "issues": issues,
    }


def _retrieval_manifest_summary(programs: list[Program]) -> dict:
    events: dict[tuple, dict] = {}
    by_plugin: dict[str, dict] = {}
    coverage_events: list[dict] = []
    for program in programs:
        metadata = program.metadata if isinstance(program.metadata, dict) else {}
        plugin_context = metadata.get("plugin_context")
        if not isinstance(plugin_context, list):
            continue
        for context_record in plugin_context:
            if not isinstance(context_record, dict):
                continue
            plugin_name = str(context_record.get("plugin") or "unknown")
            plugin_meta = context_record.get("metadata")
            if not isinstance(plugin_meta, dict):
                continue
            retrieval_events = plugin_meta.get("retrieval_events")
            if not isinstance(retrieval_events, list):
                continue
            for event in retrieval_events:
                if not isinstance(event, dict):
                    continue
                event_key = (
                    plugin_name,
                    event.get("query"),
                    event.get("timestamp"),
                    event.get("status"),
                    event.get("synthesis_sha256"),
                    event.get("error"),
                )
                if event_key in events:
                    continue
                summary = {
                    "plugin": plugin_name,
                    "provider": event.get("provider"),
                    "query": event.get("query"),
                    "query_policy": event.get("query_policy"),
                    "query_inputs": event.get("query_inputs"),
                    "generation": event.get("generation"),
                    "status": event.get("status"),
                    "timestamp": event.get("timestamp"),
                    "result_chars": event.get("result_chars", 0),
                    "synthesis_sha256": event.get("synthesis_sha256", ""),
                    "source_count": len(event.get("sources", []))
                    if isinstance(event.get("sources"), list)
                    else 0,
                }
                for key in ("trust_policy", "prompt_boundary", "authoritative"):
                    if key in event:
                        summary[key] = event.get(key)
                if isinstance(event.get("cache"), dict):
                    summary["cache"] = event.get("cache")
                if isinstance(event.get("source_metadata"), dict):
                    summary["source_metadata"] = event.get("source_metadata")
                if event.get("error"):
                    summary["error"] = event.get("error")
                if event.get("error_type"):
                    summary["error_type"] = event.get("error_type")
                for evidence_key in (
                    "transport_policy",
                    "payload_artifact_policy",
                    "source_ranking",
                    "source_grounding_policy",
                    "source_content_trust_policy",
                    "evidence_boundary_policy",
                    "context_audit_policy",
                ):
                    value = event.get(evidence_key)
                    if isinstance(value, dict):
                        summary[evidence_key] = value
                transport = event.get("transport")
                if isinstance(transport, dict):
                    transport_summary: dict = {
                        "authenticated_transport": bool(
                            transport.get("authenticated_transport")
                        ),
                    }
                    for key in (
                        "status_code",
                        "payload_bytes",
                        "payload_observed_bytes",
                        "payload_limit_bytes",
                        "payload_truncated",
                        "oversized_response",
                        "payload_sha256",
                    ):
                        if key in transport:
                            transport_summary[key] = transport.get(key)
                    request = transport.get("request")
                    if isinstance(request, dict):
                        transport_summary["request_scheme"] = request.get("scheme")
                        transport_summary["request_host"] = request.get("host")
                    final = transport.get("final")
                    if isinstance(final, dict):
                        transport_summary["final_scheme"] = final.get("scheme")
                        transport_summary["final_host"] = final.get("host")
                    if "redirected" in transport:
                        transport_summary["redirected"] = bool(transport.get("redirected"))
                    summary["transport"] = transport_summary
                events[event_key] = summary
                coverage_events.append(event)
                plugin_summary = by_plugin.setdefault(
                    plugin_name,
                    {
                        "events": 0,
                        "ok": 0,
                        "empty": 0,
                        "error": 0,
                        "sources": 0,
                    },
                )
                plugin_summary["events"] += 1
                if event.get("status") in ("ok", "empty", "error"):
                    plugin_summary[str(event.get("status"))] += 1
                plugin_summary["sources"] += summary["source_count"]
    if not events:
        return {}
    return {
        "events": len(events),
        "by_plugin": by_plugin,
        "event_summaries": list(events.values())[-20:],
        "evidence_coverage": _retrieval_evidence_coverage(coverage_events),
    }


def _plugin_artifact_manifest(
    plugins: list[PluginBase],
    *,
    errors: str = "raise",
) -> tuple[list[dict], list[dict]]:
    artifacts = []
    failures = []
    for index, plugin in enumerate(plugins):
        try:
            metadata = _call_optional_plugin_hook(
                plugin,
                index,
                "run_artifacts_metadata",
                phase="normal_finalization",
                hook_policy="fatal_run_abort",
            )
        except Exception as exc:
            if errors != "record":
                raise
            failures.append(_plugin_artifact_failure_manifest(plugin, index, exc))
            continue
        if metadata is None:
            continue
        if not isinstance(metadata, dict):
            exc = ValueError(
                "run_artifacts_metadata must return a mapping, an empty mapping, or None"
            )
            _annotate_plugin_failure(
                exc,
                plugin,
                index,
                "run_artifacts_metadata",
                generation=None,
                phase="normal_finalization",
                hook_policy="fatal_run_abort",
            )
            if errors != "record":
                raise exc
            failures.append(_plugin_artifact_failure_manifest(plugin, index, exc))
            continue
        if metadata:
            try:
                metadata = _validate_plugin_metadata(
                    f"plugin_artifacts[{plugin.__class__.__name__}]",
                    metadata,
                )
            except ValueError as exc:
                _annotate_plugin_failure(
                    exc,
                    plugin,
                    index,
                    "run_artifacts_metadata",
                    generation=None,
                    phase="normal_finalization",
                    hook_policy="fatal_run_abort",
                )
                if errors != "record":
                    raise
                failures.append(_plugin_artifact_failure_manifest(plugin, index, exc))
                continue
            artifacts.append(_plugin_artifact_record(plugin, index, metadata))
    return artifacts, failures


def _plugin_artifact_record(plugin: PluginBase, index: int, metadata: dict) -> dict:
    return {
        **_plugin_identity(plugin, index),
        "metadata": metadata,
    }


def _plugin_artifact_failure_manifest(
    plugin: PluginBase,
    index: int,
    exc: Exception,
) -> dict:
    return {
        **_plugin_identity(plugin, index),
        "hook": "run_artifacts_metadata",
        "policy": "recorded_during_abort_finalization",
        "continued": False,
        "exception_type": exc.__class__.__name__,
        **_aborted_exception_manifest(exc),
    }


def _seed_post_processing_policy() -> dict:
    return {
        "policy": "raw_evaluator_baseline",
        "llm_feedback": "not_applied",
        "plugin_score_composition": "not_applied",
    }


def _apply_plugin_scores(
    program: Program,
    initial_score: float,
    plugins: list[PluginBase],
    *,
    generation: int | None = None,
    phase: str | None = None,
) -> float:
    score = initial_score
    composition = {
        "evaluator_fitness": program.evaluation.get("fitness") if program.evaluation else None,
        "initial_fitness": initial_score,
        "final_fitness": initial_score,
        "diverged_from_evaluation": False,
        "plugins": [],
    }
    feedback_adjusted = program.metrics.get("feedback_adjusted_fitness")
    if feedback_adjusted is not None:
        composition["feedback_adjusted_fitness"] = feedback_adjusted

    for index, plugin in enumerate(plugins):
        before = score
        before_metrics = dict(program.metrics)
        before_metadata = copy.deepcopy(program.metadata)
        record = {
            **_plugin_identity(plugin, index),
            "before": before,
            "after": before,
            "delta": 0.0,
            "metrics_added": [],
            "metrics_changed": [],
            "metadata_added": [],
            "metadata_changed": [],
            "accepted": False,
            "error": None,
        }
        proposed = _call_plugin_hook(
            plugin,
            index,
            "on_evaluated",
            program,
            score,
            generation=generation,
            phase=phase,
            hook_policy="fatal_run_abort",
            parent_id=program.parent_id,
            candidate_id=program.id,
        )
        if isinstance(proposed, bool) or not isinstance(proposed, (int, float)):
            record["error"] = "invalid_plugin_score"
        elif not math.isfinite(float(proposed)):
            record["error"] = "non_finite_plugin_score"
        else:
            score = float(proposed)
            record["after"] = score
            record["delta"] = score - before
            record["accepted"] = True
        try:
            after_metrics = validate_program_metrics(program.metrics)
            program.metrics = after_metrics
        except ValueError as exc:
            program.metrics = before_metrics
            after_metrics = before_metrics
            score = before
            record["after"] = before
            record["delta"] = 0.0
            record["accepted"] = False
            record["error"] = "invalid_plugin_metrics"
            record["message"] = _bounded_redacted_text(
                str(exc),
                _MAX_PLUGIN_SIDE_EFFECT_ERROR_CHARS,
            )
        try:
            after_metadata = validate_program_metadata(
                program.metadata,
                label="Plugin-updated program metadata",
            )
            program.metadata = after_metadata
        except ValueError as exc:
            program.metrics = before_metrics
            program.metadata = before_metadata
            after_metrics = before_metrics
            after_metadata = before_metadata
            score = before
            record["after"] = before
            record["delta"] = 0.0
            record["accepted"] = False
            record["error"] = "invalid_plugin_metadata"
            record["message"] = _bounded_redacted_text(
                str(exc),
                _MAX_PLUGIN_SIDE_EFFECT_ERROR_CHARS,
            )
        record["metrics_added"] = sorted(set(after_metrics) - set(before_metrics))
        record["metrics_changed"] = sorted(
            key
            for key in set(after_metrics) & set(before_metrics)
            if after_metrics[key] != before_metrics[key]
        )
        record["metadata_added"] = sorted(set(after_metadata) - set(before_metadata))
        record["metadata_changed"] = sorted(
            key
            for key in set(after_metadata) & set(before_metadata)
            if after_metadata[key] != before_metadata[key]
        )
        composition["plugins"].append(record)
        program.fitness = score

    composition["final_fitness"] = score
    evaluation_fitness = composition["evaluator_fitness"]
    composition["diverged_from_evaluation"] = (
        isinstance(evaluation_fitness, (int, float))
        and math.isfinite(float(evaluation_fitness))
        and score != float(evaluation_fitness)
    )
    program.metadata = dict(program.metadata)
    program.metadata["score_composition"] = composition
    program.fitness = score
    return score


def _annotate_metric_policy(program: Program, problem: Problem) -> None:
    normalized: dict[str, float] = {}
    weights: dict[str, float] = {}
    for metric in problem.metrics:
        name = metric.get("name")
        if not isinstance(name, str):
            continue
        if metric.get("source") == "final_fitness":
            value = program.fitness
            if not (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(float(value))
            ):
                program.metrics[name] = float(value)
        elif name in program.metrics:
            value = program.metrics[name]
        else:
            continue
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            continue
        numeric = float(value)
        if not math.isfinite(numeric):
            continue
        normalized[name] = problem.normalize_metric(name, numeric)
        raw_weight = metric.get("weight", 1.0)
        if (
            isinstance(raw_weight, (int, float))
            and not isinstance(raw_weight, bool)
            and math.isfinite(float(raw_weight))
            and float(raw_weight) >= 0.0
        ):
            weights[name] = float(raw_weight)
        else:
            weights[name] = 1.0
    if not normalized:
        return
    total_weight = sum(weights.get(name, 1.0) for name in normalized)
    uses_non_default_weights = any(
        weights.get(name, 1.0) != 1.0 for name in normalized
    )
    if total_weight > 0.0 and uses_non_default_weights:
        selection_score = (
            sum(normalized[name] * weights.get(name, 1.0) for name in normalized)
            / total_weight
        )
        policy_type = "weighted_normalized_declared_metrics"
    elif total_weight > 0.0:
        selection_score = sum(normalized.values()) / len(normalized)
        policy_type = "mean_normalized_declared_metrics"
    else:
        selection_score = sum(normalized.values()) / len(normalized)
        policy_type = "mean_normalized_declared_metrics_zero_weight_fallback"
    program.metadata = dict(program.metadata)
    program.metadata["normalized_metrics"] = normalized
    program.metadata["selection_score"] = selection_score
    program.metadata["selection_policy"] = {
        "type": policy_type,
        "metrics": list(normalized),
        "primary_metric": problem.primary_metric,
    }
    if policy_type == "weighted_normalized_declared_metrics":
        program.metadata["selection_policy"]["weights"] = {
            name: weights[name]
            for name in normalized
        }


def _last_llm_call(llm) -> dict | None:
    call = getattr(llm, "last_call", None)
    return dict(call) if isinstance(call, dict) else None


def _generate_with_budget(
    llm,
    budget: RunBudget,
    prompt: str,
    *,
    role: str,
    budget_event_sink: Callable[[dict], dict] | None = None,
) -> tuple[str, int]:
    reason = budget.check_before_llm_call(role=role)
    if reason is not None:
        raise RuntimeError(f"LLM call budget exhausted before {role}: {reason}")
    remaining_runtime_sec = budget.remaining_runtime_seconds()
    if remaining_runtime_sec is not None and remaining_runtime_sec <= 0.0:
        raise RuntimeError(f"LLM call budget exhausted before {role}: max_runtime_seconds")
    call_count_before = _llm_call_count(llm)
    original_max_call_attempts = None
    remaining_llm_calls = _remaining_llm_call_budget(budget)
    if isinstance(llm, LLMEnsemble) and remaining_llm_calls is not None:
        original_max_call_attempts = llm.max_call_attempts
        llm.max_call_attempts = min(original_max_call_attempts, remaining_llm_calls)
    try:
        return _generate_with_runtime_deadline(
            llm,
            prompt,
            role=role,
            remaining_runtime_sec=remaining_runtime_sec,
        )
    finally:
        call_span = _llm_call_span(llm, call_count_before)
        if original_max_call_attempts is not None:
            llm.max_call_attempts = original_max_call_attempts
        call_delta = _llm_call_attempt_delta(llm, call_count_before)
        for _ in range(call_delta):
            budget.record_llm_call()
        budget.record_llm_provider_attempts(
            _llm_provider_attempt_delta(call_span),
            role=role,
        )
        budget.record_llm_tokens(_llm_token_delta(call_span), role=role)
        budget.record_llm_cost_microusd(
            _llm_cost_microusd_delta(call_span),
            role=role,
        )
        budget.record_llm_seconds(_llm_seconds_delta(call_span), role=role)
        _emit_llm_budget_events(
            call_span,
            role=role,
            fallback_call_count=call_delta,
            sink=budget_event_sink,
        )


def _remaining_llm_call_budget(budget: RunBudget) -> int | None:
    if budget.max_llm_calls is None:
        return None
    return max(1, budget.max_llm_calls - budget.llm_calls)


def _llm_call_attempt_delta(llm, call_count_before: int | None) -> int:
    call_count_after = _llm_call_count(llm)
    if (
        isinstance(call_count_before, int)
        and isinstance(call_count_after, int)
        and call_count_after >= call_count_before
    ):
        return max(1, call_count_after - call_count_before)
    return 1


def _llm_provider_attempt_delta(call_span: list[dict]) -> int:
    attempts = 0
    retained_records = 0
    for record in call_span:
        if not isinstance(record, dict):
            continue
        retained_records += 1
        attempts += _llm_provider_attempts_for_record(record)
    return attempts if retained_records else 0


def _llm_provider_attempts_for_record(record: dict) -> int:
    adapter_retry = record.get("adapter_retry")
    if isinstance(adapter_retry, dict):
        raw_attempts = adapter_retry.get("attempts")
        if (
            isinstance(raw_attempts, int)
            and not isinstance(raw_attempts, bool)
            and raw_attempts > 0
        ):
            return raw_attempts
    return 1


def _llm_token_delta(call_span: list[dict]) -> int:
    tokens = 0
    for record in call_span:
        if not isinstance(record, dict):
            continue
        tokens += _llm_tokens_for_record(record)
    return tokens


def _llm_tokens_for_record(record: dict) -> int:
    usage = record.get("usage")
    if not isinstance(usage, dict):
        return 0
    total_tokens = usage.get("total_tokens")
    if (
        isinstance(total_tokens, int)
        and not isinstance(total_tokens, bool)
        and total_tokens > 0
    ):
        return total_tokens
    return 0


def _llm_cost_microusd_delta(call_span: list[dict]) -> int:
    cost_microusd = 0
    for record in call_span:
        if not isinstance(record, dict):
            continue
        cost_microusd += _llm_cost_microusd_for_record(record)
    return cost_microusd


def _llm_cost_microusd_for_record(record: dict) -> int:
    cost_estimate = record.get("cost_estimate")
    if not isinstance(cost_estimate, dict):
        return 0
    raw_cost = cost_estimate.get("cost_microusd")
    if isinstance(raw_cost, int) and not isinstance(raw_cost, bool) and raw_cost > 0:
        return raw_cost
    return 0


def _llm_seconds_delta(call_span: list[dict]) -> float:
    seconds = 0.0
    for record in call_span:
        if not isinstance(record, dict):
            continue
        seconds += _llm_seconds_for_record(record)
    return seconds


def _llm_seconds_for_record(record: dict) -> float:
    raw_latency = record.get("latency_sec")
    if isinstance(raw_latency, bool) or not isinstance(raw_latency, (int, float)):
        return 0.0
    latency = float(raw_latency)
    if math.isfinite(latency) and latency > 0.0:
        return latency
    return 0.0


def _emit_llm_budget_events(
    call_span: list[dict],
    *,
    role: str,
    fallback_call_count: int,
    sink: Callable[[dict], dict] | None,
) -> None:
    if sink is None:
        return
    emitted = 0
    for record in call_span:
        if not isinstance(record, dict):
            continue
        sink(_llm_budget_event_for_record(record, role=role))
        emitted += 1
    for _ in range(max(0, fallback_call_count - emitted)):
        sink({"kind": "llm_call", "role": role})


def _llm_budget_event_for_record(record: dict, *, role: str) -> dict:
    event: dict[str, object] = {"kind": "llm_call", "role": role}
    provider_attempts = _llm_provider_attempts_for_record(record)
    if provider_attempts:
        event["provider_attempts"] = provider_attempts
    tokens = _llm_tokens_for_record(record)
    if tokens:
        event["tokens"] = tokens
    cost_microusd = _llm_cost_microusd_for_record(record)
    if cost_microusd:
        event["cost_microusd"] = cost_microusd
    seconds = _llm_seconds_for_record(record)
    if seconds:
        event["seconds"] = seconds
    return event


def _is_llm_budget_exhaustion(exc: BaseException) -> bool:
    return isinstance(exc, RuntimeError) and str(exc).startswith(
        "LLM call budget exhausted before "
    )


def _generate_with_runtime_deadline(
    llm,
    prompt: str,
    *,
    role: str,
    remaining_runtime_sec: float | None,
) -> tuple[str, int]:
    if (
        remaining_runtime_sec is None
        or "call_timeout_sec" not in getattr(llm, "__dict__", {})
    ):
        return llm.generate(prompt, role=role)
    original_timeout = getattr(llm, "call_timeout_sec")
    effective_timeout = remaining_runtime_sec
    if original_timeout is not None:
        effective_timeout = min(float(original_timeout), remaining_runtime_sec)
    setattr(llm, "call_timeout_sec", effective_timeout)
    try:
        return llm.generate(prompt, role=role)
    finally:
        setattr(llm, "call_timeout_sec", original_timeout)


class _BudgetedLLMProxy:
    def __init__(
        self,
        llm,
        budget: RunBudget,
        *,
        budget_event_sink: Callable[[dict], dict] | None = None,
    ):
        self._llm = llm
        self._budget = budget
        self._budget_event_sink = budget_event_sink

    def generate(self, prompt: str, role: str):
        return _generate_with_budget(
            self._llm,
            self._budget,
            prompt,
            role=role,
            budget_event_sink=self._budget_event_sink,
        )

    def __getattr__(self, name: str):
        return getattr(self._llm, name)


def _skipped_llm_budget_record(
    *,
    role: str,
    stop_reason: str | None,
    budget: RunBudget,
) -> dict:
    return {
        "status": "skipped",
        "role": role,
        "skip_reason": stop_reason or "max_llm_calls",
        "budget": budget.snapshot(),
    }


def _llm_call_count(llm) -> int | None:
    retention = getattr(llm, "call_history_retention", None)
    if isinstance(retention, dict):
        total = retention.get("total_records")
        if isinstance(total, int) and not isinstance(total, bool) and total >= 0:
            return total
    history = getattr(llm, "call_history", None)
    return len(history) if isinstance(history, list) else None


def _llm_call_span(llm, start: int | None) -> list[dict]:
    if start is None:
        return []
    history = getattr(llm, "call_history", None)
    if not isinstance(history, list) or start < 0:
        return []
    retention = getattr(llm, "call_history_retention", None)
    dropped = 0
    if isinstance(retention, dict):
        raw_dropped = retention.get("dropped_records")
        if isinstance(raw_dropped, int) and not isinstance(raw_dropped, bool) and raw_dropped >= 0:
            dropped = raw_dropped
    retained_start = max(0, start - dropped)
    if retained_start > len(history):
        return []
    return [dict(call) for call in history[retained_start:] if isinstance(call, dict)]


def _filter_inspirations_by_policy(
    inspirations: list[Program],
    sample_metadata: dict,
    *,
    required_metric: str | None,
    excluded_metrics: list[str] | tuple[str, ...] | None = None,
    fitness_threshold: dict | None = None,
    metric_thresholds: dict,
    metric_ranking: dict | None,
    requested_count: int,
    pool_requested_count: int,
) -> tuple[list[Program], dict]:
    excluded_metric_set = set(excluded_metrics or [])
    required_matching = [
        program
        for program in inspirations
        if required_metric is None
        or (isinstance(program.metrics, dict) and required_metric in program.metrics)
    ]
    excluded_metric_matching = [
        program
        for program in required_matching
        if not _program_has_excluded_inspiration_metric(program, excluded_metric_set)
    ]
    fitness_matching = [
        program
        for program in excluded_metric_matching
        if _program_matches_inspiration_fitness_threshold(
            program,
            fitness_threshold,
        )
    ]
    threshold_matching = [
        program
        for program in fitness_matching
        if _program_matches_inspiration_metric_thresholds(program, metric_thresholds)
    ]
    ranked = _rank_inspirations_by_metric(threshold_matching, metric_ranking)
    selected = ranked[:requested_count]
    selected_ids = {program.id for program in selected}
    filtered_out = [
        program
        for program in inspirations
        if program.id not in selected_ids
    ]
    metadata = dict(sample_metadata)
    metadata["requested_count"] = requested_count
    metadata["selected_count"] = len(selected)
    metadata["selected_program_ids"] = [program.id for program in selected]
    metadata["pre_filter_selected_count"] = len(inspirations)
    metadata["pool_requested_count"] = pool_requested_count
    if required_metric is not None:
        metadata["inspiration_required_metric"] = required_metric
        metadata["inspiration_required_metric_policy"] = "metric_present_filter_v1"
        metadata["required_metric_matching_count"] = len(required_matching)
    if excluded_metric_set:
        metadata["inspiration_excluded_metrics"] = sorted(excluded_metric_set)
        metadata["inspiration_excluded_metrics_policy"] = "metric_absence_filter_v1"
        metadata["excluded_metric_matching_count"] = len(excluded_metric_matching)
    if fitness_threshold is not None:
        metadata["inspiration_fitness_threshold"] = dict(fitness_threshold)
        metadata["inspiration_fitness_threshold_policy"] = (
            "fitness_value_threshold_filter_v1"
        )
        metadata["fitness_threshold_matching_count"] = len(fitness_matching)
    if metric_thresholds:
        metadata["inspiration_metric_thresholds"] = {
            name: dict(thresholds)
            for name, thresholds in metric_thresholds.items()
        }
        metadata["inspiration_metric_threshold_policy"] = (
            "metric_value_threshold_filter_v1"
        )
        metadata["metric_threshold_matching_count"] = len(threshold_matching)
    if metric_ranking is not None:
        metadata["inspiration_metric_ranking"] = dict(metric_ranking)
        metadata["inspiration_metric_ranking_policy"] = "metric_value_sort_v1"
        metadata["metric_ranking_candidate_count"] = len(ranked)
    metadata["inspiration_filter_filtered_count"] = len(filtered_out)
    metadata["inspiration_filter_filtered_program_ids"] = [
        program.id for program in filtered_out[:20]
    ]
    if "target_metrics" in metadata and isinstance(metadata["target_metrics"], list):
        metadata["target_metrics"] = [
            item
            for item in metadata["target_metrics"]
            if isinstance(item, dict) and item.get("program_id") in selected_ids
        ]
    return selected, metadata


def _program_has_excluded_inspiration_metric(
    program: Program,
    excluded_metrics: set[str],
) -> bool:
    if not excluded_metrics:
        return False
    metrics = program.metrics if isinstance(program.metrics, dict) else {}
    return any(metric in metrics for metric in excluded_metrics)


def _program_matches_inspiration_fitness_threshold(
    program: Program,
    fitness_threshold: dict | None,
) -> bool:
    if fitness_threshold is None:
        return True
    if (
        isinstance(program.fitness, bool)
        or not isinstance(program.fitness, (int, float))
        or not math.isfinite(float(program.fitness))
    ):
        return False
    fitness = float(program.fitness)
    minimum = fitness_threshold.get("min")
    maximum = fitness_threshold.get("max")
    if minimum is not None and fitness < float(minimum):
        return False
    if maximum is not None and fitness > float(maximum):
        return False
    return True


def _program_matches_inspiration_metric_thresholds(
    program: Program,
    metric_thresholds: dict,
) -> bool:
    if not metric_thresholds:
        return True
    metrics = program.metrics if isinstance(program.metrics, dict) else {}
    for metric, bounds in metric_thresholds.items():
        value = metrics.get(metric)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            return False
        number = float(value)
        if not math.isfinite(number):
            return False
        minimum = bounds.get("min") if isinstance(bounds, dict) else None
        maximum = bounds.get("max") if isinstance(bounds, dict) else None
        if minimum is not None and number < minimum:
            return False
        if maximum is not None and number > maximum:
            return False
    return True


def _rank_inspirations_by_metric(
    inspirations: list[Program],
    metric_ranking: dict | None,
) -> list[Program]:
    if metric_ranking is None:
        return inspirations
    metric = metric_ranking["metric"]
    direction = metric_ranking["direction"]
    sortable: list[tuple[float, int, Program]] = []
    unsortable: list[tuple[int, Program]] = []
    for index, program in enumerate(inspirations):
        metrics = program.metrics if isinstance(program.metrics, dict) else {}
        value = metrics.get(metric)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            unsortable.append((index, program))
            continue
        number = float(value)
        if not math.isfinite(number):
            unsortable.append((index, program))
            continue
        sortable.append((number, index, program))
    reverse = direction == "maximize"
    ranked = [
        program
        for _, _, program in sorted(
            sortable,
            key=lambda item: (item[0], -item[1] if reverse else item[1]),
            reverse=reverse,
        )
    ]
    ranked.extend(program for _, program in unsortable)
    return ranked


def _build_meta_prompt_mutation_request(
    prompt_program,
    prompt_db: PromptDatabase,
    program: Program,
    parent: Program,
    prompt_reward: float,
    recent_failures: list[dict],
    config: Config,
) -> tuple[str, dict]:
    context_policy_capabilities = validate_meta_prompt_context_policy_capabilities(
        _META_PROMPT_CONTEXT_POLICY_CAPABILITIES
    )
    evidence = {
        "reward_policy": {
            "mode": config.prompt_reward_mode,
            "bounds": [
                float(config.prompt_reward_bounds[0]),
                float(config.prompt_reward_bounds[1]),
            ],
        },
        "latest_candidate": _candidate_evidence(program, parent, prompt_reward),
        "selected_prompt": _prompt_program_evidence(prompt_program, selected=True),
        "context_policy_capabilities": context_policy_capabilities,
        "prompt_program_summaries": [
            _prompt_program_evidence(candidate, selected=candidate.id == prompt_program.id)
            for candidate in sorted(
                prompt_db.all(),
                key=lambda item: (item.mean_reward, item.uses, item.id),
                reverse=True,
            )[:5]
        ],
        "recent_failures": [_failure_evidence(failure) for failure in recent_failures[-3:]],
    }
    raw_context = json.dumps(evidence, indent=2)
    redacted_context = redact_sensitive_text(raw_context)
    truncated = len(redacted_context) > _MAX_META_PROMPT_CONTEXT_CHARS
    if truncated:
        redacted_context = (
            redacted_context[: _MAX_META_PROMPT_CONTEXT_CHARS - 15] + "...<truncated>"
        )
    retained_evidence = _retained_meta_prompt_evidence(
        raw_context=raw_context,
        prompt_context=redacted_context,
        prompt_context_truncated=truncated,
        mode=config.meta_prompt_evidence_retention_mode,
    )
    context_hash = (
        hashlib.sha256(redacted_context.encode("utf-8")).hexdigest()
        if retained_evidence["sha256"] is not None
        else None
    )
    safe_template, template_metadata = _meta_prompt_template_preview(
        prompt_program.template
    )
    context_metadata = {
        "schema": "meta_prompt_mutation_context_v1",
        "sha256": context_hash,
        "chars": (
            len(redacted_context) if retained_evidence["chars"] is not None else None
        ),
        "truncated": truncated if retained_evidence["chars"] is not None else False,
        "sections": [
            "reward_policy",
            "latest_candidate",
            "selected_prompt",
            "context_policy_capabilities",
            "prompt_program_summaries",
            "recent_failures",
        ],
        "selected_prompt_id": prompt_program.id,
        "latest_program_id": program.id,
        "latest_parent_id": parent.id,
        "current_template": template_metadata,
        "evidence_retention": {
            key: value for key, value in retained_evidence.items() if key != "text"
        },
    }
    if retained_evidence["text"] is not None:
        context_metadata["evidence"] = retained_evidence["text"]
    current_fields = sorted(prompt_template_fields(prompt_program.template))
    mutation_prompt = (
        "Improve this LibreEvolve prompt template for future code evolution. "
        "Use the bounded prompt-performance evidence to improve search behavior. "
        "Keep all existing Python format placeholders intact. You may also tune "
        "the structured context_policy.disabled_sections list and "
        "context_policy.section_priorities map to change optional context "
        "rendering and prompt-packing priorities, plus "
        "context_policy.mutation_instruction_variant with one of default, "
        "minimal, or exploratory, context_policy."
        "mutation_instruction_include_example to keep or remove the built-in "
        "mutation-format example, context_policy.proposal_metadata_enabled "
        "to override whether proposal metadata instructions and parsing are "
        "enabled for this prompt arm, and context_policy.feedback_sections to "
        "choose which evaluator/LLM-feedback subsections are rendered, plus "
        "context_policy.llm_feedback_fields to choose LLM-grader feedback "
        "fields, context_policy.llm_feedback_max_chars_by_field to cap "
        "LLM-grader feedback fields independently, "
        "context_policy.proposal_fields to choose proposal-metadata "
        "fields, context_policy.proposal_max_chars_by_field to cap "
        "proposal-metadata fields independently, "
        "context_policy.stage_summary_fields to choose stage-summary "
        "fields, context_policy.stage_summary_max_chars_by_field to cap "
        "stage-summary fields independently, "
        "context_policy.execution_output_fields to choose execution-output "
        "fields, context_policy.execution_output_max_chars_by_field to cap "
        "stdout/stderr/error text independently, context_policy.sample_retry_fields to choose sample/retry "
        "diagnostic fields, context_policy.sample_retry_max_chars_by_field to cap "
        "sample/retry diagnostic text independently, "
        "context_policy.program_output_fields to choose program-output "
        "fields, and context_policy.program_output_max_chars_by_field to cap "
        "program-output text fields independently, "
        "context_policy.validator_artifact_fields to choose validator-artifact "
        "fields, context_policy.validator_artifact_max_chars_by_field to cap "
        "validator-artifact text fields independently, "
        "context_policy.validator_artifact_content_fields to choose "
        "nested artifact-content fields, context_policy."
        "validator_artifact_content_mode and validator_artifact_content_max_bytes/"
        "max_chars to choose artifact-content rendering policy, and context_policy."
        "validator_skipped_artifact_fields to choose skipped-artifact fields, "
        "context_policy.validator_skipped_artifact_max_chars_by_field to cap "
        "skipped-artifact text fields independently, "
        "and context_policy.validator_diagnostic_groups to choose validator "
        "diagnostic groups, plus context_policy.validator_metadata_keys "
        "to choose safe validator metadata-summary keys, context_policy."
        "validator_metadata_limit to cap validator metadata-summary item count, "
        "context_policy."
        "validator_metadata_max_chars_by_key to cap validator metadata-summary "
        "values by key, and context_policy."
        "syntax_error_fields to choose syntax-error diagnostic fields, plus "
        "context_policy.syntax_error_max_chars_by_field to cap syntax-error "
        "diagnostic text fields independently, plus "
        "context_policy.metric_bound_fields to choose metric-bound diagnostic "
        "fields, context_policy.metric_bound_max_chars_by_field to cap "
        "metric-bound diagnostic text fields independently, and context_policy."
        "configured_stage_check_fields to choose "
        "configured-stage diagnostic fields, context_policy."
        "configured_stage_check_max_chars_by_field to cap configured-stage "
        "diagnostic text fields independently, context_policy.stage_metric_threshold_fields "
        "to choose nested stage metric-threshold fields, context_policy."
        "stage_metric_threshold_max_chars_by_field to cap nested stage "
        "metric-threshold text fields independently, context_policy."
        "artifact_output_check_fields to choose nested artifact-output check "
        "fields, context_policy.artifact_output_check_max_chars_by_field to "
        "cap nested artifact-output check text fields independently, plus "
        "context_policy."
        "malformed_metric_fields to choose malformed-metric diagnostic fields, "
        "context_policy.malformed_metric_max_chars_by_field to cap "
        "malformed-metric diagnostic text fields independently. "
        "context_policy.metric_aggregation_fields may choose "
        "metric-aggregation diagnostic fields. context_policy."
        "metric_aggregation_max_chars_by_field may cap metric-aggregation "
        "diagnostic text fields independently. context_policy."
        "execution_diagnostic_groups may choose execution-diagnostic subgroups. "
        "context_policy.validator_boundary_fields may choose validator-boundary diagnostic "
        "fields, context_policy.validator_boundary_max_chars_by_field may cap "
        "validator-boundary diagnostic text fields independently, context_policy."
        "validator_resource_limit_fields may choose "
        "nested validator resource-limit fields, context_policy."
        "validator_resource_limit_max_chars_by_field may cap nested validator "
        "resource-limit text fields independently, and context_policy."
        "validator_stdin_fields may choose "
        "validator-stdin diagnostic fields, while context_policy."
        "validator_stdin_max_chars_by_field may cap validator-stdin "
        "diagnostic text fields independently. context_policy."
        "diagnostic_output_fields may choose diagnostic-output fields. "
        "context_policy.diagnostic_output_max_chars_by_field may cap "
        "diagnostic-output text fields independently. "
        "context_policy.timeout_cleanup_fields may choose timeout-cleanup "
        "diagnostic fields, and context_policy."
        "timeout_cleanup_max_chars_by_field may cap timeout-cleanup "
        "diagnostic text fields independently. "
        "When "
        "stochastic prompt-format markers are configured, context_policy."
        "prompt_format_weights may override their alternative weights, and "
        "context_policy.context_source_paths may select local context paths to "
        "render, context_policy.context_source_max_chars may cap rendered local "
        "context source text, context_policy.context_source_limit may cap how many "
        "ordered local context sources render after path selection and ranking, "
        "context_policy.context_source_required_terms may require loaded local "
        "context sources to contain all listed safe terms before ranking, "
        "context_policy.context_source_excluded_terms may omit loaded local "
        "context sources containing any listed safe terms before ranking, "
        "context_policy.context_source_ranking_terms may provide explicit safe "
        "terms for deterministic local context-source ranking, "
        "context_policy.context_source_truncation may choose "
        "head or head_tail truncation, context_policy.context_source_order_policy "
        "may keep path order or rank selected context sources by deterministic "
        "task-term overlap, and context_policy.recent_failure_limit may cap rendered "
        "recent failure-memory records, context_policy."
        "recent_failure_selection_policy may choose recent, oldest, "
        "lowest_score, or highest_repetition retained failure-memory records, "
        "context_policy."
        "recent_failure_required_errors may filter retained failure-memory "
        "records by exact safe error or diff_error labels, context_policy."
        "recent_failure_excluded_errors may exclude retained failure-memory "
        "records by exact safe error or diff_error labels, context_policy."
        "recent_failure_required_changed_files may filter retained "
        "failure-memory records by exact safe changed file paths, context_policy."
        "recent_failure_excluded_changed_files may exclude retained "
        "failure-memory records by exact safe changed file paths, context_policy."
        "recent_failure_required_stage_names may filter retained "
        "failure-memory records by exact safe evaluation stage names, "
        "context_policy.recent_failure_excluded_stage_names may exclude retained "
        "failure-memory records by exact safe evaluation stage names, context_policy."
        "recent_failure_required_terms may require retained failure-memory "
        "records to contain all listed safe terms, context_policy."
        "recent_failure_excluded_terms may omit retained failure-memory records "
        "containing any listed safe terms, context_policy."
        "recent_failure_repetition_threshold may filter retained "
        "failure-memory records by repetition_count min/max bounds, context_policy."
        "recent_failure_score_threshold may filter retained failure-memory "
        "records by finite score min/max bounds, context_policy."
        "recent_failure_max_chars_by_field may cap recent failure-memory "
        "fields independently, and context_policy.inspiration_limit "
        "may cap rendered selected inspirations, context_policy."
        "inspiration_sample_count may choose how many inspirations are sampled "
        "upstream before plugin context and prompt rendering, context_policy."
        "inspiration_required_metric may filter upstream inspirations to "
        "programs carrying a safe metric name before plugin context and prompt "
        "rendering, context_policy.inspiration_excluded_metrics may filter out "
        "upstream inspirations carrying any listed safe metric names, "
        "context_policy.inspiration_fitness_threshold may filter upstream "
        "inspirations by finite fitness min/max bounds, "
        "context_policy.inspiration_metric_thresholds may filter "
        "upstream inspirations to programs whose numeric metric values meet "
        "safe min/max thresholds before plugin context and prompt rendering, "
        "context_policy.evaluator_path_fields may select prompt-visible "
        "validator path provenance and "
        "context_policy.evaluator_path_max_chars_by_field may cap those "
        "path fields, "
        "context_policy.evaluator_dependency_fields may select prompt-visible "
        "validator dependency-policy provenance and "
        "context_policy.evaluator_dependency_max_chars_by_field may cap those "
        "dependency fields, "
        "context_policy.evaluator_stage_fields may select prompt-visible "
        "validator stage-context provenance and "
        "context_policy.evaluator_stage_max_chars_by_field may cap those "
        "stage fields, "
        "context_policy.evaluator_workspace_fields may select prompt-visible "
        "evaluated workspace provenance and "
        "context_policy.evaluator_workspace_max_chars_by_field may cap those "
        "workspace fields, "
        "context_policy.validator_budget_fields may select prompt-visible "
        "stage/sample budget diagnostics and "
        "context_policy.validator_budget_max_chars_by_field may cap those "
        "budget fields, context_policy.validator_env_fields may select "
        "prompt-visible validator environment diagnostics and "
        "context_policy.validator_env_max_chars_by_field may cap those "
        "environment fields, context_policy.synthetic_metric_fields may select "
        "synthetic failure-metric diagnostics and "
        "context_policy.synthetic_metric_max_chars_by_field may cap those "
        "synthetic metric fields, context_policy.materialization_error_fields "
        "may select materialization-error diagnostics and "
        "context_policy.materialization_error_max_chars_by_field may cap those "
        "fields, "
        "context_policy.inspiration_metric_ranking may rank upstream inspirations "
        "by a numeric metric before final selection, and "
        "context_policy.extra_context_max_chars may cap rendered plugin extra-context text. "
        "context_policy.plugin_context_enabled may disable plugin prompt-context "
        "generation for this prompt arm while preserving plugin provenance, and "
        "context_policy.plugin_context_allowlist may select plugin identity labels "
        "whose prompt-context hooks should run, context_policy."
        "plugin_context_excluded_labels may omit plugin identity labels before "
        "prompt-context hooks run, and context_policy."
        "plugin_context_order may reorder selected plugin prompt-context "
        "sections by safe plugin identity labels, context_policy."
        "plugin_context_required_terms may require plugin context text to "
        "contain safe terms before prompt visibility, context_policy."
        "plugin_context_excluded_terms may omit plugin context text containing "
        "safe terms before prompt visibility, context_policy."
        "plugin_context_ranking_terms may rank prompt-visible plugin context "
        "sections by deterministic term overlap, context_policy."
        "plugin_context_limit may cap how many ordered plugin context sections "
        "become prompt-visible, and context_policy."
        "plugin_context_max_chars may globally cap each plugin context section, "
        "context_policy.plugin_context_truncation may choose head or head_tail "
        "retention under plugin context caps, "
        "while context_policy.plugin_context_max_chars_by_label may cap plugin "
        "context text by safe plugin identity label before aggregate prompt packing. "
        "Return either the complete "
        "revised template as plain text, or one JSON object with schema "
        "\"libreevolve.prompt_mutation_response.v1\", template, and optional "
        "context_policy.\n\n"
        "[Prompt Performance Evidence]\n"
        f"{redacted_context}\n\n"
        "[Current Template Placeholders]\n"
        f"{json.dumps(current_fields, sort_keys=True)}\n\n"
        "[Current Template]\n"
        f"{safe_template}"
    )
    return mutation_prompt, context_metadata


def validate_meta_prompt_context_policy_capabilities(capabilities: object) -> dict:
    """Validate the meta-prompt-visible structured context-policy capability map."""
    if not isinstance(capabilities, dict):
        raise ValueError("meta-prompt context policy capabilities must be an object")
    required = {"schema", *_META_PROMPT_CONTEXT_POLICY_CAPABILITY_SECTIONS}
    missing = required - set(capabilities)
    if missing:
        raise ValueError(
            f"meta-prompt context policy capabilities missing fields: {sorted(missing)}"
        )
    unsupported = set(capabilities) - required
    if unsupported:
        raise ValueError(
            "meta-prompt context policy capabilities has unsupported fields: "
            f"{sorted(unsupported)}"
        )
    if capabilities["schema"] != META_PROMPT_CONTEXT_POLICY_CAPABILITIES_SCHEMA:
        raise ValueError("meta-prompt context policy capabilities schema is unsupported")
    policy_fields = set(validate_prompt_context_policy({})) - {"schema"}
    advertised_fields: set[str] = set()
    normalized = {"schema": capabilities["schema"]}
    for section in _META_PROMPT_CONTEXT_POLICY_CAPABILITY_SECTIONS:
        fields = _validate_meta_prompt_context_policy_capability_section(
            capabilities[section],
            section,
        )
        duplicates = advertised_fields.intersection(fields)
        if duplicates:
            raise ValueError(
                "meta-prompt context policy capabilities duplicate fields: "
                f"{sorted(duplicates)}"
            )
        advertised_fields.update(fields)
        normalized[section] = ",".join(fields)
    missing_policy_fields = policy_fields - advertised_fields
    if missing_policy_fields:
        raise ValueError(
            "meta-prompt context policy capabilities omit prompt policy fields: "
            f"{sorted(missing_policy_fields)}"
        )
    unsupported_policy_fields = advertised_fields - policy_fields
    if unsupported_policy_fields:
        raise ValueError(
            "meta-prompt context policy capabilities advertise unsupported fields: "
            f"{sorted(unsupported_policy_fields)}"
        )
    return normalized


def _validate_meta_prompt_context_policy_capability_section(
    value: object,
    section: str,
) -> list[str]:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(
            f"meta-prompt context policy capabilities {section} must be text"
        )
    fields = value.split(",")
    normalized: list[str] = []
    seen: set[str] = set()
    for field in fields:
        if field != field.strip() or not field:
            raise ValueError(
                f"meta-prompt context policy capabilities {section} has malformed field"
            )
        if _META_PROMPT_CONTEXT_POLICY_CAPABILITY_RE.fullmatch(field) is None:
            raise ValueError(
                f"meta-prompt context policy capabilities {section} has unsafe field"
            )
        if field in seen:
            raise ValueError(
                f"meta-prompt context policy capabilities {section} repeats field"
            )
        seen.add(field)
        normalized.append(field)
    return normalized


def _retained_meta_prompt_evidence(
    *,
    raw_context: str,
    prompt_context: str,
    prompt_context_truncated: bool,
    mode: str,
) -> dict:
    if mode == "off":
        return {
            "text": None,
            "sha256": None,
            "chars": None,
            "stored_chars": 0,
            "redacted": None,
            "truncated": False,
            "prompt_sha256": None,
            "prompt_chars": None,
            "prompt_truncated": False,
            "max_retained_chars": _MAX_META_PROMPT_RETAINED_EVIDENCE_CHARS,
            "retention_mode": mode,
            "retention_policy": "off_no_evidence_or_hash",
        }
    raw_sha256 = hashlib.sha256(
        raw_context.encode("utf-8", errors="replace")
    ).hexdigest()
    prompt_sha256 = hashlib.sha256(
        prompt_context.encode("utf-8", errors="replace")
    ).hexdigest()
    if mode == "hash_only":
        return {
            "text": None,
            "sha256": raw_sha256,
            "chars": len(raw_context),
            "stored_chars": 0,
            "redacted": None,
            "truncated": False,
            "prompt_sha256": prompt_sha256,
            "prompt_chars": len(prompt_context),
            "prompt_truncated": prompt_context_truncated,
            "max_retained_chars": _MAX_META_PROMPT_RETAINED_EVIDENCE_CHARS,
            "retention_mode": mode,
            "retention_policy": "hash_only_with_raw_sha256",
        }
    if mode == "full":
        redacted = redact_sensitive_text(raw_context)
        text, metadata_truncated = _bounded_meta_prompt_retained_evidence(redacted)
        return {
            "text": text,
            "sha256": raw_sha256,
            "chars": len(raw_context),
            "stored_chars": len(text),
            "redacted": redacted != raw_context,
            "truncated": metadata_truncated,
            "prompt_sha256": prompt_sha256,
            "prompt_chars": len(prompt_context),
            "prompt_truncated": prompt_context_truncated,
            "max_retained_chars": _MAX_META_PROMPT_RETAINED_EVIDENCE_CHARS,
            "retention_mode": mode,
            "retention_policy": (
                "full_secret_redacted_text_with_metadata_cap_and_raw_sha256"
            ),
        }
    text, metadata_truncated = _bounded_meta_prompt_retained_evidence(prompt_context)
    return {
        "text": text,
        "sha256": raw_sha256,
        "chars": len(raw_context),
        "stored_chars": len(text),
        "redacted": prompt_context != raw_context,
        "truncated": prompt_context_truncated or metadata_truncated,
        "prompt_sha256": prompt_sha256,
        "prompt_chars": len(prompt_context),
        "prompt_truncated": prompt_context_truncated,
        "max_retained_chars": _MAX_META_PROMPT_RETAINED_EVIDENCE_CHARS,
        "retention_mode": mode,
        "retention_policy": (
            "redact_then_prompt_and_metadata_truncate_with_raw_sha256"
        ),
    }


def _bounded_meta_prompt_retained_evidence(text: str) -> tuple[str, bool]:
    if len(text) <= _MAX_META_PROMPT_RETAINED_EVIDENCE_CHARS:
        return text, False
    suffix = "...<truncated>"
    keep = max(0, _MAX_META_PROMPT_RETAINED_EVIDENCE_CHARS - len(suffix))
    return text[:keep] + suffix, True


def _meta_prompt_template_preview(template: str) -> tuple[str, dict]:
    redacted = redact_sensitive_text(template)
    truncated = len(redacted) > _MAX_META_PROMPT_TEMPLATE_CHARS
    if truncated:
        suffix = "...<truncated>"
        redacted = (
            redacted[: _MAX_META_PROMPT_TEMPLATE_CHARS - len(suffix)] + suffix
        )
    return redacted, {
        "sha256": hashlib.sha256(template.encode("utf-8")).hexdigest(),
        "raw_chars": len(template),
        "prompt_chars": len(redacted),
        "redacted": redacted != template,
        "truncated": truncated,
        "limit_chars": _MAX_META_PROMPT_TEMPLATE_CHARS,
    }


def _prompt_program_evidence(prompt_program, *, selected: bool) -> dict:
    metadata = prompt_program.metadata if isinstance(prompt_program.metadata, dict) else {}
    context_policy = (
        prompt_program.context_policy
        if isinstance(getattr(prompt_program, "context_policy", None), dict)
        else {}
    )
    policy = validate_prompt_context_policy(context_policy)
    evidence = {
        "id": prompt_program.id,
        "selected": selected,
        "generation": prompt_program.generation,
        "uses": prompt_program.uses,
        "reward_sum": _finite_json_number(prompt_program.reward_sum),
        "mean_reward": _finite_json_number(prompt_program.mean_reward),
        "template_sha256": hashlib.sha256(prompt_program.template.encode("utf-8")).hexdigest(),
        "template_chars": len(prompt_program.template),
        "context_policy_sha256": prompt_context_policy_sha256(policy),
        "context_policy_preview": _prompt_context_policy_preview(policy),
    }
    for key in (
        "last_prompt_reward",
        "last_prompt_penalty",
        "last_generation",
        "last_program_id",
        "last_candidate_score",
        "last_parent_score",
    ):
        if key in metadata:
            evidence[key] = _meta_prompt_safe_value(metadata[key])
    rejected = metadata.get("rejected_prompt_mutations")
    if isinstance(rejected, list) and rejected:
        evidence["recent_rejections"] = _meta_prompt_safe_value(rejected[-3:])
    return evidence


def _prompt_context_policy_preview(context_policy: dict) -> dict:
    policy = validate_prompt_context_policy(context_policy)
    default_policy = validate_prompt_context_policy({})
    non_default_policy = {
        key: value
        for key, value in policy.items()
        if value != default_policy.get(key)
    }
    return {
        "schema": "libreevolve.meta_prompt_context_policy_preview.v1",
        "sha256": prompt_context_policy_sha256(policy),
        "field_count": len(policy),
        "non_default_fields": sorted(non_default_policy),
        "non_default_policy": _meta_prompt_safe_value(non_default_policy),
    }


def _candidate_evidence(program: Program, parent: Program, prompt_reward: float) -> dict:
    evaluation = program.evaluation if isinstance(program.evaluation, dict) else {}
    composition = program.metadata.get("score_composition") if isinstance(program.metadata, dict) else None
    evidence = {
        "program_id": program.id,
        "parent_id": parent.id,
        "generation": program.generation,
        "candidate_score": _finite_json_number(program.fitness),
        "parent_score": _finite_json_number(parent.fitness),
        "prompt_reward": _finite_json_number(prompt_reward),
        "improvement": _finite_json_number(program.fitness - parent.fitness),
        "is_valid": evaluation.get("is_valid"),
        "error": _bounded_meta_prompt_text(evaluation.get("error")),
        "metrics": _meta_prompt_metrics(program.metrics),
    }
    if isinstance(composition, dict):
        evidence["score_composition"] = _meta_prompt_safe_value(composition)
    return evidence


def _failure_evidence(failure: dict) -> dict:
    keys = (
        "program_id",
        "parent_id",
        "generation",
        "score",
        "is_valid",
        "error",
        "diff_error",
        "admission_reason",
        "repetition_count",
    )
    evidence = {
        key: _meta_prompt_safe_value(failure[key])
        for key in keys
        if key in failure
    }
    if "mutation_text" in failure:
        evidence["mutation_text"] = _bounded_meta_prompt_text(failure.get("mutation_text"))
    return evidence


def _meta_prompt_metrics(metrics: dict) -> dict:
    safe: dict[str, object] = {}
    for key, value in sorted(metrics.items(), key=lambda item: str(item[0])):
        if len(safe) >= 10:
            break
        safe_key = _meta_prompt_safe_key(key)
        if safe_key in safe:
            safe_key = _meta_prompt_key_with_hash(str(key), str(key))
        safe[safe_key] = _meta_prompt_safe_value(value)
    return safe


def _meta_prompt_safe_value(value: object) -> object:
    if isinstance(value, dict):
        safe: dict[str, object] = {}
        for key, item in list(value.items())[:20]:
            safe_key = _meta_prompt_safe_key(key)
            if safe_key in safe:
                safe_key = _meta_prompt_key_with_hash(str(key), str(key))
            safe[safe_key] = _meta_prompt_safe_value(item)
        return safe
    if isinstance(value, list):
        return [_meta_prompt_safe_value(item) for item in value[:20]]
    if isinstance(value, tuple):
        return [_meta_prompt_safe_value(item) for item in value[:20]]
    if isinstance(value, str):
        return _bounded_meta_prompt_text(value)
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return _finite_json_number(value)
    return _bounded_meta_prompt_text(repr(value))


def _meta_prompt_safe_key(key: object) -> str:
    raw = str(key)
    redacted = redact_sensitive_text(raw)
    bounded = _bounded_meta_prompt_key(redacted)
    if bounded != raw:
        return _meta_prompt_key_with_hash(bounded, raw)
    return bounded


def _bounded_meta_prompt_key(key: str) -> str:
    if len(key) <= _MAX_META_PROMPT_KEY_CHARS:
        return key
    suffix = "...<truncated>"
    return key[: _MAX_META_PROMPT_KEY_CHARS - len(suffix)] + suffix


def _meta_prompt_key_with_hash(label: str, hash_source: str) -> str:
    digest = hashlib.sha256(hash_source.encode("utf-8")).hexdigest()[:12]
    suffix = f"#sha256:{digest}"
    base_limit = max(1, _MAX_META_PROMPT_KEY_CHARS - len(suffix))
    base = label if len(label) <= base_limit else label[:base_limit]
    return base + suffix


def _finite_json_number(value: object) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    numeric = float(value)
    if not math.isfinite(numeric):
        return None
    return numeric


def _bounded_meta_prompt_text(value: object) -> str | None:
    if value is None:
        return None
    text = redact_sensitive_text(str(value))
    if len(text) > _MAX_META_PROMPT_TEXT_FIELD_CHARS:
        return text[: _MAX_META_PROMPT_TEXT_FIELD_CHARS - 15] + "...<truncated>"
    return text


def _program_llm_calls(
    call_span: list[dict],
    mutation_call: dict | None,
    critique_metadata: dict | None,
    result,
) -> list[dict]:
    if call_span:
        return [dict(call) for call in call_span]
    calls = []
    seen_call_keys = set()

    def append_call(call: object) -> None:
        if not isinstance(call, dict):
            return
        key = call.get("id") if isinstance(call.get("id"), str) else json.dumps(
            call,
            sort_keys=True,
            default=str,
        )
        if key in seen_call_keys:
            return
        seen_call_keys.add(key)
        calls.append(dict(call))

    append_call(mutation_call)
    if critique_metadata and isinstance(critique_metadata.get("llm_call"), dict):
        append_call(critique_metadata["llm_call"])
    if critique_metadata and isinstance(critique_metadata.get("reviewer_pool"), dict):
        reviewers = critique_metadata["reviewer_pool"].get("reviewers")
        if isinstance(reviewers, list):
            for reviewer in reviewers:
                if isinstance(reviewer, dict) and isinstance(
                    reviewer.get("llm_call"), dict
                ):
                    append_call(reviewer["llm_call"])
    feedback_records = result.metadata.get("llm_feedback", []) if result.metadata else []
    if isinstance(feedback_records, list):
        for record in feedback_records:
            if isinstance(record, dict) and isinstance(record.get("llm_call"), dict):
                append_call(record["llm_call"])
    return calls


def _run_critique_reviewers(
    *,
    llm,
    budget: RunBudget,
    workspace: CandidateWorkspace,
    base_prompt: str,
    original_diff: str,
    original_proposal_metadata: dict,
    config: Config,
    capture_proposal_metadata: bool | None = None,
    budget_event_sink: Callable[[dict], dict] | None = None,
) -> tuple[str, dict, dict]:
    if capture_proposal_metadata is None:
        capture_proposal_metadata = config.capture_proposal_metadata
    reviewers = _critique_reviewer_specs(config)
    records: list[dict] = []
    valid_records: list[dict] = []
    for index, reviewer in enumerate(reviewers):
        reviewer_prompt = build_critique_prompt(
            base_prompt,
            original_diff,
            critique_prompt=reviewer["prompt"] or None,
        )
        role = reviewer["role"]
        budget_reason = budget.check_before_llm_call(role=role)
        if budget_reason is not None:
            skipped = _skipped_llm_budget_record(
                role=role,
                stop_reason=budget.stop_reason,
                budget=budget,
            )
            status = {
                "accepted_revision": False,
                "selected_diff": "original",
                "original_diff_error": None,
                "revised_diff_error": "critique_budget_skipped",
                "fallback_reason": "critique_budget_skipped_original_mutation",
                **skipped,
            }
            if capture_proposal_metadata:
                status = {
                    **status,
                    "proposal_source": "original",
                    "original_proposal": original_proposal_metadata,
                    "revised_proposal": {},
                }
            record = _critique_metadata_record(
                prompt=reviewer_prompt,
                original_diff=original_diff,
                revised_diff="",
                backend_idx=-1,
                llm_call=None,
                critique_status=status,
                retention_mode=config.critique_retention_mode,
            )
            record.update(_critique_reviewer_record_fields(index, reviewer))
            records.append(record)
            break
        try:
            revised_diff, backend_idx = _generate_with_budget(
                llm,
                budget,
                reviewer_prompt,
                role=role,
                budget_event_sink=budget_event_sink,
            )
        except Exception as exc:
            failure = _bounded_llm_failure_record("critique", exc, llm)
            status = {
                "accepted_revision": False,
                "selected_diff": "original",
                "original_diff_error": None,
                "revised_diff_error": "llm_critique_failed",
                "fallback_reason": "critique_provider_failure_original_mutation",
                **failure,
                "reviewer_role": role,
            }
            if capture_proposal_metadata:
                status = {
                    **status,
                    "proposal_source": "original",
                    "original_proposal": original_proposal_metadata,
                    "revised_proposal": {},
                }
            record = _critique_metadata_record(
                prompt=reviewer_prompt,
                original_diff=original_diff,
                revised_diff="",
                backend_idx=-1,
                llm_call=failure.get("llm_call"),
                critique_status=status,
                retention_mode=config.critique_retention_mode,
            )
            record.update(_critique_reviewer_record_fields(index, reviewer))
            records.append(record)
            continue

        llm_call = _last_llm_call(llm)
        revised_proposal_metadata = (
            extract_proposal_metadata(revised_diff)
            if capture_proposal_metadata and isinstance(revised_diff, str)
            else {}
        )
        selected_diff, status = _select_critique_mutation(
            workspace,
            original_diff,
            revised_diff,
            config.mutation_mode,
        )
        if capture_proposal_metadata:
            proposal_source = status.get("selected_diff")
            status = {
                **status,
                "proposal_source": proposal_source,
                "original_proposal": original_proposal_metadata,
                "revised_proposal": revised_proposal_metadata,
            }
        record = _critique_metadata_record(
            prompt=reviewer_prompt,
            original_diff=original_diff,
            revised_diff=revised_diff,
            backend_idx=backend_idx,
            llm_call=llm_call,
            critique_status=status,
            retention_mode=config.critique_retention_mode,
        )
        record.update(_critique_reviewer_record_fields(index, reviewer))
        record["selected_candidate_diff"] = selected_diff
        records.append(record)
        if status["accepted_revision"]:
            valid_records.append(record)

    selected = _select_critique_reviewer_record(
        records,
        valid_records,
        policy=config.critique_aggregation_policy,
    )
    selected_diff = (
        selected.get("selected_candidate_diff")
        if isinstance(selected.get("selected_candidate_diff"), str)
        else original_diff
    )
    selected_revised_proposal = (
        selected.get("revised_proposal")
        if isinstance(selected.get("revised_proposal"), dict)
        and selected.get("selected_diff") == "revised"
        else {}
    )
    metadata = dict(selected)
    metadata.pop("selected_candidate_diff", None)
    metadata["reviewer_pool"] = {
        "schema": "libreevolve.critique_reviewer_pool.v1",
        "enabled": len(reviewers) > 1 or bool(config.critique_reviewers),
        "aggregation_policy": config.critique_aggregation_policy,
        "reviewer_count": len(reviewers),
        "completed_review_count": len(records),
        "valid_revision_count": len(valid_records),
        "selected_reviewer": selected.get("reviewer_name"),
        "selected_reviewer_role": selected.get("reviewer_role"),
        "reviewers": [
            {key: value for key, value in record.items() if key != "selected_candidate_diff"}
            for record in records
        ],
    }
    return selected_diff, metadata, selected_revised_proposal


def _critique_reviewer_specs(config: Config) -> list[dict]:
    if config.critique_reviewers:
        return [
            {
                "name": reviewer["name"],
                "prompt": reviewer["prompt"] or config.critique_prompt,
                "role": reviewer["role"],
            }
            for reviewer in config.critique_reviewers
        ]
    return [
        {
            "name": "default",
            "prompt": config.critique_prompt,
            "role": "critique",
        }
    ]


def _critique_reviewer_record_fields(index: int, reviewer: Mapping[str, object]) -> dict:
    return {
        "reviewer_index": index,
        "reviewer_name": reviewer["name"],
        "reviewer_role": reviewer["role"],
    }


def _select_critique_reviewer_record(
    records: list[dict],
    valid_records: list[dict],
    *,
    policy: str,
) -> dict:
    if valid_records:
        if policy == "last_valid":
            return valid_records[-1]
        return valid_records[0]
    if records:
        return records[-1]
    return {
        "status": "skipped",
        "accepted_revision": False,
        "selected_diff": "original",
        "original_diff_error": None,
        "revised_diff_error": "no_critique_reviewers_completed",
        "fallback_reason": "no_critique_reviewers_completed_original_mutation",
        "backend_idx": -1,
        "llm_call": None,
        "reviewer_index": None,
        "reviewer_name": None,
        "reviewer_role": None,
    }


def _select_critique_mutation(
    workspace: CandidateWorkspace,
    original_diff: str,
    revised_diff: object,
    mutation_mode: str,
) -> tuple[str, dict]:
    """Validate critique revisions before replacing the original mutation."""

    _, revised_error = apply_workspace_mutation(
        workspace, revised_diff, mutation_mode=mutation_mode
    )
    status = {
        "selected_diff": "revised",
        "accepted_revision": revised_error is None,
        "revised_diff_error": revised_error,
        "original_diff_error": None,
        "fallback_reason": None,
    }
    if revised_error is None:
        return revised_diff, status

    _, original_error = apply_workspace_mutation(
        workspace, original_diff, mutation_mode=mutation_mode
    )
    status["original_diff_error"] = original_error
    if original_error is None:
        status["selected_diff"] = "original"
        status["fallback_reason"] = "invalid_revised_diff"
        return original_diff, status
    status["selected_diff"] = "original"
    status["fallback_reason"] = "no_valid_mutation"
    return original_diff, status


def _evaluation_is_valid(program: Program) -> bool:
    return program.evaluation.get("is_valid") is True


def _backend_reward(program: Program, parent: Program, backend_idx: int) -> dict:
    admission = (
        program.metadata.get("archive_admission")
        if isinstance(program.metadata.get("archive_admission"), dict)
        else {}
    )
    eligible = (
        admission.get("admitted") is True
        and program.evaluation.get("is_valid") is True
        and math.isfinite(program.fitness)
        and math.isfinite(parent.fitness)
    )
    raw_improvement = (
        program.fitness - parent.fitness
        if math.isfinite(program.fitness) and math.isfinite(parent.fitness)
        else None
    )
    reward = max(0.0, raw_improvement) if eligible and raw_improvement is not None else 0.0
    reason = "admitted_valid_improvement" if eligible else str(
        admission.get("reason") or program.evaluation.get("error") or "not_admitted"
    )
    return {
        "backend_idx": backend_idx,
        "policy": "admitted_valid_nonnegative_improvement",
        "eligible": eligible,
        "reward": reward,
        "raw_improvement": raw_improvement,
        "reason": reason,
    }


def _prompt_reward(score: float, parent_score: float, mode: str) -> float:
    if mode == "improvement":
        return score - parent_score
    return score
